window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JDG"]={"book":"JDG","editions":{"hbo-source":[[1,1,"וַ⁠יְהִ֗י אַחֲרֵי֙ מ֣וֹת יְהוֹשֻׁ֔עַ וַֽ⁠יִּשְׁאֲלוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל בַּ⁠יהוָ֖ה לֵ⁠אמֹ֑ר מִ֣י יַעֲלֶה־לָּ֧⁠נוּ אֶל־הַֽ⁠כְּנַעֲנִ֛י בַּ⁠תְּחִלָּ֖ה לְ⁠הִלָּ֥חֶם בּֽ⁠וֹ׃","wa⁠yĕhi֗y ʼaẖàréy֙ m֣wòţ yĕhwòşǔ֔ʻa waֽ⁠yi̇şĕ̌ʼàlẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l bȧ⁠yhwá֖h lé⁠ʼmò֑r mi֣y yaʻàleh-lá֧̇⁠nẇ ʼel-haֽ⁠kĕ̇naʻàni֛y bȧ⁠ţĕ̇ẖilá֖̇h lĕ⁠hilá֥̇ẖem ḃֽ⁠wò׃"],[1,2,"וַ⁠יֹּ֣אמֶר יְהוָ֖ה יְהוּדָ֣ה יַעֲלֶ֑ה הִנֵּ֛ה נָתַ֥תִּי אֶת־הָ⁠אָ֖רֶץ בְּ⁠יָדֽ⁠וֹ׃","wa⁠yò֣̇ʼmer yĕhwá֖h yĕhẇdá֣h yaʻàle֑h hiné֛̇h náţa֥ţi̇y ʼeţ-há⁠ʼá֖reẕ bĕ̇⁠yádֽ⁠wò׃"],[1,3,"וַ⁠יֹּ֣אמֶר יְהוּדָה֩ לְ⁠שִׁמְע֨וֹן אָחִ֜י⁠ו עֲלֵ֧ה אִתִּ֣⁠י בְ⁠גוֹרָלִ֗⁠י וְ⁠נִֽלָּחֲמָה֙ בַּֽ⁠כְּנַעֲנִ֔י וְ⁠הָלַכְתִּ֧י גַם־אֲנִ֛י אִתְּ⁠ךָ֖ בְּ⁠גוֹרָלֶ֑⁠ךָ וַ⁠יֵּ֥לֶךְ אִתּ֖⁠וֹ שִׁמְעֽוֹן׃","wa⁠yò֣̇ʼmer yĕhẇdáh֩ lĕ⁠şǐmĕʻ֨wòn ʼáẖi֜y⁠w ʻàlé֧h ʼiţi֣̇⁠y bĕ⁠gwòráli֗⁠y wĕ⁠niֽlá̇ẖàmáh֙ bȧֽ⁠kĕ̇naʻàni֔y wĕ⁠hálakĕţi֧̇y gam-ʼàni֛y ʼiţĕ̇⁠ká֖ bĕ̇⁠gwòrále֑⁠ká wa⁠yé֥̇lekĕ ʼiţ֖̇⁠wò şǐmĕʻֽwòn׃"],[1,4,"וַ⁠יַּ֣עַל יְהוּדָ֔ה וַ⁠יִּתֵּ֧ן יְהוָ֛ה אֶת־הַ⁠כְּנַעֲנִ֥י וְ⁠הַ⁠פְּרִזִּ֖י בְּ⁠יָדָ֑⁠ם וַ⁠יַּכּ֣וּ⁠ם בְּ⁠בֶ֔זֶק עֲשֶׂ֥רֶת אֲלָפִ֖ים אִֽישׁ׃","wa⁠yȧ֣ʻal yĕhẇdá֔h wa⁠yi̇ţé֧̇n yĕhwá֛h ʼeţ-ha⁠kĕ̇naʻàni֥y wĕ⁠ha⁠pĕ̇rizi֖̇y bĕ̇⁠yádá֑⁠m wa⁠yȧk֣̇ẇ⁠m bĕ̇⁠be֔zeq ʻàşê֥reţ ʼàlápi֖ym ʼiֽyş̌׃"],[1,5,"וַֽ֠⁠יִּמְצְאוּ אֶת־אֲדֹנִ֥י בֶ֨זֶק֙ בְּ⁠בֶ֔זֶק וַ⁠יִּֽלָּחֲמ֖וּ בּ֑⁠וֹ וַ⁠יַּכּ֕וּ אֶת־הַֽ⁠כְּנַעֲנִ֖י וְ⁠אֶת־הַ⁠פְּרִזִּֽי׃","waֽ֠⁠yi̇mĕẕĕʼẇ ʼeţ-ʼàdòni֥y be֨zeq֙ bĕ̇⁠be֔zeq wa⁠yiֽ̇lá̇ẖàm֖ẇ ḃ֑⁠wò wa⁠yȧk̇֕ẇ ʼeţ-haֽ⁠kĕ̇naʻàni֖y wĕ⁠ʼeţ-ha⁠pĕ̇riziֽ̇y׃"],[1,6,"וַ⁠יָּ֨נָס֙ אֲדֹ֣נִי בֶ֔זֶק וַֽ⁠יִּרְדְּפ֖וּ אַחֲרָ֑י⁠ו וַ⁠יֹּאחֲז֣וּ אֹת֔⁠וֹ וַֽ⁠יְקַצְּצ֔וּ אֶת־בְּהֹנ֥וֹת יָדָ֖י⁠ו וְ⁠רַגְלָֽי⁠ו׃","wa⁠yá̇֨nás֙ ʼàdò֣niy be֔zeq waֽ⁠yi̇rĕdĕ̇p֖ẇ ʼaẖàrá֑y⁠w wa⁠yò̇ʼẖàz֣ẇ ʼòţ֔⁠wò waֽ⁠yĕqaẕĕ̇ẕ֔ẇ ʼeţ-bĕ̇hòn֥wòţ yádá֖y⁠w wĕ⁠ragĕláֽy⁠w׃"],[1,7,"וַ⁠יֹּ֣אמֶר אֲדֹֽנִי־בֶ֗זֶק שִׁבְעִ֣ים ׀ מְלָכִ֡ים בְּֽהֹנוֹת֩ יְדֵי⁠הֶ֨ם וְ⁠רַגְלֵי⁠הֶ֜ם מְקֻצָּצִ֗ים הָי֤וּ מְלַקְּטִים֙ תַּ֣חַת שֻׁלְחָנִ֔⁠י כַּ⁠אֲשֶׁ֣ר עָשִׂ֔יתִי כֵּ֥ן שִׁלַּם־לִ֖⁠י אֱלֹהִ֑ים וַ⁠יְבִיאֻ֥⁠הוּ יְרוּשָׁלִַ֖ם וַ⁠יָּ֥מָת שָֽׁם׃פ","wa⁠yò֣̇ʼmer ʼàdòֽniy-be֗zeq şǐbĕʻi֣ym ׀ mĕláki֡ym bĕֽ̇hònwòţ֩ yĕdéy⁠he֨m wĕ⁠ragĕléy⁠he֜m mĕquẕá̇ẕi֗ym háy֤ẇ mĕlaqĕ̇tiym֙ ţȧ֣ẖaţ şǔlĕẖáni֔⁠y kȧ⁠ʼàşě֣r ʻáşî֔yţiy ké֥̇n şǐlȧm-li֖⁠y ʼèlòhi֑ym wa⁠yĕbiyʼu֥⁠hẇ yĕrẇşá̌lia֖m wa⁠yá֥̇máţ şáֽ̌m׃p"],[1,8,"וַ⁠יִּלָּחֲמ֤וּ בְנֵֽי־יְהוּדָה֙ בִּ⁠יר֣וּשָׁלִַ֔ם וַ⁠יִּלְכְּד֣וּ אוֹתָ֔⁠הּ וַ⁠יַּכּ֖וּ⁠הָ לְ⁠פִי־חָ֑רֶב וְ⁠אֶת־הָ⁠עִ֖יר שִׁלְּח֥וּ בָ⁠אֵֽשׁ׃","wa⁠yi̇lá̇ẖàm֤ẇ bĕnéֽy-yĕhẇdáh֙ bi̇⁠yr֣ẇşá̌lia֔m wa⁠yi̇lĕkĕ̇d֣ẇ ʼwòţá֔⁠ḣ wa⁠yȧk֖̇ẇ⁠há lĕ⁠piy-ẖá֑reb wĕ⁠ʼeţ-há⁠ʻi֖yr şǐlĕ̇ẖ֥ẇ bá⁠ʼéֽş̌׃"],[1,9,"וְ⁠אַחַ֗ר יָֽרְדוּ֙ בְּנֵ֣י יְהוּדָ֔ה לְ⁠הִלָּחֵ֖ם בַּֽ⁠כְּנַעֲנִ֑י יוֹשֵׁ֣ב הָ⁠הָ֔ר וְ⁠הַ⁠נֶּ֖גֶב וְ⁠הַ⁠שְּׁפֵלָֽה׃","wĕ⁠ʼaẖa֗r yáֽrĕdẇ֙ bĕ̇né֣y yĕhẇdá֔h lĕ⁠hilá̇ẖé֖m bȧֽ⁠kĕ̇naʻàni֑y ywòşé֣̌b há⁠há֔r wĕ⁠ha⁠nė֖geb wĕ⁠ha⁠şĕ̇̌péláֽh׃"],[1,10,"וַ⁠יֵּ֣לֶךְ יְהוּדָ֗ה אֶל־הַֽ⁠כְּנַעֲנִי֙ הַ⁠יּוֹשֵׁ֣ב בְּ⁠חֶבְר֔וֹן וְ⁠שֵׁם־חֶבְר֥וֹן לְ⁠פָנִ֖ים קִרְיַ֣ת אַרְבַּ֑ע וַ⁠יַּכּ֛וּ אֶת־שֵׁשַׁ֥י וְ⁠אֶת־אֲחִימַ֖ן וְ⁠אֶת־תַּלְמָֽי׃","wa⁠yé֣̇lekĕ yĕhẇdá֗h ʼel-haֽ⁠kĕ̇naʻàniy֙ ha⁠ẏwòşé֣̌b bĕ̇⁠ẖebĕr֔wòn wĕ⁠şé̌m-ẖebĕr֥wòn lĕ⁠páni֖ym qirĕya֣ţ ʼarĕbȧ֑ʻ wa⁠yȧk֛̇ẇ ʼeţ-şé̌şǎ֥y wĕ⁠ʼeţ-ʼàẖiyma֖n wĕ⁠ʼeţ-ţȧlĕmáֽy׃"],[1,11,"וַ⁠יֵּ֣לֶךְ מִ⁠שָּׁ֔ם אֶל־יוֹשְׁבֵ֖י דְּבִ֑יר וְ⁠שֵׁם־דְּבִ֥יר לְ⁠פָנִ֖ים קִרְיַת־סֵֽפֶר׃","wa⁠yé֣̇lekĕ mi⁠şá̇̌֔m ʼel-ywòşĕ̌bé֖y dĕ̇bi֑yr wĕ⁠şé̌m-dĕ̇bi֥yr lĕ⁠páni֖ym qirĕyaţ-séֽper׃"],[1,12,"וַ⁠יֹּ֣אמֶר כָּלֵ֔ב אֲשֶׁר־יַכֶּ֥ה אֶת־קִרְיַת־סֵ֖פֶר וּ⁠לְכָדָ֑⁠הּ וְ⁠נָתַ֥תִּי ל֛⁠וֹ אֶת־עַכְסָ֥ה בִתִּ֖⁠י לְ⁠אִשָּֽׁה׃","wa⁠yò֣̇ʼmer ká̇lé֔b ʼàşěr-yakė֥h ʼeţ-qirĕyaţ-sé֖per ẇ⁠lĕkádá֑⁠ḣ wĕ⁠náţa֥ţi̇y l֛⁠wò ʼeţ-ʻakĕsá֥h biţi֖̇⁠y lĕ⁠ʼişáֽ̇̌h׃"],[1,13,"וַֽ⁠יִּלְכְּדָ⁠הּ֙ עָתְנִיאֵ֣ל בֶּן־קְנַ֔ז אֲחִ֥י כָלֵ֖ב הַ⁠קָּטֹ֣ן מִמֶּ֑⁠נּוּ וַ⁠יִּתֶּן־ל֛⁠וֹ אֶת־עַכְסָ֥ה בִתּ֖⁠וֹ לְ⁠אִשָּֽׁה׃","waֽ⁠yi̇lĕkĕ̇dá⁠ḣ֙ ʻáţĕniyʼé֣l bėn-qĕna֔z ʼàẖi֥y kálé֖b ha⁠qá̇tò֣n mimė֑⁠ṅẇ wa⁠yi̇ţėn-l֛⁠wò ʼeţ-ʻakĕsá֥h biţ֖̇⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[1,14,"וַ⁠יְהִ֣י בְּ⁠בוֹאָ֗⁠הּ וַ⁠תְּסִיתֵ֨⁠הוּ֙ לִ⁠שְׁא֤וֹל מֵֽ⁠אֵת־אָבִ֨י⁠הָ֙ הַ⁠שָּׂדֶ֔ה וַ⁠תִּצְנַ֖ח מֵ⁠עַ֣ל הַ⁠חֲמ֑וֹר וַ⁠יֹּֽאמֶר־לָ֥⁠הּ כָּלֵ֖ב מַה־לָּֽ⁠ךְ׃","wa⁠yĕhi֣y bĕ̇⁠bwòʼá֗⁠ḣ wa⁠ţĕ̇siyţé֨⁠hẇ֙ li⁠şĕ̌ʼ֤wòl méֽ⁠ʼéţ-ʼábi֨y⁠há֙ ha⁠şá̇̂de֔h wa⁠ţi̇ẕĕna֖ẖ mé⁠ʻa֣l ha⁠ẖàm֑wòr wa⁠yòֽ̇ʼmer-lá֥⁠ḣ ká̇lé֖b mah-láֽ̇⁠kĕ׃"],[1,15,"וַ⁠תֹּ֨אמֶר ל֜⁠וֹ הָֽבָ⁠ה־לִּ֣⁠י בְרָכָ֗ה כִּ֣י אֶ֤רֶץ הַ⁠נֶּ֨גֶב֙ נְתַתָּ֔⁠נִי וְ⁠נָתַתָּ֥ה לִ֖⁠י גֻּלֹּ֣ת מָ֑יִם וַ⁠יִּתֶּן־לָ֣⁠הּ כָּלֵ֗ב אֵ֚ת גֻּלֹּ֣ת עִלִּ֔ית וְ⁠אֵ֖ת גֻּלֹּ֥ת תַּחְתִּֽית׃פ","wa⁠ţò̇֨ʼmer l֜⁠wò háֽbá⁠h-li֣̇⁠y bĕráká֗h ki֣̇y ʼe֤reẕ ha⁠nė֨geb֙ nĕţaţá̇֔⁠niy wĕ⁠náţaţá֥̇h li֖⁠y gu̇lò֣̇ţ má֑yim wa⁠yi̇ţėn-lá֣⁠ḣ ká̇lé֗b ʼé֚ţ gu̇lò֣̇ţ ʻili̇֔yţ wĕ⁠ʼé֖ţ gu̇lò֥̇ţ ţȧẖĕţiֽ̇yţ׃p"],[1,16,"וּ⁠בְנֵ֣י קֵינִי֩ חֹתֵ֨ן מֹשֶׁ֜ה עָל֨וּ מֵ⁠עִ֤יר הַ⁠תְּמָרִים֙ אֶת־בְּנֵ֣י יְהוּדָ֔ה מִדְבַּ֣ר יְהוּדָ֔ה אֲשֶׁ֖ר בְּ⁠נֶ֣גֶב עֲרָ֑ד וַ⁠יֵּ֖לֶךְ וַ⁠יֵּ֥שֶׁב אֶת־הָ⁠עָֽם׃","ẇ⁠bĕné֣y qéyniy֩ ẖòţé֨n mòşě֜h ʻál֨ẇ mé⁠ʻi֤yr ha⁠ţĕ̇máriym֙ ʼeţ-bĕ̇né֣y yĕhẇdá֔h midĕbȧ֣r yĕhẇdá֔h ʼàşě֖r bĕ̇⁠ne֣geb ʻàrá֑d wa⁠yé֖̇lekĕ wa⁠yé֥̇şěb ʼeţ-há⁠ʻáֽm׃"],[1,17,"וַ⁠יֵּ֤לֶךְ יְהוּדָה֙ אֶת־שִׁמְע֣וֹן אָחִ֔י⁠ו וַ⁠יַּכּ֕וּ אֶת־הַֽ⁠כְּנַעֲנִ֖י יוֹשֵׁ֣ב צְפַ֑ת וַ⁠יַּחֲרִ֣ימוּ אוֹתָ֔⁠הּ וַ⁠יִּקְרָ֥א אֶת־שֵׁם־הָ⁠עִ֖יר חָרְמָֽה׃","wa⁠yé֤̇lekĕ yĕhẇdáh֙ ʼeţ-şǐmĕʻ֣wòn ʼáẖi֔y⁠w wa⁠yȧk̇֕ẇ ʼeţ-haֽ⁠kĕ̇naʻàni֖y ywòşé֣̌b ẕĕpa֑ţ wa⁠yȧẖàri֣ymẇ ʼwòţá֔⁠ḣ wa⁠yi̇qĕrá֥ʼ ʼeţ-şé̌m-há⁠ʻi֖yr ẖárĕmáֽh׃"],[1,18,"וַ⁠יִּלְכֹּ֤ד יְהוּדָה֙ אֶת־עַזָּ֣ה וְ⁠אֶת־גְּבוּלָ֔⁠הּ וְ⁠אֶֽת־אַשְׁקְל֖וֹן וְ⁠אֶת־גְּבוּלָ֑⁠הּ וְ⁠אֶת־עֶקְר֖וֹן וְ⁠אֶת־גְּבוּלָֽ⁠הּ׃","wa⁠yi̇lĕkò֤̇d yĕhẇdáh֙ ʼeţ-ʻazá֣̇h wĕ⁠ʼeţ-gĕ̇bẇlá֔⁠ḣ wĕ⁠ʼeֽţ-ʼaşĕ̌qĕl֖wòn wĕ⁠ʼeţ-gĕ̇bẇlá֑⁠ḣ wĕ⁠ʼeţ-ʻeqĕr֖wòn wĕ⁠ʼeţ-gĕ̇bẇláֽ⁠ḣ׃"],[1,19,"וַ⁠יְהִ֤י יְהוָה֙ אֶתּ־יְהוּדָ֔ה וַ⁠יֹּ֖רֶשׁ אֶת־הָ⁠הָ֑ר כִּ֣י לֹ֤א לְ⁠הוֹרִישׁ֙ אֶת־יֹשְׁבֵ֣י הָ⁠עֵ֔מֶק כִּי־רֶ֥כֶב בַּרְזֶ֖ל לָ⁠הֶֽם׃","wa⁠yĕhi֤y yĕhwáh֙ ʼeţ̇-yĕhẇdá֔h wa⁠yò֖̇reş̌ ʼeţ-há⁠há֑r ki֣̇y lò֤ʼ lĕ⁠hwòriyş̌֙ ʼeţ-yòşĕ̌bé֣y há⁠ʻé֔meq ki̇y-re֥keb bȧrĕze֖l lá⁠heֽm׃"],[1,20,"וַ⁠יִּתְּנ֤וּ לְ⁠כָלֵב֙ אֶת־חֶבְר֔וֹן כַּֽ⁠אֲשֶׁ֖ר דִּבֶּ֣ר מֹשֶׁ֑ה וַ⁠יּ֣וֹרֶשׁ מִ⁠שָּׁ֔ם אֶת־שְׁלֹשָׁ֖ה בְּנֵ֥י הָ⁠עֲנָֽק׃","wa⁠yi̇ţĕ̇n֤ẇ lĕ⁠káléb֙ ʼeţ-ẖebĕr֔wòn kֽ̇a⁠ʼàşě֖r di̇bė֣r mòşě֑h wa⁠ẏ֣wòreş̌ mi⁠şá̇̌֔m ʼeţ-şĕ̌lòşá֖̌h bĕ̇né֥y há⁠ʻànáֽq׃"],[1,21,"וְ⁠אֶת־הַ⁠יְבוּסִי֙ יֹשֵׁ֣ב יְרֽוּשָׁלִַ֔ם לֹ֥א הוֹרִ֖ישׁוּ בְּנֵ֣י בִנְיָמִ֑ן וַ⁠יֵּ֨שֶׁב הַ⁠יְבוּסִ֜י אֶת־בְּנֵ֤י בִנְיָמִן֙ בִּ⁠יר֣וּשָׁלִַ֔ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","wĕ⁠ʼeţ-ha⁠yĕbẇsiy֙ yòşé֣̌b yĕrֽẇşá̌lia֔m lò֥ʼ hwòri֖yş̌ẇ bĕ̇né֣y binĕyámi֑n wa⁠yé̇֨şěb ha⁠yĕbẇsi֜y ʼeţ-bĕ̇né֤y binĕyámin֙ bi̇⁠yr֣ẇşá̌lia֔m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃s"],[1,22,"וַ⁠יַּעֲל֧וּ בֵית־יוֹסֵ֛ף גַּם־הֵ֖ם בֵּֽית־אֵ֑ל וַֽ⁠יהוָ֖ה עִמָּֽ⁠ם׃","wa⁠yȧʻàl֧ẇ béyţ-ywòsé֛p gȧm-hé֖m béֽ̇yţ-ʼé֑l waֽ⁠yhwá֖h ʻimáֽ̇⁠m׃"],[1,23,"וַ⁠יָּתִ֥ירוּ בֵית־יוֹסֵ֖ף בְּ⁠בֵֽית־אֵ֑ל וְ⁠שֵׁם־הָ⁠עִ֥יר לְ⁠פָנִ֖ים לֽוּז׃","wa⁠yá̇ţi֥yrẇ béyţ-ywòsé֖p bĕ̇⁠béֽyţ-ʼé֑l wĕ⁠şé̌m-há⁠ʻi֥yr lĕ⁠páni֖ym lֽẇz׃"],[1,24,"וַ⁠יִּרְאוּ֙ הַ⁠שֹּׁ֣מְרִ֔ים אִ֖ישׁ יוֹצֵ֣א מִן־הָ⁠עִ֑יר וַ⁠יֹּ֣אמְרוּ ל֗⁠וֹ הַרְאֵ֤⁠נוּ נָא֙ אֶת־מְב֣וֹא הָ⁠עִ֔יר וְ⁠עָשִׂ֥ינוּ עִמְּ⁠ךָ֖ חָֽסֶד׃","wa⁠yi̇rĕʼẇ֙ ha⁠şò֣̇̌mĕri֔ym ʼi֖yş̌ ywòẕé֣ʼ min-há⁠ʻi֑yr wa⁠yò֣̇ʼmĕrẇ l֗⁠wò harĕʼé֤⁠nẇ náʼ֙ ʼeţ-mĕb֣wòʼ há⁠ʻi֔yr wĕ⁠ʻáşî֥ynẇ ʻimĕ̇⁠ká֖ ẖáֽsed׃"],[1,25,"וַ⁠יַּרְאֵ⁠ם֙ אֶת־מְב֣וֹא הָ⁠עִ֔יר וַ⁠יַּכּ֥וּ אֶת־הָ⁠עִ֖יר לְ⁠פִי־חָ֑רֶב וְ⁠אֶת־הָ⁠אִ֥ישׁ וְ⁠אֶת־כָּל־מִשְׁפַּחְתּ֖⁠וֹ שִׁלֵּֽחוּ׃","wa⁠yȧrĕʼé⁠m֙ ʼeţ-mĕb֣wòʼ há⁠ʻi֔yr wa⁠yȧk֥̇ẇ ʼeţ-há⁠ʻi֖yr lĕ⁠piy-ẖá֑reb wĕ⁠ʼeţ-há⁠ʼi֥yş̌ wĕ⁠ʼeţ-ká̇l-mişĕ̌pȧẖĕţ֖̇⁠wò şǐléֽ̇ẖẇ׃"],[1,26,"וַ⁠יֵּ֣לֶךְ הָ⁠אִ֔ישׁ אֶ֖רֶץ הַ⁠חִתִּ֑ים וַ⁠יִּ֣בֶן עִ֗יר וַ⁠יִּקְרָ֤א שְׁמָ⁠הּ֙ ל֔וּז ה֣וּא שְׁמָ֔⁠הּ עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wa⁠yé֣̇lekĕ há⁠ʼi֔yş̌ ʼe֖reẕ ha⁠ẖiţi֑̇ym wa⁠yi֣̇ben ʻi֗yr wa⁠yi̇qĕrá֤ʼ şĕ̌má⁠ḣ֙ l֔ẇz h֣ẇʼ şĕ̌má֔⁠ḣ ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[1,27,"וְ⁠לֹא־הוֹרִ֣ישׁ מְנַשֶּׁ֗ה אֶת־בֵּית־שְׁאָ֣ן וְ⁠אֶת־בְּנוֹתֶי⁠הָ֮ וְ⁠אֶת־תַּעְנַ֣ךְ וְ⁠אֶת־בְּנֹתֶי⁠הָ֒ וְ⁠אֶת־ישב ד֜וֹר וְ⁠אֶת־בְּנוֹתֶ֗י⁠הָ וְ⁠אֶת־יוֹשְׁבֵ֤י יִבְלְעָם֙ וְ⁠אֶת־בְּנֹתֶ֔י⁠הָ וְ⁠אֶת־יוֹשְׁבֵ֥י מְגִדּ֖וֹ וְ⁠אֶת־בְּנוֹתֶ֑י⁠הָ וַ⁠יּ֨וֹאֶל֙ הַֽ⁠כְּנַעֲנִ֔י לָ⁠שֶׁ֖בֶת בָּ⁠אָ֥רֶץ הַ⁠זֹּֽאת׃","wĕ⁠lòʼ-hwòri֣yş̌ mĕnaşė̌֗h ʼeţ-bé̇yţ-şĕ̌ʼá֣n wĕ⁠ʼeţ-bĕ̇nwòţey⁠há֮ wĕ⁠ʼeţ-ţȧʻĕna֣kĕ wĕ⁠ʼeţ-bĕ̇nòţey⁠há֒ wĕ⁠ʼeţ-yşb d֜wòr wĕ⁠ʼeţ-bĕ̇nwòţe֗y⁠há wĕ⁠ʼeţ-ywòşĕ̌bé֤y yibĕlĕʻám֙ wĕ⁠ʼeţ-bĕ̇nòţe֔y⁠há wĕ⁠ʼeţ-ywòşĕ̌bé֥y mĕgiḋ֖wò wĕ⁠ʼeţ-bĕ̇nwòţe֑y⁠há wa⁠ẏ֨wòʼel֙ haֽ⁠kĕ̇naʻàni֔y lá⁠şě֖beţ bá̇⁠ʼá֥reẕ ha⁠zòֽ̇ʼţ׃"],[1,28,"וַֽ⁠יְהִי֙ כִּֽי־חָזַ֣ק יִשְׂרָאֵ֔ל וַ⁠יָּ֥שֶׂם אֶת־הַֽ⁠כְּנַעֲנִ֖י לָ⁠מַ֑ס וְ⁠הוֹרֵ֖ישׁ לֹ֥א הוֹרִישֽׁ⁠וֹ׃ס","wֽa⁠yĕhiy֙ kiֽ̇y-ẖáza֣q yişĕ̂ráʼé֔l wa⁠yá֥̇şêm ʼeţ-haֽ⁠kĕ̇naʻàni֖y lá⁠ma֑s wĕ⁠hwòré֖yş̌ lò֥ʼ hwòriyşֽ̌⁠wò׃s"],[1,29,"וְ⁠אֶפְרַ֨יִם֙ לֹ֣א הוֹרִ֔ישׁ אֶת־הַֽ⁠כְּנַעֲנִ֖י הַ⁠יּוֹשֵׁ֣ב בְּ⁠גָ֑זֶר וַ⁠יֵּ֧שֶׁב הַֽ⁠כְּנַעֲנִ֛י בְּ⁠קִרְבּ֖⁠וֹ בְּ⁠גָֽזֶר׃פ","wĕ⁠ʼepĕra֨yim֙ lò֣ʼ hwòri֔yş̌ ʼeţ-haֽ⁠kĕ̇naʻàni֖y ha⁠ẏwòşé֣̌b bĕ̇⁠gá֑zer wa⁠yé֧̇şěb haֽ⁠kĕ̇naʻàni֛y bĕ̇⁠qirĕḃ֖⁠wò bĕ̇⁠gáֽzer׃p"],[1,30,"זְבוּלֻ֗ן לֹ֤א הוֹרִישׁ֙ אֶת־יוֹשְׁבֵ֣י קִטְר֔וֹן וְ⁠אֶת־יוֹשְׁבֵ֖י נַהֲלֹ֑ל וַ⁠יֵּ֤שֶׁב הַֽ⁠כְּנַעֲנִי֙ בְּ⁠קִרְבּ֔⁠וֹ וַ⁠יִּֽהְי֖וּ לָ⁠מַֽס׃ס","zĕbẇlu֗n lò֤ʼ hwòriyş̌֙ ʼeţ-ywòşĕ̌bé֣y qitĕr֔wòn wĕ⁠ʼeţ-ywòşĕ̌bé֖y nahàlò֑l wa⁠yé֤̇şěb haֽ⁠kĕ̇naʻàniy֙ bĕ̇⁠qirĕḃ֔⁠wò wa⁠yiֽ̇hĕy֖ẇ lá⁠maֽs׃s"],[1,31,"אָשֵׁ֗ר לֹ֤א הוֹרִישׁ֙ אֶת־יֹשְׁבֵ֣י עַכּ֔וֹ וְ⁠אֶת־יוֹשְׁבֵ֖י צִיד֑וֹן וְ⁠אֶת־אַחְלָ֤ב וְ⁠אֶת־אַכְזִיב֙ וְ⁠אֶת־חֶלְבָּ֔ה וְ⁠אֶת־אֲפִ֖יק וְ⁠אֶת־רְחֹֽב׃","ʼáşé̌֗r lò֤ʼ hwòriyş̌֙ ʼeţ-yòşĕ̌bé֣y ʻak̇֔wò wĕ⁠ʼeţ-ywòşĕ̌bé֖y ẕiyd֑wòn wĕ⁠ʼeţ-ʼaẖĕlá֤b wĕ⁠ʼeţ-ʼakĕziyb֙ wĕ⁠ʼeţ-ẖelĕbá̇֔h wĕ⁠ʼeţ-ʼàpi֖yq wĕ⁠ʼeţ-rĕẖòֽb׃"],[1,32,"וַ⁠יֵּ֨שֶׁב֙ הָ⁠אָ֣שֵׁרִ֔י בְּ⁠קֶ֥רֶב הַֽ⁠כְּנַעֲנִ֖י יֹשְׁבֵ֣י הָ⁠אָ֑רֶץ כִּ֖י לֹ֥א הוֹרִישֽׁ⁠וֹ׃ס","wa⁠yé̇֨şěb֙ há⁠ʼá֣şé̌ri֔y bĕ̇⁠qe֥reb haֽ⁠kĕ̇naʻàni֖y yòşĕ̌bé֣y há⁠ʼá֑reẕ ki֖̇y lò֥ʼ hwòriyşֽ̌⁠wò׃s"],[1,33,"נַפְתָּלִ֗י לֹֽא־הוֹרִ֞ישׁ אֶת־יֹשְׁבֵ֤י בֵֽית־שֶׁ֨מֶשׁ֙ וְ⁠אֶת־יֹשְׁבֵ֣י בֵית־עֲנָ֔ת וַ⁠יֵּ֕שֶׁב בְּ⁠קֶ֥רֶב הַֽ⁠כְּנַעֲנִ֖י יֹשְׁבֵ֣י הָ⁠אָ֑רֶץ וְ⁠יֹשְׁבֵ֤י בֵֽית־שֶׁ֨מֶשׁ֙ וּ⁠בֵ֣ית עֲנָ֔ת הָי֥וּ לָ⁠הֶ֖ם לָ⁠מַֽס׃ס","napĕţá̇li֗y lòֽʼ-hwòri֞yş̌ ʼeţ-yòşĕ̌bé֤y béֽyţ-şě֨meş̌֙ wĕ⁠ʼeţ-yòşĕ̌bé֣y béyţ-ʻàná֔ţ wa⁠yé̇֕şěb bĕ̇⁠qe֥reb haֽ⁠kĕ̇naʻàni֖y yòşĕ̌bé֣y há⁠ʼá֑reẕ wĕ⁠yòşĕ̌bé֤y béֽyţ-şě֨meş̌֙ ẇ⁠bé֣yţ ʻàná֔ţ háy֥ẇ lá⁠he֖m lá⁠maֽs׃s"],[1,34,"וַ⁠יִּלְחֲצ֧וּ הָ⁠אֱמֹרִ֛י אֶת־בְּנֵי־דָ֖ן הָ⁠הָ֑רָ⁠ה כִּי־לֹ֥א נְתָנ֖⁠וֹ לָ⁠רֶ֥דֶת לָ⁠עֵֽמֶק׃","wa⁠yi̇lĕẖàẕ֧ẇ há⁠ʼèmòri֛y ʼeţ-bĕ̇néy-dá֖n há⁠há֑rá⁠h ki̇y-lò֥ʼ nĕţán֖⁠wò lá⁠re֥deţ lá⁠ʻéֽmeq׃"],[1,35,"וַ⁠יּ֤וֹאֶל הָֽ⁠אֱמֹרִי֙ לָ⁠שֶׁ֣בֶת בְּ⁠הַר־חֶ֔רֶס בְּ⁠אַיָּל֖וֹן וּ⁠בְ⁠שַֽׁעַלְבִ֑ים וַ⁠תִּכְבַּד֙ יַ֣ד בֵּית־יוֹסֵ֔ף וַ⁠יִּהְי֖וּ לָ⁠מַֽס׃","wa⁠ẏ֤wòʼel háֽ⁠ʼèmòriy֙ lá⁠şě֣beţ bĕ̇⁠har-ẖe֔res bĕ̇⁠ʼayá̇l֖wòn ẇ⁠bĕ⁠şǎֽʻalĕbi֑ym wa⁠ţi̇kĕbȧd֙ ya֣d bé̇yţ-ywòsé֔p wa⁠yi̇hĕy֖ẇ lá⁠maֽs׃"],[1,36,"וּ⁠גְבוּל֙ הָ⁠אֱמֹרִ֔י מִֽ⁠מַּעֲלֵ֖ה עַקְרַבִּ֑ים מֵ⁠הַ⁠סֶּ֖לַע וָ⁠מָֽעְלָ⁠ה׃פ","ẇ⁠gĕbẇl֙ há⁠ʼèmòri֔y miֽ⁠mȧʻàlé֖h ʻaqĕrabi֑̇ym mé⁠ha⁠sė֖laʻ wá⁠máֽʻĕlá⁠h׃p"],[2,1,"וַ⁠יַּ֧עַל מַלְאַךְ־יְהוָ֛ה מִן־הַ⁠גִּלְגָּ֖ל אֶל־הַ⁠בֹּכִ֑ים פ וַ⁠יֹּאמֶר֩ אַעֲלֶ֨ה אֶתְ⁠כֶ֜ם מִ⁠מִּצְרַ֗יִם וָ⁠אָבִ֤יא אֶתְ⁠כֶם֙ אֶל־הָ⁠אָ֗רֶץ אֲשֶׁ֤ר נִשְׁבַּ֨עְתִּי֙ לַ⁠אֲבֹ֣תֵי⁠כֶ֔ם וָ⁠אֹמַ֕ר לֹֽא־אָפֵ֧ר בְּרִיתִ֛⁠י אִתְּ⁠כֶ֖ם לְ⁠עוֹלָֽם׃","wa⁠yȧ֧ʻal malĕʼakĕ-yĕhwá֛h min-ha⁠gi̇lĕgá֖̇l ʼel-ha⁠bò̇ki֑ym p wa⁠yò̇ʼmer֩ ʼaʻàle֨h ʼeţĕ⁠ke֜m mi⁠mi̇ẕĕra֗yim wá⁠ʼábi֤yʼ ʼeţĕ⁠kem֙ ʼel-há⁠ʼá֗reẕ ʼàşě֤r nişĕ̌bȧ֨ʻĕţi̇y֙ la⁠ʼàbò֣ţéy⁠ke֔m wá⁠ʼòma֕r lòֽʼ-ʼápé֧r bĕ̇riyţi֛⁠y ʼiţĕ̇⁠ke֖m lĕ⁠ʻwòláֽm׃"],[2,2,"וְ⁠אַתֶּ֗ם לֹֽא־תִכְרְת֤וּ בְרִית֙ לְ⁠יֽוֹשְׁבֵי֙ הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את מִזְבְּחוֹתֵי⁠הֶ֖ם תִּתֹּצ֑וּ⁠ן וְ⁠לֹֽא־שְׁמַעְתֶּ֥ם בְּ⁠קֹלִ֖⁠י מַה־זֹּ֥את עֲשִׂיתֶֽם׃","wĕ⁠ʼaţė֗m lòֽʼ-ţikĕrĕţ֤ẇ bĕriyţ֙ lĕ⁠yֽwòşĕ̌béy֙ há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ mizĕbĕ̇ẖwòţéy⁠he֖m ţi̇ţò̇ẕ֑ẇ⁠n wĕ⁠lòֽʼ-şĕ̌maʻĕţė֥m bĕ̇⁠qòli֖⁠y mah-zò֥̇ʼţ ʻàşîyţeֽm׃"],[2,3,"וְ⁠גַ֣ם אָמַ֔רְתִּי לֹֽא־אֲגָרֵ֥שׁ אוֹתָ֖⁠ם מִ⁠פְּנֵי⁠כֶ֑ם וְ⁠הָי֤וּ לָ⁠כֶם֙ לְ⁠צִדִּ֔ים וֵ⁠אלֹ֣הֵי⁠הֶ֔ם יִהְי֥וּ לָ⁠כֶ֖ם לְ⁠מוֹקֵֽשׁ׃","wĕ⁠ga֣m ʼáma֔rĕţi̇y lòֽʼ-ʼàgáré֥ş̌ ʼwòţá֖⁠m mi⁠pĕ̇néy⁠ke֑m wĕ⁠háy֤ẇ lá⁠kem֙ lĕ⁠ẕidi̇֔ym wé⁠ʼlò֣héy⁠he֔m yihĕy֥ẇ lá⁠ke֖m lĕ⁠mwòqéֽş̌׃"],[2,4,"וַ⁠יְהִ֗י כְּ⁠דַבֵּ֞ר מַלְאַ֤ךְ יְהוָה֙ אֶת־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה אֶֽל־כָּל־בְּנֵ֖י יִשְׂרָאֵ֑ל וַ⁠יִּשְׂא֥וּ הָ⁠עָ֛ם אֶת־קוֹלָ֖⁠ם וַ⁠יִּבְכּֽוּ׃","wa⁠yĕhi֗y kĕ̇⁠dabé̇֞r malĕʼa֤kĕ yĕhwáh֙ ʼeţ-ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh ʼeֽl-ká̇l-bĕ̇né֖y yişĕ̂ráʼé֑l wa⁠yi̇şĕ̂ʼ֥ẇ há⁠ʻá֛m ʼeţ-qwòlá֖⁠m wa⁠yi̇bĕkֽ̇ẇ׃"],[2,5,"וַֽ⁠יִּקְרְא֛וּ שֵֽׁם־הַ⁠מָּק֥וֹם הַ⁠ה֖וּא בֹּכִ֑ים וַ⁠יִּזְבְּחוּ־שָׁ֖ם לַֽ⁠יהוָֽה׃פ","waֽ⁠yi̇qĕrĕʼ֛ẇ şéֽ̌m-ha⁠má̇q֥wòm ha⁠h֖ẇʼ bò̇ki֑ym wa⁠yi̇zĕbĕ̇ẖẇ-şá֖̌m laֽ⁠yhwáֽh׃p"],[2,6,"וַ⁠יְשַׁלַּ֥ח יְהוֹשֻׁ֖עַ אֶת־הָ⁠עָ֑ם וַ⁠יֵּלְכ֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל אִ֥ישׁ לְ⁠נַחֲלָת֖⁠וֹ לָ⁠רֶ֥שֶׁת אֶת־הָ⁠אָֽרֶץ׃","wa⁠yĕşǎlȧ֥ẖ yĕhwòşǔ֖ʻa ʼeţ-há⁠ʻá֑m wa⁠yé̇lĕk֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l ʼi֥yş̌ lĕ⁠naẖàláţ֖⁠wò lá⁠re֥şěţ ʼeţ-há⁠ʼáֽreẕ׃"],[2,7,"וַ⁠יַּעַבְד֤וּ הָ⁠עָם֙ אֶת־יְהוָ֔ה כֹּ֖ל יְמֵ֣י יְהוֹשֻׁ֑עַ וְ⁠כֹ֣ל ׀ יְמֵ֣י הַ⁠זְּקֵנִ֗ים אֲשֶׁ֨ר הֶאֱרִ֤יכוּ יָמִים֙ אַחֲרֵ֣י יְהוֹשׁ֔וּעַ אֲשֶׁ֣ר רָא֗וּ אֵ֣ת כָּל־מַעֲשֵׂ֤ה יְהוָה֙ הַ⁠גָּד֔וֹל אֲשֶׁ֥ר עָשָׂ֖ה לְ⁠יִשְׂרָאֵֽל׃","wa⁠yȧʻabĕd֤ẇ há⁠ʻám֙ ʼeţ-yĕhwá֔h kò֖̇l yĕmé֣y yĕhwòşǔ֑ʻa wĕ⁠kò֣l ׀ yĕmé֣y ha⁠zĕ̇qéni֗ym ʼàşě֨r heʼèri֤ykẇ yámiym֙ ʼaẖàré֣y yĕhwòş̌֔ẇʻa ʼàşě֣r ráʼ֗ẇ ʼé֣ţ ká̇l-maʻàşé֤̂h yĕhwáh֙ ha⁠gá̇d֔wòl ʼàşě֥r ʻáşá֖̂h lĕ⁠yişĕ̂ráʼéֽl׃"],[2,8,"וַ⁠יָּ֛מָת יְהוֹשֻׁ֥עַ בִּן־נ֖וּן עֶ֣בֶד יְהוָ֑ה בֶּן־מֵאָ֥ה וָ⁠עֶ֖שֶׂר שָׁנִֽים׃","wa⁠yá֛̇máţ yĕhwòşǔ֥ʻa bi̇n-n֖ẇn ʻe֣bed yĕhwá֑h bėn-méʼá֥h wá⁠ʻe֖şêr şá̌niֽym׃"],[2,9,"וַ⁠יִּקְבְּר֤וּ אוֹת⁠וֹ֙ בִּ⁠גְב֣וּל נַחֲלָת֔⁠וֹ בְּ⁠תִמְנַת־חֶ֖רֶס בְּ⁠הַ֣ר אֶפְרָ֑יִם מִ⁠צְּפ֖וֹן לְ⁠הַר־גָּֽעַשׁ׃","wa⁠yi̇qĕbĕ̇r֤ẇ ʼwòţ⁠wò֙ bi̇⁠gĕb֣ẇl naẖàláţ֔⁠wò bĕ̇⁠ţimĕnaţ-ẖe֖res bĕ̇⁠ha֣r ʼepĕrá֑yim mi⁠ẕĕ̇p֖wòn lĕ⁠har-gáֽ̇ʻaş̌׃"],[2,10,"וְ⁠גַם֙ כָּל־הַ⁠דּ֣וֹר הַ⁠ה֔וּא נֶאֶסְפ֖וּ אֶל־אֲבוֹתָ֑י⁠ו וַ⁠יָּקָם֩ דּ֨וֹר אַחֵ֜ר אַחֲרֵי⁠הֶ֗ם אֲשֶׁ֤ר לֹא־יָֽדְעוּ֙ אֶת־יְהוָ֔ה וְ⁠גַם֙ אֶת־הַֽ⁠מַּעֲשֶׂ֔ה אֲשֶׁ֥ר עָשָׂ֖ה לְ⁠יִשְׂרָאֵֽל׃ס","wĕ⁠gam֙ ká̇l-ha⁠ḋ֣wòr ha⁠h֔ẇʼ neʼesĕp֖ẇ ʼel-ʼàbwòţá֑y⁠w wa⁠yá̇qám֩ ḋ֨wòr ʼaẖé֜r ʼaẖàréy⁠he֗m ʼàşě֤r lòʼ-yáֽdĕʻẇ֙ ʼeţ-yĕhwá֔h wĕ⁠gam֙ ʼeţ-haֽ⁠mȧʻàşê֔h ʼàşě֥r ʻáşá֖̂h lĕ⁠yişĕ̂ráʼéֽl׃s"],[2,11,"וַ⁠יַּעֲשׂ֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל אֶת־הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יַּעַבְד֖וּ אֶת־הַ⁠בְּעָלִֽים׃","wa⁠yȧʻàş֧̂ẇ bĕnéֽy-yişĕ̂ráʼé֛l ʼeţ-há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yȧʻabĕd֖ẇ ʼeţ-ha⁠bĕ̇ʻáliֽym׃"],[2,12,"וַ⁠יַּעַזְב֞וּ אֶת־יְהוָ֣ה ׀ אֱלֹהֵ֣י אֲבוֹתָ֗⁠ם הַ⁠מּוֹצִ֣יא אוֹתָ⁠ם֮ מֵ⁠אֶ֣רֶץ מִצְרַיִם֒ וַ⁠יֵּלְכ֞וּ אַחֲרֵ֣י ׀ אֱלֹהִ֣ים אֲחֵרִ֗ים מֵ⁠אֱלֹהֵ֤י הָֽ⁠עַמִּים֙ אֲשֶׁר֙ סְבִיב֣וֹתֵי⁠הֶ֔ם וַ⁠יִּֽשְׁתַּחֲו֖וּ לָ⁠הֶ֑ם וַ⁠יַּכְעִ֖סוּ אֶת־יְהוָֽה׃","wa⁠yȧʻazĕb֞ẇ ʼeţ-yĕhwá֣h ׀ ʼèlòhé֣y ʼàbwòţá֗⁠m ha⁠ṁwòẕi֣yʼ ʼwòţá⁠m֮ mé⁠ʼe֣reẕ miẕĕrayim֒ wa⁠yé̇lĕk֞ẇ ʼaẖàré֣y ׀ ʼèlòhi֣ym ʼàẖéri֗ym mé⁠ʼèlòhé֤y háֽ⁠ʻami̇ym֙ ʼàşěr֙ sĕbiyb֣wòţéy⁠he֔m wa⁠yiֽ̇şĕ̌ţȧẖàw֖ẇ lá⁠he֑m wa⁠yȧkĕʻi֖sẇ ʼeţ-yĕhwáֽh׃"],[2,13,"וַ⁠יַּעַזְב֖וּ אֶת־יְהוָ֑ה וַ⁠יַּעַבְד֥וּ לַ⁠בַּ֖עַל וְ⁠לָ⁠עַשְׁתָּרֽוֹת׃","wa⁠yȧʻazĕb֖ẇ ʼeţ-yĕhwá֑h wa⁠yȧʻabĕd֥ẇ la⁠bȧ֖ʻal wĕ⁠lá⁠ʻaşĕ̌ţá̇rֽwòţ׃"],[2,14,"וַ⁠יִּֽחַר־אַ֤ף יְהוָה֙ בְּ⁠יִשְׂרָאֵ֔ל וַֽ⁠יִּתְּנֵ⁠ם֙ בְּ⁠יַד־שֹׁסִ֔ים וַ⁠יָּשֹׁ֖סּוּ אוֹתָ֑⁠ם וַֽ⁠יִּמְכְּרֵ֞⁠ם בְּ⁠יַ֤ד אֽוֹיְבֵי⁠הֶם֙ מִ⁠סָּבִ֔יב וְ⁠לֹֽא־יָכְל֣וּ ע֔וֹד לַ⁠עֲמֹ֖ד לִ⁠פְנֵ֥י אוֹיְבֵי⁠הֶֽם׃","wa⁠yiֽ̇ẖar-ʼa֤p yĕhwáh֙ bĕ̇⁠yişĕ̂ráʼé֔l waֽ⁠yi̇ţĕ̇né⁠m֙ bĕ̇⁠yad-şò̌si֔ym wa⁠yá̇şò֖̌ṡẇ ʼwòţá֑⁠m waֽ⁠yi̇mĕkĕ̇ré֞⁠m bĕ̇⁠ya֤d ʼֽwòyĕbéy⁠hem֙ mi⁠sá̇bi֔yb wĕ⁠lòֽʼ-yákĕl֣ẇ ʻ֔wòd la⁠ʻàmò֖d li⁠pĕné֥y ʼwòyĕbéy⁠heֽm׃"],[2,15,"בְּ⁠כֹ֣ל ׀ אֲשֶׁ֣ר יָצְא֗וּ יַד־יְהוָה֙ הָיְתָה־בָּ֣⁠ם לְ⁠רָעָ֔ה כַּֽ⁠אֲשֶׁר֙ דִּבֶּ֣ר יְהוָ֔ה וְ⁠כַ⁠אֲשֶׁ֛ר נִשְׁבַּ֥ע יְהוָ֖ה לָ⁠הֶ֑ם וַ⁠יֵּ֥צֶר לָ⁠הֶ֖ם מְאֹֽד׃","bĕ̇⁠kò֣l ׀ ʼàşě֣r yáẕĕʼ֗ẇ yad-yĕhwáh֙ háyĕţáh-bá֣̇⁠m lĕ⁠ráʻá֔h kȧֽ⁠ʼàşěr֙ di̇bė֣r yĕhwá֔h wĕ⁠ka⁠ʼàşě֛r nişĕ̌bȧ֥ʻ yĕhwá֖h lá⁠he֑m wa⁠yé֥̇ẕer lá⁠he֖m mĕʼòֽd׃"],[2,16,"וַ⁠יָּ֥קֶם יְהוָ֖ה שֹֽׁפְטִ֑ים וַ⁠יּ֣וֹשִׁיע֔וּ⁠ם מִ⁠יַּ֖ד שֹׁסֵי⁠הֶֽם׃","wa⁠yá֥̇qem yĕhwá֖h şòֽ̌pĕti֑ym wa⁠ẏ֣wòşǐyʻ֔ẇ⁠m mi⁠yȧ֖d şò̌séy⁠heֽm׃"],[2,17,"וְ⁠גַ֤ם אֶל־שֹֽׁפְטֵי⁠הֶם֙ לֹ֣א שָׁמֵ֔עוּ כִּ֣י זָנ֗וּ אַֽחֲרֵי֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וַ⁠יִּֽשְׁתַּחֲו֖וּ לָ⁠הֶ֑ם סָ֣רוּ מַהֵ֗ר מִן־הַ⁠דֶּ֜רֶךְ אֲשֶׁ֨ר הָלְכ֧וּ אֲבוֹתָ֛⁠ם לִ⁠שְׁמֹ֥עַ מִצְוֺת־יְהוָ֖ה לֹא־עָ֥שׂוּ כֵֽן׃","wĕ⁠ga֤m ʼel-şòֽ̌pĕtéy⁠hem֙ lò֣ʼ şá̌mé֔ʻẇ ki֣̇y zán֗ẇ ʼֽaẖàréy֙ ʼèlòhi֣ym ʼàẖéri֔ym wa⁠yiֽ̇şĕ̌ţȧẖàw֖ẇ lá⁠he֑m sá֣rẇ mahé֗r min-ha⁠dė֜rekĕ ʼàşě֨r hálĕk֧ẇ ʼàbwòţá֛⁠m li⁠şĕ̌mò֥ʻa miẕĕwֺţ-yĕhwá֖h lòʼ-ʻá֥ş̂ẇ kéֽn׃"],[2,18,"וְ⁠כִֽי־הֵקִ֨ים יְהוָ֥ה ׀ לָ⁠הֶם֮ שֹֽׁפְטִים֒ וְ⁠הָיָ֤ה יְהוָה֙ עִם־הַ⁠שֹּׁפֵ֔ט וְ⁠הֽוֹשִׁיעָ⁠ם֙ מִ⁠יַּ֣ד אֹֽיְבֵי⁠הֶ֔ם כֹּ֖ל יְמֵ֣י הַ⁠שּׁוֹפֵ֑ט כִּֽי־יִנָּחֵ֤ם יְהוָה֙ מִ⁠נַּֽאֲקָתָ֔⁠ם מִ⁠פְּנֵ֥י לֹחֲצֵי⁠הֶ֖ם וְ⁠דֹחֲקֵי⁠הֶֽם׃","wĕ⁠kiֽy-héqi֨ym yĕhwá֥h ׀ lá⁠hem֮ şòֽ̌pĕtiym֒ wĕ⁠háyá֤h yĕhwáh֙ ʻim-ha⁠şò̇̌pé֔t wĕ⁠hֽwòşǐyʻá⁠m֙ mi⁠yȧ֣d ʼòֽyĕbéy⁠he֔m kò֖̇l yĕmé֣y ha⁠ş̇̌wòpé֑t kiֽ̇y-yiná̇ẖé֤m yĕhwáh֙ mi⁠nȧֽʼàqáţá֔⁠m mi⁠pĕ̇né֥y lòẖàẕéy⁠he֖m wĕ⁠dòẖàqéy⁠heֽm׃"],[2,19,"וְ⁠הָיָ֣ה ׀ בְּ⁠מ֣וֹת הַ⁠שּׁוֹפֵ֗ט יָשֻׁ֨בוּ֙ וְ⁠הִשְׁחִ֣יתוּ מֵֽ⁠אֲבוֹתָ֔⁠ם לָ⁠לֶ֗כֶת אַֽחֲרֵי֙ אֱלֹהִ֣ים אֲחֵרִ֔ים לְ⁠עָבְדָ֖⁠ם וּ⁠לְ⁠הִשְׁתַּחֲוֺ֣ת לָ⁠הֶ֑ם לֹ֤א הִפִּ֨ילוּ֙ מִ⁠מַּ֣עַלְלֵי⁠הֶ֔ם וּ⁠מִ⁠דַּרְכָּ֖⁠ם הַ⁠קָּשָֽׁה׃","wĕ⁠háyá֣h ׀ bĕ̇⁠m֣wòţ ha⁠ş̇̌wòpé֗t yáşǔ֨bẇ֙ wĕ⁠hişĕ̌ẖi֣yţẇ méֽ⁠ʼàbwòţá֔⁠m lá⁠le֗keţ ʼaֽẖàréy֙ ʼèlòhi֣ym ʼàẖéri֔ym lĕ⁠ʻábĕdá֖⁠m ẇ⁠lĕ⁠hişĕ̌ţȧẖàwֺ֣ţ lá⁠he֑m lò֤ʼ hipi̇֨ylẇ֙ mi⁠mȧ֣ʻalĕléy⁠he֔m ẇ⁠mi⁠dȧrĕká֖̇⁠m ha⁠qá̇şáֽ̌h׃"],[2,20,"וַ⁠יִּֽחַר־אַ֥ף יְהוָ֖ה בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יֹּ֗אמֶר יַעַן֩ אֲשֶׁ֨ר עָבְר֜וּ הַ⁠גּ֣וֹי הַ⁠זֶּ֗ה אֶת־בְּרִיתִ⁠י֙ אֲשֶׁ֣ר צִוִּ֣יתִי אֶת־אֲבוֹתָ֔⁠ם וְ⁠לֹ֥א שָׁמְע֖וּ לְ⁠קוֹלִֽ⁠י׃","wa⁠yiֽ̇ẖar-ʼa֥p yĕhwá֖h bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yò̇֗ʼmer yaʻan֩ ʼàşě֨r ʻábĕr֜ẇ ha⁠ġ֣wòy ha⁠zė֗h ʼeţ-bĕ̇riyţi⁠y֙ ʼàşě֣r ẕiwi֣̇yţiy ʼeţ-ʼàbwòţá֔⁠m wĕ⁠lò֥ʼ şá̌mĕʻ֖ẇ lĕ⁠qwòliֽ⁠y׃"],[2,21,"גַּם־אֲנִי֙ לֹ֣א אוֹסִ֔יף לְ⁠הוֹרִ֥ישׁ אִ֖ישׁ מִ⁠פְּנֵי⁠הֶ֑ם מִן־הַ⁠גּוֹיִ֛ם אֲשֶׁר־עָזַ֥ב יְהוֹשֻׁ֖עַ וַ⁠יָּמֹֽת׃","gȧm-ʼàniy֙ lò֣ʼ ʼwòsi֔yp lĕ⁠hwòri֥yş̌ ʼi֖yş̌ mi⁠pĕ̇néy⁠he֑m min-ha⁠ġwòyi֛m ʼàşěr-ʻáza֥b yĕhwòşǔ֖ʻa wa⁠yá̇mòֽţ׃"],[2,22,"לְמַ֛עַן נַסּ֥וֹת בָּ֖⁠ם אֶת־יִשְׂרָאֵ֑ל הֲ⁠שֹׁמְרִ֣ים הֵם֩ אֶת־דֶּ֨רֶךְ יְהוָ֜ה לָ⁠לֶ֣כֶת בָּ֗⁠ם כַּ⁠אֲשֶׁ֛ר שָׁמְר֥וּ אֲבוֹתָ֖⁠ם אִם־לֹֽא׃","lĕma֛ʻan naṡ֥wòţ bá֖̇⁠m ʼeţ-yişĕ̂ráʼé֑l hà⁠şò̌mĕri֣ym hém֩ ʼeţ-dė֨rekĕ yĕhwá֜h lá⁠le֣keţ bá̇֗⁠m kȧ⁠ʼàşě֛r şá̌mĕr֥ẇ ʼàbwòţá֖⁠m ʼim-lòֽʼ׃"],[2,23,"וַ⁠יַּנַּ֤ח יְהוָה֙ אֶת־הַ⁠גּוֹיִ֣ם הָ⁠אֵ֔לֶּה לְ⁠בִלְתִּ֥י הוֹרִישָׁ֖⁠ם מַהֵ֑ר וְ⁠לֹ֥א נְתָנָ֖⁠ם בְּ⁠יַד־יְהוֹשֻֽׁעַ׃פ","wa⁠yȧnȧ֤ẖ yĕhwáh֙ ʼeţ-ha⁠ġwòyi֣m há⁠ʼé֔lėh lĕ⁠bilĕţi֥̇y hwòriyşá֖̌⁠m mahé֑r wĕ⁠lò֥ʼ nĕţáná֖⁠m bĕ̇⁠yad-yĕhwòşǔֽʻa׃p"],[3,1,"וְ⁠אֵ֤לֶּה הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר הִנִּ֣יחַ יְהוָ֔ה לְ⁠נַסּ֥וֹת בָּ֖⁠ם אֶת־יִשְׂרָאֵ֑ל אֵ֚ת כָּל־אֲשֶׁ֣ר לֹֽא־יָדְע֔וּ אֵ֖ת כָּל־מִלְחֲמ֥וֹת כְּנָֽעַן׃","wĕ⁠ʼé֤lėh ha⁠ġwòyim֙ ʼàşě֣r hini֣̇yẖa yĕhwá֔h lĕ⁠naṡ֥wòţ bá֖̇⁠m ʼeţ-yişĕ̂ráʼé֑l ʼé֚ţ ká̇l-ʼàşě֣r lòֽʼ-yádĕʻ֔ẇ ʼé֖ţ ká̇l-milĕẖàm֥wòţ kĕ̇náֽʻan׃"],[3,2,"רַ֗ק לְמַ֨עַן֙ דַּ֚עַת דֹּר֣וֹת בְּנֵֽי־יִשְׂרָאֵ֔ל לְ⁠לַמְּדָ֖⁠ם מִלְחָמָ֑ה רַ֥ק אֲשֶׁר־לְ⁠פָנִ֖ים לֹ֥א יְדָעֽוּ⁠ם׃","ra֗q lĕma֨ʻan֙ dȧ֚ʻaţ dò̇r֣wòţ bĕ̇néֽy-yişĕ̂ráʼé֔l lĕ⁠lamĕ̇dá֖⁠m milĕẖámá֑h ra֥q ʼàşěr-lĕ⁠páni֖ym lò֥ʼ yĕdáʻֽẇ⁠m׃"],[3,3,"חֲמֵ֣שֶׁת ׀ סַרְנֵ֣י פְלִשְׁתִּ֗ים וְ⁠כָל־הַֽ⁠כְּנַעֲנִי֙ וְ⁠הַ⁠צִּ֣ידֹנִ֔י וְ⁠הַ֣⁠חִוִּ֔י יֹשֵׁ֖ב הַ֣ר הַ⁠לְּבָנ֑וֹן מֵ⁠הַר֙ בַּ֣עַל חֶרְמ֔וֹן עַ֖ד לְב֥וֹא חֲמָֽת׃","ẖàmé֣şěţ ׀ sarĕné֣y pĕlişĕ̌ţi̇֗ym wĕ⁠kál-haֽ⁠kĕ̇naʻàniy֙ wĕ⁠ha⁠ẕi֣̇ydòni֔y wĕ⁠ha֣⁠ẖiwi̇֔y yòşé֖̌b ha֣r ha⁠lĕ̇bán֑wòn mé⁠har֙ bȧ֣ʻal ẖerĕm֔wòn ʻa֖d lĕb֥wòʼ ẖàmáֽţ׃"],[3,4,"וַֽ⁠יִּהְי֕וּ לְ⁠נַסּ֥וֹת בָּ֖⁠ם אֶת־יִשְׂרָאֵ֑ל לָ⁠דַ֗עַת הֲ⁠יִשְׁמְעוּ֙ אֶת־מִצְוֺ֣ת יְהוָ֔ה אֲשֶׁר־צִוָּ֥ה אֶת־אֲבוֹתָ֖⁠ם בְּ⁠יַד־מֹשֶֽׁה׃","waֽ⁠yi̇hĕy֕ẇ lĕ⁠naṡ֥wòţ bá֖̇⁠m ʼeţ-yişĕ̂ráʼé֑l lá⁠da֗ʻaţ hà⁠yişĕ̌mĕʻẇ֙ ʼeţ-miẕĕwֺ֣ţ yĕhwá֔h ʼàşěr-ẕiwá֥̇h ʼeţ-ʼàbwòţá֖⁠m bĕ̇⁠yad-mòşěֽh׃"],[3,5,"וּ⁠בְנֵ֣י יִשְׂרָאֵ֔ל יָשְׁב֖וּ בְּ⁠קֶ֣רֶב הַֽ⁠כְּנַעֲנִ֑י הַ⁠חִתִּ֤י וְ⁠הָֽ⁠אֱמֹרִי֙ וְ⁠הַ⁠פְּרִזִּ֔י וְ⁠הַ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִֽי׃","ẇ⁠bĕné֣y yişĕ̂ráʼé֔l yáşĕ̌b֖ẇ bĕ̇⁠qe֣reb haֽ⁠kĕ̇naʻàni֑y ha⁠ẖiţi֤̇y wĕ⁠háֽ⁠ʼèmòriy֙ wĕ⁠ha⁠pĕ̇rizi̇֔y wĕ⁠ha⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsiֽy׃"],[3,6,"וַ⁠יִּקְח֨וּ אֶת־בְּנוֹתֵי⁠הֶ֤ם לָ⁠הֶם֙ לְ⁠נָשִׁ֔ים וְ⁠אֶת־בְּנוֹתֵי⁠הֶ֖ם נָתְנ֣וּ לִ⁠בְנֵי⁠הֶ֑ם וַ⁠יַּעַבְד֖וּ אֶת־אֱלֹהֵי⁠הֶֽם׃פ","wa⁠yi̇qĕẖ֨ẇ ʼeţ-bĕ̇nwòţéy⁠he֤m lá⁠hem֙ lĕ⁠náşǐ֔ym wĕ⁠ʼeţ-bĕ̇nwòţéy⁠he֖m náţĕn֣ẇ li⁠bĕnéy⁠he֑m wa⁠yȧʻabĕd֖ẇ ʼeţ-ʼèlòhéy⁠heֽm׃p"],[3,7,"וַ⁠יַּעֲשׂ֨וּ בְנֵי־יִשְׂרָאֵ֤ל אֶת־הָ⁠רַע֙ בְּ⁠עֵינֵ֣י יְהוָ֔ה וַֽ⁠יִּשְׁכְּח֖וּ אֶת־יְהוָ֣ה אֱלֹֽהֵי⁠הֶ֑ם וַ⁠יַּעַבְד֥וּ אֶת־הַ⁠בְּעָלִ֖ים וְ⁠אֶת־הָ⁠אֲשֵׁרֽוֹת׃","wa⁠yȧʻàş̂֨ẇ bĕnéy-yişĕ̂ráʼé֤l ʼeţ-há⁠raʻ֙ bĕ̇⁠ʻéyné֣y yĕhwá֔h waֽ⁠yi̇şĕ̌kĕ̇ẖ֖ẇ ʼeţ-yĕhwá֣h ʼèlòֽhéy⁠he֑m wa⁠yȧʻabĕd֥ẇ ʼeţ-ha⁠bĕ̇ʻáli֖ym wĕ⁠ʼeţ-há⁠ʼàşé̌rֽwòţ׃"],[3,8,"וַ⁠יִּֽחַר־אַ֤ף יְהוָה֙ בְּ⁠יִשְׂרָאֵ֔ל וַֽ⁠יִּמְכְּרֵ֗⁠ם בְּ⁠יַד֙ כּוּשַׁ֣ן רִשְׁעָתַ֔יִם מֶ֖לֶךְ אֲרַ֣ם נַהֲרָ֑יִם וַ⁠יַּעַבְד֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל אֶת־כּוּשַׁ֥ן רִשְׁעָתַ֖יִם שְׁמֹנֶ֥ה שָׁנִֽים׃","wa⁠yiֽ̇ẖar-ʼa֤p yĕhwáh֙ bĕ̇⁠yişĕ̂ráʼé֔l waֽ⁠yi̇mĕkĕ̇ré֗⁠m bĕ̇⁠yad֙ k̇ẇşǎ֣n rişĕ̌ʻáţa֔yim me֖lekĕ ʼàra֣m nahàrá֑yim wa⁠yȧʻabĕd֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l ʼeţ-k̇ẇşǎ֥n rişĕ̌ʻáţa֖yim şĕ̌mòne֥h şá̌niֽym׃"],[3,9,"וַ⁠יִּזְעֲק֤וּ בְנֵֽי־יִשְׂרָאֵל֙ אֶל־יְהוָ֔ה וַ⁠יָּ֨קֶם יְהוָ֥ה מוֹשִׁ֛יעַ לִ⁠בְנֵ֥י יִשְׂרָאֵ֖ל וַ⁠יּֽוֹשִׁיעֵ֑⁠ם אֵ֚ת עָתְנִיאֵ֣ל בֶּן־קְנַ֔ז אֲחִ֥י כָלֵ֖ב הַ⁠קָּטֹ֥ן מִמֶּֽ⁠נּוּ׃","wa⁠yi̇zĕʻàq֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ ʼel-yĕhwá֔h wa⁠yá̇֨qem yĕhwá֥h mwòşǐ֛yʻa li⁠bĕné֥y yişĕ̂ráʼé֖l wa⁠ẏֽwòşǐyʻé֑⁠m ʼé֚ţ ʻáţĕniyʼé֣l bėn-qĕna֔z ʼàẖi֥y kálé֖b ha⁠qá̇tò֥n mimėֽ⁠ṅẇ׃"],[3,10,"וַ⁠תְּהִ֨י עָלָ֥י⁠ו רֽוּחַ־יְהוָה֮ וַ⁠יִּשְׁפֹּ֣ט אֶת־יִשְׂרָאֵל֒ וַ⁠יֵּצֵא֙ לַ⁠מִּלְחָמָ֔ה וַ⁠יִּתֵּ֤ן יְהוָה֙ בְּ⁠יָד֔⁠וֹ אֶת־כּוּשַׁ֥ן רִשְׁעָתַ֖יִם מֶ֣לֶךְ אֲרָ֑ם וַ⁠תָּ֣עָז יָד֔⁠וֹ עַ֖ל כּוּשַׁ֥ן רִשְׁעָתָֽיִם׃","wa⁠ţĕ̇hi֨y ʻálá֥y⁠w rֽẇẖa-yĕhwáh֮ wa⁠yi̇şĕ̌pò֣̇t ʼeţ-yişĕ̂ráʼél֒ wa⁠yé̇ẕéʼ֙ la⁠mi̇lĕẖámá֔h wa⁠yi̇ţé֤̇n yĕhwáh֙ bĕ̇⁠yád֔⁠wò ʼeţ-k̇ẇşǎ֥n rişĕ̌ʻáţa֖yim me֣lekĕ ʼàrá֑m wa⁠ţá֣̇ʻáz yád֔⁠wò ʻa֖l k̇ẇşǎ֥n rişĕ̌ʻáţáֽyim׃"],[3,11,"וַ⁠תִּשְׁקֹ֥ט הָ⁠אָ֖רֶץ אַרְבָּעִ֣ים שָׁנָ֑ה וַ⁠יָּ֖מָת עָתְנִיאֵ֥ל בֶּן־קְנַֽז׃פ","wa⁠ţi̇şĕ̌qò֥t há⁠ʼá֖reẕ ʼarĕbá̇ʻi֣ym şá̌ná֑h wa⁠yá֖̇máţ ʻáţĕniyʼé֥l bėn-qĕnaֽz׃p"],[3,12,"וַ⁠יֹּסִ֨פוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל לַ⁠עֲשׂ֥וֹת הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יְחַזֵּ֨ק יְהוָ֜ה אֶת־עֶגְל֤וֹן מֶֽלֶךְ־מוֹאָב֙ עַל־יִשְׂרָאֵ֔ל עַ֛ל כִּֽי־עָשׂ֥וּ אֶת־הָ⁠רַ֖ע בְּ⁠עֵינֵ֥י יְהוָֽה׃","wa⁠yò̇si֨pẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l la⁠ʻàş֥̂wòţ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yĕẖazé̇֨q yĕhwá֜h ʼeţ-ʻegĕl֤wòn meֽlekĕ-mwòʼáb֙ ʻal-yişĕ̂ráʼé֔l ʻa֛l kiֽ̇y-ʻáş֥̂ẇ ʼeţ-há⁠ra֖ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh׃"],[3,13,"וַ⁠יֶּאֱסֹ֣ף אֵלָ֔י⁠ו אֶת־בְּנֵ֥י עַמּ֖וֹן וַ⁠עֲמָלֵ֑ק וַ⁠יֵּ֗לֶךְ וַ⁠יַּךְ֙ אֶת־יִשְׂרָאֵ֔ל וַ⁠יִּֽירְשׁ֖וּ אֶת־עִ֥יר הַ⁠תְּמָרִֽים׃","wa⁠yėʼèsò֣p ʼélá֔y⁠w ʼeţ-bĕ̇né֥y ʻaṁ֖wòn wa⁠ʻàmálé֑q wa⁠yé̇֗lekĕ wa⁠yȧkĕ֙ ʼeţ-yişĕ̂ráʼé֔l wa⁠yiֽ̇yrĕş֖̌ẇ ʼeţ-ʻi֥yr ha⁠ţĕ̇máriֽym׃"],[3,14,"וַ⁠יַּעַבְד֤וּ בְנֵֽי־יִשְׂרָאֵל֙ אֶת־עֶגְל֣וֹן מֶֽלֶךְ־מוֹאָ֔ב שְׁמוֹנֶ֥ה עֶשְׂרֵ֖ה שָׁנָֽה׃ס","wa⁠yȧʻabĕd֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ ʼeţ-ʻegĕl֣wòn meֽlekĕ-mwòʼá֔b şĕ̌mwòne֥h ʻeşĕ̂ré֖h şá̌náֽh׃s"],[3,15,"וַ⁠יִּזְעֲק֣וּ בְנֵֽי־יִשְׂרָאֵל֮ אֶל־יְהוָה֒ וַ⁠יָּקֶם֩ יְהוָ֨ה לָ⁠הֶ֜ם מוֹשִׁ֗יעַ אֶת־אֵה֤וּד בֶּן־גֵּרָא֙ בֶּן־הַ⁠יְמִינִ֔י אִ֥ישׁ אִטֵּ֖ר יַד־יְמִינ֑⁠וֹ וַ⁠יִּשְׁלְח֨וּ בְנֵי־יִשְׂרָאֵ֤ל בְּ⁠יָד⁠וֹ֙ מִנְחָ֔ה לְ⁠עֶגְל֖וֹן מֶ֥לֶךְ מוֹאָֽב׃","wa⁠yi̇zĕʻàq֣ẇ bĕnéֽy-yişĕ̂ráʼél֮ ʼel-yĕhwáh֒ wa⁠yá̇qem֩ yĕhwá֨h lá⁠he֜m mwòşǐ֗yʻa ʼeţ-ʼéh֤ẇd bėn-gé̇ráʼ֙ bėn-ha⁠yĕmiyni֔y ʼi֥yş̌ ʼité֖̇r yad-yĕmiyn֑⁠wò wa⁠yi̇şĕ̌lĕẖ֨ẇ bĕnéy-yişĕ̂ráʼé֤l bĕ̇⁠yád⁠wò֙ minĕẖá֔h lĕ⁠ʻegĕl֖wòn me֥lekĕ mwòʼáֽb׃"],[3,16,"וַ⁠יַּעַשׂ֩ ל֨⁠וֹ אֵה֜וּד חֶ֗רֶב וְ⁠לָ֛⁠הּ שְׁנֵ֥י פֵי֖וֹת גֹּ֣מֶד אָרְכָּ֑⁠הּ וַ⁠יַּחְגֹּ֤ר אוֹתָ⁠הּ֙ מִ⁠תַּ֣חַת לְ⁠מַדָּ֔י⁠ו עַ֖ל יֶ֥רֶךְ יְמִינֽ⁠וֹ׃","wa⁠yȧʻaş̂֩ l֨⁠wò ʼéh֜ẇd ẖe֗reb wĕ⁠lá֛⁠ḣ şĕ̌né֥y péy֖wòţ gò֣̇med ʼárĕká֑̇⁠ḣ wa⁠yȧẖĕgò֤̇r ʼwòţá⁠ḣ֙ mi⁠ţȧ֣ẖaţ lĕ⁠madá̇֔y⁠w ʻa֖l ye֥rekĕ yĕmiynֽ⁠wò׃"],[3,17,"וַ⁠יַּקְרֵב֙ אֶת־הַ⁠מִּנְחָ֔ה לְ⁠עֶגְל֖וֹן מֶ֣לֶךְ מוֹאָ֑ב וְ⁠עֶגְל֕וֹן אִ֥ישׁ בָּרִ֖יא מְאֹֽד׃","wa⁠yȧqĕréb֙ ʼeţ-ha⁠mi̇nĕẖá֔h lĕ⁠ʻegĕl֖wòn me֣lekĕ mwòʼá֑b wĕ⁠ʻegĕl֕wòn ʼi֥yş̌ bá̇ri֖yʼ mĕʼòֽd׃"],[3,18,"וַֽ⁠יְהִי֙ כַּ⁠אֲשֶׁ֣ר כִּלָּ֔ה לְ⁠הַקְרִ֖יב אֶת־הַ⁠מִּנְחָ֑ה וַ⁠יְשַׁלַּח֙ אֶת־הָ⁠עָ֔ם נֹשְׂאֵ֖י הַ⁠מִּנְחָֽה׃","waֽ⁠yĕhiy֙ kȧ⁠ʼàşě֣r ki̇lá̇֔h lĕ⁠haqĕri֖yb ʼeţ-ha⁠mi̇nĕẖá֑h wa⁠yĕşǎlȧẖ֙ ʼeţ-há⁠ʻá֔m nòşĕ̂ʼé֖y ha⁠mi̇nĕẖáֽh׃"],[3,19,"וְ⁠ה֣וּא שָׁ֗ב מִן־הַ⁠פְּסִילִים֙ אֲשֶׁ֣ר אֶת־הַ⁠גִּלְגָּ֔ל וַ⁠יֹּ֕אמֶר דְּבַר־סֵ֥תֶר לִ֛⁠י אֵלֶ֖י⁠ךָ הַ⁠מֶּ֑לֶךְ וַ⁠יֹּ֣אמֶר הָ֔ס וַ⁠יֵּֽצְאוּ֙ מֵֽ⁠עָלָ֔י⁠ו כָּל־הָ⁠עֹמְדִ֖ים עָלָֽי⁠ו׃","wĕ⁠h֣ẇʼ şá̌֗b min-ha⁠pĕ̇siyliym֙ ʼàşě֣r ʼeţ-ha⁠gi̇lĕgá̇֔l wa⁠yò̇֕ʼmer dĕ̇bar-sé֥ţer li֛⁠y ʼéle֖y⁠ká ha⁠mė֑lekĕ wa⁠yò֣̇ʼmer há֔s wa⁠yéֽ̇ẕĕʼẇ֙ méֽ⁠ʻálá֔y⁠w ká̇l-há⁠ʻòmĕdi֖ym ʻáláֽy⁠w׃"],[3,20,"וְ⁠אֵה֣וּד ׀ בָּ֣א אֵלָ֗י⁠ו וְ⁠הֽוּא־יֹ֠שֵׁב בַּ⁠עֲלִיַּ֨ת הַ⁠מְּקֵרָ֤ה אֲשֶׁר־ל⁠וֹ֙ לְ⁠בַדּ֔⁠וֹ וַ⁠יֹּ֣אמֶר אֵה֔וּד דְּבַר־אֱלֹהִ֥ים לִ֖⁠י אֵלֶ֑י⁠ךָ וַ⁠יָּ֖קָם מֵ⁠עַ֥ל הַ⁠כִּסֵּֽא׃","wĕ⁠ʼéh֣ẇd ׀ bá֣̇ʼ ʼélá֗y⁠w wĕ⁠hֽẇʼ-yò֠şé̌b bȧ⁠ʻàliyȧ֨ţ ha⁠mĕ̇qérá֤h ʼàşěr-l⁠wò֙ lĕ⁠baḋ֔⁠wò wa⁠yò֣̇ʼmer ʼéh֔ẇd dĕ̇bar-ʼèlòhi֥ym li֖⁠y ʼéle֑y⁠ká wa⁠yá֖̇qám mé⁠ʻa֥l ha⁠ki̇séֽ̇ʼ׃"],[3,21,"וַ⁠יִּשְׁלַ֤ח אֵהוּד֙ אֶת־יַ֣ד שְׂמֹאל֔⁠וֹ וַ⁠יִּקַּח֙ אֶת־הַ⁠חֶ֔רֶב מֵ⁠עַ֖ל יֶ֣רֶךְ יְמִינ֑⁠וֹ וַ⁠יִּתְקָעֶ֖⁠הָ בְּ⁠בִטְנֽ⁠וֹ׃","wa⁠yi̇şĕ̌la֤ẖ ʼéhẇd֙ ʼeţ-ya֣d şĕ̂mòʼl֔⁠wò wa⁠yi̇qȧẖ֙ ʼeţ-ha⁠ẖe֔reb mé⁠ʻa֖l ye֣rekĕ yĕmiyn֑⁠wò wa⁠yi̇ţĕqáʻe֖⁠há bĕ̇⁠bitĕnֽ⁠wò׃"],[3,22,"וַ⁠יָּבֹ֨א גַֽם־הַ⁠נִּצָּ֜ב אַחַ֣ר הַ⁠לַּ֗הַב וַ⁠יִּסְגֹּ֤ר הַ⁠חֵ֨לֶב֙ בְּעַ֣ד הַ⁠לַּ֔הַב כִּ֣י לֹ֥א שָׁלַ֛ף הַ⁠חֶ֖רֶב מִ⁠בִּטְנ֑⁠וֹ וַ⁠יֵּצֵ֖א הַֽ⁠פַּרְשְׁדֹֽנָ⁠ה׃","wa⁠yá̇bò֨ʼ gaֽm-ha⁠ni̇ẕá̇֜b ʼaẖa֣r ha⁠lȧ֗hab wa⁠yi̇sĕgò֤̇r ha⁠ẖé֨leb֙ bĕ̇ʻa֣d ha⁠lȧ֔hab ki֣̇y lò֥ʼ şá̌la֛p ha⁠ẖe֖reb mi⁠bi̇tĕn֑⁠wò wa⁠yé̇ẕé֖ʼ hֽa⁠pȧrĕşĕ̌dòֽná⁠h׃"],[3,23,"וַ⁠יֵּצֵ֥א אֵה֖וּד הַֽ⁠מִּסְדְּר֑וֹנָ⁠ה וַ⁠יִּסְגֹּ֞ר דַּלְת֧וֹת הָ⁠עַלִיָּ֛ה בַּעֲד֖⁠וֹ וְ⁠נָעָֽל׃","wa⁠yé̇ẕé֥ʼ ʼéh֖ẇd haֽ⁠mi̇sĕdĕ̇r֑wòná⁠h wa⁠yi̇sĕgò̇֞r dȧlĕţ֧wòţ há⁠ʻaliyá֛̇h bȧʻàd֖⁠wò wĕ⁠náʻáֽl׃"],[3,24,"וְ⁠ה֤וּא יָצָא֙ וַ⁠עֲבָדָ֣י⁠ו בָּ֔אוּ וַ⁠יִּרְא֕וּ וְ⁠הִנֵּ֛ה דַּלְת֥וֹת הָ⁠עֲלִיָּ֖ה נְעֻל֑וֹת וַ⁠יֹּ֣אמְר֔וּ אַ֣ךְ מֵסִ֥יךְ ה֛וּא אֶת־רַגְלָ֖י⁠ו בַּ⁠חֲדַ֥ר הַ⁠מְּקֵרָֽה׃","wĕ⁠h֤ẇʼ yáẕáʼ֙ wa⁠ʻàbádá֣y⁠w bá̇֔ʼẇ wa⁠yi̇rĕʼ֕ẇ wĕ⁠hiné֛̇h dȧlĕţ֥wòţ há⁠ʻàliyá֖̇h nĕʻul֑wòţ wa⁠yò֣̇ʼmĕr֔ẇ ʼa֣kĕ mési֥ykĕ h֛ẇʼ ʼeţ-ragĕlá֖y⁠w bȧ⁠ẖàda֥r ha⁠mĕ̇qéráֽh׃"],[3,25,"וַ⁠יָּחִ֣ילוּ עַד־בּ֔וֹשׁ וְ⁠הְנֵּ֛ה אֵינֶ֥⁠נּוּ פֹתֵ֖חַ דַּלְת֣וֹת הָֽ⁠עֲלִיָּ֑ה וַ⁠יִּקְח֤וּ אֶת־הַ⁠מַּפְתֵּ֨חַ֙ וַ⁠יִּפְתָּ֔חוּ וְ⁠הִנֵּה֙ אֲדֹ֣נֵי⁠הֶ֔ם נֹפֵ֥ל אַ֖רְצָ⁠ה מֵֽת׃","wa⁠yá̇ẖi֣ylẇ ʻad-ḃ֔wòş̌ wĕ⁠hĕné֛̇h ʼéyne֥⁠ṅẇ pòţé֖ẖa dȧlĕţ֣wòţ háֽ⁠ʻàliyá֑̇h wa⁠yi̇qĕẖ֤ẇ ʼeţ-ha⁠mȧpĕţé̇֨ẖa֙ wa⁠yi̇pĕţá̇֔ẖẇ wĕ⁠hiné̇h֙ ʼàdò֣néy⁠he֔m nòpé֥l ʼa֖rĕẕá⁠h méֽţ׃"],[3,26,"וְ⁠אֵה֥וּד נִמְלַ֖ט עַ֣ד הִֽתְמַהְמְהָ֑⁠ם וְ⁠הוּא֙ עָבַ֣ר אֶת־הַ⁠פְּסִילִ֔ים וַ⁠יִּמָּלֵ֖ט הַ⁠שְּׂעִירָֽתָ⁠ה׃","wĕ⁠ʼéh֥ẇd nimĕla֖t ʻa֣d hiֽţĕmahĕmĕhá֑⁠m wĕ⁠hẇʼ֙ ʻába֣r ʼeţ-ha⁠pĕ̇siyli֔ym wa⁠yi̇má̇lé֖t ha⁠şĕ̇̂ʻiyráֽţá⁠h׃"],[3,27,"וַ⁠יְהִ֣י בְּ⁠בוֹא֔⁠וֹ וַ⁠יִּתְקַ֥ע בַּ⁠שּׁוֹפָ֖ר בְּ⁠הַ֣ר אֶפְרָ֑יִם וַ⁠יֵּרְד֨וּ עִמּ֧⁠וֹ בְנֵֽי־יִשְׂרָאֵ֛ל מִן־הָ⁠הָ֖ר וְ⁠ה֥וּא לִ⁠פְנֵי⁠הֶֽם׃","wa⁠yĕhi֣y bĕ̇⁠bwòʼ֔⁠wò wa⁠yi̇ţĕqa֥ʻ bȧ⁠ş̇̌wòpá֖r bĕ̇⁠ha֣r ʼepĕrá֑yim wa⁠yé̇rĕd֨ẇ ʻiṁ֧⁠wò bĕnéֽy-yişĕ̂ráʼé֛l min-há⁠há֖r wĕ⁠h֥ẇʼ li⁠pĕnéy⁠heֽm׃"],[3,28,"וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ רִדְפ֣וּ אַחֲרַ֔⁠י כִּֽי־נָתַ֨ן יְהוָ֧ה אֶת־אֹיְבֵי⁠כֶ֛ם אֶת־מוֹאָ֖ב בְּ⁠יֶדְ⁠כֶ֑ם וַ⁠יֵּרְד֣וּ אַחֲרָ֗י⁠ו וַֽ⁠יִּלְכְּד֞וּ אֶת־מַעְבְּר֤וֹת הַ⁠יַּרְדֵּן֙ לְ⁠מוֹאָ֔ב וְ⁠לֹֽא־נָתְנ֥וּ אִ֖ישׁ לַ⁠עֲבֹֽר׃","wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ ridĕp֣ẇ ʼaẖàra֔⁠y kiֽ̇y-náţa֨n yĕhwá֧h ʼeţ-ʼòyĕbéy⁠ke֛m ʼeţ-mwòʼá֖b bĕ̇⁠yedĕ⁠ke֑m wa⁠yé̇rĕd֣ẇ ʼaẖàrá֗y⁠w waֽ⁠yi̇lĕkĕ̇d֞ẇ ʼeţ-maʻĕbĕ̇r֤wòţ ha⁠yȧrĕdé̇n֙ lĕ⁠mwòʼá֔b wĕ⁠lòֽʼ-náţĕn֥ẇ ʼi֖yş̌ la⁠ʻàbòֽr׃"],[3,29,"וַ⁠יַּכּ֨וּ אֶת־מוֹאָ֜ב בָּ⁠עֵ֣ת הַ⁠הִ֗יא כַּ⁠עֲשֶׂ֤רֶת אֲלָפִים֙ אִ֔ישׁ כָּל־שָׁמֵ֖ן וְ⁠כָל־אִ֣ישׁ חָ֑יִל וְ⁠לֹ֥א נִמְלַ֖ט אִֽישׁ׃","wa⁠yȧk̇֨ẇ ʼeţ-mwòʼá֜b bá̇⁠ʻé֣ţ ha⁠hi֗yʼ kȧ⁠ʻàşê֤reţ ʼàlápiym֙ ʼi֔yş̌ ká̇l-şá̌mé֖n wĕ⁠kál-ʼi֣yş̌ ẖá֑yil wĕ⁠lò֥ʼ nimĕla֖t ʼiֽyş̌׃"],[3,30,"וַ⁠תִּכָּנַ֤ע מוֹאָב֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא תַּ֖חַת יַ֣ד יִשְׂרָאֵ֑ל וַ⁠תִּשְׁקֹ֥ט הָ⁠אָ֖רֶץ שְׁמוֹנִ֥ים שָׁנָֽה׃ס","wa⁠ţi̇ká̇na֤ʻ mwòʼáb֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ţȧ֖ẖaţ ya֣d yişĕ̂ráʼé֑l wa⁠ţi̇şĕ̌qò֥t há⁠ʼá֖reẕ şĕ̌mwòni֥ym şá̌náֽh׃s"],[3,31,"וְ⁠אַחֲרָ֤י⁠ו הָיָה֙ שַׁמְגַּ֣ר בֶּן־עֲנָ֔ת וַ⁠יַּ֤ךְ אֶת־פְּלִשְׁתִּים֙ שֵֽׁשׁ־מֵא֣וֹת אִ֔ישׁ בְּ⁠מַלְמַ֖ד הַ⁠בָּקָ֑ר וַ⁠יֹּ֥שַׁע גַּם־ה֖וּא אֶת־יִשְׂרָאֵֽל׃ס","wĕ⁠ʼaẖàrá֤y⁠w háyáh֙ şǎmĕgȧ֣r bėn-ʻàná֔ţ wa⁠yȧ֤kĕ ʼeţ-pĕ̇lişĕ̌ţi̇ym֙ şéֽ̌ş̌-méʼ֣wòţ ʼi֔yş̌ bĕ̇⁠malĕma֖d ha⁠bá̇qá֑r wa⁠yò֥̇şǎʻ gȧm-h֖ẇʼ ʼeţ-yişĕ̂ráʼéֽl׃s"],[4,1,"וַ⁠יֹּסִ֨פוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל לַ⁠עֲשׂ֥וֹת הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וְ⁠אֵה֖וּד מֵֽת׃","wa⁠yò̇si֨pẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l la⁠ʻàş֥̂wòţ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wĕ⁠ʼéh֖ẇd méֽţ׃"],[4,2,"וַ⁠יִּמְכְּרֵ֣⁠ם יְהוָ֗ה בְּ⁠יַד֙ יָבִ֣ין מֶֽלֶךְ־כְּנַ֔עַן אֲשֶׁ֥ר מָלַ֖ךְ בְּ⁠חָצ֑וֹר וְ⁠שַׂר־צְבָא⁠וֹ֙ סִֽיסְרָ֔א וְ⁠ה֥וּא יוֹשֵׁ֖ב בַּ⁠חֲרֹ֥שֶׁת הַגּוֹיִֽם׃","wa⁠yi̇mĕkĕ̇ré֣⁠m yĕhwá֗h bĕ̇⁠yad֙ yábi֣yn meֽlekĕ-kĕ̇na֔ʻan ʼàşě֥r mála֖kĕ bĕ̇⁠ẖáẕ֑wòr wĕ⁠şâr-ẕĕbáʼ⁠wò֙ siֽysĕrá֔ʼ wĕ⁠h֥ẇʼ ywòşé֖̌b bȧ⁠ẖàrò֥şěţ haġwòyiֽm׃"],[4,3,"וַ⁠יִּצְעֲק֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל אֶל־יְהוָ֑ה כִּ֠י תְּשַׁ֨ע מֵא֤וֹת רֶֽכֶב־בַּרְזֶל֙ ל֔⁠וֹ וְ֠⁠הוּא לָחַ֞ץ אֶת־בְּנֵ֧י יִשְׂרָאֵ֛ל בְּ⁠חָזְקָ֖ה עֶשְׂרִ֥ים שָׁנָֽה׃ס","wa⁠yi̇ẕĕʻàq֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l ʼel-yĕhwá֑h ki̇֠y ţĕ̇şǎ֨ʻ méʼ֤wòţ reֽkeb-bȧrĕzel֙ l֔⁠wò wĕ֠⁠hẇʼ láẖa֞ẕ ʼeţ-bĕ̇né֧y yişĕ̂ráʼé֛l bĕ̇⁠ẖázĕqá֖h ʻeşĕ̂ri֥ym şá̌náֽh׃s"],[4,4,"וּ⁠דְבוֹרָה֙ אִשָּׁ֣ה נְבִיאָ֔ה אֵ֖שֶׁת לַפִּיד֑וֹת הִ֛יא שֹׁפְטָ֥ה אֶת־יִשְׂרָאֵ֖ל בָּ⁠עֵ֥ת הַ⁠הִֽיא׃","ẇ⁠dĕbwòráh֙ ʼişá֣̇̌h nĕbiyʼá֔h ʼé֖şěţ lapi̇yd֑wòţ hi֛yʼ şò̌pĕtá֥h ʼeţ-yişĕ̂ráʼé֖l bá̇⁠ʻé֥ţ ha⁠hiֽyʼ׃"],[4,5,"וְ֠⁠הִיא יוֹשֶׁ֨בֶת תַּֽחַת־תֹּ֜מֶר דְּבוֹרָ֗ה בֵּ֧ין הָ⁠רָמָ֛ה וּ⁠בֵ֥ין בֵּֽית־אֵ֖ל בְּ⁠הַ֣ר אֶפְרָ֑יִם וַ⁠יַּעֲל֥וּ אֵלֶ֛י⁠הָ בְּנֵ֥י יִשְׂרָאֵ֖ל לַ⁠מִּשְׁפָּֽט׃","wĕ֠⁠hiyʼ ywòşě֨beţ ţȧֽẖaţ-ţò̇֜mer dĕ̇bwòrá֗h bé֧̇yn há⁠rámá֛h ẇ⁠bé֥yn béֽ̇yţ-ʼé֖l bĕ̇⁠ha֣r ʼepĕrá֑yim wa⁠yȧʻàl֥ẇ ʼéle֛y⁠há bĕ̇né֥y yişĕ̂ráʼé֖l la⁠mi̇şĕ̌páֽ̇t׃"],[4,6,"וַ⁠תִּשְׁלַ֗ח וַ⁠תִּקְרָא֙ לְ⁠בָרָ֣ק בֶּן־אֲבִינֹ֔עַם מִ⁠קֶּ֖דֶשׁ נַפְתָּלִ֑י וַ⁠תֹּ֨אמֶר אֵלָ֜י⁠ו הֲ⁠לֹ֥א צִוָּ֣ה ׀ יְהוָ֣ה אֱלֹהֵֽי־יִשְׂרָאֵ֗ל לֵ֤ךְ וּ⁠מָֽשַׁכְתָּ֙ בְּ⁠הַ֣ר תָּב֔וֹר וְ⁠לָקַחְתָּ֣ עִמְּ⁠ךָ֗ עֲשֶׂ֤רֶת אֲלָפִים֙ אִ֔ישׁ מִ⁠בְּנֵ֥י נַפְתָּלִ֖י וּ⁠מִ⁠בְּנֵ֥י זְבֻלֽוּן׃","wa⁠ţi̇şĕ̌la֗ẖ wa⁠ţi̇qĕráʼ֙ lĕ⁠bárá֣q bėn-ʼàbiynò֔ʻam mi⁠qė֖deş̌ napĕţá̇li֑y wa⁠ţò̇֨ʼmer ʼélá֜y⁠w hà⁠lò֥ʼ ẕiwá֣̇h ׀ yĕhwá֣h ʼèlòhéֽy-yişĕ̂ráʼé֗l lé֤kĕ ẇ⁠máֽşǎkĕţá̇֙ bĕ̇⁠ha֣r ţá̇b֔wòr wĕ⁠láqaẖĕţá֣̇ ʻimĕ̇⁠ká֗ ʻàşê֤reţ ʼàlápiym֙ ʼi֔yş̌ mi⁠bĕ̇né֥y napĕţá̇li֖y ẇ⁠mi⁠bĕ̇né֥y zĕbulֽẇn׃"],[4,7,"וּ⁠מָשַׁכְתִּ֨י אֵלֶ֜י⁠ךָ אֶל־נַ֣חַל קִישׁ֗וֹן אֶת־סִֽיסְרָא֙ שַׂר־צְבָ֣א יָבִ֔ין וְ⁠אֶת־רִכְבּ֖⁠וֹ וְ⁠אֶת־הֲמוֹנ֑⁠וֹ וּ⁠נְתַתִּ֖י⁠הוּ בְּ⁠יָדֶֽ⁠ךָ׃","ẇ⁠máşǎkĕţi̇֨y ʼéle֜y⁠ká ʼel-na֣ẖal qiyş̌֗wòn ʼeţ-siֽysĕráʼ֙ şâr-ẕĕbá֣ʼ yábi֔yn wĕ⁠ʼeţ-rikĕḃ֖⁠wò wĕ⁠ʼeţ-hàmwòn֑⁠wò ẇ⁠nĕţaţi֖̇y⁠hẇ bĕ̇⁠yádeֽ⁠ká׃"],[4,8,"וַ⁠יֹּ֤אמֶר אֵלֶ֨י⁠הָ֙ בָּרָ֔ק אִם־תֵּלְכִ֥י עִמִּ֖⁠י וְ⁠הָלָ֑כְתִּי וְ⁠אִם־לֹ֥א תֵלְכִ֛י עִמִּ֖⁠י לֹ֥א אֵלֵֽךְ׃","wa⁠yò֤̇ʼmer ʼéle֨y⁠há֙ bá̇rá֔q ʼim-ţé̇lĕki֥y ʻimi֖̇⁠y wĕ⁠hálá֑kĕţi̇y wĕ⁠ʼim-lò֥ʼ ţélĕki֛y ʻimi֖̇⁠y lò֥ʼ ʼéléֽkĕ׃"],[4,9,"וַ⁠תֹּ֜אמֶר הָלֹ֧ךְ אֵלֵ֣ךְ עִמָּ֗⁠ךְ אֶ֚פֶס כִּי֩ לֹ֨א תִֽהְיֶ֜ה תִּֽפְאַרְתְּ⁠ךָ֗ עַל־הַ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר אַתָּ֣ה הוֹלֵ֔ךְ כִּ֣י בְֽ⁠יַד־אִשָּׁ֔ה יִמְכֹּ֥ר יְהוָ֖ה אֶת־סִֽיסְרָ֑א וַ⁠תָּ֧קָם דְּבוֹרָ֛ה וַ⁠תֵּ֥לֶך עִם־בָּרָ֖ק קֶֽדְשָׁ⁠ה׃","wa⁠ţò̇֜ʼmer hálò֧kĕ ʼélé֣kĕ ʻimá̇֗⁠kĕ ʼe֚pes ki̇y֩ lò֨ʼ ţiֽhĕye֜h ţiֽ̇pĕʼarĕţĕ̇⁠ká֗ ʻal-ha⁠dė֨rekĕ֙ ʼàşě֣r ʼaţá֣̇h hwòlé֔kĕ ki֣̇y bĕֽ⁠yad-ʼişá̇̌֔h yimĕkò֥̇r yĕhwá֖h ʼeţ-siֽysĕrá֑ʼ wa⁠ţá֧̇qám dĕ̇bwòrá֛h wa⁠ţé֥̇lek ʻim-bá̇rá֖q qeֽdĕşá̌⁠h׃"],[4,10,"וַ⁠יַּזְעֵ֨ק בָּרָ֜ק אֶת־זְבוּלֻ֤ן וְ⁠אֶת־נַפְתָּלִי֙ קֶ֔דְשָׁ⁠ה וַ⁠יַּ֣עַל בְּ⁠רַגְלָ֔י⁠ו עֲשֶׂ֥רֶת אַלְפֵ֖י אִ֑ישׁ וַ⁠תַּ֥עַל עִמּ֖⁠וֹ דְּבוֹרָֽה׃","wa⁠yȧzĕʻé֨q bá̇rá֜q ʼeţ-zĕbẇlu֤n wĕ⁠ʼeţ-napĕţá̇liy֙ qe֔dĕşá̌⁠h wa⁠yȧ֣ʻal bĕ̇⁠ragĕlá֔y⁠w ʻàşê֥reţ ʼalĕpé֖y ʼi֑yş̌ wa⁠ţȧ֥ʻal ʻiṁ֖⁠wò dĕ̇bwòráֽh׃"],[4,11,"וְ⁠חֶ֤בֶר הַ⁠קֵּינִי֙ נִפְרָ֣ד מִ⁠קַּ֔יִן מִ⁠בְּנֵ֥י חֹבָ֖ב חֹתֵ֣ן מֹשֶׁ֑ה וַ⁠יֵּ֣ט אָהֳל֔⁠וֹ עַד־אֵל֥וֹן ב⁠צענים אֲשֶׁ֥ר אֶת־קֶֽדֶשׁ׃","wĕ⁠ẖe֤ber ha⁠qé̇yniy֙ nipĕrá֣d mi⁠qȧ֔yin mi⁠bĕ̇né֥y ẖòbá֖b ẖòţé֣n mòşě֑h wa⁠yé֣̇t ʼáhol֔⁠wò ʻad-ʼél֥wòn b⁠ẕʻnym ʼàşě֥r ʼeţ-qeֽdeş̌׃"],[4,12,"וַ⁠יַּגִּ֖דוּ לְ⁠סִֽיסְרָ֑א כִּ֥י עָלָ֛ה בָּרָ֥ק בֶּן־אֲבִינֹ֖עַם הַר־תָּבֽוֹר׃ס","wa⁠yȧgi֖̇dẇ lĕ⁠siֽysĕrá֑ʼ ki֥̇y ʻálá֛h bá̇rá֥q bėn-ʼàbiynò֖ʻam har-ţá̇bֽwòr׃s"],[4,13,"וַ⁠יַּזְעֵ֨ק סִֽיסְרָ֜א אֶת־כָּל־רִכְבּ֗⁠וֹ תְּשַׁ֤ע מֵאוֹת֙ רֶ֣כֶב בַּרְזֶ֔ל וְ⁠אֶת־כָּל־הָ⁠עָ֖ם אֲשֶׁ֣ר אִתּ֑⁠וֹ מֵ⁠חֲרֹ֥שֶׁת הַגּוֹיִ֖ם אֶל־נַ֥חַל קִישֽׁוֹן׃","wa⁠yȧzĕʻé֨q siֽysĕrá֜ʼ ʼeţ-ká̇l-rikĕḃ֗⁠wò ţĕ̇şǎ֤ʻ méʼwòţ֙ re֣keb bȧrĕze֔l wĕ⁠ʼeţ-ká̇l-há⁠ʻá֖m ʼàşě֣r ʼiţ֑̇⁠wò mé⁠ẖàrò֥şěţ haġwòyi֖m ʼel-na֥ẖal qiyşֽ̌wòn׃"],[4,14,"וַ⁠תֹּאמֶר֩ דְּבֹרָ֨ה אֶל־בָּרָ֜ק ק֗וּם כִּ֣י זֶ֤ה הַ⁠יּוֹם֙ אֲשֶׁר֩ נָתַ֨ן יְהוָ֤ה אֶת־סִֽיסְרָא֙ בְּ⁠יָדֶ֔⁠ךָ הֲ⁠לֹ֥א יְהוָ֖ה יָצָ֣א לְ⁠פָנֶ֑י⁠ךָ וַ⁠יֵּ֤רֶד בָּרָק֙ מֵ⁠הַ֣ר תָּב֔וֹר וַ⁠עֲשֶׂ֧רֶת אֲלָפִ֛ים אִ֖ישׁ אַחֲרָֽי⁠ו׃","wa⁠ţò̇ʼmer֩ dĕ̇bòrá֨h ʼel-bá̇rá֜q q֗ẇm ki֣̇y ze֤h ha⁠ẏwòm֙ ʼàşěr֩ náţa֨n yĕhwá֤h ʼeţ-siֽysĕráʼ֙ bĕ̇⁠yáde֔⁠ká hà⁠lò֥ʼ yĕhwá֖h yáẕá֣ʼ lĕ⁠páne֑y⁠ká wa⁠yé֤̇red bá̇ráq֙ mé⁠ha֣r ţá̇b֔wòr wa⁠ʻàşê֧reţ ʼàlápi֛ym ʼi֖yş̌ ʼaẖàráֽy⁠w׃"],[4,15,"וַ⁠יָּ֣הָם יְ֠הוָה אֶת־סִֽיסְרָ֨א וְ⁠אֶת־כָּל־הָ⁠רֶ֧כֶב וְ⁠אֶת־כָּל־הַֽ⁠מַּחֲנֶ֛ה לְ⁠פִי־חֶ֖רֶב לִ⁠פְנֵ֣י בָרָ֑ק וַ⁠יֵּ֧רֶד סִֽיסְרָ֛א מֵ⁠עַ֥ל הַ⁠מֶּרְכָּבָ֖ה וַ⁠יָּ֥נָס בְּ⁠רַגְלָֽי⁠ו׃","wa⁠yá֣̇hám yĕ֠hwáh ʼeţ-siֽysĕrá֨ʼ wĕ⁠ʼeţ-ká̇l-há⁠re֧keb wĕ⁠ʼeţ-ká̇l-haֽ⁠mȧẖàne֛h lĕ⁠piy-ẖe֖reb li⁠pĕné֣y bárá֑q wa⁠yé֧̇red siֽysĕrá֛ʼ mé⁠ʻa֥l ha⁠mėrĕká̇bá֖h wa⁠yá֥̇nás bĕ̇⁠ragĕláֽy⁠w׃"],[4,16,"וּ⁠בָרָ֗ק רָדַ֞ף אַחֲרֵ֤י הָ⁠רֶ֨כֶב֙ וְ⁠אַחֲרֵ֣י הַֽ⁠מַּחֲנֶ֔ה עַ֖ד חֲרֹ֣שֶׁת הַגּוֹיִ֑ם וַ⁠יִּפֹּ֞ל כָּל־מַחֲנֵ֤ה סִֽיסְרָא֙ לְ⁠פִי־חֶ֔רֶב לֹ֥א נִשְׁאַ֖ר עַד־אֶחָֽד׃","ẇ⁠bárá֗q ráda֞p ʼaẖàré֤y há⁠re֨keb֙ wĕ⁠ʼaẖàré֣y haֽ⁠mȧẖàne֔h ʻa֖d ẖàrò֣şěţ haġwòyi֑m wa⁠yi̇pò̇֞l ká̇l-maẖàné֤h siֽysĕráʼ֙ lĕ⁠piy-ẖe֔reb lò֥ʼ nişĕ̌ʼa֖r ʻad-ʼeẖáֽd׃"],[4,17,"וְ⁠סִֽיסְרָא֙ נָ֣ס בְּ⁠רַגְלָ֔י⁠ו אֶל־אֹ֣הֶל יָעֵ֔ל אֵ֖שֶּׁת חֶ֣בֶר הַ⁠קֵּינִ֑י כִּ֣י שָׁל֗וֹם בֵּ֚ין יָבִ֣ין מֶֽלֶךְ־חָצ֔וֹר וּ⁠בֵ֕ין בֵּ֖ית חֶ֥בֶר הַ⁠קֵּינִֽי׃","wĕ⁠siֽysĕráʼ֙ ná֣s bĕ̇⁠ragĕlá֔y⁠w ʼel-ʼò֣hel yáʻé֔l ʼé֖şė̌ţ ẖe֣ber ha⁠qé̇yni֑y ki֣̇y şá̌l֗wòm bé֚̇yn yábi֣yn meֽlekĕ-ẖáẕ֔wòr ẇ⁠bé֕yn bé֖̇yţ ẖe֥ber ha⁠qé̇yniֽy׃"],[4,18,"וַ⁠תֵּצֵ֣א יָעֵל֮ לִ⁠קְרַ֣את סִֽיסְרָא֒ וַ⁠תֹּ֣אמֶר אֵלָ֗י⁠ו סוּרָ֧⁠ה אֲדֹנִ֛⁠י סוּרָ֥⁠ה אֵלַ֖⁠י אַל־תִּירָ֑א וַ⁠יָּ֤סַר אֵלֶ֨י⁠הָ֙ הָ⁠אֹ֔הֱלָ⁠ה וַ⁠תְּכַסֵּ֖⁠הוּ בַּ⁠שְּׂמִיכָֽה׃","wa⁠ţé̇ẕé֣ʼ yáʻél֮ li⁠qĕra֣ʼţ siֽysĕráʼ֒ wa⁠ţò֣̇ʼmer ʼélá֗y⁠w sẇrá֧⁠h ʼàdòni֛⁠y sẇrá֥⁠h ʼéla֖⁠y ʼal-ţi̇yrá֑ʼ wa⁠yá֤̇sar ʼéle֨y⁠há֙ há⁠ʼò֔hèlá⁠h wa⁠ţĕ̇kasé֖̇⁠hẇ bȧ⁠şĕ̇̂miykáֽh׃"],[4,19,"וַ⁠יֹּ֧אמֶר אֵלֶ֛י⁠הָ הַשְׁקִי⁠נִי־נָ֥א מְעַט־מַ֖יִם כִּ֣י צָמֵ֑אתִי וַ⁠תִּפְתַּ֞ח אֶת־נֹ֧אוד הֶ⁠חָלָ֛ב וַ⁠תַּשְׁקֵ֖⁠הוּ וַ⁠תְּכַסֵּֽ⁠הוּ׃","wa⁠yò֧̇ʼmer ʼéle֛y⁠há haşĕ̌qiy⁠niy-ná֥ʼ mĕʻat-ma֖yim ki֣̇y ẕámé֑ʼţiy wa⁠ţi̇pĕţȧ֞ẖ ʼeţ-nò֧ʼwd he⁠ẖálá֛b wa⁠ţȧşĕ̌qé֖⁠hẇ wa⁠ţĕ̇kaséֽ̇⁠hẇ׃"],[4,20,"וַ⁠יֹּ֣אמֶר אֵלֶ֔י⁠הָ עֲמֹ֖ד פֶּ֣תַח הָ⁠אֹ֑הֶל וְ⁠הָיָה֩ אִם־אִ֨ישׁ יָב֜וֹא וּ⁠שְׁאֵלֵ֗⁠ךְ וְ⁠אָמַ֛ר הֲ⁠יֵֽשׁ־פֹּ֥ה אִ֖ישׁ וְ⁠אָמַ֥רְתְּ אָֽיִן׃","wa⁠yò֣̇ʼmer ʼéle֔y⁠há ʻàmò֖d pė֣ţaẖ há⁠ʼò֑hel wĕ⁠háyáh֩ ʼim-ʼi֨yş̌ yáb֜wòʼ ẇ⁠şĕ̌ʼélé֗⁠kĕ wĕ⁠ʼáma֛r hà⁠yéֽş̌-pò֥̇h ʼi֖yş̌ wĕ⁠ʼáma֥rĕţĕ̇ ʼáֽyin׃"],[4,21,"וַ⁠תִּקַּ֣ח יָעֵ֣ל אֵֽשֶׁת־חֶ֠בֶר אֶת־יְתַ֨ד הָ⁠אֹ֜הֶל וַ⁠תָּ֧שֶׂם אֶת־הַ⁠מַּקֶּ֣בֶת בְּ⁠יָדָ֗⁠הּ וַ⁠תָּב֤וֹא אֵלָי⁠ו֙ בַּ⁠לָּ֔אט וַ⁠תִּתְקַ֤ע אֶת־הַ⁠יָּתֵד֙ בְּ⁠רַקָּת֔⁠וֹ וַ⁠תִּצְנַ֖ח בָּ⁠אָ֑רֶץ וְ⁠הֽוּא־נִרְדָּ֥ם וַ⁠יָּ֖עַף וַ⁠יָּמֹֽת׃","wa⁠ţi̇qȧ֣ẖ yáʻé֣l ʼéֽşěţ-ẖe֠ber ʼeţ-yĕţa֨d há⁠ʼò֜hel wa⁠ţá֧̇şêm ʼeţ-ha⁠mȧqė֣beţ bĕ̇⁠yádá֗⁠ḣ wa⁠ţá̇b֤wòʼ ʼéláy⁠w֙ bȧ⁠lá̇֔ʼt wa⁠ţi̇ţĕqa֤ʻ ʼeţ-ha⁠yá̇ţéd֙ bĕ̇⁠raqá̇ţ֔⁠wò wa⁠ţi̇ẕĕna֖ẖ bá̇⁠ʼá֑reẕ wĕ⁠hֽẇʼ-nirĕdá֥̇m wa⁠yá֖̇ʻap wa⁠yá̇mòֽţ׃"],[4,22,"וְ⁠הִנֵּ֣ה בָרָק֮ רֹדֵ֣ף אֶת־סִֽיסְרָא֒ וַ⁠תֵּצֵ֤א יָעֵל֙ לִ⁠קְרָאת֔⁠וֹ וַ⁠תֹּ֣אמֶר ל֔⁠וֹ לֵ֣ךְ וְ⁠אַרְאֶ֔⁠ךָּ אֶת־הָ⁠אִ֖ישׁ אֲשֶׁר־אַתָּ֣ה מְבַקֵּ֑שׁ וַ⁠יָּבֹ֣א אֵלֶ֔י⁠הָ וְ⁠הִנֵּ֤ה סִֽיסְרָא֙ נֹפֵ֣ל מֵ֔ת וְ⁠הַ⁠יָּתֵ֖ד בְּ⁠רַקָּתֽ⁠וֹ׃","wĕ⁠hiné֣̇h báráq֮ ròdé֣p ʼeţ-siֽysĕráʼ֒ wa⁠ţé̇ẕé֤ʼ yáʻél֙ li⁠qĕráʼţ֔⁠wò wa⁠ţò֣̇ʼmer l֔⁠wò lé֣kĕ wĕ⁠ʼarĕʼe֔⁠ká̇ ʼeţ-há⁠ʼi֖yş̌ ʼàşěr-ʼaţá֣̇h mĕbaqé֑̇ş̌ wa⁠yá̇bò֣ʼ ʼéle֔y⁠há wĕ⁠hiné֤̇h siֽysĕráʼ֙ nòpé֣l mé֔ţ wĕ⁠ha⁠yá̇ţé֖d bĕ̇⁠raqá̇ţֽ⁠wò׃"],[4,23,"וַ⁠יַּכְנַ֤ע אֱלֹהִים֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא אֵ֖ת יָבִ֣ין מֶֽלֶךְ־כְּנָ֑עַן לִ⁠פְנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yȧkĕna֤ʻ ʼèlòhiym֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ʼé֖ţ yábi֣yn meֽlekĕ-kĕ̇ná֑ʻan li⁠pĕné֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[4,24,"וַ⁠תֵּ֜לֶךְ יַ֤ד בְּנֵֽי־יִשְׂרָאֵל֙ הָל֣וֹךְ וְ⁠קָשָׁ֔ה עַ֖ל יָבִ֣ין מֶֽלֶךְ־כְּנָ֑עַן עַ֚ד אֲשֶׁ֣ר הִכְרִ֔יתוּ אֵ֖ת יָבִ֥ין מֶֽלֶךְ־כְּנָֽעַן׃פ","wa⁠ţé̇֜lekĕ ya֤d bĕ̇néֽy-yişĕ̂ráʼél֙ hál֣wòkĕ wĕ⁠qáşá̌֔h ʻa֖l yábi֣yn meֽlekĕ-kĕ̇ná֑ʻan ʻa֚d ʼàşě֣r hikĕri֔yţẇ ʼé֖ţ yábi֥yn meֽlekĕ-kĕ̇náֽʻan׃p"],[5,1,"וַ⁠תָּ֣שַׁר דְּבוֹרָ֔ה וּ⁠בָרָ֖ק בֶּן־אֲבִינֹ֑עַם בַּ⁠יּ֥וֹם הַ⁠ה֖וּא לֵ⁠אמֹֽר׃","wa⁠ţá֣̇şǎr dĕ̇bwòrá֔h ẇ⁠bárá֖q bėn-ʼàbiynò֑ʻam bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ lé⁠ʼmòֽr׃"],[5,2,"בִּ⁠פְרֹ֤עַ פְּרָעוֹת֙ בְּ⁠יִשְׂרָאֵ֔ל בְּ⁠הִתְנַדֵּ֖ב עָ֑ם בָּרֲכ֖וּ יְהוָֽה׃","bi̇⁠pĕrò֤ʻa pĕ̇ráʻwòţ֙ bĕ̇⁠yişĕ̂ráʼé֔l bĕ̇⁠hiţĕnadé֖̇b ʻá֑m bá̇ràk֖ẇ yĕhwáֽh׃"],[5,3,"שִׁמְע֣וּ מְלָכִ֔ים הַאֲזִ֖ינוּ רֹֽזְנִ֑ים אָֽנֹכִ֗י לַֽ⁠יהוָה֙ אָנֹכִ֣י אָשִׁ֔ירָה אֲזַמֵּ֕ר לַֽ⁠יהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","şǐmĕʻ֣ẇ mĕláki֔ym haʼàzi֖ynẇ ròֽzĕni֑ym ʼֽánòki֗y laֽ⁠yhwáh֙ ʼánòki֣y ʼáşǐ֔yráh ʼàzamé̇֕r laֽ⁠yhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[5,4,"יְהוָ֗ה בְּ⁠צֵאתְ⁠ךָ֤ מִ⁠שֵּׂעִיר֙ בְּ⁠צַעְדְּ⁠ךָ֙ מִ⁠שְּׂדֵ֣ה אֱד֔וֹם אֶ֣רֶץ רָעָ֔שָׁה גַּם־שָׁמַ֖יִם נָטָ֑פוּ גַּם־עָבִ֖ים נָ֥טְפוּ מָֽיִם׃","yĕhwá֗h bĕ̇⁠ẕéʼţĕ⁠ká֤ mi⁠şé̇̂ʻiyr֙ bĕ̇⁠ẕaʻĕdĕ̇⁠ká֙ mi⁠şĕ̇̂dé֣h ʼèd֔wòm ʼe֣reẕ ráʻá֔şá̌h gȧm-şá̌ma֖yim nátá֑pẇ gȧm-ʻábi֖ym ná֥tĕpẇ máֽyim׃"],[5,5,"הָרִ֥ים נָזְל֖וּ מִ⁠פְּנֵ֣י יְהוָ֑ה זֶ֣ה סִינַ֔י מִ⁠פְּנֵ֕י יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","hári֥ym názĕl֖ẇ mi⁠pĕ̇né֣y yĕhwá֑h ze֣h siyna֔y mi⁠pĕ̇né֕y yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[5,6,"בִּ⁠ימֵ֞י שַׁמְגַּ֤ר בֶּן־עֲנָת֙ בִּ⁠ימֵ֣י יָעֵ֔ל חָדְל֖וּ אֳרָח֑וֹת וְ⁠הֹלְכֵ֣י נְתִיב֔וֹת יֵלְכ֕וּ אֳרָח֖וֹת עֲקַלְקַלּֽוֹת׃","bi̇⁠ymé֞y şǎmĕgȧ֤r bėn-ʻànáţ֙ bi̇⁠ymé֣y yáʻé֔l ẖádĕl֖ẇ ʼoráẖ֑wòţ wĕ⁠hòlĕké֣y nĕţiyb֔wòţ yélĕk֕ẇ ʼoráẖ֖wòţ ʻàqalĕqalֽ̇wòţ׃"],[5,7,"חָדְל֧וּ פְרָז֛וֹן בְּ⁠יִשְׂרָאֵ֖ל חָדֵ֑לּוּ עַ֤ד שַׁ⁠קַּ֨מְתִּי֙ דְּבוֹרָ֔ה שַׁ⁠קַּ֥מְתִּי אֵ֖ם בְּ⁠יִשְׂרָאֵֽל׃","ẖádĕl֧ẇ pĕráz֛wòn bĕ̇⁠yişĕ̂ráʼé֖l ẖádé֑l̇ẇ ʻa֤d şǎ⁠qȧ֨mĕţi̇y֙ dĕ̇bwòrá֔h şǎ⁠qȧ֥mĕţi̇y ʼé֖m bĕ̇⁠yişĕ̂ráʼéֽl׃"],[5,8,"יִבְחַר֙ אֱלֹהִ֣ים חֲדָשִׁ֔ים אָ֖ז לָחֶ֣ם שְׁעָרִ֑ים מָגֵ֤ן אִם־יֵֽרָאֶה֙ וָ⁠רֹ֔מַח בְּ⁠אַרְבָּעִ֥ים אֶ֖לֶף בְּ⁠יִשְׂרָאֵֽל׃","yibĕẖar֙ ʼèlòhi֣ym ẖàdáşǐ֔ym ʼá֖z láẖe֣m şĕ̌ʻári֑ym mágé֤n ʼim-yéֽráʼeh֙ wá⁠rò֔maẖ bĕ̇⁠ʼarĕbá̇ʻi֥ym ʼe֖lep bĕ̇⁠yişĕ̂ráʼéֽl׃"],[5,9,"לִבִּ⁠י֙ לְ⁠חוֹקְקֵ֣י יִשְׂרָאֵ֔ל הַ⁠מִּֽתְנַדְּבִ֖ים בָּ⁠עָ֑ם בָּרֲכ֖וּ יְהוָֽה׃","libi̇⁠y֙ lĕ⁠ẖwòqĕqé֣y yişĕ̂ráʼé֔l ha⁠miֽ̇ţĕnadĕ̇bi֖ym bá̇⁠ʻá֑m bá̇ràk֖ẇ yĕhwáֽh׃"],[5,10,"רֹכְבֵי֩ אֲתֹנ֨וֹת צְחֹר֜וֹת יֹשְׁבֵ֧י עַל־מִדִּ֛ין וְ⁠הֹלְכֵ֥י עַל־דֶּ֖רֶךְ שִֽׂיחוּ׃","ròkĕbéy֩ ʼàţòn֨wòţ ẕĕẖòr֜wòţ yòşĕ̌bé֧y ʻal-midi֛̇yn wĕ⁠hòlĕké֥y ʻal-dė֖rekĕ şîֽyẖẇ׃"],[5,11,"מִ⁠קּ֣וֹל מְחַֽצְצִ֗ים בֵּ֚ין מַשְׁאַבִּ֔ים שָׁ֤ם יְתַנּוּ֙ צִדְק֣וֹת יְהוָ֔ה צִדְקֹ֥ת פִּרְזֹנ֖⁠וֹ בְּ⁠יִשְׂרָאֵ֑ל אָ֛ז יָרְד֥וּ לַ⁠שְּׁעָרִ֖ים עַם־יְהוָֽה׃","mi⁠q֣̇wòl mĕẖaֽẕĕẕi֗ym bé֚̇yn maşĕ̌ʼabi̇֔ym şá֤̌m yĕţaṅẇ֙ ẕidĕq֣wòţ yĕhwá֔h ẕidĕqò֥ţ pi̇rĕzòn֖⁠wò bĕ̇⁠yişĕ̂ráʼé֑l ʼá֛z yárĕd֥ẇ la⁠şĕ̇̌ʻári֖ym ʻam-yĕhwáֽh׃"],[5,12,"עוּרִ֤י עוּרִי֙ דְּבוֹרָ֔ה ע֥וּרִי ע֖וּרִי דַּבְּרִי־שִׁ֑יר ק֥וּם בָּרָ֛ק וּֽ⁠שֲׁבֵ֥ה שֶׁבְיְ⁠ךָ֖ בֶּן־אֲבִינֹֽעַם׃","ʻẇri֤y ʻẇriy֙ dĕ̇bwòrá֔h ʻ֥ẇriy ʻ֖ẇriy dȧbĕ̇riy-şǐ֑yr q֥ẇm bá̇rá֛q ẇֽ⁠şà̌bé֥h şěbĕyĕ⁠ká֖ bėn-ʼàbiynòֽʻam׃"],[5,13,"אָ֚ז יְרַ֣ד שָׂרִ֔יד לְ⁠אַדִּירִ֖ים עָ֑ם יְהוָ֕ה יְרַד־לִ֖⁠י בַּ⁠גִּבּוֹרִֽים׃","ʼá֚z yĕra֣d şá̂ri֔yd lĕ⁠ʼadi̇yri֖ym ʻá֑m yĕhwá֕h yĕrad-li֖⁠y bȧ⁠gi̇ḃwòriֽym׃"],[5,14,"מִנִּ֣י אֶפְרַ֗יִם שָׁרְשָׁ⁠ם֙ בַּ⁠עֲמָלֵ֔ק אַחֲרֶ֥י⁠ךָ בִנְיָמִ֖ין בַּֽ⁠עֲמָמֶ֑י⁠ךָ מִנִּ֣י מָכִ֗יר יָֽרְדוּ֙ מְחֹ֣קְקִ֔ים וּ⁠מִ֨⁠זְּבוּלֻ֔ן מֹשְׁכִ֖ים בְּ⁠שֵׁ֥בֶט סֹפֵֽר׃","mini֣̇y ʼepĕra֗yim şá̌rĕşá̌⁠m֙ bȧ⁠ʻàmálé֔q ʼaẖàre֥y⁠ká binĕyámi֖yn ḃֽa⁠ʻàmáme֑y⁠ká mini֣̇y máki֗yr yáֽrĕdẇ֙ mĕẖò֣qĕqi֔ym ẇ⁠mi֨⁠zĕ̇bẇlu֔n mòşĕ̌ki֖ym bĕ̇⁠şé֥̌bet sòpéֽr׃"],[5,15,"וְ⁠שָׂרַ֤⁠י בְּ⁠יִשָּׂשכָר֙ עִם־דְּבֹרָ֔ה וְ⁠יִשָּׂשכָר֙ כֵּ֣ן בָּרָ֔ק בָּ⁠עֵ֖מֶק שֻׁלַּ֣ח בְּ⁠רַגְלָ֑י⁠ו בִּ⁠פְלַגּ֣וֹת רְאוּבֵ֔ן גְּדֹלִ֖ים חִקְקֵי־לֵֽב׃","wĕ⁠şá̂ra֤⁠y bĕ̇⁠yişá̇̂şkár֙ ʻim-dĕ̇bòrá֔h wĕ⁠yişá̇̂şkár֙ ké֣̇n bá̇rá֔q bá̇⁠ʻé֖meq şǔlȧ֣ẖ bĕ̇⁠ragĕlá֑y⁠w bi̇⁠pĕlaġ֣wòţ rĕʼẇbé֔n gĕ̇dòli֖ym ẖiqĕqéy-léֽb׃"],[5,16,"לָ֣⁠מָּה יָשַׁ֗בְתָּ בֵּ֚ין הַֽ⁠מִּשְׁפְּתַ֔יִם לִ⁠שְׁמֹ֖עַ שְׁרִק֣וֹת עֲדָרִ֑ים לִ⁠פְלַגּ֣וֹת רְאוּבֵ֔ן גְּדוֹלִ֖ים חִקְרֵי־לֵֽב׃","lá֣⁠má̇h yáşǎ֗bĕţá̇ bé֚̇yn haֽ⁠mi̇şĕ̌pĕ̇ţa֔yim li⁠şĕ̌mò֖ʻa şĕ̌riq֣wòţ ʻàdári֑ym li⁠pĕlaġ֣wòţ rĕʼẇbé֔n gĕ̇dwòli֖ym ẖiqĕréy-léֽb׃"],[5,17,"גִּלְעָ֗ד בְּ⁠עֵ֤בֶר הַ⁠יַּרְדֵּן֙ שָׁכֵ֔ן וְ⁠דָ֕ן לָ֥⁠מָּה יָג֖וּר אֳנִיּ֑וֹת אָשֵׁ֗ר יָשַׁב֙ לְ⁠ח֣וֹף יַמִּ֔ים וְ⁠עַ֥ל מִפְרָצָ֖י⁠ו יִשְׁכּֽוֹן׃","gi̇lĕʻá֗d bĕ̇⁠ʻé֤ber ha⁠yȧrĕdé̇n֙ şá̌ké֔n wĕ⁠dá֕n lá֥⁠má̇h yág֖ẇr ʼoniẏ֑wòţ ʼáşé̌֗r yáşǎb֙ lĕ⁠ẖ֣wòp yami̇֔ym wĕ⁠ʻa֥l mipĕráẕá֖y⁠w yişĕ̌kֽ̇wòn׃"],[5,18,"זְבֻל֗וּן עַ֣ם חֵרֵ֥ף נַפְשׁ֛⁠וֹ לָ⁠מ֖וּת וְ⁠נַפְתָּלִ֑י עַ֖ל מְרוֹמֵ֥י שָׂדֶֽה׃","zĕbul֗ẇn ʻa֣m ẖéré֥p napĕş֛̌⁠wò lá⁠m֖ẇţ wĕ⁠napĕţá̇li֑y ʻa֖l mĕrwòmé֥y şá̂deֽh׃"],[5,19,"בָּ֤אוּ מְלָכִים֙ נִלְחָ֔מוּ אָ֤ז נִלְחֲמוּ֙ מַלְכֵ֣י כְנַ֔עַן בְּ⁠תַעְנַ֖ךְ עַל־מֵ֣י מְגִדּ֑וֹ בֶּ֥צַע כֶּ֖סֶף לֹ֥א לָקָֽחוּ׃","bá֤̇ʼẇ mĕlákiym֙ nilĕẖá֔mẇ ʼá֤z nilĕẖàmẇ֙ malĕké֣y kĕna֔ʻan bĕ̇⁠ţaʻĕna֖kĕ ʻal-mé֣y mĕgiḋ֑wò bė֥ẕaʻ kė֖sep lò֥ʼ láqáֽẖẇ׃"],[5,20,"מִן־שָׁמַ֖יִם נִלְחָ֑מוּ הַ⁠כּֽוֹכָבִים֙ מִ⁠מְּסִלּוֹתָ֔⁠ם נִלְחֲמ֖וּ עִם־סִיסְרָֽא׃","min-şá̌ma֖yim nilĕẖá֑mẇ ha⁠kֽ̇wòkábiym֙ mi⁠mĕ̇sil̇wòţá֔⁠m nilĕẖàm֖ẇ ʻim-siysĕráֽʼ׃"],[5,21,"נַ֤חַל קִישׁוֹן֙ גְּרָפָ֔⁠ם נַ֥חַל קְדוּמִ֖ים נַ֣חַל קִישׁ֑וֹן תִּדְרְכִ֥י נַפְשִׁ֖⁠י עֹֽז׃","na֤ẖal qiyş̌wòn֙ gĕ̇rápá֔⁠m na֥ẖal qĕdẇmi֖ym na֣ẖal qiyş֑̌wòn ţi̇dĕrĕki֥y napĕşǐ֖⁠y ʻòֽz׃"],[5,22,"אָ֥ז הָלְמ֖וּ עִקְּבֵי־ס֑וּס מִֽ⁠דַּהֲר֖וֹת דַּהֲר֥וֹת אַבִּירָֽי⁠ו׃","ʼá֥z hálĕm֖ẇ ʻiqĕ̇béy-s֑ẇs miֽ⁠dȧhàr֖wòţ dȧhàr֥wòţ ʼabi̇yráֽy⁠w׃"],[5,23,"א֣וֹרוּ מֵר֗וֹז אָמַר֙ מַלְאַ֣ךְ יְהוָ֔ה אֹ֥רוּ אָר֖וֹר יֹשְׁבֶ֑י⁠הָ כִּ֤י לֹֽא־בָ֨אוּ֙ לְ⁠עֶזְרַ֣ת יְהוָ֔ה לְ⁠עֶזְרַ֥ת יְהוָ֖ה בַּ⁠גִּבּוֹרִֽים׃","ʼ֣wòrẇ mér֗wòz ʼámar֙ malĕʼa֣kĕ yĕhwá֔h ʼò֥rẇ ʼár֖wòr yòşĕ̌be֑y⁠há ki֤̇y lòֽʼ-bá֨ʼẇ֙ lĕ⁠ʻezĕra֣ţ yĕhwá֔h lĕ⁠ʻezĕra֥ţ yĕhwá֖h bȧ⁠gi̇ḃwòriֽym׃"],[5,24,"תְּבֹרַךְ֙ מִ⁠נָּשִׁ֔ים יָעֵ֕ל אֵ֖שֶׁת חֶ֣בֶר הַ⁠קֵּינִ֑י מִ⁠נָּשִׁ֥ים בָּ⁠אֹ֖הֶל תְּבֹרָֽךְ׃","ţĕ̇bòrakĕ֙ mi⁠ná̇şǐ֔ym yáʻé֕l ʼé֖şěţ ẖe֣ber ha⁠qé̇yni֑y mi⁠ná̇şǐ֥ym bá̇⁠ʼò֖hel ţĕ̇bòráֽkĕ׃"],[5,25,"מַ֥יִם שָׁאַ֖ל חָלָ֣ב נָתָ֑נָה בְּ⁠סֵ֥פֶל אַדִּירִ֖ים הִקְרִ֥יבָה חֶמְאָֽה׃","ma֥yim şá̌ʼa֖l ẖálá֣b náţá֑náh bĕ̇⁠sé֥pel ʼadi̇yri֖ym hiqĕri֥ybáh ẖemĕʼáֽh׃"],[5,26,"יָדָ⁠הּ֙ לַ⁠יָּתֵ֣ד תִּשְׁלַ֔חְנָה וִֽ⁠ימִינָ֖⁠הּ לְ⁠הַלְמ֣וּת עֲמֵלִ֑ים וְ⁠הָלְמָ֤ה סִֽיסְרָא֙ מָחֲקָ֣ה רֹאשׁ֔⁠וֹ וּ⁠מָחֲצָ֥ה וְ⁠חָלְפָ֖ה רַקָּתֽ⁠וֹ׃","yádá⁠ḣ֙ la⁠yá̇ţé֣d ţi̇şĕ̌la֔ẖĕnáh wiֽ⁠ymiyná֖⁠ḣ lĕ⁠halĕm֣ẇţ ʻàméli֑ym wĕ⁠hálĕmá֤h siֽysĕráʼ֙ máẖàqá֣h ròʼş̌֔⁠wò ẇ⁠máẖàẕá֥h wĕ⁠ẖálĕpá֖h raqá̇ţֽ⁠wò׃"],[5,27,"בֵּ֣ין רַגְלֶ֔י⁠הָ כָּרַ֥ע נָפַ֖ל שָׁכָ֑ב בֵּ֤ין רַגְלֶ֨י⁠הָ֙ כָּרַ֣ע נָפָ֔ל בַּ⁠אֲשֶׁ֣ר כָּרַ֔ע שָׁ֖ם נָפַ֥ל שָׁדֽוּד׃","bé֣̇yn ragĕle֔y⁠há ká̇ra֥ʻ nápa֖l şá̌ká֑b bé֤̇yn ragĕle֨y⁠há֙ ká̇ra֣ʻ nápá֔l bȧ⁠ʼàşě֣r ká̇ra֔ʻ şá֖̌m nápa֥l şá̌dֽẇd׃"],[5,28,"בְּעַד֩ הַ⁠חַלּ֨וֹן נִשְׁקְפָ֧ה וַ⁠תְּיַבֵּ֛ב אֵ֥ם סִֽיסְרָ֖א בְּעַ֣ד הָֽ⁠אֶשְׁנָ֑ב מַדּ֗וּעַ בֹּשֵׁ֤שׁ רִכְבּ⁠וֹ֙ לָ⁠ב֔וֹא מַדּ֣וּעַ אֶֽחֱר֔וּ פַּעֲמֵ֖י מַרְכְּבוֹתָֽי⁠ו׃","bĕ̇ʻad֩ ha⁠ẖal̇֨wòn nişĕ̌qĕpá֧h wa⁠ţĕ̇yabé֛̇b ʼé֥m siֽysĕrá֖ʼ bĕ̇ʻa֣d hֽá⁠ʼeşĕ̌ná֑b maḋ֗ẇʻa bò̇şé֤̌ş̌ rikĕḃ⁠wò֙ lá⁠b֔wòʼ maḋ֣ẇʻa ʼeֽẖèr֔ẇ pȧʻàmé֖y marĕkĕ̇bwòţáֽy⁠w׃"],[5,29,"חַכְמ֥וֹת שָׂרוֹתֶ֖י⁠הָ תַּעֲנֶ֑ינָּה אַף־הִ֕יא תָּשִׁ֥יב אֲמָרֶ֖י⁠הָ לָֽ⁠הּ׃","ẖakĕm֥wòţ şá̂rwòţe֖y⁠há ţȧʻàne֑yná̇h ʼap-hi֕yʼ ţá̇şǐ֥yb ʼàmáre֖y⁠há láֽ⁠ḣ׃"],[5,30,"הֲ⁠לֹ֨א יִמְצְא֜וּ יְחַלְּק֣וּ שָׁלָ֗ל רַ֤חַם רַחֲמָתַ֨יִם֙ לְ⁠רֹ֣אשׁ גֶּ֔בֶר שְׁלַ֤ל צְבָעִים֙ לְ⁠סִ֣יסְרָ֔א שְׁלַ֥ל צְבָעִ֖ים רִקְמָ֑ה צֶ֥בַע רִקְמָתַ֖יִם לְ⁠צַוְּארֵ֥י שָׁלָֽל׃","hà⁠lò֨ʼ yimĕẕĕʼ֜ẇ yĕẖalĕ̇q֣ẇ şá̌lá֗l ra֤ẖam raẖàmáţa֨yim֙ lĕ⁠rò֣ʼş̌ gė֔ber şĕ̌la֤l ẕĕbáʻiym֙ lĕ⁠si֣ysĕrá֔ʼ şĕ̌la֥l ẕĕbáʻi֖ym riqĕmá֑h ẕe֥baʻ riqĕmáţa֖yim lĕ⁠ẕawĕ̇ʼré֥y şá̌láֽl׃"],[5,31,"כֵּ֠ן יֹאבְד֤וּ כָל־אוֹיְבֶ֨י⁠ךָ֙ יְהוָ֔ה וְ⁠אֹ֣הֲבָ֔י⁠ו כְּ⁠צֵ֥את הַ⁠שֶּׁ֖מֶשׁ בִּ⁠גְבֻרָת֑⁠וֹ וַ⁠תִּשְׁקֹ֥ט הָ⁠אָ֖רֶץ אַרְבָּעִ֥ים שָׁנָֽה׃פ","ké̇֠n yòʼbĕd֤ẇ kál-ʼwòyĕbe֨y⁠ká֙ yĕhwá֔h wĕ⁠ʼò֣hàbá֔y⁠w kĕ̇⁠ẕé֥ʼţ ha⁠şė֖̌meş̌ bi̇⁠gĕburáţ֑⁠wò wa⁠ţi̇şĕ̌qò֥t há⁠ʼá֖reẕ ʼarĕbá̇ʻi֥ym şá̌náֽh׃p"],[6,1,"וַ⁠יַּעֲשׂ֧וּ בְנֵי־יִשְׂרָאֵ֛ל הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יִּתְּנֵ֧⁠ם יְהוָ֛ה בְּ⁠יַד־מִדְיָ֖ן שֶׁ֥בַע שָׁנִֽים׃","wa⁠yȧʻàş֧̂ẇ bĕnéy-yişĕ̂ráʼé֛l há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yi̇ţĕ̇né֧⁠m yĕhwá֛h bĕ̇⁠yad-midĕyá֖n şě֥baʻ şá̌niֽym׃"],[6,2,"וַ⁠תָּ֥עָז יַד־מִדְיָ֖ן עַל־יִשְׂרָאֵ֑ל מִ⁠פְּנֵ֨י מִדְיָ֜ן עָשֽׂוּ לָ⁠הֶ֣ם ׀ בְּנֵ֣י יִשְׂרָאֵ֗ל אֶת־הַ⁠מִּנְהָרוֹת֙ אֲשֶׁ֣ר בֶּֽ⁠הָרִ֔ים וְ⁠אֶת־הַ⁠מְּעָר֖וֹת וְ⁠אֶת־הַ⁠מְּצָדֽוֹת׃","wa⁠ţá֥̇ʻáz yad-midĕyá֖n ʻal-yişĕ̂ráʼé֑l mi⁠pĕ̇né֨y midĕyá֜n ʻáşֽ̂ẇ lá⁠he֣m ׀ bĕ̇né֣y yişĕ̂ráʼé֗l ʼeţ-ha⁠mi̇nĕhárwòţ֙ ʼàşě֣r bėֽ⁠hári֔ym wĕ⁠ʼeţ-ha⁠mĕ̇ʻár֖wòţ wĕ⁠ʼeţ-ha⁠mĕ̇ẕádֽwòţ׃"],[6,3,"וְ⁠הָיָ֖ה אִם־זָרַ֣ע יִשְׂרָאֵ֑ל וְ⁠עָלָ֨ה מִדְיָ֧ן וַֽ⁠עֲמָלֵ֛ק וּ⁠בְנֵי־קֶ֖דֶם וְ⁠עָל֥וּ עָלָֽי⁠ו׃","wĕ⁠háyá֖h ʼim-zára֣ʻ yişĕ̂ráʼé֑l wĕ⁠ʻálá֨h midĕyá֧n wֽa⁠ʻàmálé֛q ẇ⁠bĕnéy-qe֖dem wĕ⁠ʻál֥ẇ ʻáláֽy⁠w׃"],[6,4,"וַ⁠יַּחֲנ֣וּ עֲלֵי⁠הֶ֗ם וַ⁠יַּשְׁחִ֨יתוּ֙ אֶת־יְב֣וּל הָ⁠אָ֔רֶץ עַד־בּוֹאֲ⁠ךָ֖ עַזָּ֑ה וְ⁠לֹֽא־יַשְׁאִ֤ירוּ מִֽחְיָה֙ בְּ⁠יִשְׂרָאֵ֔ל וְ⁠שֶׂ֥ה וָ⁠שׁ֖וֹר וַ⁠חֲמֽוֹר׃","wa⁠yȧẖàn֣ẇ ʻàléy⁠he֗m wa⁠yȧşĕ̌ẖi֨yţẇ֙ ʼeţ-yĕb֣ẇl há⁠ʼá֔reẕ ʻad-ḃwòʼà⁠ká֖ ʻazá֑̇h wĕ⁠lòֽʼ-yaşĕ̌ʼi֤yrẇ miֽẖĕyáh֙ bĕ̇⁠yişĕ̂ráʼé֔l wĕ⁠şê֥h wá⁠ş֖̌wòr wa⁠ẖàmֽwòr׃"],[6,5,"כִּ֡י הֵם֩ וּ⁠מִקְנֵי⁠הֶ֨ם יַעֲל֜וּ וְ⁠אָהֳלֵי⁠הֶ֗ם יבאו כְ⁠דֵֽי־אַרְבֶּה֙ לָ⁠רֹ֔ב וְ⁠לָ⁠הֶ֥ם וְ⁠לִ⁠גְמַלֵּי⁠הֶ֖ם אֵ֣ין מִסְפָּ֑ר וַ⁠יָּבֹ֥אוּ בָ⁠אָ֖רֶץ לְ⁠שַׁחֲתָֽ⁠הּ׃","ki̇֡y hém֩ ẇ⁠miqĕnéy⁠he֨m yaʻàl֜ẇ wĕ⁠ʼáholéy⁠he֗m ybʼw kĕ⁠déֽy-ʼarĕbėh֙ lá⁠rò֔b wĕ⁠lá⁠he֥m wĕ⁠li⁠gĕmalé̇y⁠he֖m ʼé֣yn misĕpá֑̇r wa⁠yá̇bò֥ʼẇ bá⁠ʼá֖reẕ lĕ⁠şǎẖàţáֽ⁠ḣ׃"],[6,6,"וַ⁠יִּדַּ֧ל יִשְׂרָאֵ֛ל מְאֹ֖ד מִ⁠פְּנֵ֣י מִדְיָ֑ן וַ⁠יִּזְעֲק֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל אֶל־יְהוָֽה׃פ","wa⁠yi̇dȧ֧l yişĕ̂ráʼé֛l mĕʼò֖d mi⁠pĕ̇né֣y midĕyá֑n wa⁠yi̇zĕʻàq֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l ʼel-yĕhwáֽh׃p"],[6,7,"וַ⁠יְהִ֕י כִּֽי־זָעֲק֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל אֶל־יְהוָ֑ה עַ֖ל אֹד֥וֹת מִדְיָֽן׃","wa⁠yĕhi֕y kiֽ̇y-záʻàq֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l ʼel-yĕhwá֑h ʻa֖l ʼòd֥wòţ midĕyáֽn׃"],[6,8,"וַ⁠יִּשְׁלַ֧ח יְהוָ֛ה אִ֥ישׁ נָבִ֖יא אֶל־בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יֹּ֨אמֶר לָ⁠הֶ֜ם כֹּה־אָמַ֥ר יְהוָ֣ה ׀ אֱלֹהֵ֣י יִשְׂרָאֵ֗ל אָנֹכִ֞י הֶעֱלֵ֤יתִי אֶתְ⁠כֶם֙ מִ⁠מִּצְרַ֔יִם וָ⁠אֹצִ֥יא אֶתְ⁠כֶ֖ם מִ⁠בֵּ֥ית עֲבָדִֽים׃","wa⁠yi̇şĕ̌la֧ẖ yĕhwá֛h ʼi֥yş̌ nábi֖yʼ ʼel-bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yò̇֨ʼmer lá⁠he֜m kò̇h-ʼáma֥r yĕhwá֣h ׀ ʼèlòhé֣y yişĕ̂ráʼé֗l ʼánòki֞y heʻèlé֤yţiy ʼeţĕ⁠kem֙ mi⁠mi̇ẕĕra֔yim wá⁠ʼòẕi֥yʼ ʼeţĕ⁠ke֖m mi⁠bé֥̇yţ ʻàbádiֽym׃"],[6,9,"וָ⁠אַצִּ֤ל אֶתְ⁠כֶם֙ מִ⁠יַּ֣ד מִצְרַ֔יִם וּ⁠מִ⁠יַּ֖ד כָּל־לֹחֲצֵי⁠כֶ֑ם וָ⁠אֲגָרֵ֤שׁ אוֹתָ⁠ם֙ מִ⁠פְּנֵי⁠כֶ֔ם וָ⁠אֶתְּנָ֥⁠ה לָ⁠כֶ֖ם אֶת־אַרְצָֽ⁠ם׃","wá⁠ʼaẕi֤̇l ʼeţĕ⁠kem֙ mi⁠yȧ֣d miẕĕra֔yim ẇ⁠mi⁠yȧ֖d ká̇l-lòẖàẕéy⁠ke֑m wá⁠ʼàgáré֤ş̌ ʼwòţá⁠m֙ mi⁠pĕ̇néy⁠ke֔m wá⁠ʼeţĕ̇ná֥⁠h lá⁠ke֖m ʼeţ-ʼarĕẕáֽ⁠m׃"],[6,10,"וָ⁠אֹמְרָ֣⁠ה לָ⁠כֶ֗ם אֲנִי֙ יְהוָ֣ה אֱלֹהֵי⁠כֶ֔ם לֹ֤א תִֽירְאוּ֙ אֶת־אֱלֹהֵ֣י הָ⁠אֱמֹרִ֔י אֲשֶׁ֥ר אַתֶּ֖ם יוֹשְׁבִ֣ים בְּ⁠אַרְצָ֑⁠ם וְ⁠לֹ֥א שְׁמַעְתֶּ֖ם בְּ⁠קוֹלִֽ⁠י׃פ","wá⁠ʼòmĕrá֣⁠h lá⁠ke֗m ʼàniy֙ yĕhwá֣h ʼèlòhéy⁠ke֔m lò֤ʼ ţiֽyrĕʼẇ֙ ʼeţ-ʼèlòhé֣y há⁠ʼèmòri֔y ʼàşě֥r ʼaţė֖m ywòşĕ̌bi֣ym bĕ̇⁠ʼarĕẕá֑⁠m wĕ⁠lò֥ʼ şĕ̌maʻĕţė֖m bĕ̇⁠qwòliֽ⁠y׃p"],[6,11,"וַ⁠יָּבֹ֞א מַלְאַ֣ךְ יְהוָ֗ה וַ⁠יֵּ֨שֶׁב֙ תַּ֤חַת הָֽ⁠אֵלָה֙ אֲשֶׁ֣ר בְּ⁠עָפְרָ֔ה אֲשֶׁ֥ר לְ⁠יוֹאָ֖שׁ אֲבִ֣י הָֽעֶזְרִ֑י וְ⁠גִדְע֣וֹן בְּנ֗⁠וֹ חֹבֵ֤ט חִטִּים֙ בַּ⁠גַּ֔ת לְ⁠הָנִ֖יס מִ⁠פְּנֵ֥י מִדְיָֽן׃","wa⁠yá̇bò֞ʼ malĕʼa֣kĕ yĕhwá֗h wa⁠yé̇֨şěb֙ ţȧ֤ẖaţ háֽ⁠ʼéláh֙ ʼàşě֣r bĕ̇⁠ʻápĕrá֔h ʼàşě֥r lĕ⁠ywòʼá֖ş̌ ʼàbi֣y háֽʻezĕri֑y wĕ⁠gidĕʻ֣wòn bĕ̇n֗⁠wò ẖòbé֤t ẖiti̇ym֙ bȧ⁠gȧ֔ţ lĕ⁠háni֖ys mi⁠pĕ̇né֥y midĕyáֽn׃"],[6,12,"וַ⁠יֵּרָ֥א אֵלָ֖י⁠ו מַלְּאַ֣ךְ יְהוָ֑ה וַ⁠יֹּ֣אמֶר אֵלָ֔י⁠ו יְהוָ֥ה עִמְּ⁠ךָ֖ גִּבּ֥וֹר הֶ⁠חָֽיִל׃","wa⁠yé̇rá֥ʼ ʼélá֖y⁠w malĕ̇ʼa֣kĕ yĕhwá֑h wa⁠yò֣̇ʼmer ʼélá֔y⁠w yĕhwá֥h ʻimĕ̇⁠ká֖ gi̇ḃ֥wòr he⁠ẖáֽyil׃"],[6,13,"וַ⁠יֹּ֨אמֶר אֵלָ֤י⁠ו גִּדְעוֹן֙ בִּ֣י אֲדֹנִ֔⁠י וְ⁠יֵ֤שׁ יְהוָה֙ עִמָּ֔⁠נוּ וְ⁠לָ֥⁠מָּה מְצָאַ֖תְ⁠נוּ כָּל־זֹ֑את וְ⁠אַיֵּ֣ה כָֽל־נִפְלְאֹתָ֡י⁠ו אֲשֶׁר֩ סִפְּרוּ־לָ֨⁠נוּ אֲבוֹתֵ֜י⁠נוּ לֵ⁠אמֹ֗ר הֲ⁠לֹ֤א מִ⁠מִּצְרַ֨יִם֙ הֶעֱלָ֣⁠נוּ יְהוָ֔ה וְ⁠עַתָּה֙ נְטָשָׁ֣⁠נוּ יְהוָ֔ה וַֽ⁠יִּתְּנֵ֖⁠נוּ בְּ⁠כַף־מִדְיָֽן׃","wa⁠yò̇֨ʼmer ʼélá֤y⁠w gi̇dĕʻwòn֙ bi֣̇y ʼàdòni֔⁠y wĕ⁠yé֤ş̌ yĕhwáh֙ ʻimá̇֔⁠nẇ wĕ⁠lá֥⁠má̇h mĕẕáʼa֖ţĕ⁠nẇ ká̇l-zò֑ʼţ wĕ⁠ʼayé֣̇h káֽl-nipĕlĕʼòţá֡y⁠w ʼàşěr֩ sipĕ̇rẇ-lá֨⁠nẇ ʼàbwòţé֜y⁠nẇ lé⁠ʼmò֗r hà⁠lò֤ʼ mi⁠mi̇ẕĕra֨yim֙ heʻèlá֣⁠nẇ yĕhwá֔h wĕ⁠ʻaţá̇h֙ nĕtáşá֣̌⁠nẇ yĕhwá֔h waֽ⁠yi̇ţĕ̇né֖⁠nẇ bĕ̇⁠kap-midĕyáֽn׃"],[6,14,"וַ⁠יִּ֤פֶן אֵלָי⁠ו֙ יְהוָ֔ה וַ⁠יֹּ֗אמֶר לֵ֚ךְ בְּ⁠כֹחֲ⁠ךָ֣ זֶ֔ה וְ⁠הוֹשַׁעְתָּ֥ אֶת־יִשְׂרָאֵ֖ל מִ⁠כַּ֣ף מִדְיָ֑ן הֲ⁠לֹ֖א שְׁלַחְתִּֽי⁠ךָ׃","wa⁠yi֤̇pen ʼéláy⁠w֙ yĕhwá֔h wa⁠yò̇֗ʼmer lé֚kĕ bĕ̇⁠kòẖà⁠ká֣ ze֔h wĕ⁠hwòşǎʻĕţá֥̇ ʼeţ-yişĕ̂ráʼé֖l mi⁠kȧ֣p midĕyá֑n hà⁠lò֖ʼ şĕ̌laẖĕţiֽ̇y⁠ká׃"],[6,15,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ בִּ֣י אֲדֹנָ֔⁠י בַּ⁠מָּ֥ה אוֹשִׁ֖יעַ אֶת־יִשְׂרָאֵ֑ל הִנֵּ֤ה אַלְפִּ⁠י֙ הַ⁠דַּ֣ל בִּ⁠מְנַשֶּׁ֔ה וְ⁠אָנֹכִ֥י הַ⁠צָּעִ֖יר בְּ⁠בֵ֥ית אָבִֽ⁠י׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ bi֣̇y ʼàdòná֔⁠y bȧ⁠má֥̇h ʼwòşǐ֖yʻa ʼeţ-yişĕ̂ráʼé֑l hiné֤̇h ʼalĕpi̇⁠y֙ ha⁠dȧ֣l bi̇⁠mĕnaşė̌֔h wĕ⁠ʼánòki֥y ha⁠ẕá̇ʻi֖yr bĕ̇⁠bé֥yţ ʼábiֽ⁠y׃"],[6,16,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ יְהוָ֔ה כִּ֥י אֶהְיֶ֖ה עִמָּ֑⁠ךְ וְ⁠הִכִּיתָ֥ אֶת־מִדְיָ֖ן כְּ⁠אִ֥ישׁ אֶחָֽד׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ yĕhwá֔h ki֥̇y ʼehĕye֖h ʻimá֑̇⁠kĕ wĕ⁠hiki̇yţá֥ ʼeţ-midĕyá֖n kĕ̇⁠ʼi֥yş̌ ʼeẖáֽd׃"],[6,17,"וַ⁠יֹּ֣אמֶר אֵלָ֔י⁠ו אִם־נָ֛א מָצָ֥אתִי חֵ֖ן בְּ⁠עֵינֶ֑י⁠ךָ וְ⁠עָשִׂ֤יתָ לִּ⁠י֙ א֔וֹת שָׁ⁠אַתָּ֖ה מְדַבֵּ֥ר עִמִּֽ⁠י׃","wa⁠yò֣̇ʼmer ʼélá֔y⁠w ʼim-ná֛ʼ máẕá֥ʼţiy ẖé֖n bĕ̇⁠ʻéyne֑y⁠ká wĕ⁠ʻáşî֤yţá li̇⁠y֙ ʼ֔wòţ şá̌⁠ʼaţá֖̇h mĕdabé֥̇r ʻimiֽ̇⁠y׃"],[6,18,"אַל־נָ֨א תָמֻ֤שׁ מִ⁠זֶּה֙ עַד־בֹּאִ֣⁠י אֵלֶ֔י⁠ךָ וְ⁠הֹֽצֵאתִי֙ אֶת־מִנְחָתִ֔⁠י וְ⁠הִנַּחְתִּ֖י לְ⁠פָנֶ֑י⁠ךָ וַ⁠יֹּאמַ֕ר אָנֹכִ֥י אֵשֵׁ֖ב עַ֥ד שׁוּבֶֽ⁠ךָ׃","ʼal-ná֨ʼ ţámu֤ş̌ mi⁠zėh֙ ʻad-bò̇ʼi֣⁠y ʼéle֔y⁠ká wĕ⁠hòֽẕéʼţiy֙ ʼeţ-minĕẖáţi֔⁠y wĕ⁠hinȧẖĕţi֖̇y lĕ⁠páne֑y⁠ká wa⁠yò̇ʼma֕r ʼánòki֥y ʼéşé֖̌b ʻa֥d ş̌ẇbeֽ⁠ká׃"],[6,19,"וְ⁠גִדְע֣וֹן בָּ֗א וַ⁠יַּ֤עַשׂ גְּדִֽי־עִזִּים֙ וְ⁠אֵיפַת־קֶ֣מַח מַצּ֔וֹת הַ⁠בָּשָׂר֙ שָׂ֣ם בַּ⁠סַּ֔ל וְ⁠הַ⁠מָּרַ֖ק שָׂ֣ם בַּ⁠פָּר֑וּר וַ⁠יּוֹצֵ֥א אֵלָ֛י⁠ו אֶל־תַּ֥חַת הָ⁠אֵלָ֖ה וַ⁠יַּגַּֽשׁ׃ס","wĕ⁠gidĕʻ֣wòn bá̇֗ʼ wa⁠yȧ֤ʻaş̂ gĕ̇diֽy-ʻizi̇ym֙ wĕ⁠ʼéypaţ-qe֣maẖ maẕ̇֔wòţ ha⁠bá̇şá̂r֙ şá֣̂m bȧ⁠sȧ֔l wĕ⁠ha⁠má̇ra֖q şá֣̂m bȧ⁠pá̇r֑ẇr wa⁠ẏwòẕé֥ʼ ʼélá֛y⁠w ʼel-ţȧ֥ẖaţ há⁠ʼélá֖h wa⁠yȧgȧֽş̌׃s"],[6,20,"וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו מַלְאַ֣ךְ הָ⁠אֱלֹהִ֗ים קַ֣ח אֶת־הַ⁠בָּשָׂ֤ר וְ⁠אֶת־הַ⁠מַּצּוֹת֙ וְ⁠הַנַּח֙ אֶל־הַ⁠סֶּ֣לַע הַלָּ֔ז וְ⁠אֶת־הַ⁠מָּרַ֖ק שְׁפ֑וֹךְ וַ⁠יַּ֖עַשׂ כֵּֽן׃","wa⁠yò̇֨ʼmer ʼélá֜y⁠w malĕʼa֣kĕ há⁠ʼèlòhi֗ym qa֣ẖ ʼeţ-ha⁠bá̇şá֤̂r wĕ⁠ʼeţ-ha⁠mȧẕ̇wòţ֙ wĕ⁠hanȧẖ֙ ʼel-ha⁠sė֣laʻ halá̇֔z wĕ⁠ʼeţ-ha⁠má̇ra֖q şĕ̌p֑wòkĕ wa⁠yȧ֖ʻaş̂ kéֽ̇n׃"],[6,21,"וַ⁠יִּשְׁלַ֞ח מַלְאַ֣ךְ יְהוָ֗ה אֶת־קְצֵ֤ה הַ⁠מִּשְׁעֶ֨נֶת֙ אֲשֶׁ֣ר בְּ⁠יָד֔⁠וֹ וַ⁠יִּגַּ֥ע בַּ⁠בָּשָׂ֖ר וּ⁠בַ⁠מַּצּ֑וֹת וַ⁠תַּ֨עַל הָ⁠אֵ֜שׁ מִן־הַ⁠צּ֗וּר וַ⁠תֹּ֤אכַל אֶת־הַ⁠בָּשָׂר֙ וְ⁠אֶת־הַ⁠מַּצּ֔וֹת וּ⁠מַלְאַ֣ךְ יְהוָ֔ה הָלַ֖ךְ מֵ⁠עֵינָֽי⁠ו׃","wa⁠yi̇şĕ̌la֞ẖ malĕʼa֣kĕ yĕhwá֗h ʼeţ-qĕẕé֤h ha⁠mi̇şĕ̌ʻe֨neţ֙ ʼàşě֣r bĕ̇⁠yád֔⁠wò wa⁠yi̇gȧ֥ʻ bȧ⁠bá̇şá֖̂r ẇ⁠ba⁠mȧẕ֑̇wòţ wa⁠ţȧ֨ʻal há⁠ʼé֜ş̌ min-ha⁠ẕ̇֗ẇr wa⁠ţò֤̇ʼkal ʼeţ-ha⁠bá̇şá̂r֙ wĕ⁠ʼeţ-ha⁠mȧẕ̇֔wòţ ẇ⁠malĕʼa֣kĕ yĕhwá֔h hála֖kĕ mé⁠ʻéynáֽy⁠w׃"],[6,22,"וַ⁠יַּ֣רְא גִּדְע֔וֹן כִּֽי־מַלְאַ֥ךְ יְהוָ֖ה ה֑וּא ס וַ⁠יֹּ֣אמֶר גִּדְע֗וֹן אֲהָהּ֙ אֲדֹנָ֣⁠י יְהוִ֔ה כִּֽי־עַל־כֵּ֤ן רָאִ֨יתִי֙ מַלְאַ֣ךְ יְהוָ֔ה פָּנִ֖ים אֶל־פָּנִֽים׃","wa⁠yȧ֣rĕʼ gi̇dĕʻ֔wòn kiֽ̇y-malĕʼa֥kĕ yĕhwá֖h h֑ẇʼ s wa⁠yò֣̇ʼmer gi̇dĕʻ֗wòn ʼàháḣ֙ ʼàdòná֣⁠y yĕhwi֔h kiֽ̇y-ʻal-ké֤̇n ráʼi֨yţiy֙ malĕʼa֣kĕ yĕhwá֔h pá̇ni֖ym ʼel-pá̇niֽym׃"],[6,23,"וַ⁠יֹּ֨אמֶר ל֧⁠וֹ יְהוָ֛ה שָׁל֥וֹם לְ⁠ךָ֖ אַל־תִּירָ֑א לֹ֖א תָּמֽוּת׃","wa⁠yò̇֨ʼmer l֧⁠wò yĕhwá֛h şá̌l֥wòm lĕ⁠ká֖ ʼal-ţi̇yrá֑ʼ lò֖ʼ ţá̇mֽẇţ׃"],[6,24,"וַ⁠יִּבֶן֩ שָׁ֨ם גִּדְע֤וֹן מִזְבֵּ֨חַ֙ לַֽ⁠יהוָ֔ה וַ⁠יִּקְרָא־ל֥⁠וֹ יְהוָ֖ה שָׁל֑וֹם עַ֚ד הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה עוֹדֶ֕⁠נּוּ בְּ⁠עָפְרָ֖ת אֲבִ֥י הָעֶזְרִֽי׃פ","wa⁠yi̇ben֩ şá̌֨m gi̇dĕʻ֤wòn mizĕbé̇֨ẖa֙ laֽ⁠yhwá֔h wa⁠yi̇qĕráʼ-l֥⁠wò yĕhwá֖h şá̌l֑wòm ʻa֚d ha⁠ẏ֣wòm ha⁠zė֔h ʻwòde֕⁠ṅẇ bĕ̇⁠ʻápĕrá֖ţ ʼàbi֥y háʻezĕriֽy׃p"],[6,25,"וַ⁠יְהִי֮ בַּ⁠לַּ֣יְלָה הַ⁠הוּא֒ וַ⁠יֹּ֧אמֶר ל֣⁠וֹ יְהוָ֗ה קַ֤ח אֶת־פַּר־הַ⁠שּׁוֹר֙ אֲשֶׁ֣ר לְ⁠אָבִ֔י⁠ךָ וּ⁠פַ֥ר הַ⁠שֵּׁנִ֖י שֶׁ֣בַע שָׁנִ֑ים וְ⁠הָרַסְתָּ֗ אֶת־מִזְבַּ֤ח הַ⁠בַּ֨עַל֙ אֲשֶׁ֣ר לְ⁠אָבִ֔י⁠ךָ וְ⁠אֶת־הָ⁠אֲשֵׁרָ֥ה אֲשֶׁר־עָלָ֖י⁠ו תִּכְרֹֽת׃","wa⁠yĕhiy֮ bȧ⁠lȧ֣yĕláh ha⁠hẇʼ֒ wa⁠yò֧̇ʼmer l֣⁠wò yĕhwá֗h qa֤ẖ ʼeţ-pȧr-ha⁠ş̇̌wòr֙ ʼàşě֣r lĕ⁠ʼábi֔y⁠ká ẇ⁠pa֥r ha⁠şé̇̌ni֖y şě֣baʻ şá̌ni֑ym wĕ⁠hárasĕţá̇֗ ʼeţ-mizĕbȧ֤ẖ ha⁠bȧ֨ʻal֙ ʼàşě֣r lĕ⁠ʼábi֔y⁠ká wĕ⁠ʼeţ-há⁠ʼàşé̌rá֥h ʼàşěr-ʻálá֖y⁠w ţi̇kĕròֽţ׃"],[6,26,"וּ⁠בָנִ֨יתָ מִזְבֵּ֜חַ לַ⁠יהוָ֣ה אֱלֹהֶ֗י⁠ךָ עַ֣ל רֹ֧אשׁ הַ⁠מָּע֛וֹז הַ⁠זֶּ֖ה בַּ⁠מַּֽעֲרָכָ֑ה וְ⁠לָֽקַחְתָּ֙ אֶת־הַ⁠פָּ֣ר הַ⁠שֵּׁנִ֔י וְ⁠הַעֲלִ֣יתָ עוֹלָ֔ה בַּ⁠עֲצֵ֥י הָ⁠אֲשֵׁרָ֖ה אֲשֶׁ֥ר תִּכְרֹֽת׃","ẇ⁠báni֨yţá mizĕbé̇֜ẖa la⁠yhwá֣h ʼèlòhe֗y⁠ká ʻa֣l rò֧ʼş̌ ha⁠má̇ʻ֛wòz ha⁠zė֖h bȧ⁠mȧֽʻàráká֑h wĕ⁠láֽqaẖĕţá̇֙ ʼeţ-ha⁠pá֣̇r ha⁠şé̇̌ni֔y wĕ⁠haʻàli֣yţá ʻwòlá֔h bȧ⁠ʻàẕé֥y há⁠ʼàşé̌rá֖h ʼàşě֥r ţi̇kĕròֽţ׃"],[6,27,"וַ⁠יִּקַּ֨ח גִּדְע֜וֹן עֲשָׂרָ֤ה אֲנָשִׁים֙ מֵֽ⁠עֲבָדָ֔י⁠ו וַ⁠יַּ֕עַשׂ כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר אֵלָ֖י⁠ו יְהוָ֑ה וַ⁠יְהִ֡י כַּ⁠אֲשֶׁ֣ר יָרֵא֩ אֶת־בֵּ֨ית אָבִ֜י⁠ו וְ⁠אֶת־אַנְשֵׁ֥י הָ⁠עִ֛יר מֵ⁠עֲשׂ֥וֹת יוֹמָ֖ם וַ⁠יַּ֥עַשׂ לָֽיְלָה׃","wa⁠yi̇qȧ֨ẖ gi̇dĕʻ֜wòn ʻàşá̂rá֤h ʼànáşǐym֙ méֽ⁠ʻàbádá֔y⁠w wa⁠yȧ֕ʻaş̂ kȧ⁠ʼàşě֛r di̇bė֥r ʼélá֖y⁠w yĕhwá֑h wa⁠yĕhi֡y kȧ⁠ʼàşě֣r yáréʼ֩ ʼeţ-bé̇֨yţ ʼábi֜y⁠w wĕ⁠ʼeţ-ʼanĕşé֥̌y há⁠ʻi֛yr mé⁠ʻàş֥̂wòţ ywòmá֖m wa⁠yȧ֥ʻaş̂ láֽyĕláh׃"],[6,28,"וַ⁠יַּשְׁכִּ֜ימוּ אַנְשֵׁ֤י הָ⁠עִיר֙ בַּ⁠בֹּ֔קֶר וְ⁠הִנֵּ֤ה נֻתַּץ֙ מִזְבַּ֣ח הַ⁠בַּ֔עַל וְ⁠הָ⁠אֲשֵׁרָ֥ה אֲשֶׁר־עָלָ֖י⁠ו כֹּרָ֑תָה וְ⁠אֵת֙ הַ⁠פָּ֣ר הַ⁠שֵּׁנִ֔י הֹֽעֲלָ֔ה עַל־הַ⁠מִּזְבֵּ֖חַ הַ⁠בָּנֽוּי׃","wa⁠yȧşĕ̌ki̇֜ymẇ ʼanĕşé֤̌y há⁠ʻiyr֙ bȧ⁠bò̇֔qer wĕ⁠hiné֤̇h nuţȧẕ֙ mizĕbȧ֣ẖ ha⁠bȧ֔ʻal wĕ⁠há⁠ʼàşé̌rá֥h ʼàşěr-ʻálá֖y⁠w kò̇rá֑ţáh wĕ⁠ʼéţ֙ ha⁠pá֣̇r ha⁠şé̇̌ni֔y hòֽʻàlá֔h ʻal-ha⁠mi̇zĕbé֖̇ẖa ha⁠bá̇nֽẇy׃"],[6,29,"וַ⁠יֹּֽאמְרוּ֙ אִ֣ישׁ אֶל־רֵעֵ֔⁠הוּ מִ֥י עָשָׂ֖ה הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וַֽ⁠יִּדְרְשׁוּ֙ וַ⁠יְבַקְשׁ֔וּ וַ⁠יֹּ֣אמְר֔וּ גִּדְעוֹן֙ בֶּן־יוֹאָ֔שׁ עָשָׂ֖ה הַ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","wa⁠yòֽ̇ʼmĕrẇ֙ ʼi֣yş̌ ʼel-réʻé֔⁠hẇ mi֥y ʻáşá֖̂h ha⁠dá̇bá֣r ha⁠zė֑h waֽ⁠yi̇dĕrĕş̌ẇ֙ wa⁠yĕbaqĕş̌֔ẇ wa⁠yò֣̇ʼmĕr֔ẇ gi̇dĕʻwòn֙ bėn-ywòʼá֔ş̌ ʻáşá֖̂h ha⁠dá̇bá֥r ha⁠zėֽh׃"],[6,30,"וַ⁠יֹּ֨אמְר֜וּ אַנְשֵׁ֤י הָ⁠עִיר֙ אֶל־יוֹאָ֔שׁ הוֹצֵ֥א אֶת־בִּנְ⁠ךָ֖ וְ⁠יָמֹ֑ת כִּ֤י נָתַץ֙ אֶת־מִזְבַּ֣ח הַ⁠בַּ֔עַל וְ⁠כִ֥י כָרַ֖ת הָ⁠אֲשֵׁרָ֥ה אֲשֶׁר־עָלָֽי⁠ו׃","wa⁠yò̇֨ʼmĕr֜ẇ ʼanĕşé֤̌y há⁠ʻiyr֙ ʼel-ywòʼá֔ş̌ hwòẕé֥ʼ ʼeţ-bi̇nĕ⁠ká֖ wĕ⁠yámò֑ţ ki֤̇y náţaẕ֙ ʼeţ-mizĕbȧ֣ẖ ha⁠bȧ֔ʻal wĕ⁠ki֥y kára֖ţ há⁠ʼàşé̌rá֥h ʼàşěr-ʻáláֽy⁠w׃"],[6,31,"וַ⁠יֹּ֣אמֶר יוֹאָ֡שׁ לְ⁠כֹל֩ אֲשֶׁר־עָמְד֨וּ עָלָ֜י⁠ו הַ⁠אַתֶּ֣ם ׀ תְּרִיב֣וּ⁠ן לַ⁠בַּ֗עַל אִם־אַתֶּם֙ תּוֹשִׁיע֣וּ⁠ן אוֹת֔⁠וֹ אֲשֶׁ֨ר יָרִ֥יב ל֛⁠וֹ יוּמַ֖ת עַד־הַ⁠בֹּ֑קֶר אִם־אֱלֹהִ֥ים הוּא֙ יָ֣רֶב ל֔⁠וֹ כִּ֥י נָתַ֖ץ אֶֽת־מִזְבְּחֽ⁠וֹ׃","wa⁠yò֣̇ʼmer ywòʼá֡ş̌ lĕ⁠kòl֩ ʼàşěr-ʻámĕd֨ẇ ʻálá֜y⁠w ha⁠ʼaţė֣m ׀ ţĕ̇riyb֣ẇ⁠n la⁠bȧ֗ʻal ʼim-ʼaţėm֙ ţ̇wòşǐyʻ֣ẇ⁠n ʼwòţ֔⁠wò ʼàşě֨r yári֥yb l֛⁠wò yẇma֖ţ ʻad-ha⁠bò֑̇qer ʼim-ʼèlòhi֥ym hẇʼ֙ yá֣reb l֔⁠wò ki֥̇y náţa֖ẕ ʼeֽţ-mizĕbĕ̇ẖֽ⁠wò׃"],[6,32,"וַ⁠יִּקְרָא־ל֥⁠וֹ בַ⁠יּוֹם־הַ⁠ה֖וּא יְרֻבַּ֣עַל לֵ⁠אמֹ֑ר יָ֤רֶב בּ⁠וֹ֙ הַ⁠בַּ֔עַל כִּ֥י נָתַ֖ץ אֶֽת־מִזְבְּחֽ⁠וֹ׃פ","wa⁠yi̇qĕráʼ-l֥⁠wò ba⁠ẏwòm-ha⁠h֖ẇʼ yĕrubȧ֣ʻal lé⁠ʼmò֑r yá֤reb ḃ⁠wò֙ ha⁠bȧ֔ʻal ki֥̇y náţa֖ẕ ʼeֽţ-mizĕbĕ̇ẖֽ⁠wò׃p"],[6,33,"וְ⁠כָל־מִדְיָ֧ן וַ⁠עֲמָלֵ֛ק וּ⁠בְנֵי־קֶ֖דֶם נֶאֶסְפ֣וּ יַחְדָּ֑ו וַ⁠יַּעַבְר֥וּ וַֽ⁠יַּחֲנ֖וּ בְּ⁠עֵ֥מֶק יִזְרְעֶֽאל׃","wĕ⁠kál-midĕyá֧n wa⁠ʻàmálé֛q ẇ⁠bĕnéy-qe֖dem neʼesĕp֣ẇ yaẖĕdá֑̇w wa⁠yȧʻabĕr֥ẇ waֽ⁠yȧẖàn֖ẇ bĕ̇⁠ʻé֥meq yizĕrĕʻeֽʼl׃"],[6,34,"וְ⁠ר֣וּחַ יְהוָ֔ה לָבְשָׁ֖ה אֶת־גִּדְע֑וֹן וַ⁠יִּתְקַע֙ בַּ⁠שּׁוֹפָ֔ר וַ⁠יִזָּעֵ֥ק אֲבִיעֶ֖זֶר אַחֲרָֽי⁠ו׃","wĕ⁠r֣ẇẖa yĕhwá֔h lábĕşá֖̌h ʼeţ-gi̇dĕʻ֑wòn wa⁠yi̇ţĕqaʻ֙ bȧ⁠ş̇̌wòpá֔r wa⁠yizá̇ʻé֥q ʼàbiyʻe֖zer ʼaẖàráֽy⁠w׃"],[6,35,"וּ⁠מַלְאָכִים֙ שָׁלַ֣ח בְּ⁠כָל־מְנַשֶּׁ֔ה וַ⁠יִזָּעֵ֥ק גַּם־ה֖וּא אַחֲרָ֑י⁠ו וּ⁠מַלְאָכִ֣ים שָׁלַ֗ח בְּ⁠אָשֵׁ֤ר וּ⁠בִ⁠זְבֻלוּן֙ וּ⁠בְ⁠נַפְתָּלִ֔י וַֽ⁠יַּעֲל֖וּ לִ⁠קְרָאתָֽ⁠ם׃","ẇ⁠malĕʼákiym֙ şá̌la֣ẖ bĕ̇⁠kál-mĕnaşė̌֔h wa⁠yizá̇ʻé֥q gȧm-h֖ẇʼ ʼaẖàrá֑y⁠w ẇ⁠malĕʼáki֣ym şá̌la֗ẖ bĕ̇⁠ʼáşé֤̌r ẇ⁠bi⁠zĕbulẇn֙ ẇ⁠bĕ⁠napĕţá̇li֔y waֽ⁠yȧʻàl֖ẇ li⁠qĕráʼţáֽ⁠m׃"],[6,36,"וַ⁠יֹּ֥אמֶר גִּדְע֖וֹן אֶל־הָ⁠אֱלֹהִ֑ים אִם־יֶשְׁ⁠ךָ֞ מוֹשִׁ֧יעַ בְּ⁠יָדִ֛⁠י אֶת־יִשְׂרָאֵ֖ל כַּ⁠אֲשֶׁ֥ר דִּבַּֽרְתָּ׃","wa⁠yò֥̇ʼmer gi̇dĕʻ֖wòn ʼel-há⁠ʼèlòhi֑ym ʼim-yeşĕ̌⁠ká֞ mwòşǐ֧yʻa bĕ̇⁠yádi֛⁠y ʼeţ-yişĕ̂ráʼé֖l kȧ⁠ʼàşě֥r di̇bȧֽrĕţá̇׃"],[6,37,"הִנֵּ֣ה אָנֹכִ֗י מַצִּ֛יג אֶת־גִּזַּ֥ת הַ⁠צֶּ֖מֶר בַּ⁠גֹּ֑רֶן אִ֡ם טַל֩ יִהְיֶ֨ה עַֽל־הַ⁠גִּזָּ֜ה לְ⁠בַדָּ֗⁠הּ וְ⁠עַל־כָּל־הָ⁠אָ֨רֶץ֙ חֹ֔רֶב וְ⁠יָדַעְתִּ֗י כִּֽי־תוֹשִׁ֧יעַ בְּ⁠יָדִ֛⁠י אֶת־יִשְׂרָאֵ֖ל כַּ⁠אֲשֶׁ֥ר דִּבַּֽרְתָּ׃","hiné֣̇h ʼánòki֗y maẕi֛̇yg ʼeţ-gi̇zȧ֥ţ ha⁠ẕė֖mer bȧ⁠gò֑̇ren ʼi֡m tal֩ yihĕye֨h ʻaֽl-ha⁠gi̇zá̇֜h lĕ⁠badá̇֗⁠ḣ wĕ⁠ʻal-ká̇l-há⁠ʼá֨reẕ֙ ẖò֔reb wĕ⁠yádaʻĕţi̇֗y kiֽ̇y-ţwòşǐ֧yʻa bĕ̇⁠yádi֛⁠y ʼeţ-yişĕ̂ráʼé֖l kȧ⁠ʼàşě֥r di̇bȧֽrĕţá̇׃"],[6,38,"וַ⁠יְהִי־כֵ֕ן וַ⁠יַּשְׁכֵּם֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יָּ֖זַר אֶת־הַ⁠גִּזָּ֑ה וַ⁠יִּ֤מֶץ טַל֙ מִן־הַ⁠גִּזָּ֔ה מְל֥וֹא הַ⁠סֵּ֖פֶל מָֽיִם׃","wa⁠yĕhiy-ké֕n wa⁠yȧşĕ̌ké̇m֙ miֽ⁠má̇ẖorá֔ţ wa⁠yá֖̇zar ʼeţ-ha⁠gi̇zá֑̇h wa⁠yi֤̇meẕ tal֙ min-ha⁠gi̇zá̇֔h mĕl֥wòʼ ha⁠sé֖̇pel máֽyim׃"],[6,39,"וַ⁠יֹּ֤אמֶר גִּדְעוֹן֙ אֶל־הָ֣⁠אֱלֹהִ֔ים אַל־יִ֤חַר אַפְּ⁠ךָ֙ בִּ֔⁠י וַ⁠אֲדַבְּרָ֖ה אַ֣ךְ הַ⁠פָּ֑עַם אֲנַסֶּ֤ה נָּא־רַק־הַ⁠פַּ֨עַם֙ בַּ⁠גִּזָּ֔ה יְהִי־נָ֨א חֹ֤רֶב אֶל־הַ⁠גִּזָּה֙ לְ⁠בַדָּ֔⁠הּ וְ⁠עַל־כָּל־הָ⁠אָ֖רֶץ יִֽהְיֶה־טָּֽל׃","wa⁠yò֤̇ʼmer gi̇dĕʻwòn֙ ʼel-há֣⁠ʼèlòhi֔ym ʼal-yi֤ẖar ʼapĕ̇⁠ká֙ bi̇֔⁠y wa⁠ʼàdabĕ̇rá֖h ʼa֣kĕ ha⁠pá֑̇ʻam ʼànasė֤h ná̇ʼ-raq-ha⁠pȧ֨ʻam֙ bȧ⁠gi̇zá̇֔h yĕhiy-ná֨ʼ ẖò֤reb ʼel-ha⁠gi̇zá̇h֙ lĕ⁠badá̇֔⁠ḣ wĕ⁠ʻal-ká̇l-há⁠ʼá֖reẕ yiֽhĕyeh-táֽ̇l׃"],[6,40,"וַ⁠יַּ֧עַשׂ אֱלֹהִ֛ים כֵּ֖ן בַּ⁠לַּ֣יְלָה הַ⁠ה֑וּא וַ⁠יְהִי־חֹ֤רֶב אֶל־הַ⁠גִּזָּה֙ לְ⁠בַדָּ֔⁠הּ וְ⁠עַל־כָּל־הָ⁠אָ֖רֶץ הָ֥יָה טָֽל׃פ","wa⁠yȧ֧ʻaş̂ ʼèlòhi֛ym ké֖̇n bȧ⁠lȧ֣yĕláh ha⁠h֑ẇʼ wa⁠yĕhiy-ẖò֤reb ʼel-ha⁠gi̇zá̇h֙ lĕ⁠badá̇֔⁠ḣ wĕ⁠ʻal-ká̇l-há⁠ʼá֖reẕ há֥yáh táֽl׃p"],[7,1,"וַ⁠יַּשְׁכֵּ֨ם יְרֻבַּ֜עַל ה֣וּא גִדְע֗וֹן וְ⁠כָל־הָ⁠עָם֙ אֲשֶׁ֣ר אִתּ֔⁠וֹ וַֽ⁠יַּחֲנ֖וּ עַל־עֵ֣ין חֲרֹ֑ד וּ⁠מַחֲנֵ֤ה מִדְיָן֙ הָיָה־ל֣⁠וֹ מִ⁠צָּפ֔וֹן מִ⁠גִּבְעַ֥ת הַ⁠מּוֹרֶ֖ה בָּ⁠עֵֽמֶק׃","wa⁠yȧşĕ̌ké̇֨m yĕrubȧ֜ʻal h֣ẇʼ gidĕʻ֗wòn wĕ⁠kál-há⁠ʻám֙ ʼàşě֣r ʼiţ̇֔⁠wò waֽ⁠yȧẖàn֖ẇ ʻal-ʻé֣yn ẖàrò֑d ẇ⁠maẖàné֤h midĕyán֙ háyáh-l֣⁠wò mi⁠ẕá̇p֔wòn mi⁠gi̇bĕʻa֥ţ ha⁠ṁwòre֖h bá̇⁠ʻéֽmeq׃"],[7,2,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־גִּדְע֔וֹן רַ֗ב הָ⁠עָם֙ אֲשֶׁ֣ר אִתָּ֔⁠ךְ מִ⁠תִּתִּ֥⁠י אֶת־מִדְיָ֖ן בְּ⁠יָדָ֑⁠ם פֶּן־יִתְפָּאֵ֨ר עָלַ֤⁠י יִשְׂרָאֵל֙ לֵ⁠אמֹ֔ר יָדִ֖⁠י הוֹשִׁ֥יעָה לִּֽ⁠י׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-gi̇dĕʻ֔wòn ra֗b há⁠ʻám֙ ʼàşě֣r ʼiţá̇֔⁠kĕ mi⁠ţi̇ţi֥̇⁠y ʼeţ-midĕyá֖n bĕ̇⁠yádá֑⁠m pėn-yiţĕpá̇ʼé֨r ʻála֤⁠y yişĕ̂ráʼél֙ lé⁠ʼmò֔r yádi֖⁠y hwòşǐ֥yʻáh liֽ̇⁠y׃"],[7,3,"וְ⁠עַתָּ֗ה קְרָ֨א נָ֜א בְּ⁠אָזְנֵ֤י הָ⁠עָם֙ לֵ⁠אמֹ֔ר מִֽי־יָרֵ֣א וְ⁠חָרֵ֔ד יָשֹׁ֥ב וְ⁠יִצְפֹּ֖ר מֵ⁠הַ֣ר הַ⁠גִּלְעָ֑ד וַ⁠יָּ֣שָׁב מִן־הָ⁠עָ֗ם עֶשְׂרִ֤ים וּ⁠שְׁנַ֨יִם֙ אֶ֔לֶף וַ⁠עֲשֶׂ֥רֶת אֲלָפִ֖ים נִשְׁאָֽרוּ׃ס","wĕ⁠ʻaţá̇֗h qĕrá֨ʼ ná֜ʼ bĕ̇⁠ʼázĕné֤y há⁠ʻám֙ lé⁠ʼmò֔r miֽy-yáré֣ʼ wĕ⁠ẖáré֔d yáşò֥̌b wĕ⁠yiẕĕpò֖̇r mé⁠ha֣r ha⁠gi̇lĕʻá֑d wa⁠yá֣̇şá̌b min-há⁠ʻá֗m ʻeşĕ̂ri֤ym ẇ⁠şĕ̌na֨yim֙ ʼe֔lep wa⁠ʻàşê֥reţ ʼàlápi֖ym nişĕ̌ʼáֽrẇ׃s"],[7,4,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־גִּדְע֗וֹן עוֹד֮ הָ⁠עָ֣ם רָב֒ הוֹרֵ֤ד אוֹתָ⁠ם֙ אֶל־הַ⁠מַּ֔יִם וְ⁠אֶצְרְפֶ֥⁠נּוּ לְ⁠ךָ֖ שָׁ֑ם וְ⁠הָיָ֡ה אֲשֶׁר֩ אֹמַ֨ר אֵלֶ֜י⁠ךָ זֶ֣ה ׀ יֵלֵ֣ךְ אִתָּ֗⁠ךְ ה֚וּא יֵלֵ֣ךְ אִתָּ֔⁠ךְ וְ⁠כֹ֨ל אֲשֶׁר־אֹמַ֜ר אֵלֶ֗י⁠ךָ זֶ֚ה לֹא־יֵלֵ֣ךְ עִמָּ֔⁠ךְ ה֖וּא לֹ֥א יֵלֵֽךְ׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-gi̇dĕʻ֗wòn ʻwòd֮ há⁠ʻá֣m ráb֒ hwòré֤d ʼwòţá⁠m֙ ʼel-ha⁠mȧ֔yim wĕ⁠ʼeẕĕrĕpe֥⁠ṅẇ lĕ⁠ká֖ şá֑̌m wĕ⁠háyá֡h ʼàşěr֩ ʼòma֨r ʼéle֜y⁠ká ze֣h ׀ yélé֣kĕ ʼiţá̇֗⁠kĕ h֚ẇʼ yélé֣kĕ ʼiţá̇֔⁠kĕ wĕ⁠kò֨l ʼàşěr-ʼòma֜r ʼéle֗y⁠ká ze֚h lòʼ-yélé֣kĕ ʻimá̇֔⁠kĕ h֖ẇʼ lò֥ʼ yéléֽkĕ׃"],[7,5,"וַ⁠יּ֥וֹרֶד אֶת־הָ⁠עָ֖ם אֶל־הַ⁠מָּ֑יִם ס וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־גִּדְע֗וֹן כֹּ֣ל אֲשֶׁר־יָלֹק֩ בִּ⁠לְשׁוֹנ֨⁠וֹ מִן־הַ⁠מַּ֜יִם כַּ⁠אֲשֶׁ֧ר יָלֹ֣ק הַ⁠כֶּ֗לֶב תַּצִּ֤יג אוֹת⁠וֹ֙ לְ⁠בָ֔ד וְ⁠כֹ֛ל אֲשֶׁר־יִכְרַ֥ע עַל־בִּרְכָּ֖י⁠ו לִ⁠שְׁתּֽוֹת׃","wa⁠ẏ֥wòred ʼeţ-há⁠ʻá֖m ʼel-ha⁠má֑̇yim s wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-gi̇dĕʻ֗wòn kò֣̇l ʼàşěr-yálòq֩ bi̇⁠lĕş̌wòn֨⁠wò min-ha⁠mȧ֜yim kȧ⁠ʼàşě֧r yálò֣q ha⁠kė֗leb ţȧẕi֤̇yg ʼwòţ⁠wò֙ lĕ⁠bá֔d wĕ⁠kò֛l ʼàşěr-yikĕra֥ʻ ʻal-bi̇rĕká֖̇y⁠w li⁠şĕ̌ţֽ̇wòţ׃"],[7,6,"וַ⁠יְהִ֗י מִסְפַּ֞ר הַֽ⁠מֲלַקְקִ֤ים בְּ⁠יָדָ⁠ם֙ אֶל־פִּי⁠הֶ֔ם שְׁלֹ֥שׁ מֵא֖וֹת אִ֑ישׁ וְ⁠כֹל֙ יֶ֣תֶר הָ⁠עָ֔ם כָּרְע֥וּ עַל־בִּרְכֵי⁠הֶ֖ם לִ⁠שְׁתּ֥וֹת מָֽיִם׃ס","wa⁠yĕhi֗y misĕpȧ֞r haֽ⁠màlaqĕqi֤ym bĕ̇⁠yádá⁠m֙ ʼel-pi̇y⁠he֔m şĕ̌lò֥ş̌ méʼ֖wòţ ʼi֑yş̌ wĕ⁠kòl֙ ye֣ţer há⁠ʻá֔m ká̇rĕʻ֥ẇ ʻal-bi̇rĕkéy⁠he֖m li⁠şĕ̌ţ֥̇wòţ máֽyim׃s"],[7,7,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־גִּדְע֗וֹן בִּ⁠שְׁלֹשׁ֩ מֵא֨וֹת הָ⁠אִ֤ישׁ הַֽ⁠מֲלַקְקִים֙ אוֹשִׁ֣יעַ אֶתְ⁠כֶ֔ם וְ⁠נָתַתִּ֥י אֶת־מִדְיָ֖ן בְּ⁠יָדֶ֑⁠ךָ וְ⁠כָל־הָ⁠עָ֔ם יֵלְכ֖וּ אִ֥ישׁ לִ⁠מְקֹמֽ⁠וֹ׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-gi̇dĕʻ֗wòn bi̇⁠şĕ̌lòş̌֩ méʼ֨wòţ há⁠ʼi֤yş̌ haֽ⁠màlaqĕqiym֙ ʼwòşǐ֣yʻa ʼeţĕ⁠ke֔m wĕ⁠náţaţi֥̇y ʼeţ-midĕyá֖n bĕ̇⁠yáde֑⁠ká wĕ⁠kál-há⁠ʻá֔m yélĕk֖ẇ ʼi֥yş̌ li⁠mĕqòmֽ⁠wò׃"],[7,8,"וַ⁠יִּקְח֣וּ אֶת־צֵדָה֩ הָ⁠עָ֨ם בְּ⁠יָדָ֜⁠ם וְ⁠אֵ֣ת שׁוֹפְרֹֽתֵי⁠הֶ֗ם וְ⁠אֵ֨ת כָּל־אִ֤ישׁ יִשְׂרָאֵל֙ שִׁלַּח֙ אִ֣ישׁ לְ⁠אֹֽהָלָ֔י⁠ו וּ⁠בִ⁠שְׁלֹשׁ־מֵא֥וֹת הָ⁠אִ֖ישׁ הֶֽחֱזִ֑יק וּ⁠מַחֲנֵ֣ה מִדְיָ֔ן הָ֥יָה ל֖⁠וֹ מִ⁠תַּ֥חַת בָּ⁠עֵֽמֶק׃פ","wa⁠yi̇qĕẖ֣ẇ ʼeţ-ẕédáh֩ há⁠ʻá֨m bĕ̇⁠yádá֜⁠m wĕ⁠ʼé֣ţ ş̌wòpĕròֽţéy⁠he֗m wĕ⁠ʼé֨ţ ká̇l-ʼi֤yş̌ yişĕ̂ráʼél֙ şǐlȧẖ֙ ʼi֣yş̌ lĕ⁠ʼòֽhálá֔y⁠w ẇ⁠bi⁠şĕ̌lòş̌-méʼ֥wòţ há⁠ʼi֖yş̌ hֽeẖèzi֑yq ẇ⁠maẖàné֣h midĕyá֔n há֥yáh l֖⁠wò mi⁠ţȧ֥ẖaţ bá̇⁠ʻéֽmeq׃p"],[7,9,"וַֽ⁠יְהִי֙ בַּ⁠לַּ֣יְלָה הַ⁠ה֔וּא וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ יְהוָ֔ה ק֖וּם רֵ֣ד בַּֽ⁠מַּחֲנֶ֑ה כִּ֥י נְתַתִּ֖י⁠ו בְּ⁠יָדֶֽ⁠ךָ׃","wֽa⁠yĕhiy֙ bȧ⁠lȧ֣yĕláh ha⁠h֔ẇʼ wa⁠yò֤̇ʼmer ʼéláy⁠w֙ yĕhwá֔h q֖ẇm ré֣d bȧֽ⁠mȧẖàne֑h ki֥̇y nĕţaţi֖̇y⁠w bĕ̇⁠yádeֽ⁠ká׃"],[7,10,"וְ⁠אִם־יָרֵ֥א אַתָּ֖ה לָ⁠רֶ֑דֶת רֵ֥ד אַתָּ֛ה וּ⁠פֻרָ֥ה נַעַרְ⁠ךָ֖ אֶל־הַֽ⁠מַּחֲנֶֽה׃","wĕ⁠ʼim-yáré֥ʼ ʼaţá֖̇h lá⁠re֑deţ ré֥d ʼaţá֛̇h ẇ⁠purá֥h naʻarĕ⁠ká֖ ʼel-haֽ⁠mȧẖàneֽh׃"],[7,11,"וְ⁠שָֽׁמַעְתָּ֙ מַה־יְדַבֵּ֔רוּ וְ⁠אַחַר֙ תֶּחֱזַ֣קְנָה יָדֶ֔י⁠ךָ וְ⁠יָרַדְתָּ֖ בַּֽ⁠מַּחֲנֶ֑ה וַ⁠יֵּ֤רֶד הוּא֙ וּ⁠פֻרָ֣ה נַעֲר֔⁠וֹ אֶל־קְצֵ֥ה הַ⁠חֲמֻשִׁ֖ים אֲשֶׁ֥ר בַּֽ⁠מַּחֲנֶֽה׃","wĕ⁠şáֽ̌maʻĕţá̇֙ mah-yĕdabé̇֔rẇ wĕ⁠ʼaẖar֙ ţėẖèza֣qĕnáh yáde֔y⁠ká wĕ⁠yáradĕţá֖̇ bȧֽ⁠mȧẖàne֑h wa⁠yé֤̇red hẇʼ֙ ẇ⁠purá֣h naʻàr֔⁠wò ʼel-qĕẕé֥h ha⁠ẖàmuşǐ֖ym ʼàşě֥r bȧֽ⁠mȧẖàneֽh׃"],[7,12,"וּ⁠מִדְיָ֨ן וַ⁠עֲמָלֵ֤ק וְ⁠כָל־בְּנֵי־קֶ֨דֶם֙ נֹפְלִ֣ים בָּ⁠עֵ֔מֶק כָּ⁠אַרְבֶּ֖ה לָ⁠רֹ֑ב וְ⁠לִ⁠גְמַלֵּי⁠הֶם֙ אֵ֣ין מִסְפָּ֔ר כַּ⁠ח֛וֹל שֶׁ⁠עַל־שְׂפַ֥ת הַ⁠יָּ֖ם לָ⁠רֹֽב׃","ẇ⁠midĕyá֨n wa⁠ʻàmálé֤q wĕ⁠kál-bĕ̇néy-qe֨dem֙ nòpĕli֣ym bá̇⁠ʻé֔meq ká̇⁠ʼarĕbė֖h lá⁠rò֑b wĕ⁠li⁠gĕmalé̇y⁠hem֙ ʼé֣yn misĕpá̇֔r kȧ⁠ẖ֛wòl şě⁠ʻal-şĕ̂pa֥ţ ha⁠yá֖̇m lá⁠ròֽb׃"],[7,13,"וַ⁠יָּבֹ֣א גִדְע֔וֹן וְ⁠הִ֨נֵּה־אִ֔ישׁ מְסַפֵּ֥ר לְ⁠רֵעֵ֖⁠הוּ חֲל֑וֹם וַ⁠יֹּ֜אמֶר הִנֵּ֧ה חֲל֣וֹם חָלַ֗מְתִּי וְ⁠הִנֵּ֨ה צלול לֶ֤חֶם שְׂעֹרִים֙ מִתְהַפֵּךְ֙ בְּ⁠מַחֲנֵ֣ה מִדְיָ֔ן וַ⁠יָּבֹ֣א עַד־הָ֠⁠אֹהֶל וַ⁠יַּכֵּ֧⁠הוּ וַ⁠יִּפֹּ֛ל וַ⁠יַּהַפְכֵ֥⁠הוּ לְ⁠מַ֖עְלָ⁠ה וְ⁠נָפַ֥ל הָ⁠אֹֽהֶל׃","wa⁠yá̇bò֣ʼ gidĕʻ֔wòn wĕ⁠hi֨né̇h-ʼi֔yş̌ mĕsapé֥̇r lĕ⁠réʻé֖⁠hẇ ẖàl֑wòm wa⁠yò̇֜ʼmer hiné֧̇h ẖàl֣wòm ẖála֗mĕţi̇y wĕ⁠hiné̇֨h ẕlwl le֤ẖem şĕ̂ʻòriym֙ miţĕhapé̇kĕ֙ bĕ̇⁠maẖàné֣h midĕyá֔n wa⁠yá̇bò֣ʼ ʻad-há֠⁠ʼòhel wa⁠yȧké֧̇⁠hẇ wa⁠yi̇pò֛̇l wa⁠yȧhapĕké֥⁠hẇ lĕ⁠ma֖ʻĕlá⁠h wĕ⁠nápa֥l há⁠ʼòֽhel׃"],[7,14,"וַ⁠יַּ֨עַן רֵעֵ֤⁠הוּ וַ⁠יֹּ֨אמֶר֙ אֵ֣ין זֹ֔את בִּלְתִּ֗י אִם־חֶ֛רֶב גִּדְע֥וֹן בֶּן־יוֹאָ֖שׁ אִ֣ישׁ יִשְׂרָאֵ֑ל נָתַ֤ן הָֽ⁠אֱלֹהִים֙ בְּ⁠יָד֔⁠וֹ אֶת־מִדְיָ֖ן וְ⁠אֶת־כָּל־הַֽ⁠מַּחֲנֶֽה׃פ","wa⁠yȧ֨ʻan réʻé֤⁠hẇ wa⁠yò̇֨ʼmer֙ ʼé֣yn zò֔ʼţ bi̇lĕţi̇֗y ʼim-ẖe֛reb gi̇dĕʻ֥wòn bėn-ywòʼá֖ş̌ ʼi֣yş̌ yişĕ̂ráʼé֑l náţa֤n háֽ⁠ʼèlòhiym֙ bĕ̇⁠yád֔⁠wò ʼeţ-midĕyá֖n wĕ⁠ʼeţ-ká̇l-haֽ⁠mȧẖàneֽh׃p"],[7,15,"וַ⁠יְהִי֩ כִ⁠שְׁמֹ֨עַ גִּדְע֜וֹן אֶת־מִסְפַּ֧ר הַ⁠חֲל֛וֹם וְ⁠אֶת־שִׁבְר֖⁠וֹ וַ⁠יִּשְׁתָּ֑חוּ וַ⁠יָּ֨שָׁב֙ אֶל־מַחֲנֵ֣ה יִשְׂרָאֵ֔ל וַ⁠יֹּ֣אמֶר ק֔וּמוּ כִּֽי־נָתַ֧ן יְהוָ֛ה בְּ⁠יֶדְ⁠כֶ֖ם אֶת־מַחֲנֵ֥ה מִדְיָֽן׃","wa⁠yĕhiy֩ ki⁠şĕ̌mò֨ʻa gi̇dĕʻ֜wòn ʼeţ-misĕpȧ֧r ha⁠ẖàl֛wòm wĕ⁠ʼeţ-şǐbĕr֖⁠wò wa⁠yi̇şĕ̌ţá֑̇ẖẇ wa⁠yá̇֨şá̌b֙ ʼel-maẖàné֣h yişĕ̂ráʼé֔l wa⁠yò֣̇ʼmer q֔ẇmẇ kiֽ̇y-náţa֧n yĕhwá֛h bĕ̇⁠yedĕ⁠ke֖m ʼeţ-maẖàné֥h midĕyáֽn׃"],[7,16,"וַ⁠יַּ֛חַץ אֶת־שְׁלֹשׁ־מֵא֥וֹת הָ⁠אִ֖ישׁ שְׁלֹשָׁ֣ה רָאשִׁ֑ים וַ⁠יִּתֵּ֨ן שׁוֹפָר֤וֹת בְּ⁠יַד־כֻּלָּ⁠ם֙ וְ⁠כַדִּ֣ים רֵקִ֔ים וְ⁠לַפִּדִ֖ים בְּ⁠ת֥וֹךְ הַ⁠כַּדִּֽים׃","wa⁠yȧ֛ẖaẕ ʼeţ-şĕ̌lòş̌-méʼ֥wòţ há⁠ʼi֖yş̌ şĕ̌lòşá֣̌h ráʼşǐ֑ym wa⁠yi̇ţé̇֨n ş̌wòpár֤wòţ bĕ̇⁠yad-ku̇lá̇⁠m֙ wĕ⁠kadi֣̇ym réqi֔ym wĕ⁠lapi̇di֖ym bĕ̇⁠ţ֥wòkĕ ha⁠kȧdiֽ̇ym׃"],[7,17,"וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֔ם מִמֶּ֥⁠נִּי תִרְא֖וּ וְ⁠כֵ֣ן תַּעֲשׂ֑וּ וְ⁠הִנֵּ֨ה אָנֹכִ֥י בָא֙ בִּ⁠קְצֵ֣ה הַֽ⁠מַּחֲנֶ֔ה וְ⁠הָיָ֥ה כַ⁠אֲשֶׁר־אֶעֱשֶׂ֖ה כֵּ֥ן תַּעֲשֽׂוּ⁠ן׃","wa⁠yò֣̇ʼmer ʼàléy⁠he֔m mimė֥⁠ni̇y ţirĕʼ֖ẇ wĕ⁠ké֣n ţȧʻàş֑̂ẇ wĕ⁠hiné̇֨h ʼánòki֥y báʼ֙ bi̇⁠qĕẕé֣h haֽ⁠mȧẖàne֔h wĕ⁠háyá֥h ka⁠ʼàşěr-ʼeʻèşê֖h ké֥̇n ţȧʻàşֽ̂ẇ⁠n׃"],[7,18,"וְ⁠תָקַעְתִּי֙ בַּ⁠שּׁוֹפָ֔ר אָנֹכִ֖י וְ⁠כָל־אֲשֶׁ֣ר אִתִּ֑⁠י וּ⁠תְקַעְתֶּ֨ם בַּ⁠שּׁוֹפָר֜וֹת גַּם־אַתֶּ֗ם סְבִיבוֹת֙ כָּל־הַֽ⁠מַּחֲנֶ֔ה וַ⁠אֲמַרְתֶּ֖ם לַ⁠יהוָ֥ה וּ⁠לְ⁠גִדְעֽוֹן׃פ","wĕ⁠ţáqaʻĕţi̇y֙ bȧ⁠ş̇̌wòpá֔r ʼánòki֖y wĕ⁠kál-ʼàşě֣r ʼiţi֑̇⁠y ẇ⁠ţĕqaʻĕţė֨m bȧ⁠ş̇̌wòpár֜wòţ gȧm-ʼaţė֗m sĕbiybwòţ֙ ká̇l-haֽ⁠mȧẖàne֔h wa⁠ʼàmarĕţė֖m la⁠yhwá֥h ẇ⁠lĕ⁠gidĕʻֽwòn׃p"],[7,19,"וַ⁠יָּבֹ֣א גִ֠דְעוֹן וּ⁠מֵאָה־אִ֨ישׁ אֲשֶׁר־אִתּ֜⁠וֹ בִּ⁠קְצֵ֣ה הַֽ⁠מַּחֲנֶ֗ה רֹ֚אשׁ הָ⁠אַשְׁמֹ֣רֶת הַ⁠תִּֽיכוֹנָ֔ה אַ֛ךְ הָקֵ֥ם הֵקִ֖ימוּ אֶת־הַ⁠שֹּֽׁמְרִ֑ים וַֽ⁠יִּתְקְעוּ֙ בַּ⁠שּׁ֣וֹפָר֔וֹת וְ⁠נָפ֥וֹץ הַ⁠כַּדִּ֖ים אֲשֶׁ֥ר בְּ⁠יָדָֽ⁠ם׃","wa⁠yá̇bò֣ʼ gi֠dĕʻwòn ẇ⁠méʼáh-ʼi֨yş̌ ʼàşěr-ʼiţ̇֜⁠wò bi̇⁠qĕẕé֣h haֽ⁠mȧẖàne֗h rò֚ʼş̌ há⁠ʼaşĕ̌mò֣reţ ha⁠ţiֽ̇ykwòná֔h ʼa֛kĕ háqé֥m héqi֖ymẇ ʼeţ-ha⁠şòֽ̇̌mĕri֑ym waֽ⁠yi̇ţĕqĕʻẇ֙ bȧ⁠ş֣̇̌wòpár֔wòţ wĕ⁠náp֥wòẕ ha⁠kȧdi֖̇ym ʼàşě֥r bĕ̇⁠yádáֽ⁠m׃"],[7,20,"וַֽ֠⁠יִּתְקְעוּ שְׁלֹ֨שֶׁת הָ⁠רָאשִׁ֥ים בַּ⁠שּֽׁוֹפָרוֹת֮ וַ⁠יִּשְׁבְּר֣וּ הַ⁠כַּדִּים֒ וַ⁠יַּחֲזִ֤יקוּ בְ⁠יַד־שְׂמאוֹלָ⁠ם֙ בַּ⁠לַּפִּדִ֔ים וּ⁠בְ⁠יַ֨ד־יְמִינָ֔⁠ם הַ⁠שּׁוֹפָר֖וֹת לִ⁠תְק֑וֹעַ וַֽ⁠יִּקְרְא֔וּ חֶ֥רֶב לַֽ⁠יהוָ֖ה וּ⁠לְ⁠גִדְעֽוֹן׃","waֽ֠⁠yi̇ţĕqĕʻẇ şĕ̌lò֨şěţ há⁠ráʼşǐ֥ym bȧ⁠şֽ̇̌wòpárwòţ֮ wa⁠yi̇şĕ̌bĕ̇r֣ẇ ha⁠kȧdi̇ym֒ wa⁠yȧẖàzi֤yqẇ bĕ⁠yad-şĕ̂mʼwòlá⁠m֙ bȧ⁠lȧpi̇di֔ym ẇ⁠bĕ⁠ya֨d-yĕmiyná֔⁠m ha⁠ş̇̌wòpár֖wòţ li⁠ţĕq֑wòʻa waֽ⁠yi̇qĕrĕʼ֔ẇ ẖe֥reb laֽ⁠yhwá֖h ẇ⁠lĕ⁠gidĕʻֽwòn׃"],[7,21,"וַ⁠יַּֽעַמְדוּ֙ אִ֣ישׁ תַּחְתָּ֔י⁠ו סָבִ֖יב לַֽ⁠מַּחֲנֶ֑ה וַ⁠יָּ֧רָץ כָּל־הַֽ⁠מַּחֲנֶ֛ה וַ⁠יָּרִ֖יעוּ ו⁠יניסו׃","wa⁠yȧֽʻamĕdẇ֙ ʼi֣yş̌ ţȧẖĕţá̇֔y⁠w sábi֖yb laֽ⁠mȧẖàne֑h wa⁠yá֧̇ráẕ ká̇l-haֽ⁠mȧẖàne֛h wa⁠yá̇ri֖yʻẇ w⁠ynysw׃"],[7,22,"וַֽ⁠יִּתְקְעוּ֮ שְׁלֹשׁ־מֵא֣וֹת הַ⁠שּׁוֹפָרוֹת֒ וַ⁠יָּ֣שֶׂם יְהוָ֗ה אֵ֣ת חֶ֥רֶב אִ֛ישׁ בְּ⁠רֵעֵ֖⁠הוּ וּ⁠בְ⁠כָל־הַֽ⁠מַּחֲנֶ֑ה וַ⁠יָּ֨נָס הַֽ⁠מַּחֲנֶ֜ה עַד־בֵּ֤ית הַשִּׁטָּה֙ צְֽרֵרָ֔תָ⁠ה עַ֛ד שְׂפַת־אָבֵ֥ל מְחוֹלָ֖ה עַל־טַבָּֽת׃","waֽ⁠yi̇ţĕqĕʻẇ֮ şĕ̌lòş̌-méʼ֣wòţ ha⁠ş̇̌wòpárwòţ֒ wa⁠yá֣̇şêm yĕhwá֗h ʼé֣ţ ẖe֥reb ʼi֛yş̌ bĕ̇⁠réʻé֖⁠hẇ ẇ⁠bĕ⁠kál-haֽ⁠mȧẖàne֑h wa⁠yá̇֨nás haֽ⁠mȧẖàne֜h ʻad-bé֤̇yţ haşi̇̌tá̇h֙ ẕĕֽrérá֔ţá⁠h ʻa֛d şĕ̂paţ-ʼábé֥l mĕẖwòlá֖h ʻal-tabáֽ̇ţ׃"],[7,23,"וַ⁠יִּצָּעֵ֧ק אִֽישׁ־יִשְׂרָאֵ֛ל מִ⁠נַּפְתָּלִ֥י וּ⁠מִן־אָשֵׁ֖ר וּ⁠מִן־כָּל־מְנַשֶּׁ֑ה וַֽ⁠יִּרְדְּפ֖וּ אַחֲרֵ֥י מִדְיָֽן׃","wa⁠yi̇ẕá̇ʻé֧q ʼiֽyş̌-yişĕ̂ráʼé֛l mi⁠nȧpĕţá̇li֥y ẇ⁠min-ʼáşé֖̌r ẇ⁠min-ká̇l-mĕnaşė֑̌h waֽ⁠yi̇rĕdĕ̇p֖ẇ ʼaẖàré֥y midĕyáֽn׃"],[7,24,"וּ⁠מַלְאָכִ֡ים שָׁלַ֣ח גִּדְעוֹן֩ בְּ⁠כָל־הַ֨ר אֶפְרַ֜יִם לֵ⁠אמֹ֗ר רְד֞וּ לִ⁠קְרַ֤את מִדְיָן֙ וְ⁠לִכְד֤וּ לָ⁠הֶם֙ אֶת־הַ⁠מַּ֔יִם עַ֛ד בֵּ֥ית בָּרָ֖ה וְ⁠אֶת־הַ⁠יַּרְדֵּ֑ן וַ⁠יִּצָּעֵ֞ק כָּל־אִ֤ישׁ אֶפְרַ֨יִם֙ וַ⁠יִּלְכְּד֣וּ אֶת־הַ⁠מַּ֔יִם עַ֛ד בֵּ֥ית בָּרָ֖ה וְ⁠אֶת־הַ⁠יַּרְדֵּֽן׃","ẇ⁠malĕʼáki֡ym şá̌la֣ẖ gi̇dĕʻwòn֩ bĕ̇⁠kál-ha֨r ʼepĕra֜yim lé⁠ʼmò֗r rĕd֞ẇ li⁠qĕra֤ʼţ midĕyán֙ wĕ⁠likĕd֤ẇ lá⁠hem֙ ʼeţ-ha⁠mȧ֔yim ʻa֛d bé֥̇yţ bá̇rá֖h wĕ⁠ʼeţ-ha⁠yȧrĕdé֑̇n wa⁠yi̇ẕá̇ʻé֞q ká̇l-ʼi֤yş̌ ʼepĕra֨yim֙ wa⁠yi̇lĕkĕ̇d֣ẇ ʼeţ-ha⁠mȧ֔yim ʻa֛d bé֥̇yţ bá̇rá֖h wĕ⁠ʼeţ-ha⁠yȧrĕdéֽ̇n׃"],[7,25,"וַֽ⁠יִּלְכְּד֡וּ שְׁנֵֽי־שָׂרֵ֨י מִדְיָ֜ן אֶת־עֹרֵ֣ב וְ⁠אֶת־זְאֵ֗ב וַ⁠יַּהַרְג֨וּ אֶת־עוֹרֵ֤ב בְּ⁠צוּר־עוֹרֵב֙ וְ⁠אֶת־זְאֵב֙ הָרְג֣וּ בְ⁠יֶֽקֶב־זְאֵ֔ב וַֽ⁠יִּרְדְּפ֖וּ אֶל־מִדְיָ֑ן וְ⁠רֹאשׁ־עֹרֵ֣ב וּ⁠זְאֵ֔ב הֵבִ֨יאוּ֙ אֶל־גִּדְע֔וֹן מֵ⁠עֵ֖בֶר לַ⁠יַּרְדֵּֽן׃","waֽ⁠yi̇lĕkĕ̇d֡ẇ şĕ̌néֽy-şá̂ré֨y midĕyá֜n ʼeţ-ʻòré֣b wĕ⁠ʼeţ-zĕʼé֗b wa⁠yȧharĕg֨ẇ ʼeţ-ʻwòré֤b bĕ̇⁠ẕẇr-ʻwòréb֙ wĕ⁠ʼeţ-zĕʼéb֙ hárĕg֣ẇ bĕ⁠yeֽqeb-zĕʼé֔b waֽ⁠yi̇rĕdĕ̇p֖ẇ ʼel-midĕyá֑n wĕ⁠ròʼş̌-ʻòré֣b ẇ⁠zĕʼé֔b hébi֨yʼẇ֙ ʼel-gi̇dĕʻ֔wòn mé⁠ʻé֖ber la⁠yȧrĕdéֽ̇n׃"],[8,1,"וַ⁠יֹּאמְר֨וּ אֵלָ֜י⁠ו אִ֣ישׁ אֶפְרַ֗יִם מָֽה־הַ⁠דָּבָ֤ר הַ⁠זֶּה֙ עָשִׂ֣יתָ לָּ֔⁠נוּ לְ⁠בִלְתִּי֙ קְרֹ֣אות לָ֔⁠נוּ כִּ֥י הָלַ֖כְתָּ לְ⁠הִלָּחֵ֣ם בְּ⁠מִדְיָ֑ן וַ⁠יְרִיב֥וּ⁠ן אִתּ֖⁠וֹ בְּ⁠חָזְקָֽה׃","wa⁠yò̇ʼmĕr֨ẇ ʼélá֜y⁠w ʼi֣yş̌ ʼepĕra֗yim máֽh-ha⁠dá̇bá֤r ha⁠zėh֙ ʻáşî֣yţá lá̇֔⁠nẇ lĕ⁠bilĕţi̇y֙ qĕrò֣ʼwţ lá֔⁠nẇ ki֥̇y hála֖kĕţá̇ lĕ⁠hilá̇ẖé֣m bĕ̇⁠midĕyá֑n wa⁠yĕriyb֥ẇ⁠n ʼiţ֖̇⁠wò bĕ̇⁠ẖázĕqáֽh׃"],[8,2,"וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֔ם מֶה־עָשִׂ֥יתִי עַתָּ֖ה כָּ⁠כֶ֑ם הֲ⁠ל֗וֹא ט֛וֹב עֹלְל֥וֹת אֶפְרַ֖יִם מִ⁠בְצִ֥יר אֲבִיעֶֽזֶר׃","wa⁠yò֣̇ʼmer ʼàléy⁠he֔m meh-ʻáşî֥yţiy ʻaţá֖̇h ká̇⁠ke֑m hà⁠l֗wòʼ t֛wòb ʻòlĕl֥wòţ ʼepĕra֖yim mi⁠bĕẕi֥yr ʼàbiyʻeֽzer׃"],[8,3,"בְּ⁠יֶדְ⁠כֶם֩ נָתַ֨ן אֱלֹהִ֜ים אֶת־שָׂרֵ֤י מִדְיָן֙ אֶת־עֹרֵ֣ב וְ⁠אֶת־זְאֵ֔ב וּ⁠מַה־יָּכֹ֖לְתִּי עֲשׂ֣וֹת כָּ⁠כֶ֑ם אָ֗ז רָפְתָ֤ה רוּחָ⁠ם֙ מֵֽ⁠עָלָ֔י⁠ו בְּ⁠דַבְּר֖⁠וֹ הַ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","bĕ̇⁠yedĕ⁠kem֩ náţa֨n ʼèlòhi֜ym ʼeţ-şá̂ré֤y midĕyán֙ ʼeţ-ʻòré֣b wĕ⁠ʼeţ-zĕʼé֔b ẇ⁠mah-yá̇kò֖lĕţi̇y ʻàş֣̂wòţ ká̇⁠ke֑m ʼá֗z rápĕţá֤h rẇẖá⁠m֙ méֽ⁠ʻálá֔y⁠w bĕ̇⁠dabĕ̇r֖⁠wò ha⁠dá̇bá֥r ha⁠zėֽh׃"],[8,4,"וַ⁠יָּבֹ֥א גִדְע֖וֹן הַ⁠יַּרְדֵּ֑נָ⁠ה עֹבֵ֣ר ה֗וּא וּ⁠שְׁלֹשׁ־מֵא֤וֹת הָ⁠אִישׁ֙ אֲשֶׁ֣ר אִתּ֔⁠וֹ עֲיֵפִ֖ים וְ⁠רֹדְפִֽים׃","wa⁠yá̇bò֥ʼ gidĕʻ֖wòn ha⁠yȧrĕdé֑̇ná⁠h ʻòbé֣r h֗ẇʼ ẇ⁠şĕ̌lòş̌-méʼ֤wòţ há⁠ʼiyş̌֙ ʼàşě֣r ʼiţ̇֔⁠wò ʻàyépi֖ym wĕ⁠ròdĕpiֽym׃"],[8,5,"וַ⁠יֹּ֨אמֶר֙ לְ⁠אַנְשֵׁ֣י סֻכּ֔וֹת תְּנוּ־נָא֙ כִּכְּר֣וֹת לֶ֔חֶם לָ⁠עָ֖ם אֲשֶׁ֣ר בְּ⁠רַגְלָ֑⁠י כִּי־עֲיֵפִ֣ים הֵ֔ם וְ⁠אָנֹכִ֗י רֹדֵ֛ף אַחֲרֵ֛י זֶ֥בַח וְ⁠צַלְמֻנָּ֖ע מַלְכֵ֥י מִדְיָֽן׃","wa⁠yò̇֨ʼmer֙ lĕ⁠ʼanĕşé֣̌y suk̇֔wòţ ţĕ̇nẇ-náʼ֙ ki̇kĕ̇r֣wòţ le֔ẖem lá⁠ʻá֖m ʼàşě֣r bĕ̇⁠ragĕlá֑⁠y ki̇y-ʻàyépi֣ym hé֔m wĕ⁠ʼánòki֗y ròdé֛p ʼaẖàré֛y ze֥baẖ wĕ⁠ẕalĕmuná֖̇ʻ malĕké֥y midĕyáֽn׃"],[8,6,"וַ⁠יֹּ֨אמֶר֙ שָׂרֵ֣י סֻכּ֔וֹת הֲ֠⁠כַף זֶ֧בַח וְ⁠צַלְמֻנָּ֛ע עַתָּ֖ה בְּ⁠יָדֶ֑⁠ךָ כִּֽי־נִתֵּ֥ן לִֽ⁠צְבָאֲ⁠ךָ֖ לָֽחֶם׃","wa⁠yò̇֨ʼmer֙ şá̂ré֣y suk̇֔wòţ hà֠⁠kap ze֧baẖ wĕ⁠ẕalĕmuná֛̇ʻ ʻaţá֖̇h bĕ̇⁠yáde֑⁠ká kiֽ̇y-niţé֥̇n liֽ⁠ẕĕbáʼà⁠ká֖ láֽẖem׃"],[8,7,"וַ⁠יֹּ֣אמֶר גִּדְע֔וֹן לָ⁠כֵ֗ן בְּ⁠תֵ֧ת יְהוָ֛ה אֶת־זֶ֥בַח וְ⁠אֶת־צַלְמֻנָּ֖ע בְּ⁠יָדִ֑⁠י וְ⁠דַשְׁתִּי֙ אֶת־בְּשַׂרְ⁠כֶ֔ם אֶת־קוֹצֵ֥י הַ⁠מִּדְבָּ֖ר וְ⁠אֶת־הַֽ⁠בַּרְקֳנִֽים׃","wa⁠yò֣̇ʼmer gi̇dĕʻ֔wòn lá⁠ké֗n bĕ̇⁠ţé֧ţ yĕhwá֛h ʼeţ-ze֥baẖ wĕ⁠ʼeţ-ẕalĕmuná֖̇ʻ bĕ̇⁠yádi֑⁠y wĕ⁠daşĕ̌ţi̇y֙ ʼeţ-bĕ̇şârĕ⁠ke֔m ʼeţ-qwòẕé֥y ha⁠mi̇dĕbá֖̇r wĕ⁠ʼeţ-haֽ⁠bȧrĕqoniֽym׃"],[8,8,"וַ⁠יַּ֤עַל מִ⁠שָּׁם֙ פְּנוּאֵ֔ל וַ⁠יְדַבֵּ֥ר אֲלֵי⁠הֶ֖ם כָּ⁠זֹ֑את וַ⁠יַּעֲנ֤וּ אוֹת⁠וֹ֙ אַנְשֵׁ֣י פְנוּאֵ֔ל כַּ⁠אֲשֶׁ֥ר עָנ֖וּ אַנְשֵׁ֥י סֻכּֽוֹת׃","wa⁠yȧ֤ʻal mi⁠şá̇̌m֙ pĕ̇nẇʼé֔l wa⁠yĕdabé֥̇r ʼàléy⁠he֖m ká̇⁠zò֑ʼţ wa⁠yȧʻàn֤ẇ ʼwòţ⁠wò֙ ʼanĕşé֣̌y pĕnẇʼé֔l kȧ⁠ʼàşě֥r ʻán֖ẇ ʼanĕşé֥̌y sukֽ̇wòţ׃"],[8,9,"וַ⁠יֹּ֛אמֶר גַּם־לְ⁠אַנְשֵׁ֥י פְנוּאֵ֖ל לֵ⁠אמֹ֑ר בְּ⁠שׁוּבִ֣⁠י בְ⁠שָׁל֔וֹם אֶתֹּ֖ץ אֶת־הַ⁠מִּגְדָּ֥ל הַ⁠זֶּֽה׃פ","wa⁠yò֛̇ʼmer gȧm-lĕ⁠ʼanĕşé֥̌y pĕnẇʼé֖l lé⁠ʼmò֑r bĕ̇⁠ş̌ẇbi֣⁠y bĕ⁠şá̌l֔wòm ʼeţò֖̇ẕ ʼeţ-ha⁠mi̇gĕdá֥̇l ha⁠zėֽh׃p"],[8,10,"וְ⁠זֶ֨בַח וְ⁠צַלְמֻנָּ֜ע בַּ⁠קַּרְקֹ֗ר וּ⁠מַחֲנֵי⁠הֶ֤ם עִמָּ⁠ם֙ כַּ⁠חֲמֵ֤שֶׁת עָשָׂר֙ אֶ֔לֶף כֹּ֚ל הַ⁠נּ֣וֹתָרִ֔ים מִ⁠כֹּ֖ל מַחֲנֵ֣ה בְנֵי־קֶ֑דֶם וְ⁠הַ⁠נֹּ֣פְלִ֔ים מֵאָ֨ה וְ⁠עֶשְׂרִ֥ים אֶ֛לֶף אִ֖ישׁ שֹׁ֥לֵֽף חָֽרֶב׃","wĕ⁠ze֨baẖ wĕ⁠ẕalĕmuná̇֜ʻ bȧ⁠qȧrĕqò֗r ẇ⁠maẖànéy⁠he֤m ʻimá̇⁠m֙ kȧ⁠ẖàmé֤şěţ ʻáşá̂r֙ ʼe֔lep kò֚̇l ha⁠ṅ֣wòţári֔ym mi⁠kò֖̇l maẖàné֣h bĕnéy-qe֑dem wĕ⁠ha⁠nò֣̇pĕli֔ym méʼá֨h wĕ⁠ʻeşĕ̂ri֥ym ʼe֛lep ʼi֖yş̌ şò֥̌léֽp ẖáֽreb׃"],[8,11,"וַ⁠יַּ֣עַל גִּדְע֗וֹן דֶּ֚רֶךְ הַ⁠שְּׁכוּנֵ֣י בָֽ⁠אֳהָלִ֔ים מִ⁠קֶּ֥דֶם לְ⁠נֹ֖בַח וְ⁠יָגְבֳּהָ֑ה וַ⁠יַּךְ֙ אֶת־הַֽ⁠מַּחֲנֶ֔ה וְ⁠הַֽ⁠מַּחֲנֶ֖ה הָ֥יָה בֶֽטַח׃","wa⁠yȧ֣ʻal gi̇dĕʻ֗wòn dė֚rekĕ ha⁠şĕ̇̌kẇné֣y bֽá⁠ʼoháli֔ym mi⁠qė֥dem lĕ⁠nò֖baẖ wĕ⁠yágĕbȯhá֑h wa⁠yȧkĕ֙ ʼeţ-haֽ⁠mȧẖàne֔h wĕ⁠haֽ⁠mȧẖàne֖h há֥yáh beֽtaẖ׃"],[8,12,"וַ⁠יָּנ֗וּסוּ זֶ֚בַח וְ⁠צַלְמֻנָּ֔ע וַ⁠יִּרְדֹּ֖ף אַחֲרֵי⁠הֶ֑ם וַ⁠יִּלְכֹּ֞ד אֶת־שְׁנֵ֣י ׀ מַלְכֵ֣י מִדְיָ֗ן אֶת־זֶ֨בַח֙ וְ⁠אֶת־צַלְמֻנָּ֔ע וְ⁠כָל־הַֽ⁠מַּחֲנֶ֖ה הֶחֱרִֽיד׃","wa⁠yá̇n֗ẇsẇ ze֚baẖ wĕ⁠ẕalĕmuná̇֔ʻ wa⁠yi̇rĕdò֖̇p ʼaẖàréy⁠he֑m wa⁠yi̇lĕkò̇֞d ʼeţ-şĕ̌né֣y ׀ malĕké֣y midĕyá֗n ʼeţ-ze֨baẖ֙ wĕ⁠ʼeţ-ẕalĕmuná̇֔ʻ wĕ⁠kál-haֽ⁠mȧẖàne֖h heẖèriֽyd׃"],[8,13,"וַ⁠יָּ֛שָׁב גִּדְע֥וֹן בֶּן־יוֹאָ֖שׁ מִן־הַ⁠מִּלְחָמָ֑ה מִֽ⁠לְ⁠מַעֲלֵ֖ה הֶ⁠חָֽרֶס׃","wa⁠yá֛̇şá̌b gi̇dĕʻ֥wòn bėn-ywòʼá֖ş̌ min-ha⁠mi̇lĕẖámá֑h miֽ⁠lĕ⁠maʻàlé֖h he⁠ẖáֽres׃"],[8,14,"וַ⁠יִּלְכָּד־נַ֛עַר מֵ⁠אַנְשֵׁ֥י סֻכּ֖וֹת וַ⁠יִּשְׁאָלֵ֑⁠הוּ וַ⁠יִּכְתֹּ֨ב אֵלָ֜י⁠ו אֶת־שָׂרֵ֤י סֻכּוֹת֙ וְ⁠אֶת־זְקֵנֶ֔י⁠הָ שִׁבְעִ֥ים וְ⁠שִׁבְעָ֖ה אִֽישׁ׃","wa⁠yi̇lĕká̇d-na֛ʻar mé⁠ʼanĕşé֥̌y suk֖̇wòţ wa⁠yi̇şĕ̌ʼálé֑⁠hẇ wa⁠yi̇kĕţò̇֨b ʼélá֜y⁠w ʼeţ-şá̂ré֤y suk̇wòţ֙ wĕ⁠ʼeţ-zĕqéne֔y⁠há şǐbĕʻi֥ym wĕ⁠şǐbĕʻá֖h ʼiֽyş̌׃"],[8,15,"וַ⁠יָּבֹא֙ אֶל־אַנְשֵׁ֣י סֻכּ֔וֹת וַ⁠יֹּ֕אמֶר הִנֵּ֖ה זֶ֣בַח וְ⁠צַלְמֻנָּ֑ע אֲשֶׁר֩ חֵרַפְתֶּ֨ם אוֹתִ֜⁠י לֵ⁠אמֹ֗ר הֲ֠⁠כַף זֶ֣בַח וְ⁠צַלְמֻנָּ֤ע עַתָּה֙ בְּ⁠יָדֶ֔⁠ךָ כִּ֥י נִתֵּ֛ן לַ⁠אֲנָשֶׁ֥י⁠ךָ הַ⁠יְּעֵפִ֖ים לָֽחֶם׃","wa⁠yá̇bòʼ֙ ʼel-ʼanĕşé֣̌y suk̇֔wòţ wa⁠yò̇֕ʼmer hiné֖̇h ze֣baẖ wĕ⁠ẕalĕmuná֑̇ʻ ʼàşěr֩ ẖérapĕţė֨m ʼwòţi֜⁠y lé⁠ʼmò֗r hà֠⁠kap ze֣baẖ wĕ⁠ẕalĕmuná֤̇ʻ ʻaţá̇h֙ bĕ̇⁠yáde֔⁠ká ki֥̇y niţé֛̇n la⁠ʼànáşě֥y⁠ká ha⁠yĕ̇ʻépi֖ym láֽẖem׃"],[8,16,"וַ⁠יִּקַּח֙ אֶת־זִקְנֵ֣י הָ⁠עִ֔יר וְ⁠אֶת־קוֹצֵ֥י הַ⁠מִּדְבָּ֖ר וְ⁠אֶת־הַֽ⁠בַּרְקֳנִ֑ים וַ⁠יֹּ֣דַע בָּ⁠הֶ֔ם אֵ֖ת אַנְשֵׁ֥י סֻכּֽוֹת׃","wa⁠yi̇qȧẖ֙ ʼeţ-ziqĕné֣y há⁠ʻi֔yr wĕ⁠ʼeţ-qwòẕé֥y ha⁠mi̇dĕbá֖̇r wĕ⁠ʼeţ-haֽ⁠bȧrĕqoni֑ym wa⁠yò֣̇daʻ bá̇⁠he֔m ʼé֖ţ ʼanĕşé֥̌y sukֽ̇wòţ׃"],[8,17,"וְ⁠אֶת־מִגְדַּ֥ל פְּנוּאֵ֖ל נָתָ֑ץ וַֽ⁠יַּהֲרֹ֖ג אֶת־אַנְשֵׁ֥י הָ⁠עִֽיר׃","wĕ⁠ʼeţ-migĕdȧ֥l pĕ̇nẇʼé֖l náţá֑ẕ waֽ⁠yȧhàrò֖g ʼeţ-ʼanĕşé֥̌y há⁠ʻiֽyr׃"],[8,18,"וַ⁠יֹּ֗אמֶר אֶל־זֶ֨בַח֙ וְ⁠אֶל־צַלְמֻנָּ֔ע אֵיפֹה֙ הָ⁠אֲנָשִׁ֔ים אֲשֶׁ֥ר הֲרַגְתֶּ֖ם בְּ⁠תָב֑וֹר וַֽ⁠יֹּאמרוּ֙ כָּמ֣וֹ⁠ךָ כְמוֹ⁠הֶ֔ם אֶחָ֕ד כְּ⁠תֹ֖אַר בְּנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yò̇֗ʼmer ʼel-ze֨baẖ֙ wĕ⁠ʼel-ẕalĕmuná̇֔ʻ ʼéypòh֙ há⁠ʼànáşǐ֔ym ʼàşě֥r hàragĕţė֖m bĕ̇⁠ţáb֑wòr waֽ⁠yò̇ʼmrẇ֙ ká̇m֣wò⁠ká kĕmwò⁠he֔m ʼeẖá֕d kĕ̇⁠ţò֖ʼar bĕ̇né֥y ha⁠mėֽlekĕ׃"],[8,19,"וַ⁠יֹּאמַ֕ר אַחַ֥⁠י בְּנֵֽי־אִמִּ֖⁠י הֵ֑ם חַי־יְהוָ֗ה ל֚וּ הַחֲיִתֶ֣ם אוֹתָ֔⁠ם לֹ֥א הָרַ֖גְתִּי אֶתְ⁠כֶֽם׃","wa⁠yò̇ʼma֕r ʼaẖa֥⁠y bĕ̇néֽy-ʼimi֖̇⁠y hé֑m ẖay-yĕhwá֗h l֚ẇ haẖàyiţe֣m ʼwòţá֔⁠m lò֥ʼ hára֖gĕţi̇y ʼeţĕ⁠keֽm׃"],[8,20,"וַ⁠יֹּ֨אמֶר֙ לְ⁠יֶ֣תֶר בְּכוֹר֔⁠וֹ ק֖וּם הֲרֹ֣ג אוֹתָ֑⁠ם וְ⁠לֹא־שָׁלַ֨ף הַ⁠נַּ֤עַר חַרְבּ⁠וֹ֙ כִּ֣י יָרֵ֔א כִּ֥י עוֹדֶ֖⁠נּוּ נָֽעַר׃","wa⁠yò̇֨ʼmer֙ lĕ⁠ye֣ţer bĕ̇kwòr֔⁠wò q֖ẇm hàrò֣g ʼwòţá֑⁠m wĕ⁠lòʼ-şá̌la֨p ha⁠nȧ֤ʻar ẖarĕḃ⁠wò֙ ki֣̇y yáré֔ʼ ki֥̇y ʻwòde֖⁠ṅẇ náֽʻar׃"],[8,21,"וַ⁠יֹּ֜אמֶר זֶ֣בַח וְ⁠צַלְמֻנָּ֗ע ק֤וּם אַתָּה֙ וּ⁠פְגַע־בָּ֔⁠נוּ כִּ֥י כָ⁠אִ֖ישׁ גְּבוּרָת֑⁠וֹ וַ⁠יָּ֣קָם גִּדְע֗וֹן וַֽ⁠יַּהֲרֹג֙ אֶת־זֶ֣בַח וְ⁠אֶת־צַלְמֻנָּ֔ע וַ⁠יִּקַּח֙ אֶת־הַ⁠שַּׂ֣הֲרֹנִ֔ים אֲשֶׁ֖ר בְּ⁠צַוְּארֵ֥י גְמַלֵּי⁠הֶֽם׃","wa⁠yò̇֜ʼmer ze֣baẖ wĕ⁠ẕalĕmuná̇֗ʻ q֤ẇm ʼaţá̇h֙ ẇ⁠pĕgaʻ-bá̇֔⁠nẇ ki֥̇y ká⁠ʼi֖yş̌ gĕ̇bẇráţ֑⁠wò wa⁠yá֣̇qám gi̇dĕʻ֗wòn waֽ⁠yȧhàròg֙ ʼeţ-ze֣baẖ wĕ⁠ʼeţ-ẕalĕmuná̇֔ʻ wa⁠yi̇qȧẖ֙ ʼeţ-ha⁠şȧ֣̂hàròni֔ym ʼàşě֖r bĕ̇⁠ẕawĕ̇ʼré֥y gĕmalé̇y⁠heֽm׃"],[8,22,"וַ⁠יֹּאמְר֤וּ אִֽישׁ־יִשְׂרָאֵל֙ אֶל־גִּדְע֔וֹן מְשָׁל־בָּ֨⁠נוּ֙ גַּם־אַתָּ֔ה גַּם־בִּנְ⁠ךָ֖ גַּ֣ם בֶּן־בְּנֶ֑⁠ךָ כִּ֥י הוֹשַׁעְתָּ֖⁠נוּ מִ⁠יַּ֥ד מִדְיָֽן׃","wa⁠yò̇ʼmĕr֤ẇ ʼiֽyş̌-yişĕ̂ráʼél֙ ʼel-gi̇dĕʻ֔wòn mĕşá̌l-bá̇֨⁠nẇ֙ gȧm-ʼaţá̇֔h gȧm-bi̇nĕ⁠ká֖ gȧ֣m bėn-bĕ̇ne֑⁠ká ki֥̇y hwòşǎʻĕţá֖̇⁠nẇ mi⁠yȧ֥d midĕyáֽn׃"],[8,23,"וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ גִּדְע֔וֹן לֹֽא־אֶמְשֹׁ֤ל אֲנִי֙ בָּ⁠כֶ֔ם וְ⁠לֹֽא־יִמְשֹׁ֥ל בְּנִ֖⁠י בָּ⁠כֶ֑ם יְהוָ֖ה יִמְשֹׁ֥ל בָּ⁠כֶֽם׃","wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ gi̇dĕʻ֔wòn lòֽʼ-ʼemĕşò֤̌l ʼàniy֙ bá̇⁠ke֔m wĕ⁠lòֽʼ-yimĕşò֥̌l bĕ̇ni֖⁠y bá̇⁠ke֑m yĕhwá֖h yimĕşò֥̌l bá̇⁠keֽm׃"],[8,24,"וַ⁠יֹּ֨אמֶר אֲלֵ⁠הֶ֜ם גִּדְע֗וֹן אֶשְׁאֲלָ֤ה מִ⁠כֶּם֙ שְׁאֵלָ֔ה וּ⁠תְנוּ־לִ֕⁠י אִ֖ישׁ נֶ֣זֶם שְׁלָל֑⁠וֹ כִּֽי־נִזְמֵ֤י זָהָב֙ לָ⁠הֶ֔ם כִּ֥י יִשְׁמְעֵאלִ֖ים הֵֽם׃","wa⁠yò̇֨ʼmer ʼàlé⁠he֜m gi̇dĕʻ֗wòn ʼeşĕ̌ʼàlá֤h mi⁠kėm֙ şĕ̌ʼélá֔h ẇ⁠ţĕnẇ-li֕⁠y ʼi֖yş̌ ne֣zem şĕ̌lál֑⁠wò kiֽ̇y-nizĕmé֤y záháb֙ lá⁠he֔m ki֥̇y yişĕ̌mĕʻéʼli֖ym héֽm׃"],[8,25,"וַ⁠יֹּאמְר֖וּ נָת֣וֹן נִתֵּ֑ן וַֽ⁠יִּפְרְשׂוּ֙ אֶת־הַ⁠שִּׂמְלָ֔ה וַ⁠יַּשְׁלִ֣יכוּ שָׁ֔מָּ⁠ה אִ֖ישׁ נֶ֥זֶם שְׁלָלֽ⁠וֹ׃","wa⁠yò̇ʼmĕr֖ẇ náţ֣wòn niţé֑̇n waֽ⁠yi̇pĕrĕş̂ẇ֙ ʼeţ-ha⁠şi̇̂mĕlá֔h wa⁠yȧşĕ̌li֣ykẇ şá̌֔má̇⁠h ʼi֖yş̌ ne֥zem şĕ̌lálֽ⁠wò׃"],[8,26,"וַ⁠יְהִ֗י מִשְׁקַ֞ל נִזְמֵ֤י הַ⁠זָּהָב֙ אֲשֶׁ֣ר שָׁאָ֔ל אֶ֥לֶף וּ⁠שְׁבַע־מֵא֖וֹת זָהָ֑ב לְ֠⁠בַד מִן־הַ⁠שַּׂהֲרֹנִ֨ים וְ⁠הַ⁠נְּטִפ֜וֹת וּ⁠בִגְדֵ֣י הָ⁠אַרְגָּמָ֗ן שֶׁ⁠עַל֙ מַלְכֵ֣י מִדְיָ֔ן וּ⁠לְ⁠בַד֙ מִן־הָ֣⁠עֲנָק֔וֹת אֲשֶׁ֖ר בְּ⁠צַוְּארֵ֥י גְמַלֵּי⁠הֶֽם׃","wa⁠yĕhi֗y mişĕ̌qa֞l nizĕmé֤y ha⁠zá̇háb֙ ʼàşě֣r şá̌ʼá֔l ʼe֥lep ẇ⁠şĕ̌baʻ-méʼ֖wòţ záhá֑b lĕ֠⁠bad min-ha⁠şȧ̂hàròni֨ym wĕ⁠ha⁠nĕ̇tip֜wòţ ẇ⁠bigĕdé֣y há⁠ʼarĕgá̇má֗n şě⁠ʻal֙ malĕké֣y midĕyá֔n ẇ⁠lĕ⁠bad֙ min-há֣⁠ʻànáq֔wòţ ʼàşě֖r bĕ̇⁠ẕawĕ̇ʼré֥y gĕmalé̇y⁠heֽm׃"],[8,27,"וַ⁠יַּעַשׂ֩ אוֹת֨⁠וֹ גִדְע֜וֹן לְ⁠אֵפ֗וֹד וַ⁠יַּצֵּ֨ג אוֹת֤⁠וֹ בְ⁠עִיר⁠וֹ֙ בְּ⁠עָפְרָ֔ה וַ⁠יִּזְנ֧וּ כָֽל־יִשְׂרָאֵ֛ל אַחֲרָ֖י⁠ו שָׁ֑ם וַ⁠יְהִ֛י לְ⁠גִדְע֥וֹן וּ⁠לְ⁠בֵית֖⁠וֹ לְ⁠מוֹקֵֽשׁ׃","wa⁠yȧʻaş̂֩ ʼwòţ֨⁠wò gidĕʻ֜wòn lĕ⁠ʼép֗wòd wa⁠yȧẕé̇֨g ʼwòţ֤⁠wò bĕ⁠ʻiyr⁠wò֙ bĕ̇⁠ʻápĕrá֔h wa⁠yi̇zĕn֧ẇ káֽl-yişĕ̂ráʼé֛l ʼaẖàrá֖y⁠w şá֑̌m wa⁠yĕhi֛y lĕ⁠gidĕʻ֥wòn ẇ⁠lĕ⁠béyţ֖⁠wò lĕ⁠mwòqéֽş̌׃"],[8,28,"וַ⁠יִּכָּנַ֣ע מִדְיָ֗ן לִ⁠פְנֵי֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠לֹ֥א יָסְפ֖וּ לָ⁠שֵׂ֣את רֹאשָׁ֑⁠ם וַ⁠תִּשְׁקֹ֥ט הָ⁠אָ֛רֶץ אַרְבָּעִ֥ים שָׁנָ֖ה בִּ⁠ימֵ֥י גִדְעֽוֹן׃פ","wa⁠yi̇ká̇na֣ʻ midĕyá֗n li⁠pĕnéy֙ bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠lò֥ʼ yásĕp֖ẇ lá⁠şé֣̂ʼţ ròʼşá֑̌⁠m wa⁠ţi̇şĕ̌qò֥t há⁠ʼá֛reẕ ʼarĕbá̇ʻi֥ym şá̌ná֖h bi̇⁠ymé֥y gidĕʻֽwòn׃p"],[8,29,"וַ⁠יֵּ֛לֶךְ יְרֻבַּ֥עַל בֶּן־יוֹאָ֖שׁ וַ⁠יֵּ֥שֶׁב בְּ⁠בֵיתֽ⁠וֹ׃","wa⁠yé֛̇lekĕ yĕrubȧ֥ʻal bėn-ywòʼá֖ş̌ wa⁠yé֥̇şěb bĕ̇⁠béyţֽ⁠wò׃"],[8,30,"וּ⁠לְ⁠גִדְע֗וֹן הָיוּ֙ שִׁבְעִ֣ים בָּנִ֔ים יֹצְאֵ֖י יְרֵכ֑⁠וֹ כִּֽי־נָשִׁ֥ים רַבּ֖וֹת הָ֥יוּ לֽ⁠וֹ׃","ẇ⁠lĕ⁠gidĕʻ֗wòn háyẇ֙ şǐbĕʻi֣ym bá̇ni֔ym yòẕĕʼé֖y yĕrék֑⁠wò kiֽ̇y-náşǐ֥ym raḃ֖wòţ há֥yẇ lֽ⁠wò׃"],[8,31,"וּ⁠פִֽילַגְשׁ⁠וֹ֙ אֲשֶׁ֣ר בִּ⁠שְׁכֶ֔ם יָֽלְדָה־לּ֥⁠וֹ גַם־הִ֖יא בֵּ֑ן וַ⁠יָּ֥שֶׂם אֶת־שְׁמ֖⁠וֹ אֲבִימֶֽלֶךְ׃","ẇ⁠piֽylagĕş̌⁠wò֙ ʼàşě֣r bi̇⁠şĕ̌ke֔m yáֽlĕdáh-l֥̇⁠wò gam-hi֖yʼ bé֑̇n wa⁠yá֥̇şêm ʼeţ-şĕ̌m֖⁠wò ʼàbiymeֽlekĕ׃"],[8,32,"וַ⁠יָּ֛מָת גִּדְע֥וֹן בֶּן־יוֹאָ֖שׁ בְּ⁠שֵׂיבָ֣ה טוֹבָ֑ה וַ⁠יִּקָּבֵ֗ר בְּ⁠קֶ֨בֶר֙ יוֹאָ֣שׁ אָבִ֔י⁠ו בְּ⁠עָפְרָ֖ה אֲבִ֥י הָֽעֶזְרִֽי׃פ","wa⁠yá֛̇máţ gi̇dĕʻ֥wòn bėn-ywòʼá֖ş̌ bĕ̇⁠şé̂ybá֣h twòbá֑h wa⁠yi̇qá̇bé֗r bĕ̇⁠qe֨ber֙ ywòʼá֣ş̌ ʼábi֔y⁠w bĕ̇⁠ʻápĕrá֖h ʼàbi֥y háֽʻezĕriֽy׃p"],[8,33,"וַ⁠יְהִ֗י כַּֽ⁠אֲשֶׁר֙ מֵ֣ת גִּדְע֔וֹן וַ⁠יָּשׁ֨וּבוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יִּזְנ֖וּ אַחֲרֵ֣י הַ⁠בְּעָלִ֑ים וַ⁠יָּשִׂ֧ימוּ לָ⁠הֶ֛ם בַּ֥עַל בְּרִ֖ית לֵ⁠אלֹהִֽים׃","wa⁠yĕhi֗y kȧֽ⁠ʼàşěr֙ mé֣ţ gi̇dĕʻ֔wòn wa⁠yá̇ş̌֨ẇbẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l wa⁠yi̇zĕn֖ẇ ʼaẖàré֣y ha⁠bĕ̇ʻáli֑ym wa⁠yá̇şî֧ymẇ lá⁠he֛m bȧ֥ʻal bĕ̇ri֖yţ lé⁠ʼlòhiֽym׃"],[8,34,"וְ⁠לֹ֤א זָֽכְרוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֶת־יְהוָ֖ה אֱלֹהֵי⁠הֶ֑ם הַ⁠מַּצִּ֥יל אוֹתָ֛⁠ם מִ⁠יַּ֥ד כָּל־אֹיְבֵי⁠הֶ֖ם מִ⁠סָּבִֽיב׃","wĕ⁠lò֤ʼ záֽkĕrẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼeţ-yĕhwá֖h ʼèlòhéy⁠he֑m ha⁠mȧẕi֥̇yl ʼwòţá֛⁠m mi⁠yȧ֥d ká̇l-ʼòyĕbéy⁠he֖m mi⁠sá̇biֽyb׃"],[8,35,"וְ⁠לֹֽא־עָשׂ֣וּ חֶ֔סֶד עִם־בֵּ֥ית יְרֻבַּ֖עַל גִּדְע֑וֹן כְּ⁠כָל־הַ⁠טּוֹבָ֔ה אֲשֶׁ֥ר עָשָׂ֖ה עִם־יִשְׂרָאֵֽל׃פ","wĕ⁠lòֽʼ-ʻáş֣̂ẇ ẖe֔sed ʻim-bé֥̇yţ yĕrubȧ֖ʻal gi̇dĕʻ֑wòn kĕ̇⁠kál-ha⁠ṫwòbá֔h ʼàşě֥r ʻáşá֖̂h ʻim-yişĕ̂ráʼéֽl׃p"],[9,1,"וַ⁠יֵּ֨לֶךְ אֲבִימֶ֤לֶךְ בֶּן־יְרֻבַּ֨עַל֙ שְׁכֶ֔מָ⁠ה אֶל־אֲחֵ֖י אִמּ֑⁠וֹ וַ⁠יְדַבֵּ֣ר אֲלֵי⁠הֶ֔ם וְ⁠אֶל־כָּל־מִשְׁפַּ֛חַת בֵּית־אֲבִ֥י אִמּ֖⁠וֹ לֵ⁠אמֹֽר׃","wa⁠yé̇֨lekĕ ʼàbiyme֤lekĕ bėn-yĕrubȧ֨ʻal֙ şĕ̌ke֔má⁠h ʼel-ʼàẖé֖y ʼiṁ֑⁠wò wa⁠yĕdabé֣̇r ʼàléy⁠he֔m wĕ⁠ʼel-ká̇l-mişĕ̌pȧ֛ẖaţ bé̇yţ-ʼàbi֥y ʼiṁ֖⁠wò lé⁠ʼmòֽr׃"],[9,2,"דַּבְּרוּ־נָ֞א בְּ⁠אָזְנֵ֨י כָל־בַּעֲלֵ֣י שְׁכֶם֮ מַה־טּ֣וֹב לָ⁠כֶם֒ הַ⁠מְשֹׁ֨ל בָּ⁠כֶ֜ם שִׁבְעִ֣ים אִ֗ישׁ כֹּ֚ל בְּנֵ֣י יְרֻבַּ֔עַל אִם־מְשֹׁ֥ל בָּ⁠כֶ֖ם אִ֣ישׁ אֶחָ֑ד וּ⁠זְכַרְתֶּ֕ם כִּֽי־עַצְמֵ⁠כֶם וּ⁠בְשַׂרְ⁠כֶ֖ם אָנִֽי׃","dȧbĕ̇rẇ-ná֞ʼ bĕ̇⁠ʼázĕné֨y kál-bȧʻàlé֣y şĕ̌kem֮ mah-ṫ֣wòb lá⁠kem֒ ha⁠mĕşò̌֨l bá̇⁠ke֜m şǐbĕʻi֣ym ʼi֗yş̌ kò֚̇l bĕ̇né֣y yĕrubȧ֔ʻal ʼim-mĕşò֥̌l bá̇⁠ke֖m ʼi֣yş̌ ʼeẖá֑d ẇ⁠zĕkarĕţė֕m kiֽ̇y-ʻaẕĕmé⁠kem ẇ⁠bĕşârĕ⁠ke֖m ʼániֽy׃"],[9,3,"וַ⁠יְדַבְּר֨וּ אֲחֵֽי־אִמּ֜⁠וֹ עָלָ֗י⁠ו בְּ⁠אָזְנֵי֙ כָּל־בַּעֲלֵ֣י שְׁכֶ֔ם אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה וַ⁠יֵּ֤ט לִבָּ⁠ם֙ אַחֲרֵ֣י אֲבִימֶ֔לֶךְ כִּ֥י אָמְר֖וּ אָחִ֥י⁠נוּ הֽוּא׃","wa⁠yĕdabĕ̇r֨ẇ ʼàẖéֽy-ʼiṁ֜⁠wò ʻálá֗y⁠w bĕ̇⁠ʼázĕnéy֙ ká̇l-bȧʻàlé֣y şĕ̌ke֔m ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh wa⁠yé֤̇t libá̇⁠m֙ ʼaẖàré֣y ʼàbiyme֔lekĕ ki֥̇y ʼámĕr֖ẇ ʼáẖi֥y⁠nẇ hֽẇʼ׃"],[9,4,"וַ⁠יִּתְּנוּ־ל⁠וֹ֙ שִׁבְעִ֣ים כֶּ֔סֶף מִ⁠בֵּ֖יתּ בַ֣עַל בְּרִ֑ית וַ⁠יִּשְׂכֹּ֨ר בָּ⁠הֶ֜ם אֲבִימֶ֗לֶךְ אֲנָשִׁ֤ים רֵיקִים֙ וּ⁠פֹ֣חֲזִ֔ים וַ⁠יֵּלְכ֖וּ אַחֲרָֽי⁠ו׃","wa⁠yi̇ţĕ̇nẇ-l⁠wò֙ şǐbĕʻi֣ym kė֔sep mi⁠bé֖̇yţ̇ ba֣ʻal bĕ̇ri֑yţ wa⁠yi̇şĕ̂kò̇֨r bá̇⁠he֜m ʼàbiyme֗lekĕ ʼànáşǐ֤ym réyqiym֙ ẇ⁠pò֣ẖàzi֔ym wa⁠yé̇lĕk֖ẇ ʼaẖàráֽy⁠w׃"],[9,5,"וַ⁠יָּבֹ֤א בֵית־אָבִי⁠ו֙ עָפְרָ֔תָ⁠ה וַֽ⁠יַּהֲרֹ֞ג אֶת־אֶחָ֧י⁠ו בְּנֵֽי־יְרֻבַּ֛עַל שִׁבְּעִ֥ים אִ֖ישׁ עַל־אֶ֣בֶן אֶחָ֑ת וַ⁠יִּוָּתֵ֞ר יוֹתָ֧ם בֶּן־יְרֻבַּ֛עַל הַ⁠קָּטֹ֖ן כִּ֥י נֶחְבָּֽא׃ס","wa⁠yá̇bò֤ʼ béyţ-ʼábiy⁠w֙ ʻápĕrá֔ţá⁠h waֽ⁠yȧhàrò֞g ʼeţ-ʼeẖá֧y⁠w bĕ̇néֽy-yĕrubȧ֛ʻal şǐbĕ̇ʻi֥ym ʼi֖yş̌ ʻal-ʼe֣ben ʼeẖá֑ţ wa⁠yi̇wá̇ţé֞r ywòţá֧m bėn-yĕrubȧ֛ʻal ha⁠qá̇tò֖n ki֥̇y neẖĕbáֽ̇ʼ׃s"],[9,6,"וַ⁠יֵּאָ֨סְפ֜וּ כָּל־בַּעֲלֵ֤י שְׁכֶם֙ וְ⁠כָל־בֵּ֣ית מִלּ֔וֹא וַ⁠יֵּ֣לְכ֔וּ וַ⁠יַּמְלִ֥יכוּ אֶת־אֲבִימֶ֖לֶךְ לְ⁠מֶ֑לֶךְ עִם־אֵל֥וֹן מֻצָּ֖ב אֲשֶׁ֥ר בִּ⁠שְׁכֶֽם׃","wa⁠yé̇ʼá֨sĕp֜ẇ ká̇l-bȧʻàlé֤y şĕ̌kem֙ wĕ⁠kál-bé֣̇yţ mil̇֔wòʼ wa⁠yé֣̇lĕk֔ẇ wa⁠yȧmĕli֥ykẇ ʼeţ-ʼàbiyme֖lekĕ lĕ⁠me֑lekĕ ʻim-ʼél֥wòn muẕá֖̇b ʼàşě֥r bi̇⁠şĕ̌keֽm׃"],[9,7,"וַ⁠יַּגִּ֣דוּ לְ⁠יוֹתָ֗ם וַ⁠יֵּ֨לֶךְ֙ וַֽ⁠יַּעֲמֹד֙ בְּ⁠רֹ֣אשׁ הַר־גְּרִזִ֔ים וַ⁠יִּשָּׂ֥א קוֹל֖⁠וֹ וַ⁠יִּקְרָ֑א וַ⁠יֹּ֣אמֶר לָ⁠הֶ֗ם שִׁמְע֤וּ אֵלַ⁠י֙ בַּעֲלֵ֣י שְׁכֶ֔ם וְ⁠יִשְׁמַ֥ע אֲלֵי⁠כֶ֖ם אֱלֹהִֽים׃","wa⁠yȧgi֣̇dẇ lĕ⁠ywòţá֗m wa⁠yé̇֨lekĕ֙ waֽ⁠yȧʻàmòd֙ bĕ̇⁠rò֣ʼş̌ har-gĕ̇rizi֔ym wa⁠yi̇şá֥̇̂ʼ qwòl֖⁠wò wa⁠yi̇qĕrá֑ʼ wa⁠yò֣̇ʼmer lá⁠he֗m şǐmĕʻ֤ẇ ʼéla⁠y֙ bȧʻàlé֣y şĕ̌ke֔m wĕ⁠yişĕ̌ma֥ʻ ʼàléy⁠ke֖m ʼèlòhiֽym׃"],[9,8,"הָל֤וֹךְ הָֽלְכוּ֙ הָ⁠עֵצִ֔ים לִ⁠מְשֹׁ֥חַ עֲלֵי⁠הֶ֖ם מֶ֑לֶךְ וַ⁠יֹּאמְר֥וּ לַ⁠זַּ֖יִת מלוכ⁠ה עָלֵֽי⁠נוּ׃","hál֤wòkĕ háֽlĕkẇ֙ há⁠ʻéẕi֔ym li⁠mĕşò֥̌ẖa ʻàléy⁠he֖m me֑lekĕ wa⁠yò̇ʼmĕr֥ẇ la⁠zȧ֖yiţ mlwk⁠h ʻáléֽy⁠nẇ׃"],[9,9,"וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ הַ⁠זַּ֔יִת הֶ⁠חֳדַ֨לְתִּי֙ אֶת־דִּשְׁנִ֔⁠י אֲשֶׁר־בִּ֛⁠י יְכַבְּד֥וּ אֱלֹהִ֖ים וַ⁠אֲנָשִׁ֑ים וְ⁠הָ֣לַכְתִּ֔י לָ⁠נ֖וּעַ עַל־הָ⁠עֵצִֽים׃","wa⁠yò֤̇ʼmer lá⁠hem֙ ha⁠zȧ֔yiţ he⁠ẖoda֨lĕţi̇y֙ ʼeţ-di̇şĕ̌ni֔⁠y ʼàşěr-bi֛̇⁠y yĕkabĕ̇d֥ẇ ʼèlòhi֖ym wa⁠ʼànáşǐ֑ym wĕ⁠há֣lakĕţi̇֔y lá⁠n֖ẇʻa ʻal-há⁠ʻéẕiֽym׃"],[9,10,"וַ⁠יֹּאמְר֥וּ הָ⁠עֵצִ֖ים לַ⁠תְּאֵנָ֑ה לְכִי־אַ֖תְּ מָלְכִ֥י עָלֵֽי⁠נוּ׃","wa⁠yò̇ʼmĕr֥ẇ há⁠ʻéẕi֖ym la⁠ţĕ̇ʼéná֑h lĕkiy-ʼa֖ţĕ̇ málĕki֥y ʻáléֽy⁠nẇ׃"],[9,11,"וַ⁠תֹּ֤אמֶר לָ⁠הֶם֙ הַ⁠תְּאֵנָ֔ה הֶ⁠חֳדַ֨לְתִּי֙ אֶת־מָתְקִ֔⁠י וְ⁠אֶת־תְּנוּבָתִ֖⁠י הַ⁠טּוֹבָ֑ה וְ⁠הָ֣לַכְתִּ֔י לָ⁠נ֖וּעַ עַל־הָ⁠עֵצִֽים׃","wa⁠ţò֤̇ʼmer lá⁠hem֙ ha⁠ţĕ̇ʼéná֔h he⁠ẖoda֨lĕţi̇y֙ ʼeţ-máţĕqi֔⁠y wĕ⁠ʼeţ-ţĕ̇nẇbáţi֖⁠y ha⁠ṫwòbá֑h wĕ⁠há֣lakĕţi̇֔y lá⁠n֖ẇʻa ʻal-há⁠ʻéẕiֽym׃"],[9,12,"וַ⁠יֹּאמְר֥וּ הָ⁠עֵצִ֖ים לַ⁠גָּ֑פֶן לְכִי־אַ֖תְּ מלוכי עָלֵֽי⁠נוּ׃","wa⁠yò̇ʼmĕr֥ẇ há⁠ʻéẕi֖ym la⁠gá֑̇pen lĕkiy-ʼa֖ţĕ̇ mlwky ʻáléֽy⁠nẇ׃"],[9,13,"וַ⁠תֹּ֤אמֶר לָ⁠הֶם֙ הַ⁠גֶּ֔פֶן הֶ⁠חֳדַ֨לְתִּי֙ אֶת־תִּ֣ירוֹשִׁ֔⁠י הַֽ⁠מְשַׂמֵּ֥חַ אֱלֹהִ֖ים וַ⁠אֲנָשִׁ֑ים וְ⁠הָ֣לַכְתִּ֔י לָ⁠נ֖וּעַ עַל־הָ⁠עֵצִֽים׃","wa⁠ţò֤̇ʼmer lá⁠hem֙ ha⁠gė֔pen he⁠ẖoda֨lĕţi̇y֙ ʼeţ-ţi֣̇yrwòşǐ֔⁠y haֽ⁠mĕşâmé֥̇ẖa ʼèlòhi֖ym wa⁠ʼànáşǐ֑ym wĕ⁠há֣lakĕţi̇֔y lá⁠n֖ẇʻa ʻal-há⁠ʻéẕiֽym׃"],[9,14,"וַ⁠יֹּאמְר֥וּ כָל־הָ⁠עֵצִ֖ים אֶל־הָ⁠אָטָ֑ד לֵ֥ךְ אַתָּ֖ה מְלָךְ־עָלֵֽי⁠נוּ׃","wa⁠yò̇ʼmĕr֥ẇ kál-há⁠ʻéẕi֖ym ʼel-há⁠ʼátá֑d lé֥kĕ ʼaţá֖̇h mĕlákĕ-ʻáléֽy⁠nẇ׃"],[9,15,"וַ⁠יֹּ֣אמֶר הָ⁠אָטָד֮ אֶל־הָ⁠עֵצִים֒ אִ֡ם בֶּ⁠אֱמֶ֣ת אַתֶּם֩ מֹשְׁחִ֨ים אֹתִ֤⁠י לְ⁠מֶ֨לֶךְ֙ עֲלֵי⁠כֶ֔ם בֹּ֖אוּ חֲס֣וּ בְ⁠צִלִּ֑⁠י וְ⁠אִם־אַ֕יִן תֵּ֤צֵא אֵשׁ֙ מִן־הָ֣⁠אָטָ֔ד וְ⁠תֹאכַ֖ל אֶת־אַרְזֵ֥י הַ⁠לְּבָנֽוֹן׃","wa⁠yò֣̇ʼmer há⁠ʼátád֮ ʼel-há⁠ʻéẕiym֒ ʼi֡m bė⁠ʼème֣ţ ʼaţėm֩ mòşĕ̌ẖi֨ym ʼòţi֤⁠y lĕ⁠me֨lekĕ֙ ʻàléy⁠ke֔m bò֖̇ʼẇ ẖàs֣ẇ bĕ⁠ẕili֑̇⁠y wĕ⁠ʼim-ʼa֕yin ţé֤̇ẕéʼ ʼéş̌֙ min-há֣⁠ʼátá֔d wĕ⁠ţòʼka֖l ʼeţ-ʼarĕzé֥y ha⁠lĕ̇bánֽwòn׃"],[9,16,"וְ⁠עַתָּ֗ה אִם־בֶּ⁠אֱמֶ֤ת וּ⁠בְ⁠תָמִים֙ עֲשִׂיתֶ֔ם וַ⁠תַּמְלִ֖יכוּ אֶת־אֲבִימֶ֑לֶךְ וְ⁠אִם־טוֹבָ֤ה עֲשִׂיתֶם֙ עִם־יְרֻבַּ֣עַל וְ⁠עִם־בֵּית֔⁠וֹ וְ⁠אִם־כִּ⁠גְמ֥וּל יָדָ֖י⁠ו עֲשִׂ֥יתֶם לֽ⁠וֹ׃","wĕ⁠ʻaţá̇֗h ʼim-bė⁠ʼème֤ţ ẇ⁠bĕ⁠ţámiym֙ ʻàşîyţe֔m wa⁠ţȧmĕli֖ykẇ ʼeţ-ʼàbiyme֑lekĕ wĕ⁠ʼim-twòbá֤h ʻàşîyţem֙ ʻim-yĕrubȧ֣ʻal wĕ⁠ʻim-bé̇yţ֔⁠wò wĕ⁠ʼim-ki̇⁠gĕm֥ẇl yádá֖y⁠w ʻàşî֥yţem lֽ⁠wò׃"],[9,17,"אֲשֶׁר־נִלְחַ֥ם אָבִ֖⁠י עֲלֵי⁠כֶ֑ם וַ⁠יַּשְׁלֵ֤ךְ אֶת־נַפְשׁ⁠וֹ֙ מִ⁠נֶּ֔גֶד וַ⁠יַּצֵּ֥ל אֶתְ⁠כֶ֖ם מִ⁠יַּ֥ד מִדְיָֽן׃","ʼàşěr-nilĕẖa֥m ʼábi֖⁠y ʻàléy⁠ke֑m wa⁠yȧşĕ̌lé֤kĕ ʼeţ-napĕş̌⁠wò֙ mi⁠nė֔ged wa⁠yȧẕé֥̇l ʼeţĕ⁠ke֖m mi⁠yȧ֥d midĕyáֽn׃"],[9,18,"וְ⁠אַתֶּ֞ם קַמְתֶּ֨ם עַל־בֵּ֤ית אָבִ⁠י֙ הַ⁠יּ֔וֹם וַ⁠תַּהַרְג֧וּ אֶת־בָּנָ֛י⁠ו שִׁבְעִ֥ים אִ֖ישׁ עַל־אֶ֣בֶן אֶחָ֑ת וַ⁠תַּמְלִ֜יכוּ אֶת־אֲבִימֶ֤לֶךְ בֶּן־אֲמָת⁠וֹ֙ עַל־בַּעֲלֵ֣י שְׁכֶ֔ם כִּ֥י אֲחִי⁠כֶ֖ם הֽוּא׃","wĕ⁠ʼaţė֞m qamĕţė֨m ʻal-bé֤̇yţ ʼábi⁠y֙ ha⁠ẏ֔wòm wa⁠ţȧharĕg֧ẇ ʼeţ-bá̇ná֛y⁠w şǐbĕʻi֥ym ʼi֖yş̌ ʻal-ʼe֣ben ʼeẖá֑ţ wa⁠ţȧmĕli֜ykẇ ʼeţ-ʼàbiyme֤lekĕ bėn-ʼàmáţ⁠wò֙ ʻal-bȧʻàlé֣y şĕ̌ke֔m ki֥̇y ʼàẖiy⁠ke֖m hֽẇʼ׃"],[9,19,"וְ⁠אִם־בֶּ⁠אֱמֶ֨ת וּ⁠בְ⁠תָמִ֧ים עֲשִׂיתֶ֛ם עִם־יְרֻבַּ֥עַל וְ⁠עִם־בֵּית֖⁠וֹ הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה שִׂמְחוּ֙ בַּ⁠אֲבִימֶ֔לֶךְ וְ⁠יִשְׂמַ֥ח גַּם־ה֖וּא בָּ⁠כֶֽם׃","wĕ⁠ʼim-bė⁠ʼème֨ţ ẇ⁠bĕ⁠ţámi֧ym ʻàşîyţe֛m ʻim-yĕrubȧ֥ʻal wĕ⁠ʻim-bé̇yţ֖⁠wò ha⁠ẏ֣wòm ha⁠zė֑h şîmĕẖẇ֙ bȧ⁠ʼàbiyme֔lekĕ wĕ⁠yişĕ̂ma֥ẖ gȧm-h֖ẇʼ bá̇⁠keֽm׃"],[9,20,"וְ⁠אִם־אַ֕יִן תֵּ֤צֵא אֵשׁ֙ מֵ⁠אֲבִימֶ֔לֶךְ וְ⁠תֹאכַ֛ל אֶת־בַּעֲלֵ֥י שְׁכֶ֖ם וְ⁠אֶת־בֵּ֣ית מִלּ֑וֹא וְ⁠תֵצֵ֨א אֵ֜שׁ מִ⁠בַּעֲלֵ֤י שְׁכֶם֙ וּ⁠מִ⁠בֵּ֣ית מִלּ֔וֹא וְ⁠תֹאכַ֖ל אֶת־אֲבִימֶֽלֶךְ׃","wĕ⁠ʼim-ʼa֕yin ţé֤̇ẕéʼ ʼéş̌֙ mé⁠ʼàbiyme֔lekĕ wĕ⁠ţòʼka֛l ʼeţ-bȧʻàlé֥y şĕ̌ke֖m wĕ⁠ʼeţ-bé֣̇yţ mil֑̇wòʼ wĕ⁠ţéẕé֨ʼ ʼé֜ş̌ mi⁠bȧʻàlé֤y şĕ̌kem֙ ẇ⁠mi⁠bé֣̇yţ mil̇֔wòʼ wĕ⁠ţòʼka֖l ʼeţ-ʼàbiymeֽlekĕ׃"],[9,21,"וַ⁠יָּ֣נָס יוֹתָ֔ם וַ⁠יִּבְרַ֖ח וַ⁠יֵּ֣לֶךְ בְּאֵ֑רָ⁠ה וַ⁠יֵּ֣שֶׁב שָׁ֔ם מִ⁠פְּנֵ֖י אֲבִימֶ֥לֶךְ אָחִֽי⁠ו׃פ","wa⁠yá֣̇nás ywòţá֔m wa⁠yi̇bĕra֖ẖ wa⁠yé֣̇lekĕ bĕ̇ʼé֑rá⁠h wa⁠yé֣̇şěb şá̌֔m mi⁠pĕ̇né֖y ʼàbiyme֥lekĕ ʼáẖiֽy⁠w׃p"],[9,22,"וַ⁠יָּ֧שַׂר אֲבִימֶ֛לֶךְ עַל־יִשְׂרָאֵ֖ל שָׁלֹ֥שׁ שָׁנִֽים׃","wa⁠yá֧̇şâr ʼàbiyme֛lekĕ ʻal-yişĕ̂ráʼé֖l şá̌lò֥ş̌ şá̌niֽym׃"],[9,23,"וַ⁠יִּשְׁלַ֤ח אֱלֹהִים֙ ר֣וּחַ רָעָ֔ה בֵּ֣ין אֲבִימֶ֔לֶךְ וּ⁠בֵ֖ין בַּעֲלֵ֣י שְׁכֶ֑ם וַ⁠יִּבְגְּד֥וּ בַעֲלֵי־שְׁכֶ֖ם בַּ⁠אֲבִימֶֽלֶךְ׃","wa⁠yi̇şĕ̌la֤ẖ ʼèlòhiym֙ r֣ẇẖa ráʻá֔h bé֣̇yn ʼàbiyme֔lekĕ ẇ⁠bé֖yn bȧʻàlé֣y şĕ̌ke֑m wa⁠yi̇bĕgĕ̇d֥ẇ baʻàléy-şĕ̌ke֖m bȧ⁠ʼàbiymeֽlekĕ׃"],[9,24,"לָ⁠ב֕וֹא חֲמַ֖ס שִׁבְעִ֣ים בְּנֵֽי־יְרֻבָּ֑עַל וְ⁠דָמָ֗⁠ם לָ⁠שׂ֞וּם עַל־אֲבִימֶ֤לֶךְ אֲחִי⁠הֶם֙ אֲשֶׁ֣ר הָרַ֣ג אוֹתָ֔⁠ם וְ⁠עַל֙ בַּעֲלֵ֣י שְׁכֶ֔ם אֲשֶׁר־חִזְּק֥וּ אֶת־יָדָ֖י⁠ו לַ⁠הֲרֹ֥ג אֶת־אֶחָֽי⁠ו׃","lá⁠b֕wòʼ ẖàma֖s şǐbĕʻi֣ym bĕ̇néֽy-yĕrubá֑̇ʻal wĕ⁠dámá֗⁠m lá⁠ş̂֞ẇm ʻal-ʼàbiyme֤lekĕ ʼàẖiy⁠hem֙ ʼàşě֣r hára֣g ʼwòţá֔⁠m wĕ⁠ʻal֙ bȧʻàlé֣y şĕ̌ke֔m ʼàşěr-ẖizĕ̇q֥ẇ ʼeţ-yádá֖y⁠w la⁠hàrò֥g ʼeţ-ʼeẖáֽy⁠w׃"],[9,25,"וַ⁠יָּשִׂ֣ימוּ ל⁠וֹ֩ בַעֲלֵ֨י שְׁכֶ֜ם מְאָרְבִ֗ים עַ֚ל רָאשֵׁ֣י הֶ⁠הָרִ֔ים וַ⁠יִּגְזְל֗וּ אֵ֛ת כָּל־אֲשֶׁר־יַעֲבֹ֥ר עֲלֵי⁠הֶ֖ם בַּ⁠דָּ֑רֶךְ וַ⁠יֻּגַּ֖ד לַ⁠אֲבִימֶֽלֶךְ׃פ","wa⁠yá̇şî֣ymẇ l⁠wò֩ baʻàlé֨y şĕ̌ke֜m mĕʼárĕbi֗ym ʻa֚l ráʼşé֣̌y he⁠hári֔ym wa⁠yi̇gĕzĕl֗ẇ ʼé֛ţ ká̇l-ʼàşěr-yaʻàbò֥r ʻàléy⁠he֖m bȧ⁠dá֑̇rekĕ wa⁠yu̇gȧ֖d la⁠ʼàbiymeֽlekĕ׃p"],[9,26,"וַ⁠יָּבֹ֞א גַּ֤עַל בֶּן־עֶ֨בֶד֙ וְ⁠אֶחָ֔י⁠ו וַ⁠יַּעַבְר֖וּ בִּ⁠שְׁכֶ֑ם וַ⁠יִּבְטְחוּ־ב֖⁠וֹ בַּעֲלֵ֥י שְׁכֶֽם׃","wa⁠yá̇bò֞ʼ gȧ֤ʻal bėn-ʻe֨bed֙ wĕ⁠ʼeẖá֔y⁠w wa⁠yȧʻabĕr֖ẇ bi̇⁠şĕ̌ke֑m wa⁠yi̇bĕtĕẖẇ-b֖⁠wò bȧʻàlé֥y şĕ̌keֽm׃"],[9,27,"וַ⁠יֵּצְא֨וּ הַ⁠שָּׂדֶ֜ה וַֽ⁠יִּבְצְר֤וּ אֶת־כַּרְמֵי⁠הֶם֙ וַֽ⁠יִּדְרְכ֔וּ וַֽ⁠יַּעֲשׂ֖וּ הִלּוּלִ֑ים וַ⁠יָּבֹ֨אוּ֙ בֵּ֣ית אֱֽלֹֽהֵי⁠הֶ֔ם וַ⁠יֹּֽאכְלוּ֙ וַ⁠יִּשְׁתּ֔וּ וַֽ⁠יְקַלְל֖וּ אֶת־אֲבִימֶֽלֶךְ׃","wa⁠yé̇ẕĕʼ֨ẇ ha⁠şá̇̂de֜h waֽ⁠yi̇bĕẕĕr֤ẇ ʼeţ-kȧrĕméy⁠hem֙ waֽ⁠yi̇dĕrĕk֔ẇ waֽ⁠yȧʻàş֖̂ẇ hil̇ẇli֑ym wa⁠yá̇bò֨ʼẇ֙ bé֣̇yţ ʼèֽlòֽhéy⁠he֔m wa⁠yòֽ̇ʼkĕlẇ֙ wa⁠yi̇şĕ̌ţ̇֔ẇ waֽ⁠yĕqalĕl֖ẇ ʼeţ-ʼàbiymeֽlekĕ׃"],[9,28,"וַ⁠יֹּ֣אמֶר ׀ גַּ֣עַל בֶּן־עֶ֗בֶד מִֽי־אֲבִימֶ֤לֶךְ וּ⁠מִֽי־שְׁכֶם֙ כִּ֣י נַעַבְדֶ֔⁠נּוּ הֲ⁠לֹ֥א בֶן־יְרֻבַּ֖עַל וּ⁠זְבֻ֣ל פְּקִיד֑⁠וֹ עִבְד֗וּ אֶת־אַנְשֵׁ֤י חֲמוֹר֙ אֲבִ֣י שְׁכֶ֔ם וּ⁠מַדּ֖וּעַ נַעַבְדֶ֥⁠נּוּ אֲנָֽחְנוּ׃","wa⁠yò֣̇ʼmer ׀ gȧ֣ʻal bėn-ʻe֗bed miֽy-ʼàbiyme֤lekĕ ẇ⁠miֽy-şĕ̌kem֙ ki֣̇y naʻabĕde֔⁠ṅẇ hà⁠lò֥ʼ ben-yĕrubȧ֖ʻal ẇ⁠zĕbu֣l pĕ̇qiyd֑⁠wò ʻibĕd֗ẇ ʼeţ-ʼanĕşé֤̌y ẖàmwòr֙ ʼàbi֣y şĕ̌ke֔m ẇ⁠maḋ֖ẇʻa naʻabĕde֥⁠ṅẇ ʼànáֽẖĕnẇ׃"],[9,29,"וּ⁠מִ֨י יִתֵּ֜ן אֶת־הָ⁠עָ֤ם הַ⁠זֶּה֙ בְּ⁠יָדִ֔⁠י וְ⁠אָסִ֖ירָה אֶת־אֲבִימֶ֑לֶךְ וַ⁠יֹּ֨אמֶר֙ לַ⁠אֲבִימֶ֔לֶךְ רַבֶּ֥ה צְבָאֲ⁠ךָ֖ וָ⁠צֵֽאָ⁠ה׃","ẇ⁠mi֨y yiţé̇֜n ʼeţ-há⁠ʻá֤m ha⁠zėh֙ bĕ̇⁠yádi֔⁠y wĕ⁠ʼási֖yráh ʼeţ-ʼàbiyme֑lekĕ wa⁠yò̇֨ʼmer֙ la⁠ʼàbiyme֔lekĕ rabė֥h ẕĕbáʼà⁠ká֖ wá⁠ẕéֽʼá⁠h׃"],[9,30,"וַ⁠יִּשְׁמַ֗ע זְבֻל֙ שַׂר־הָ⁠עִ֔יר אֶת־דִּבְרֵ֖י גַּ֣עַל בֶּן־עָ֑בֶד וַ⁠יִּ֖חַר אַפּֽ⁠וֹ׃","wa⁠yi̇şĕ̌ma֗ʻ zĕbul֙ şâr-há⁠ʻi֔yr ʼeţ-di̇bĕré֖y gȧ֣ʻal bėn-ʻá֑bed wa⁠yi֖̇ẖar ʼaṗֽ⁠wò׃"],[9,31,"וַ⁠יִּשְׁלַ֧ח מַלְאָכִ֛ים אֶל־אֲבִימֶ֖לֶךְ בְּ⁠תָרְמָ֣ה לֵ⁠אמֹ֑ר הִנֵּה֩ גַ֨עַל בֶּן־עֶ֤בֶד וְ⁠אֶחָי⁠ו֙ בָּאִ֣ים שְׁכֶ֔מָ⁠ה וְ⁠הִנָּ֛⁠ם צָרִ֥ים אֶת־הָ⁠עִ֖יר עָלֶֽי⁠ךָ׃","wa⁠yi̇şĕ̌la֧ẖ malĕʼáki֛ym ʼel-ʼàbiyme֖lekĕ bĕ̇⁠ţárĕmá֣h lé⁠ʼmò֑r hiné̇h֩ ga֨ʻal bėn-ʻe֤bed wĕ⁠ʼeẖáy⁠w֙ bá̇ʼi֣ym şĕ̌ke֔má⁠h wĕ⁠hiná֛̇⁠m ẕári֥ym ʼeţ-há⁠ʻi֖yr ʻáleֽy⁠ká׃"],[9,32,"וְ⁠עַתָּה֙ ק֣וּם לַ֔יְלָה אַתָּ֖ה וְ⁠הָ⁠עָ֣ם אֲשֶׁר־אִתָּ֑⁠ךְ וֶ⁠אֱרֹ֖ב בַּ⁠שָּׂדֶֽה׃","wĕ⁠ʻaţá̇h֙ q֣ẇm la֔yĕláh ʼaţá֖̇h wĕ⁠há⁠ʻá֣m ʼàşěr-ʼiţá֑̇⁠kĕ we⁠ʼèrò֖b bȧ⁠şá̇̂deֽh׃"],[9,33,"וְ⁠הָיָ֤ה בַ⁠בֹּ֨קֶר֙ כִּ⁠זְרֹ֣חַ הַ⁠שֶּׁ֔מֶשׁ תַּשְׁכִּ֖ים וּ⁠פָשַׁטְתָּ֣ עַל־הָ⁠עִ֑יר וְ⁠הִנֵּה־ה֞וּא וְ⁠הָ⁠עָ֤ם אֲשֶׁר־אִתּ⁠וֹ֙ יֹצְאִ֣ים אֵלֶ֔י⁠ךָ וְ⁠עָשִׂ֣יתָ לּ֔⁠וֹ כַּ⁠אֲשֶׁ֖ר תִּמְצָ֥א יָדֶֽ⁠ךָ׃ס","wĕ⁠háyá֤h ba⁠bò̇֨qer֙ ki̇⁠zĕrò֣ẖa ha⁠şė̌֔meş̌ ţȧşĕ̌ki֖̇ym ẇ⁠páşǎtĕţá֣̇ ʻal-há⁠ʻi֑yr wĕ⁠hiné̇h-h֞ẇʼ wĕ⁠há⁠ʻá֤m ʼàşěr-ʼiţ̇⁠wò֙ yòẕĕʼi֣ym ʼéle֔y⁠ká wĕ⁠ʻáşî֣yţá l̇֔⁠wò kȧ⁠ʼàşě֖r ţi̇mĕẕá֥ʼ yádeֽ⁠ká׃s"],[9,34,"וַ⁠יָּ֧קָם אֲבִימֶ֛לֶךְ וְ⁠כָל־הָ⁠עָ֥ם אֲשֶׁר־עִמּ֖⁠וֹ לָ֑יְלָה וַ⁠יֶּאֶרְב֣וּ עַל־שְׁכֶ֔ם אַרְבָּעָ֖ה רָאשִֽׁים׃","wa⁠yá֧̇qám ʼàbiyme֛lekĕ wĕ⁠kál-há⁠ʻá֥m ʼàşěr-ʻiṁ֖⁠wò lá֑yĕláh wa⁠yėʼerĕb֣ẇ ʻal-şĕ̌ke֔m ʼarĕbá̇ʻá֖h ráʼşǐֽym׃"],[9,35,"וַ⁠יֵּצֵא֙ גַּ֣עַל בֶּן־עֶ֔בֶד וַ⁠יַּעֲמֹ֕ד פֶּ֖תַח שַׁ֣עַר הָ⁠עִ֑יר וַ⁠יָּ֧קָם אֲבִימֶ֛לֶךְ וְ⁠הָ⁠עָ֥ם אֲשֶׁר־אִתּ֖⁠וֹ מִן־הַ⁠מַּאְרָֽב׃","wa⁠yé̇ẕéʼ֙ gȧ֣ʻal bėn-ʻe֔bed wa⁠yȧʻàmò֕d pė֖ţaẖ şǎ֣ʻar há⁠ʻi֑yr wa⁠yá֧̇qám ʼàbiyme֛lekĕ wĕ⁠há⁠ʻá֥m ʼàşěr-ʼiţ֖̇⁠wò min-ha⁠mȧʼĕráֽb׃"],[9,36,"וַ⁠יַּרְא־גַּעַל֮ אֶת־הָ⁠עָם֒ וַ⁠יֹּ֣אמֶר אֶל־זְבֻ֔ל הִנֵּה־עָ֣ם יוֹרֵ֔ד מֵ⁠רָאשֵׁ֖י הֶ⁠הָרִ֑ים וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ זְבֻ֔ל אֵ֣ת צֵ֧ל הֶ⁠הָרִ֛ים אַתָּ֥ה רֹאֶ֖ה כָּ⁠אֲנָשִֽׁים׃ס","wa⁠yȧrĕʼ-gȧʻal֮ ʼeţ-há⁠ʻám֒ wa⁠yò֣̇ʼmer ʼel-zĕbu֔l hiné̇h-ʻá֣m ywòré֔d mé⁠ráʼşé֖̌y he⁠hári֑ym wa⁠yò֤̇ʼmer ʼéláy⁠w֙ zĕbu֔l ʼé֣ţ ẕé֧l he⁠hári֛ym ʼaţá֥̇h ròʼe֖h ká̇⁠ʼànáşǐֽym׃s"],[9,37,"וַ⁠יֹּ֨סֶף ע֣וֹד גַּעַל֮ לְ⁠דַבֵּר֒ וַ⁠יֹּ֕אמֶר הִנֵּה־עָם֙ יֽוֹרְדִ֔ים מֵ⁠עִ֖ם טַבּ֣וּר הָ⁠אָ֑רֶץ וְ⁠רֹאשׁ־אֶחָ֣ד בָּ֔א מִ⁠דֶּ֖רֶךְ אֵל֥וֹן מְעוֹנְנִֽים׃","wa⁠yò̇֨sep ʻ֣wòd gȧʻal֮ lĕ⁠dabé̇r֒ wa⁠yò̇֕ʼmer hiné̇h-ʻám֙ yֽwòrĕdi֔ym mé⁠ʻi֖m taḃ֣ẇr há⁠ʼá֑reẕ wĕ⁠ròʼş̌-ʼeẖá֣d bá̇֔ʼ mi⁠dė֖rekĕ ʼél֥wòn mĕʻwònĕniֽym׃"],[9,38,"וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו זְבֻ֗ל אַיֵּ֨ה אֵפ֥וֹא פִ֨י⁠ךָ֙ אֲשֶׁ֣ר תֹּאמַ֔ר מִ֥י אֲבִימֶ֖לֶךְ כִּ֣י נַעַבְדֶ֑⁠נּוּ הֲ⁠לֹ֨א זֶ֤ה הָ⁠עָם֙ אֲשֶׁ֣ר מָאַ֣סְתָּה בּ֔⁠וֹ צֵא־נָ֥א עַתָּ֖ה וְ⁠הִלָּ֥חֶם בּֽ⁠וֹ׃ס","wa⁠yò̇֨ʼmer ʼélá֜y⁠w zĕbu֗l ʼayé̇֨h ʼép֥wòʼ pi֨y⁠ká֙ ʼàşě֣r ţò̇ʼma֔r mi֥y ʼàbiyme֖lekĕ ki֣̇y naʻabĕde֑⁠ṅẇ hà⁠lò֨ʼ ze֤h há⁠ʻám֙ ʼàşě֣r máʼa֣sĕţá̇h ḃ֔⁠wò ẕéʼ-ná֥ʼ ʻaţá֖̇h wĕ⁠hilá֥̇ẖem ḃֽ⁠wò׃s"],[9,39,"וַ⁠יֵּ֣צֵא גַ֔עַל לִ⁠פְנֵ֖י בַּעֲלֵ֣י שְׁכֶ֑ם וַ⁠יִּלָּ֖חֶם בַּ⁠אֲבִימֶֽלֶךְ׃","wa⁠yé֣̇ẕéʼ ga֔ʻal li⁠pĕné֖y bȧʻàlé֣y şĕ̌ke֑m wa⁠yi̇lá֖̇ẖem bȧ⁠ʼàbiymeֽlekĕ׃"],[9,40,"וַ⁠יִּרְדְּפֵ֣⁠הוּ אֲבִימֶ֔לֶךְ וַ⁠יָּ֖נָס מִ⁠פָּנָ֑י⁠ו וַֽ⁠יִּפְּל֛וּ חֲלָלִ֥ים רַבִּ֖ים עַד־פֶּ֥תַח הַ⁠שָּֽׁעַר׃","wa⁠yi̇rĕdĕ̇pé֣⁠hẇ ʼàbiyme֔lekĕ wa⁠yá֖̇nás mi⁠pá̇ná֑y⁠w waֽ⁠yi̇pĕ̇l֛ẇ ẖàláli֥ym rabi֖̇ym ʻad-pė֥ţaẖ ha⁠şáֽ̇̌ʻar׃"],[9,41,"וַ⁠יֵּ֥שֶׁב אֲבִימֶ֖לֶךְ בָּ⁠ארוּמָ֑ה וַ⁠יְגָ֧רֶשׁ זְבֻ֛ל אֶת־גַּ֥עַל וְ⁠אֶת־אֶחָ֖י⁠ו מִ⁠שֶּׁ֥בֶת בִּ⁠שְׁכֶֽם׃","wa⁠yé֥̇şěb ʼàbiyme֖lekĕ bá̇⁠ʼrẇmá֑h wa⁠yĕgá֧reş̌ zĕbu֛l ʼeţ-gȧ֥ʻal wĕ⁠ʼeţ-ʼeẖá֖y⁠w mi⁠şė֥̌beţ bi̇⁠şĕ̌keֽm׃"],[9,42,"וַֽ⁠יְהִי֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יֵּצֵ֥א הָ⁠עָ֖ם הַ⁠שָּׂדֶ֑ה וַ⁠יַּגִּ֖דוּ לַ⁠אֲבִימֶֽלֶךְ׃","waֽ⁠yĕhiy֙ miֽ⁠má̇ẖorá֔ţ wa⁠yé̇ẕé֥ʼ há⁠ʻá֖m ha⁠şá̇̂de֑h wa⁠yȧgi֖̇dẇ la⁠ʼàbiymeֽlekĕ׃"],[9,43,"וַ⁠יִּקַּ֣ח אֶת־הָ⁠עָ֗ם וַֽ⁠יֶּחֱצֵ⁠ם֙ לִ⁠שְׁלֹשָׁ֣ה רָאשִׁ֔ים וַ⁠יֶּאֱרֹ֖ב בַּ⁠שָּׂדֶ֑ה וַ⁠יַּ֗רְא וְ⁠הִנֵּ֤ה הָ⁠עָם֙ יֹצֵ֣א מִן־הָ⁠עִ֔יר וַ⁠יָּ֥קָם עֲלֵי⁠הֶ֖ם וַ⁠יַּכֵּֽ⁠ם׃","wa⁠yi̇qȧ֣ẖ ʼeţ-há⁠ʻá֗m waֽ⁠yėẖèẕé⁠m֙ li⁠şĕ̌lòşá֣̌h ráʼşǐ֔ym wa⁠yėʼèrò֖b bȧ⁠şá̇̂de֑h wa⁠yȧ֗rĕʼ wĕ⁠hiné֤̇h há⁠ʻám֙ yòẕé֣ʼ min-há⁠ʻi֔yr wa⁠yá֥̇qám ʻàléy⁠he֖m wa⁠yȧkéֽ̇⁠m׃"],[9,44,"וַ⁠אֲבִימֶ֗לֶךְ וְ⁠הָ⁠רָאשִׁים֙ אֲשֶׁ֣ר עִמּ֔⁠וֹ פָּשְׁט֕וּ וַ⁠יַּ֣עַמְד֔וּ פֶּ֖תַח שַׁ֣עַר הָ⁠עִ֑יר וּ⁠שְׁנֵ֣י הָֽ⁠רָאשִׁ֗ים פָּֽשְׁט֛וּ עַֽל־כָּל־אֲשֶׁ֥ר בַּ⁠שָּׂדֶ֖ה וַ⁠יַּכּֽוּ⁠ם׃","wa⁠ʼàbiyme֗lekĕ wĕ⁠há⁠ráʼşǐym֙ ʼàşě֣r ʻiṁ֔⁠wò pá̇şĕ̌t֕ẇ wa⁠yȧ֣ʻamĕd֔ẇ pė֖ţaẖ şǎ֣ʻar há⁠ʻi֑yr ẇ⁠şĕ̌né֣y hֽá⁠ráʼşǐ֗ym páֽ̇şĕ̌t֛ẇ ʻaֽl-ká̇l-ʼàşě֥r bȧ⁠şá̇̂de֖h wa⁠yȧkֽ̇ẇ⁠m׃"],[9,45,"וַ⁠אֲבִימֶ֜לֶךְ נִלְחָ֣ם בָּ⁠עִ֗יר כֹּ֚ל הַ⁠יּ֣וֹם הַ⁠ה֔וּא וַ⁠יִּלְכֹּד֙ אֶת־הָ⁠עִ֔יר וְ⁠אֶת־הָ⁠עָ֥ם אֲשֶׁר־בָּ֖⁠הּ הָרָ֑ג וַ⁠יִּתֹּץ֙ אֶת־הָ⁠עִ֔יר וַ⁠יִּזְרָעֶ֖⁠הָ מֶֽלַח׃פ","wa⁠ʼàbiyme֜lekĕ nilĕẖá֣m bá̇⁠ʻi֗yr kò֚̇l ha⁠ẏ֣wòm ha⁠h֔ẇʼ wa⁠yi̇lĕkò̇d֙ ʼeţ-há⁠ʻi֔yr wĕ⁠ʼeţ-há⁠ʻá֥m ʼàşěr-bá֖̇⁠ḣ hárá֑g wa⁠yi̇ţò̇ẕ֙ ʼeţ-há⁠ʻi֔yr wa⁠yi̇zĕráʻe֖⁠há meֽlaẖ׃p"],[9,46,"וַֽ⁠יִּשְׁמְע֔וּ כָּֽל־בַּעֲלֵ֖י מִֽגְדַּל־שְׁכֶ֑ם וַ⁠יָּבֹ֣אוּ אֶל־צְרִ֔יחַ בֵּ֖ית אֵ֥ל בְּרִֽית׃","waֽ⁠yi̇şĕ̌mĕʻ֔ẇ káֽ̇l-bȧʻàlé֖y miֽgĕdȧl-şĕ̌ke֑m wa⁠yá̇bò֣ʼẇ ʼel-ẕĕri֔yẖa bé֖̇yţ ʼé֥l bĕ̇riֽyţ׃"],[9,47,"וַ⁠יֻּגַּ֖ד לַ⁠אֲבִימֶ֑לֶךְ כִּ֣י הִֽתְקַבְּצ֔וּ כָּֽל־בַּעֲלֵ֖י מִֽגְדַּל־שְׁכֶֽם׃","wa⁠yu̇gȧ֖d la⁠ʼàbiyme֑lekĕ ki֣̇y hiֽţĕqabĕ̇ẕ֔ẇ káֽ̇l-bȧʻàlé֖y miֽgĕdȧl-şĕ̌keֽm׃"],[9,48,"וַ⁠יַּ֨עַל אֲבִימֶ֜לֶךְ הַר־צַלְמ֗וֹן הוּא֮ וְ⁠כָל־הָ⁠עָ֣ם אֲשֶׁר־אִתּ⁠וֹ֒ וַ⁠יִּקַּח֩ אֲבִימֶ֨לֶךְ אֶת־הַ⁠קַּרְדֻּמּ֜וֹת בְּ⁠יָד֗⁠וֹ וַ⁠יִּכְרֹת֙ שׂוֹכַ֣ת עֵצִ֔ים וַ⁠יִּ֨שָּׂאֶ֔⁠הָ וַ⁠יָּ֖שֶׂם עַל־שִׁכְמ֑⁠וֹ וַ⁠יֹּ֜אמֶר אֶל־הָ⁠עָ֣ם אֲשֶׁר־עִמּ֗⁠וֹ מָ֤ה רְאִיתֶם֙ עָשִׂ֔יתִי מַהֲר֖וּ עֲשׂ֥וּ כָמֽוֹ⁠נִי׃","wa⁠yȧ֨ʻal ʼàbiyme֜lekĕ har-ẕalĕm֗wòn hẇʼ֮ wĕ⁠kál-há⁠ʻá֣m ʼàşěr-ʼiţ̇⁠wò֒ wa⁠yi̇qȧẖ֩ ʼàbiyme֨lekĕ ʼeţ-ha⁠qȧrĕdu̇ṁ֜wòţ bĕ̇⁠yád֗⁠wò wa⁠yi̇kĕròţ֙ ş̂wòka֣ţ ʻéẕi֔ym wa⁠yi̇֨şá̇̂ʼe֔⁠há wa⁠yá֖̇şêm ʻal-şǐkĕm֑⁠wò wa⁠yò̇֜ʼmer ʼel-há⁠ʻá֣m ʼàşěr-ʻiṁ֗⁠wò má֤h rĕʼiyţem֙ ʻáşî֔yţiy mahàr֖ẇ ʻàş֥̂ẇ kámֽwò⁠niy׃"],[9,49,"וַ⁠יִּכְרְת֨וּ גַם־כָּל־הָ⁠עָ֜ם אִ֣ישׁ שׂוֹכֹ֗⁠ה וַ⁠יֵּ֨לְכ֜וּ אַחֲרֵ֤י אֲבִימֶ֨לֶךְ֙ וַ⁠יָּשִׂ֣ימוּ עַֽל־הַ⁠צְּרִ֔יחַ וַ⁠יַּצִּ֧יתוּ עֲלֵי⁠הֶ֛ם אֶֽת־הַ⁠צְּרִ֖יחַ בָּ⁠אֵ֑שׁ וַ⁠יָּמֻ֜תוּ גַּ֣ם כָּל־אַנְשֵׁ֧י מִֽגְדַּל־שְׁכֶ֛ם כְּ⁠אֶ֖לֶף אִ֥ישׁ וְ⁠אִשָּֽׁה׃פ","wa⁠yi̇kĕrĕţ֨ẇ gam-ká̇l-há⁠ʻá֜m ʼi֣yş̌ ş̂wòkò֗⁠h wa⁠yé̇֨lĕk֜ẇ ʼaẖàré֤y ʼàbiyme֨lekĕ֙ wa⁠yá̇şî֣ymẇ ʻaֽl-ha⁠ẕĕ̇ri֔yẖa wa⁠yȧẕi֧̇yţẇ ʻàléy⁠he֛m ʼeֽţ-ha⁠ẕĕ̇ri֖yẖa bá̇⁠ʼé֑ş̌ wa⁠yá̇mu֜ţẇ gȧ֣m ká̇l-ʼanĕşé֧̌y miֽgĕdȧl-şĕ̌ke֛m kĕ̇⁠ʼe֖lep ʼi֥yş̌ wĕ⁠ʼişáֽ̇̌h׃p"],[9,50,"וַ⁠יֵּ֥לֶךְ אֲבִימֶ֖לֶךְ אֶל־תֵּבֵ֑ץ וַ⁠יִּ֥חַן בְּ⁠תֵבֵ֖ץ וַֽ⁠יִּלְכְּדָֽ⁠הּ׃","wa⁠yé֥̇lekĕ ʼàbiyme֖lekĕ ʼel-ţé̇bé֑ẕ wa⁠yi֥̇ẖan bĕ̇⁠ţébé֖ẕ waֽ⁠yi̇lĕkĕ̇dáֽ⁠ḣ׃"],[9,51,"וּ⁠מִגְדַּל־עֹז֮ הָיָ֣ה בְ⁠תוֹךְ־הָ⁠עִיר֒ וַ⁠יָּנֻ֨סוּ שָׁ֜מָּ⁠ה כָּל־הָ⁠אֲנָשִׁ֣ים וְ⁠הַ⁠נָּשִׁ֗ים וְ⁠כֹל֙ בַּעֲלֵ֣י הָ⁠עִ֔יר וַֽ⁠יִּסְגְּר֖וּ בַּעֲדָ֑⁠ם וַֽ⁠יַּעֲל֖וּ עַל־גַּ֥ג הַ⁠מִּגְדָּֽל׃","ẇ⁠migĕdȧl-ʻòz֮ háyá֣h bĕ⁠ţwòkĕ-há⁠ʻiyr֒ wa⁠yá̇nu֨sẇ şá̌֜má̇⁠h ká̇l-há⁠ʼànáşǐ֣ym wĕ⁠ha⁠ná̇şǐ֗ym wĕ⁠kòl֙ bȧʻàlé֣y há⁠ʻi֔yr waֽ⁠yi̇sĕgĕ̇r֖ẇ bȧʻàdá֑⁠m waֽ⁠yȧʻàl֖ẇ ʻal-gȧ֥g ha⁠mi̇gĕdáֽ̇l׃"],[9,52,"וַ⁠יָּבֹ֤א אֲבִימֶ֨לֶךְ֙ עַד־הַ⁠מִּגְדָּ֔ל וַ⁠יִּלָּ֖חֶם בּ֑⁠וֹ וַ⁠יִּגַּ֛שׁ עַד־פֶּ֥תַח הַ⁠מִּגְדָּ֖ל לְ⁠שָׂרְפ֥⁠וֹ בָ⁠אֵֽשׁ׃","wa⁠yá̇bò֤ʼ ʼàbiyme֨lekĕ֙ ʻad-ha⁠mi̇gĕdá̇֔l wa⁠yi̇lá֖̇ẖem ḃ֑⁠wò wa⁠yi̇gȧ֛ş̌ ʻad-pė֥ţaẖ ha⁠mi̇gĕdá֖̇l lĕ⁠şá̂rĕp֥⁠wò bá⁠ʼéֽş̌׃"],[9,53,"וַ⁠תַּשְׁלֵ֞ךְ אִשָּׁ֥ה אַחַ֛ת פֶּ֥לַח רֶ֖כֶב עַל־רֹ֣אשׁ אֲבִימֶ֑לֶךְ וַ⁠תָּ֖רִץ אֶת־גֻּלְגָּלְתּֽ⁠וֹ׃","wa⁠ţȧşĕ̌lé֞kĕ ʼişá֥̇̌h ʼaẖa֛ţ pė֥laẖ re֖keb ʻal-rò֣ʼş̌ ʼàbiyme֑lekĕ wa⁠ţá֖̇riẕ ʼeţ-gu̇lĕgá̇lĕţֽ̇⁠wò׃"],[9,54,"וַ⁠יִּקְרָ֨א מְהֵרָ֜ה אֶל־הַ⁠נַּ֣עַר ׀ נֹשֵׂ֣א כֵלָ֗י⁠ו וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ שְׁלֹ֤ף חַרְבְּ⁠ךָ֙ וּ⁠מ֣וֹתְתֵ֔⁠נִי פֶּן־יֹ֥אמְרוּ לִ֖⁠י אִשָּׁ֣ה הֲרָגָ֑תְ⁠הוּ וַ⁠יִּדְקְרֵ֥⁠הוּ נַעֲר֖⁠וֹ וַ⁠יָּמֹֽת׃","wa⁠yi̇qĕrá֨ʼ mĕhérá֜h ʼel-ha⁠nȧ֣ʻar ׀ nòşé֣̂ʼ kélá֗y⁠w wa⁠yò֤̇ʼmer l⁠wò֙ şĕ̌lò֤p ẖarĕbĕ̇⁠ká֙ ẇ⁠m֣wòţĕţé֔⁠niy pėn-yò֥ʼmĕrẇ li֖⁠y ʼişá֣̇̌h hàrágá֑ţĕ⁠hẇ wa⁠yi̇dĕqĕré֥⁠hẇ naʻàr֖⁠wò wa⁠yá̇mòֽţ׃"],[9,55,"וַ⁠יִּרְא֥וּ אִֽישׁ־יִשְׂרָאֵ֖ל כִּ֣י מֵ֣ת אֲבִימֶ֑לֶךְ וַ⁠יֵּלְכ֖וּ אִ֥ישׁ לִ⁠מְקֹמֽ⁠וֹ׃","wa⁠yi̇rĕʼ֥ẇ ʼiֽyş̌-yişĕ̂ráʼé֖l ki֣̇y mé֣ţ ʼàbiyme֑lekĕ wa⁠yé̇lĕk֖ẇ ʼi֥yş̌ li⁠mĕqòmֽ⁠wò׃"],[9,56,"וַ⁠יָּ֣שֶׁב אֱלֹהִ֔ים אֵ֖ת רָעַ֣ת אֲבִימֶ֑לֶךְ אֲשֶׁ֤ר עָשָׂה֙ לְ⁠אָבִ֔י⁠ו לַ⁠הֲרֹ֖ג אֶת־שִׁבְעִ֥ים אֶחָֽי⁠ו׃","wa⁠yá֣̇şěb ʼèlòhi֔ym ʼé֖ţ ráʻa֣ţ ʼàbiyme֑lekĕ ʼàşě֤r ʻáşá̂h֙ lĕ⁠ʼábi֔y⁠w la⁠hàrò֖g ʼeţ-şǐbĕʻi֥ym ʼeẖáֽy⁠w׃"],[9,57,"וְ⁠אֵ֗ת כָּל־רָעַת֙ אַנְשֵׁ֣י שְׁכֶ֔ם הֵשִׁ֥יב אֱלֹהִ֖ים בְּ⁠רֹאשָׁ֑⁠ם וַ⁠תָּבֹ֣א אֲלֵי⁠הֶ֔ם קִֽלֲלַ֖ת יוֹתָ֥ם בֶּן־יְרֻבָּֽעַל׃פ","wĕ⁠ʼé֗ţ ká̇l-ráʻaţ֙ ʼanĕşé֣̌y şĕ̌ke֔m héşǐ֥yb ʼèlòhi֖ym bĕ̇⁠ròʼşá֑̌⁠m wa⁠ţá̇bò֣ʼ ʼàléy⁠he֔m qiֽlàla֖ţ ywòţá֥m bėn-yĕrubáֽ̇ʻal׃p"],[10,1,"וַ⁠יָּקָם֩ אַחֲרֵ֨י אֲבִימֶ֜לֶךְ לְ⁠הוֹשִׁ֣יעַ אֶת־יִשְׂרָאֵ֗ל תּוֹלָ֧ע בֶּן־פּוּאָ֛ה בֶּן־דּוֹד֖וֹ אִ֣ישׁ יִשָּׂשכָ֑ר וְ⁠הֽוּא־יֹשֵׁ֥ב בְּ⁠שָׁמִ֖יר בְּ⁠הַ֥ר אֶפְרָֽיִם׃","wa⁠yá̇qám֩ ʼaẖàré֨y ʼàbiyme֜lekĕ lĕ⁠hwòşǐ֣yʻa ʼeţ-yişĕ̂ráʼé֗l ţ̇wòlá֧ʻ bėn-ṗẇʼá֛h bėn-ḋwòd֖wò ʼi֣yş̌ yişá̇̂şká֑r wĕ⁠hֽẇʼ-yòşé֥̌b bĕ̇⁠şá̌mi֖yr bĕ̇⁠ha֥r ʼepĕráֽyim׃"],[10,2,"וַ⁠יִּשְׁפֹּט֙ אֶת־יִשְׂרָאֵ֔ל עֶשְׂרִ֥ים וְ⁠שָׁלֹ֖שׁ שָׁנָ֑ה וַ⁠יָּ֖מָת וַ⁠יִּקָּבֵ֥ר בְּ⁠שָׁמִֽיר׃פ","wa⁠yi̇şĕ̌pò̇t֙ ʼeţ-yişĕ̂ráʼé֔l ʻeşĕ̂ri֥ym wĕ⁠şá̌lò֖ş̌ şá̌ná֑h wa⁠yá֖̇máţ wa⁠yi̇qá̇bé֥r bĕ̇⁠şá̌miֽyr׃p"],[10,3,"וַ⁠יָּ֣קָם אַחֲרָ֔י⁠ו יָאִ֖יר הַ⁠גִּלְעָדִ֑י וַ⁠יִּשְׁפֹּט֙ אֶת־יִשְׂרָאֵ֔ל עֶשְׂרִ֥ים וּ⁠שְׁתַּ֖יִם שָׁנָֽה׃","wa⁠yá֣̇qám ʼaẖàrá֔y⁠w yáʼi֖yr ha⁠gi̇lĕʻádi֑y wa⁠yi̇şĕ̌pò̇t֙ ʼeţ-yişĕ̂ráʼé֔l ʻeşĕ̂ri֥ym ẇ⁠şĕ̌ţȧ֖yim şá̌náֽh׃"],[10,4,"וַֽ⁠יְהִי־ל֞⁠וֹ שְׁלֹשִׁ֣ים בָּנִ֗ים רֹֽכְבִים֙ עַל־שְׁלֹשִׁ֣ים עֲיָרִ֔ים וּ⁠שְׁלֹשִׁ֥ים עֲיָרִ֖ים לָ⁠הֶ֑ם לָ⁠הֶ֞ם יִקְרְא֣וּ ׀ חַוֺּ֣ת יָאִ֗יר עַ֚ד הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה אֲשֶׁ֖ר בְּ⁠אֶ֥רֶץ הַ⁠גִּלְעָֽד׃","waֽ⁠yĕhiy-l֞⁠wò şĕ̌lòşǐ֣ym bá̇ni֗ym ròֽkĕbiym֙ ʻal-şĕ̌lòşǐ֣ym ʻàyári֔ym ẇ⁠şĕ̌lòşǐ֥ym ʻàyári֖ym lá⁠he֑m lá⁠he֞m yiqĕrĕʼ֣ẇ ׀ ẖaẇֺ֣ţ yáʼi֗yr ʻa֚d ha⁠ẏ֣wòm ha⁠zė֔h ʼàşě֖r bĕ̇⁠ʼe֥reẕ ha⁠gi̇lĕʻáֽd׃"],[10,5,"וַ⁠יָּ֣מָת יָאִ֔יר וַ⁠יִּקָּבֵ֖ר בְּ⁠קָמֽוֹן׃פ","wa⁠yá֣̇máţ yáʼi֔yr wa⁠yi̇qá̇bé֖r bĕ̇⁠qámֽwòn׃p"],[10,6,"וַ⁠יֹּסִ֣פוּ ׀ בְּנֵ֣י יִשְׂרָאֵ֗ל לַ⁠עֲשׂ֣וֹת הָ⁠רַע֮ בְּ⁠עֵינֵ֣י יְהוָה֒ וַ⁠יַּעַבְד֣וּ אֶת־הַ⁠בְּעָלִ֣ים וְ⁠אֶת־הָ⁠עַשְׁתָּר֡וֹת וְ⁠אֶת־אֱלֹהֵ֣י אֲרָם֩ וְ⁠אֶת־אֱלֹהֵ֨י צִיד֜וֹן וְ⁠אֵ֣ת ׀ אֱלֹהֵ֣י מוֹאָ֗ב וְ⁠אֵת֙ אֱלֹהֵ֣י בְנֵי־עַמּ֔וֹן וְ⁠אֵ֖ת אֱלֹהֵ֣י פְלִשְׁתִּ֑ים וַ⁠יַּעַזְב֥וּ אֶת־יְהוָ֖ה וְ⁠לֹ֥א עֲבָדֽוּ⁠הוּ׃","wa⁠yò̇si֣pẇ ׀ bĕ̇né֣y yişĕ̂ráʼé֗l la⁠ʻàş֣̂wòţ há⁠raʻ֮ bĕ̇⁠ʻéyné֣y yĕhwáh֒ wa⁠yȧʻabĕd֣ẇ ʼeţ-ha⁠bĕ̇ʻáli֣ym wĕ⁠ʼeţ-há⁠ʻaşĕ̌ţá̇r֡wòţ wĕ⁠ʼeţ-ʼèlòhé֣y ʼàrám֩ wĕ⁠ʼeţ-ʼèlòhé֨y ẕiyd֜wòn wĕ⁠ʼé֣ţ ׀ ʼèlòhé֣y mwòʼá֗b wĕ⁠ʼéţ֙ ʼèlòhé֣y bĕnéy-ʻaṁ֔wòn wĕ⁠ʼé֖ţ ʼèlòhé֣y pĕlişĕ̌ţi֑̇ym wa⁠yȧʻazĕb֥ẇ ʼeţ-yĕhwá֖h wĕ⁠lò֥ʼ ʻàbádֽẇ⁠hẇ׃"],[10,7,"וַ⁠יִּֽחַר־אַ֥ף יְהוָ֖ה בְּ⁠יִשְׂרָאֵ֑ל וַֽ⁠יִּמְכְּרֵ⁠ם֙ בְּ⁠יַד־פְּלִשְׁתִּ֔ים וּ⁠בְ⁠יַ֖ד בְּנֵ֥י עַמּֽוֹן׃","wa⁠yiֽ̇ẖar-ʼa֥p yĕhwá֖h bĕ̇⁠yişĕ̂ráʼé֑l waֽ⁠yi̇mĕkĕ̇ré⁠m֙ bĕ̇⁠yad-pĕ̇lişĕ̌ţi̇֔ym ẇ⁠bĕ⁠ya֖d bĕ̇né֥y ʻaṁֽwòn׃"],[10,8,"וַֽ⁠יִּרְעֲצ֤וּ וַ⁠יְרֹֽצְצוּ֙ אֶת־בְּנֵ֣י יִשְׂרָאֵ֔ל בַּ⁠שָּׁנָ֖ה הַ⁠הִ֑יא שְׁמֹנֶ֨ה עֶשְׂרֵ֜ה שָׁנָ֗ה אֶֽת־כָּל־בְּנֵ֤י יִשְׂרָאֵל֙ אֲשֶׁר֙ בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֔ן בְּ⁠אֶ֥רֶץ הָ⁠אֱמֹרִ֖י אֲשֶׁ֥ר בַּ⁠גִּלְעָֽד׃","waֽ⁠yi̇rĕʻàẕ֤ẇ wa⁠yĕròֽẕĕẕẇ֙ ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֔l bȧ⁠şá̇̌ná֖h ha⁠hi֑yʼ şĕ̌mòne֨h ʻeşĕ̂ré֜h şá̌ná֗h ʼeֽţ-ká̇l-bĕ̇né֤y yişĕ̂ráʼél֙ ʼàşěr֙ bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé̇֔n bĕ̇⁠ʼe֥reẕ há⁠ʼèmòri֖y ʼàşě֥r bȧ⁠gi̇lĕʻáֽd׃"],[10,9,"וַ⁠יַּעַבְר֤וּ בְנֵֽי־עַמּוֹן֙ אֶת־הַ⁠יַּרְדֵּ֔ן לְ⁠הִלָּחֵ֛ם גַּם־בִּ⁠יהוּדָ֥ה וּ⁠בְ⁠בִנְיָמִ֖ין וּ⁠בְ⁠בֵ֣ית אֶפְרָ֑יִם וַ⁠תֵּ֥צֶר לְ⁠יִשְׂרָאֵ֖ל מְאֹֽד׃","wa⁠yȧʻabĕr֤ẇ bĕnéֽy-ʻaṁwòn֙ ʼeţ-ha⁠yȧrĕdé̇֔n lĕ⁠hilá̇ẖé֛m gȧm-bi̇⁠yhẇdá֥h ẇ⁠bĕ⁠binĕyámi֖yn ẇ⁠bĕ⁠bé֣yţ ʼepĕrá֑yim wa⁠ţé֥̇ẕer lĕ⁠yişĕ̂ráʼé֖l mĕʼòֽd׃"],[10,10,"וַֽ⁠יִּזְעֲקוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֶל־יְהוָ֖ה לֵ⁠אמֹ֑ר חָטָ֣אנוּ לָ֔⁠ךְ וְ⁠כִ֤י עָזַ֨בְנוּ֙ אֶת־אֱלֹהֵ֔י⁠נוּ וַֽ⁠נַּעֲבֹ֖ד אֶת־הַ⁠בְּעָלִֽים׃פ","waֽ⁠yi̇zĕʻàqẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼel-yĕhwá֖h lé⁠ʼmò֑r ẖátá֣ʼnẇ lá֔⁠kĕ wĕ⁠ki֤y ʻáza֨bĕnẇ֙ ʼeţ-ʼèlòhé֔y⁠nẇ waֽ⁠nȧʻàbò֖d ʼeţ-ha⁠bĕ̇ʻáliֽym׃p"],[10,11,"וַ֥⁠יֹּאמֶר יְהוָ֖ה אֶל־בְּנֵ֣י יִשְׂרָאֵ֑ל הֲ⁠לֹ֤א מִ⁠מִּצְרַ֨יִם֙ וּ⁠מִן־הָ֣⁠אֱמֹרִ֔י וּ⁠מִן־בְּנֵ֥י עַמּ֖וֹן וּ⁠מִן־פְּלִשְׁתִּֽים׃","wa֥⁠yò̇ʼmer yĕhwá֖h ʼel-bĕ̇né֣y yişĕ̂ráʼé֑l hà⁠lò֤ʼ mi⁠mi̇ẕĕra֨yim֙ ẇ⁠min-há֣⁠ʼèmòri֔y ẇ⁠min-bĕ̇né֥y ʻaṁ֖wòn ẇ⁠min-pĕ̇lişĕ̌ţiֽ̇ym׃"],[10,12,"וְ⁠צִידוֹנִ֤ים וַֽ⁠עֲמָלֵק֙ וּ⁠מָע֔וֹן לָחֲצ֖וּ אֶתְ⁠כֶ֑ם וַ⁠תִּצְעֲק֣וּ אֵלַ֔⁠י וָ⁠אוֹשִׁ֥יעָ⁠ה אֶתְ⁠כֶ֖ם מִ⁠יָּדָֽ⁠ם׃","wĕ⁠ẕiydwòni֤ym waֽ⁠ʻàmáléq֙ ẇ⁠máʻ֔wòn láẖàẕ֖ẇ ʼeţĕ⁠ke֑m wa⁠ţi̇ẕĕʻàq֣ẇ ʼéla֔⁠y wá⁠ʼwòşǐ֥yʻá⁠h ʼeţĕ⁠ke֖m mi⁠yá̇dáֽ⁠m׃"],[10,13,"וְ⁠אַתֶּם֙ עֲזַבְתֶּ֣ם אוֹתִ֔⁠י וַ⁠תַּעַבְד֖וּ אֱלֹהִ֣ים אֲחֵרִ֑ים לָ⁠כֵ֥ן לֹֽא־אוֹסִ֖יף לְ⁠הוֹשִׁ֥יעַ אֶתְ⁠כֶֽם׃","wĕ⁠ʼaţėm֙ ʻàzabĕţė֣m ʼwòţi֔⁠y wa⁠ţȧʻabĕd֖ẇ ʼèlòhi֣ym ʼàẖéri֑ym lá⁠ké֥n lòֽʼ-ʼwòsi֖yp lĕ⁠hwòşǐ֥yʻa ʼeţĕ⁠keֽm׃"],[10,14,"לְכ֗וּ וְ⁠זַֽעֲקוּ֙ אֶל־הָ֣⁠אֱלֹהִ֔ים אֲשֶׁ֥ר בְּחַרְתֶּ֖ם בָּ֑⁠ם הֵ֛מָּה יוֹשִׁ֥יעוּ לָ⁠כֶ֖ם בְּ⁠עֵ֥ת צָרַתְ⁠כֶֽם׃","lĕk֗ẇ wĕ⁠zaֽʻàqẇ֙ ʼel-há֣⁠ʼèlòhi֔ym ʼàşě֥r bĕ̇ẖarĕţė֖m bá֑̇⁠m hé֛má̇h ywòşǐ֥yʻẇ lá⁠ke֖m bĕ̇⁠ʻé֥ţ ẕáraţĕ⁠keֽm׃"],[10,15,"וַ⁠יֹּאמְר֨וּ בְנֵי־יִשְׂרָאֵ֤ל אֶל־יְהוָה֙ חָטָ֔אנוּ עֲשֵׂה־אַתָּ֣ה לָ֔⁠נוּ כְּ⁠כָל־הַ⁠טּ֖וֹב בְּ⁠עֵינֶ֑י⁠ךָ אַ֛ךְ הַצִּילֵ֥⁠נוּ נָ֖א הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yò̇ʼmĕr֨ẇ bĕnéy-yişĕ̂ráʼé֤l ʼel-yĕhwáh֙ ẖátá֔ʼnẇ ʻàşé̂h-ʼaţá֣̇h lá֔⁠nẇ kĕ̇⁠kál-ha⁠ṫ֖wòb bĕ̇⁠ʻéyne֑y⁠ká ʼa֛kĕ haẕi̇ylé֥⁠nẇ ná֖ʼ ha⁠ẏ֥wòm ha⁠zėֽh׃"],[10,16,"וַ⁠יָּסִ֜ירוּ אֶת־אֱלֹהֵ֤י הַ⁠נֵּכָר֙ מִ⁠קִּרְבָּ֔⁠ם וַ⁠יַּעַבְד֖וּ אֶת־יְהוָ֑ה וַ⁠תִּקְצַ֥ר נַפְשׁ֖⁠וֹ בַּ⁠עֲמַ֥ל יִשְׂרָאֵֽל׃פ","wa⁠yá̇si֜yrẇ ʼeţ-ʼèlòhé֤y ha⁠né̇kár֙ mi⁠qi̇rĕbá̇֔⁠m wa⁠yȧʻabĕd֖ẇ ʼeţ-yĕhwá֑h wa⁠ţi̇qĕẕa֥r napĕş֖̌⁠wò bȧ⁠ʻàma֥l yişĕ̂ráʼéֽl׃p"],[10,17,"וַ⁠יִּצָּֽעֲקוּ֙ בְּנֵ֣י עַמּ֔וֹן וַֽ⁠יַּחֲנ֖וּ בַּ⁠גִּלְעָ֑ד וַ⁠יֵּאָֽסְפוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַֽ⁠יַּחֲנ֖וּ בַּ⁠מִּצְפָּֽה׃","wa⁠yi̇ẕáֽ̇ʻàqẇ֙ bĕ̇né֣y ʻaṁ֔wòn waֽ⁠yȧẖàn֖ẇ bȧ⁠gi̇lĕʻá֑d wa⁠yé̇ʼáֽsĕpẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l waֽ⁠yȧẖàn֖ẇ bȧ⁠mi̇ẕĕpáֽ̇h׃"],[10,18,"וַ⁠יֹּאמְר֨וּ הָ⁠עָ֜ם שָׂרֵ֤י גִלְעָד֙ אִ֣ישׁ אֶל־רֵעֵ֔⁠הוּ מִ֣י הָ⁠אִ֔ישׁ אֲשֶׁ֣ר יָחֵ֔ל לְ⁠הִלָּחֵ֖ם בִּ⁠בְנֵ֣י עַמּ֑וֹן יִֽהְיֶ֣ה לְ⁠רֹ֔אשׁ לְ⁠כֹ֖ל יֹשְׁבֵ֥י גִלְעָֽד׃פ","wa⁠yò̇ʼmĕr֨ẇ há⁠ʻá֜m şá̂ré֤y gilĕʻád֙ ʼi֣yş̌ ʼel-réʻé֔⁠hẇ mi֣y há⁠ʼi֔yş̌ ʼàşě֣r yáẖé֔l lĕ⁠hilá̇ẖé֖m bi̇⁠bĕné֣y ʻaṁ֑wòn yiֽhĕye֣h lĕ⁠rò֔ʼş̌ lĕ⁠kò֖l yòşĕ̌bé֥y gilĕʻáֽd׃p"],[11,1,"וְ⁠יִפְתָּ֣ח הַ⁠גִּלְעָדִ֗י הָיָה֙ גִּבּ֣וֹר חַ֔יִל וְ⁠ה֖וּא בֶּן־אִשָּׁ֣ה זוֹנָ֑ה וַ⁠יּ֥וֹלֶד גִּלְעָ֖ד אֶת־יִפְתָּֽח׃","wĕ⁠yipĕţá֣̇ẖ ha⁠gi̇lĕʻádi֗y háyáh֙ gi̇ḃ֣wòr ẖa֔yil wĕ⁠h֖ẇʼ bėn-ʼişá֣̇̌h zwòná֑h wa⁠ẏ֥wòled gi̇lĕʻá֖d ʼeţ-yipĕţáֽ̇ẖ׃"],[11,2,"וַ⁠תֵּ֧לֶד אֵֽשֶׁת־גִּלְעָ֛ד ל֖⁠וֹ בָּנִ֑ים וַ⁠יִּגְדְּל֨וּ בְֽנֵי־הָ⁠אִשָּׁ֜ה וַ⁠יְגָרְשׁ֣וּ אֶת־יִפְתָּ֗ח וַ⁠יֹּ֤אמְרוּ ל⁠וֹ֙ לֹֽא־תִנְחַ֣ל בְּ⁠בֵית־אָבִ֔י⁠נוּ כִּ֛י בֶּן־אִשָּׁ֥ה אַחֶ֖רֶת אָֽתָּה׃","wa⁠ţé֧̇led ʼéֽşěţ-gi̇lĕʻá֛d l֖⁠wò bá̇ni֑ym wa⁠yi̇gĕdĕ̇l֨ẇ bĕֽnéy-há⁠ʼişá̇̌֜h wa⁠yĕgárĕş֣̌ẇ ʼeţ-yipĕţá̇֗ẖ wa⁠yò֤̇ʼmĕrẇ l⁠wò֙ lòֽʼ-ţinĕẖa֣l bĕ̇⁠béyţ-ʼábi֔y⁠nẇ ki֛̇y bėn-ʼişá֥̇̌h ʼaẖe֖reţ ʼáֽţá̇h׃"],[11,3,"וַ⁠יִּבְרַ֤ח יִפְתָּח֙ מִ⁠פְּנֵ֣י אֶחָ֔י⁠ו וַ⁠יֵּ֖שֶׁב בְּ⁠אֶ֣רֶץ ט֑וֹב וַ⁠יִּֽתְלַקְּט֤וּ אֶל־יִפְתָּח֙ אֲנָשִׁ֣ים רֵיקִ֔ים וַ⁠יֵּצְא֖וּ עִמּֽ⁠וֹ׃פ","wa⁠yi̇bĕra֤ẖ yipĕţá̇ẖ֙ mi⁠pĕ̇né֣y ʼeẖá֔y⁠w wa⁠yé֖̇şěb bĕ̇⁠ʼe֣reẕ t֑wòb wa⁠yiֽ̇ţĕlaqĕ̇t֤ẇ ʼel-yipĕţá̇ẖ֙ ʼànáşǐ֣ym réyqi֔ym wa⁠yé̇ẕĕʼ֖ẇ ʻiṁֽ⁠wò׃p"],[11,4,"וַ⁠יְהִ֖י מִ⁠יָּמִ֑ים וַ⁠יִּלָּחֲמ֥וּ בְנֵֽי־עַמּ֖וֹן עִם־יִשְׂרָאֵֽל׃","wa⁠yĕhi֖y mi⁠yá̇mi֑ym wa⁠yi̇lá̇ẖàm֥ẇ bĕnéֽy-ʻaṁ֖wòn ʻim-yişĕ̂ráʼéֽl׃"],[11,5,"וַ⁠יְהִ֕י כַּ⁠אֲשֶׁר־נִלְחֲמ֥וּ בְנֵֽי־עַמּ֖וֹן עִם־יִשְׂרָאֵ֑ל וַ⁠יֵּֽלְכוּ֙ זִקְנֵ֣י גִלְעָ֔ד לָ⁠קַ֥חַת אֶת־יִפְתָּ֖ח מֵ⁠אֶ֥רֶץ טֽוֹב׃","wa⁠yĕhi֕y kȧ⁠ʼàşěr-nilĕẖàm֥ẇ bĕnéֽy-ʻaṁ֖wòn ʻim-yişĕ̂ráʼé֑l wa⁠yéֽ̇lĕkẇ֙ ziqĕné֣y gilĕʻá֔d lá⁠qa֥ẖaţ ʼeţ-yipĕţá֖̇ẖ mé⁠ʼe֥reẕ tֽwòb׃"],[11,6,"וַ⁠יֹּאמְר֣וּ לְ⁠יִפְתָּ֔ח לְכָ֕⁠ה וְ⁠הָיִ֥יתָה לָּ֖⁠נוּ לְ⁠קָצִ֑ין וְ⁠נִֽלָּחֲמָ֖ה בִּ⁠בְנֵ֥י עַמּֽוֹן׃","wa⁠yò̇ʼmĕr֣ẇ lĕ⁠yipĕţá̇֔ẖ lĕká֕⁠h wĕ⁠háyi֥yţáh lá֖̇⁠nẇ lĕ⁠qáẕi֑yn wĕ⁠niֽlá̇ẖàmá֖h bi̇⁠bĕné֥y ʻaṁֽwòn׃"],[11,7,"וַ⁠יֹּ֤אמֶר יִפְתָּח֙ לְ⁠זִקְנֵ֣י גִלְעָ֔ד הֲ⁠לֹ֤א אַתֶּם֙ שְׂנֵאתֶ֣ם אוֹתִ֔⁠י וַ⁠תְּגָרְשׁ֖וּ⁠נִי מִ⁠בֵּ֣ית אָבִ֑⁠י וּ⁠מַדּ֜וּעַ בָּאתֶ֤ם אֵלַ⁠י֙ עַ֔תָּה כַּ⁠אֲשֶׁ֖ר צַ֥ר לָ⁠כֶֽם׃","wa⁠yò֤̇ʼmer yipĕţá̇ẖ֙ lĕ⁠ziqĕné֣y gilĕʻá֔d hà⁠lò֤ʼ ʼaţėm֙ şĕ̂néʼţe֣m ʼwòţi֔⁠y wa⁠ţĕ̇gárĕş֖̌ẇ⁠niy mi⁠bé֣̇yţ ʼábi֑⁠y ẇ⁠maḋ֜ẇʻa bá̇ʼţe֤m ʼéla⁠y֙ ʻa֔ţá̇h kȧ⁠ʼàşě֖r ẕa֥r lá⁠keֽm׃"],[11,8,"וַ⁠יֹּאמְרוּ֩ זִקְנֵ֨י גִלְעָ֜ד אֶל־יִפְתָּ֗ח לָ⁠כֵן֙ עַתָּה֙ שַׁ֣בְנוּ אֵלֶ֔י⁠ךָ וְ⁠הָלַכְתָּ֣ עִמָּ֔⁠נוּ וְ⁠נִלְחַמְתָּ֖ בִּ⁠בְנֵ֣י עַמּ֑וֹן וְ⁠הָיִ֤יתָ לָּ֨⁠נוּ֙ לְ⁠רֹ֔אשׁ לְ⁠כֹ֖ל יֹשְׁבֵ֥י גִלְעָֽד׃","wa⁠yò̇ʼmĕrẇ֩ ziqĕné֨y gilĕʻá֜d ʼel-yipĕţá̇֗ẖ lá⁠kén֙ ʻaţá̇h֙ şǎ֣bĕnẇ ʼéle֔y⁠ká wĕ⁠hálakĕţá֣̇ ʻimá̇֔⁠nẇ wĕ⁠nilĕẖamĕţá֖̇ bi̇⁠bĕné֣y ʻaṁ֑wòn wĕ⁠háyi֤yţá lá̇֨⁠nẇ֙ lĕ⁠rò֔ʼş̌ lĕ⁠kò֖l yòşĕ̌bé֥y gilĕʻáֽd׃"],[11,9,"וַ⁠יֹּ֨אמֶר יִפְתָּ֜ח אֶל־זִקְנֵ֣י גִלְעָ֗ד אִם־מְשִׁיבִ֨ים אַתֶּ֤ם אוֹתִ⁠י֙ לְ⁠הִלָּחֵם֙ בִּ⁠בְנֵ֣י עַמּ֔וֹן וְ⁠נָתַ֧ן יְהוָ֛ה אוֹתָ֖⁠ם לְ⁠פָנָ֑⁠י אָנֹכִ֕י אֶהְיֶ֥ה לָ⁠כֶ֖ם לְ⁠רֹֽאשׁ׃","wa⁠yò̇֨ʼmer yipĕţá̇֜ẖ ʼel-ziqĕné֣y gilĕʻá֗d ʼim-mĕşǐybi֨ym ʼaţė֤m ʼwòţi⁠y֙ lĕ⁠hilá̇ẖém֙ bi̇⁠bĕné֣y ʻaṁ֔wòn wĕ⁠náţa֧n yĕhwá֛h ʼwòţá֖⁠m lĕ⁠páná֑⁠y ʼánòki֕y ʼehĕye֥h lá⁠ke֖m lĕ⁠ròֽʼş̌׃"],[11,10,"וַ⁠יֹּאמְר֥וּ זִקְנֵֽי־גִלְעָ֖ד אֶל־יִפְתָּ֑ח יְהוָ֗ה יִהְיֶ֤ה שֹׁמֵ֨עַ֙ בֵּֽינוֹתֵ֔י⁠נוּ אִם־לֹ֥א כִ⁠דְבָרְ⁠ךָ֖ כֵּ֥ן נַעֲשֶֽׂה׃","wa⁠yò̇ʼmĕr֥ẇ ziqĕnéֽy-gilĕʻá֖d ʼel-yipĕţá֑̇ẖ yĕhwá֗h yihĕye֤h şò̌mé֨ʻa֙ béֽ̇ynwòţé֔y⁠nẇ ʼim-lò֥ʼ ki⁠dĕbárĕ⁠ká֖ ké֥̇n naʻàşêֽh׃"],[11,11,"וַ⁠יֵּ֤לֶךְ יִפְתָּח֙ עִם־זִקְנֵ֣י גִלְעָ֔ד וַ⁠יָּשִׂ֨ימוּ הָ⁠עָ֥ם אוֹת֛⁠וֹ עֲלֵי⁠הֶ֖ם לְ⁠רֹ֣אשׁ וּ⁠לְ⁠קָצִ֑ין וַ⁠יְדַבֵּ֨ר יִפְתָּ֧ח אֶת־כָּל־דְּבָרָ֛י⁠ו לִ⁠פְנֵ֥י יְהוָ֖ה בַּ⁠מִּצְפָּֽה׃פ","wa⁠yé֤̇lekĕ yipĕţá̇ẖ֙ ʻim-ziqĕné֣y gilĕʻá֔d wa⁠yá̇şî֨ymẇ há⁠ʻá֥m ʼwòţ֛⁠wò ʻàléy⁠he֖m lĕ⁠rò֣ʼş̌ ẇ⁠lĕ⁠qáẕi֑yn wa⁠yĕdabé̇֨r yipĕţá֧̇ẖ ʼeţ-ká̇l-dĕ̇bárá֛y⁠w li⁠pĕné֥y yĕhwá֖h bȧ⁠mi̇ẕĕpáֽ̇h׃p"],[11,12,"וַ⁠יִּשְׁלַ֤ח יִפְתָּח֙ מַלְאָכִ֔ים אֶל־מֶ֥לֶךְ בְּנֵֽי־עַמּ֖וֹן לֵ⁠אמֹ֑ר מַה־לִּ֣⁠י וָ⁠לָ֔⁠ךְ כִּֽי־בָ֥אתָ אֵלַ֖⁠י לְ⁠הִלָּחֵ֥ם בְּ⁠אַרְצִֽ⁠י׃","wa⁠yi̇şĕ̌la֤ẖ yipĕţá̇ẖ֙ malĕʼáki֔ym ʼel-me֥lekĕ bĕ̇néֽy-ʻaṁ֖wòn lé⁠ʼmò֑r mah-li֣̇⁠y wá⁠lá֔⁠kĕ kiֽ̇y-bá֥ʼţá ʼéla֖⁠y lĕ⁠hilá̇ẖé֥m bĕ̇⁠ʼarĕẕiֽ⁠y׃"],[11,13,"וַ⁠יֹּאמֶר֩ מֶ֨לֶךְ בְּנֵי־עַמּ֜וֹן אֶל־מַלְאֲכֵ֣י יִפְתָּ֗ח כִּֽי־לָקַ֨ח יִשְׂרָאֵ֤ל אֶת־אַרְצִ⁠י֙ בַּ⁠עֲלוֹת֣⁠וֹ מִ⁠מִּצְרַ֔יִם מֵ⁠אַרְנ֥וֹן וְ⁠עַד־הַ⁠יַּבֹּ֖ק וְ⁠עַד־הַ⁠יַּרְדֵּ֑ן וְ⁠עַתָּ֕ה הָשִׁ֥יבָ⁠ה אֶתְ⁠הֶ֖ן בְּ⁠שָׁלֽוֹם׃","wa⁠yò̇ʼmer֩ me֨lekĕ bĕ̇néy-ʻaṁ֜wòn ʼel-malĕʼàké֣y yipĕţá̇֗ẖ kiֽ̇y-láqa֨ẖ yişĕ̂ráʼé֤l ʼeţ-ʼarĕẕi⁠y֙ bȧ⁠ʻàlwòţ֣⁠wò mi⁠mi̇ẕĕra֔yim mé⁠ʼarĕn֥wòn wĕ⁠ʻad-ha⁠yȧbò֖̇q wĕ⁠ʻad-ha⁠yȧrĕdé֑̇n wĕ⁠ʻaţá̇֕h háşǐ֥ybá⁠h ʼeţĕ⁠he֖n bĕ̇⁠şá̌lֽwòm׃"],[11,14,"וַ⁠יּ֥וֹסֶף ע֖וֹד יִפְתָּ֑ח וַ⁠יִּשְׁלַח֙ מַלְאָכִ֔ים אֶל־מֶ֖לֶךְ בְּנֵ֥י עַמּֽוֹן׃","wa⁠ẏ֥wòsep ʻ֖wòd yipĕţá֑̇ẖ wa⁠yi̇şĕ̌laẖ֙ malĕʼáki֔ym ʼel-me֖lekĕ bĕ̇né֥y ʻaṁֽwòn׃"],[11,15,"וַ⁠יֹּ֣אמֶר ל֔⁠וֹ כֹּ֖ה אָמַ֣ר יִפְתָּ֑ח לֹֽא־לָקַ֤ח יִשְׂרָאֵל֙ אֶת־אֶ֣רֶץ מוֹאָ֔ב וְ⁠אֶת־אֶ֖רֶץ בְּנֵ֥י עַמּֽוֹן׃","wa⁠yò֣̇ʼmer l֔⁠wò kò֖̇h ʼáma֣r yipĕţá֑̇ẖ lòֽʼ-láqa֤ẖ yişĕ̂ráʼél֙ ʼeţ-ʼe֣reẕ mwòʼá֔b wĕ⁠ʼeţ-ʼe֖reẕ bĕ̇né֥y ʻaṁֽwòn׃"],[11,16,"כִּ֖י בַּ⁠עֲלוֹתָ֣⁠ם מִ⁠מִּצְרָ֑יִם וַ⁠יֵּ֨לֶךְ יִשְׂרָאֵ֤ל בַּ⁠מִּדְבָּר֙ עַד־יַם־ס֔וּף וַ⁠יָּבֹ֖א קָדֵֽשָׁ⁠ה׃","ki֖̇y bȧ⁠ʻàlwòţá֣⁠m mi⁠mi̇ẕĕrá֑yim wa⁠yé̇֨lekĕ yişĕ̂ráʼé֤l bȧ⁠mi̇dĕbá̇r֙ ʻad-yam-s֔ẇp wa⁠yá̇bò֖ʼ qádéֽşá̌⁠h׃"],[11,17,"וַ⁠יִּשְׁלַ֣ח יִשְׂרָאֵ֣ל מַלְאָכִ֣ים ׀ אֶל־מֶלֶךְ֩ אֱד֨וֹם ׀ לֵ⁠אמֹ֜ר אֶעְבְּרָה־נָּ֣א בְ⁠אַרְצֶ֗⁠ךָ וְ⁠לֹ֤א שָׁמַע֙ מֶ֣לֶךְ אֱד֔וֹם וְ⁠גַ֨ם אֶל־מֶ֧לֶךְ מוֹאָ֛ב שָׁלַ֖ח וְ⁠לֹ֣א אָבָ֑ה וַ⁠יֵּ֥שֶׁב יִשְׂרָאֵ֖ל בְּ⁠קָדֵֽשׁ׃","wa⁠yi̇şĕ̌la֣ẖ yişĕ̂ráʼé֣l malĕʼáki֣ym ׀ ʼel-melekĕ֩ ʼèd֨wòm ׀ lé⁠ʼmò֜r ʼeʻĕbĕ̇ráh-ná֣̇ʼ bĕ⁠ʼarĕẕe֗⁠ká wĕ⁠lò֤ʼ şá̌maʻ֙ me֣lekĕ ʼèd֔wòm wĕ⁠ga֨m ʼel-me֧lekĕ mwòʼá֛b şá̌la֖ẖ wĕ⁠lò֣ʼ ʼábá֑h wa⁠yé֥̇şěb yişĕ̂ráʼé֖l bĕ̇⁠qádéֽş̌׃"],[11,18,"וַ⁠יֵּ֣לֶךְ בַּ⁠מִּדְבָּ֗ר וַ⁠יָּ֜סָב אֶת־אֶ֤רֶץ אֱדוֹם֙ וְ⁠אֶת־אֶ֣רֶץ מוֹאָ֔ב וַ⁠יָּבֹ֤א מִ⁠מִּזְרַח־שֶׁ֨מֶשׁ֙ לְ⁠אֶ֣רֶץ מוֹאָ֔ב וַֽ⁠יַּחֲנ֖וּ⁠ן בְּ⁠עֵ֣בֶר אַרְנ֑וֹן וְ⁠לֹא־בָ֨אוּ֙ בִּ⁠גְב֣וּל מוֹאָ֔ב כִּ֥י אַרְנ֖וֹן גְּב֥וּל מוֹאָֽב׃","wa⁠yé֣̇lekĕ bȧ⁠mi̇dĕbá̇֗r wa⁠yá̇֜sáb ʼeţ-ʼe֤reẕ ʼèdwòm֙ wĕ⁠ʼeţ-ʼe֣reẕ mwòʼá֔b wa⁠yá̇bò֤ʼ mi⁠mi̇zĕraẖ-şě֨meş̌֙ lĕ⁠ʼe֣reẕ mwòʼá֔b waֽ⁠yȧẖàn֖ẇ⁠n bĕ̇⁠ʻé֣ber ʼarĕn֑wòn wĕ⁠lòʼ-bá֨ʼẇ֙ bi̇⁠gĕb֣ẇl mwòʼá֔b ki֥̇y ʼarĕn֖wòn gĕ̇b֥ẇl mwòʼáֽb׃"],[11,19,"וַ⁠יִּשְׁלַ֤ח יִשְׂרָאֵל֙ מַלְאָכִ֔ים אֶל־סִיח֥וֹן מֶֽלֶךְ־הָ⁠אֱמֹרִ֖י מֶ֣לֶךְ חֶשְׁבּ֑וֹן וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ יִשְׂרָאֵ֔ל נַעְבְּרָה־נָּ֥א בְ⁠אַרְצְ⁠ךָ֖ עַד־מְקוֹמִֽ⁠י׃","wa⁠yi̇şĕ̌la֤ẖ yişĕ̂ráʼél֙ malĕʼáki֔ym ʼel-siyẖ֥wòn meֽlekĕ-há⁠ʼèmòri֖y me֣lekĕ ẖeşĕ̌ḃ֑wòn wa⁠yò֤̇ʼmer l⁠wò֙ yişĕ̂ráʼé֔l naʻĕbĕ̇ráh-ná֥̇ʼ bĕ⁠ʼarĕẕĕ⁠ká֖ ʻad-mĕqwòmiֽ⁠y׃"],[11,20,"וְ⁠לֹא־הֶאֱמִ֨ין סִיח֤וֹן אֶת־יִשְׂרָאֵל֙ עֲבֹ֣ר בִּ⁠גְבֻל֔⁠וֹ וַ⁠יֶּאֱסֹ֤ף סִיחוֹן֙ אֶת־כָּל־עַמּ֔⁠וֹ וַֽ⁠יַּחֲנ֖וּ בְּ⁠יָ֑הְצָ⁠ה וַ⁠יִּלָּ֖חֶם עִם־יִשְׂרָאֵֽל׃","wĕ⁠lòʼ-heʼèmi֨yn siyẖ֤wòn ʼeţ-yişĕ̂ráʼél֙ ʻàbò֣r bi̇⁠gĕbul֔⁠wò wa⁠yėʼèsò֤p siyẖwòn֙ ʼeţ-ká̇l-ʻaṁ֔⁠wò waֽ⁠yȧẖàn֖ẇ bĕ̇⁠yá֑hĕẕá⁠h wa⁠yi̇lá֖̇ẖem ʻim-yişĕ̂ráʼéֽl׃"],[11,21,"וַ֠⁠יִּתֵּן יְהוָ֨ה אֱלֹהֵֽי־יִשְׂרָאֵ֜ל אֶת־סִיח֧וֹן וְ⁠אֶת־כָּל־עַמּ֛⁠וֹ בְּ⁠יַ֥ד יִשְׂרָאֵ֖ל וַ⁠יַּכּ֑וּ⁠ם וַ⁠יִּירַשׁ֙ יִשְׂרָאֵ֔ל אֵ֚ת כָּל־אֶ֣רֶץ הָ⁠אֱמֹרִ֔י יוֹשֵׁ֖ב הָ⁠אָ֥רֶץ הַ⁠הִֽיא׃","wa֠⁠yi̇ţé̇n yĕhwá֨h ʼèlòhéֽy-yişĕ̂ráʼé֜l ʼeţ-siyẖ֧wòn wĕ⁠ʼeţ-ká̇l-ʻaṁ֛⁠wò bĕ̇⁠ya֥d yişĕ̂ráʼé֖l wa⁠yȧk֑̇ẇ⁠m wa⁠yi̇yraş̌֙ yişĕ̂ráʼé֔l ʼé֚ţ ká̇l-ʼe֣reẕ há⁠ʼèmòri֔y ywòşé֖̌b há⁠ʼá֥reẕ ha⁠hiֽyʼ׃"],[11,22,"וַ⁠יִּ֣ירְשׁ֔וּ אֵ֖ת כָּל־גְּב֣וּל הָ⁠אֱמֹרִ֑י מֵֽ⁠אַרְנוֹן֙ וְ⁠עַד־הַ⁠יַּבֹּ֔ק וּ⁠מִן־הַ⁠מִּדְבָּ֖ר וְ⁠עַד־הַ⁠יַּרְדֵּֽן׃","wa⁠yi֣̇yrĕş̌֔ẇ ʼé֖ţ ká̇l-gĕ̇b֣ẇl há⁠ʼèmòri֑y méֽ⁠ʼarĕnwòn֙ wĕ⁠ʻad-ha⁠yȧbò̇֔q ẇ⁠min-ha⁠mi̇dĕbá֖̇r wĕ⁠ʻad-ha⁠yȧrĕdéֽ̇n׃"],[11,23,"וְ⁠עַתָּ֞ה יְהוָ֣ה ׀ אֱלֹהֵ֣י יִשְׂרָאֵ֗ל הוֹרִישׁ֙ אֶת־הָ֣⁠אֱמֹרִ֔י מִ⁠פְּנֵ֖י עַמּ֣⁠וֹ יִשְׂרָאֵ֑ל וְ⁠אַתָּ֖ה תִּירָשֶֽׁ⁠נּוּ׃","wĕ⁠ʻaţá̇֞h yĕhwá֣h ׀ ʼèlòhé֣y yişĕ̂ráʼé֗l hwòriyş̌֙ ʼeţ-há֣⁠ʼèmòri֔y mi⁠pĕ̇né֖y ʻaṁ֣⁠wò yişĕ̂ráʼé֑l wĕ⁠ʼaţá֖̇h ţi̇yráşěֽ⁠ṅẇ׃"],[11,24,"הֲ⁠לֹ֞א אֵ֣ת אֲשֶׁ֧ר יוֹרִֽישְׁ⁠ךָ֛ כְּמ֥וֹשׁ אֱלֹהֶ֖י⁠ךָ אוֹת֥⁠וֹ תִירָ֑שׁ וְ⁠אֵת֩ כָּל־אֲשֶׁ֨ר הוֹרִ֜ישׁ יְהוָ֧ה אֱלֹהֵ֛י⁠נוּ מִ⁠פָּנֵ֖י⁠נוּ אוֹת֥⁠וֹ נִירָֽשׁ׃","hà⁠lò֞ʼ ʼé֣ţ ʼàşě֧r ywòriֽyşĕ̌⁠ká֛ kĕ̇m֥wòş̌ ʼèlòhe֖y⁠ká ʼwòţ֥⁠wò ţiyrá֑ş̌ wĕ⁠ʼéţ֩ ká̇l-ʼàşě֨r hwòri֜yş̌ yĕhwá֧h ʼèlòhé֛y⁠nẇ mi⁠pá̇né֖y⁠nẇ ʼwòţ֥⁠wò niyráֽş̌׃"],[11,25,"וְ⁠עַתָּ֗ה הֲ⁠ט֥וֹב טוֹב֙ אַתָּ֔ה מִ⁠בָּלָ֥ק בֶּן־צִפּ֖וֹר מֶ֣לֶךְ מוֹאָ֑ב הֲ⁠ר֥וֹב רָב֙ עִם־יִשְׂרָאֵ֔ל אִם־נִלְחֹ֥ם נִלְחַ֖ם בָּֽ⁠ם׃","wĕ⁠ʻaţá̇֗h hà⁠t֥wòb twòb֙ ʼaţá̇֔h mi⁠bá̇lá֥q bėn-ẕiṗ֖wòr me֣lekĕ mwòʼá֑b hà⁠r֥wòb ráb֙ ʻim-yişĕ̂ráʼé֔l ʼim-nilĕẖò֥m nilĕẖa֖m báֽ̇⁠m׃"],[11,26,"בְּ⁠שֶׁ֣בֶת יִ֠שְׂרָאֵל בְּ⁠חֶשְׁבּ֨וֹן וּ⁠בִ⁠בְנוֹתֶ֜י⁠הָ וּ⁠בְ⁠עַרְע֣וֹר וּ⁠בִ⁠בְנוֹתֶ֗י⁠הָ וּ⁠בְ⁠כָל־הֶֽ⁠עָרִים֙ אֲשֶׁר֙ עַל־יְדֵ֣י אַרְנ֔וֹן שְׁלֹ֥שׁ מֵא֖וֹת שָׁנָ֑ה וּ⁠מַדּ֥וּעַ לֹֽא־הִצַּלְתֶּ֖ם בָּ⁠עֵ֥ת הַ⁠הִֽיא׃","bĕ̇⁠şě֣beţ yi֠şĕ̂ráʼél bĕ̇⁠ẖeşĕ̌ḃ֨wòn ẇ⁠bi⁠bĕnwòţe֜y⁠há ẇ⁠bĕ⁠ʻarĕʻ֣wòr ẇ⁠bi⁠bĕnwòţe֗y⁠há ẇ⁠bĕ⁠kál-heֽ⁠ʻáriym֙ ʼàşěr֙ ʻal-yĕdé֣y ʼarĕn֔wòn şĕ̌lò֥ş̌ méʼ֖wòţ şá̌ná֑h ẇ⁠maḋ֥ẇʻa lòֽʼ-hiẕȧlĕţė֖m bá̇⁠ʻé֥ţ ha⁠hiֽyʼ׃"],[11,27,"וְ⁠אָֽנֹכִי֙ לֹֽא־חָטָ֣אתִי לָ֔⁠ךְ וְ⁠אַתָּ֞ה עֹשֶׂ֥ה אִתִּ֛⁠י רָעָ֖ה לְ⁠הִלָּ֣חֶם בִּ֑⁠י יִשְׁפֹּ֨ט יְהוָ֤ה הַ⁠שֹּׁפֵט֙ הַ⁠יּ֔וֹם בֵּ֚ין בְּנֵ֣י יִשְׂרָאֵ֔ל וּ⁠בֵ֖ין בְּנֵ֥י עַמּֽוֹן׃","wĕ⁠ʼáֽnòkiy֙ lòֽʼ-ẖátá֣ʼţiy lá֔⁠kĕ wĕ⁠ʼaţá̇֞h ʻòşê֥h ʼiţi֛̇⁠y ráʻá֖h lĕ⁠hilá֣̇ẖem bi֑̇⁠y yişĕ̌pò̇֨t yĕhwá֤h ha⁠şò̇̌pét֙ ha⁠ẏ֔wòm bé֚̇yn bĕ̇né֣y yişĕ̂ráʼé֔l ẇ⁠bé֖yn bĕ̇né֥y ʻaṁֽwòn׃"],[11,28,"וְ⁠לֹ֣א שָׁמַ֔ע מֶ֖לֶךְ בְּנֵ֣י עַמּ֑וֹן אֶל־דִּבְרֵ֣י יִפְתָּ֔ח אֲשֶׁ֥ר שָׁלַ֖ח אֵלָֽי⁠ו׃פ","wĕ⁠lò֣ʼ şá̌ma֔ʻ me֖lekĕ bĕ̇né֣y ʻaṁ֑wòn ʼel-di̇bĕré֣y yipĕţá̇֔ẖ ʼàşě֥r şá̌la֖ẖ ʼéláֽy⁠w׃p"],[11,29,"וַ⁠תְּהִ֤י עַל־יִפְתָּח֙ ר֣וּחַ יְהוָ֔ה וַ⁠יַּעֲבֹ֥ר אֶת־הַ⁠גִּלְעָ֖ד וְ⁠אֶת־מְנַשֶּׁ֑ה וַֽ⁠יַּעֲבֹר֙ אֶת־מִצְפֵּ֣ה גִלְעָ֔ד וּ⁠מִ⁠מִּצְפֵּ֣ה גִלְעָ֔ד עָבַ֖ר בְּנֵ֥י עַמּֽוֹן׃","wa⁠ţĕ̇hi֤y ʻal-yipĕţá̇ẖ֙ r֣ẇẖa yĕhwá֔h wa⁠yȧʻàbò֥r ʼeţ-ha⁠gi̇lĕʻá֖d wĕ⁠ʼeţ-mĕnaşė֑̌h waֽ⁠yȧʻàbòr֙ ʼeţ-miẕĕpé֣̇h gilĕʻá֔d ẇ⁠mi⁠mi̇ẕĕpé֣̇h gilĕʻá֔d ʻába֖r bĕ̇né֥y ʻaṁֽwòn׃"],[11,30,"וַ⁠יִּדַּ֨ר יִפְתָּ֥ח נֶ֛דֶר לַ⁠יהוָ֖ה וַ⁠יֹּאמַ֑ר אִם־נָת֥וֹן תִּתֵּ֛ן אֶת־בְּנֵ֥י עַמּ֖וֹן בְּ⁠יָדִֽ⁠י׃","wa⁠yi̇dȧ֨r yipĕţá֥̇ẖ ne֛der la⁠yhwá֖h wa⁠yò̇ʼma֑r ʼim-náţ֥wòn ţi̇ţé֛̇n ʼeţ-bĕ̇né֥y ʻaṁ֖wòn bĕ̇⁠yádiֽ⁠y׃"],[11,31,"וְ⁠הָיָ֣ה הַ⁠יּוֹצֵ֗א אֲשֶׁ֨ר יֵצֵ֜א מִ⁠דַּלְתֵ֤י בֵיתִ⁠י֙ לִ⁠קְרָאתִ֔⁠י בְּ⁠שׁוּבִ֥⁠י בְ⁠שָׁל֖וֹם מִ⁠בְּנֵ֣י עַמּ֑וֹן וְ⁠הָיָה֙ לַֽ⁠יהוָ֔ה וְ⁠הַעֲלִיתִ֖⁠הוּ עוֹלָֽה׃פ","wĕ⁠háyá֣h ha⁠ẏwòẕé֗ʼ ʼàşě֨r yéẕé֜ʼ mi⁠dȧlĕţé֤y béyţi⁠y֙ li⁠qĕráʼţi֔⁠y bĕ̇⁠ş̌ẇbi֥⁠y bĕ⁠şá̌l֖wòm mi⁠bĕ̇né֣y ʻaṁ֑wòn wĕ⁠háyáh֙ laֽ⁠yhwá֔h wĕ⁠haʻàliyţi֖⁠hẇ ʻwòláֽh׃p"],[11,32,"וַ⁠יַּעֲבֹ֥ר יִפְתָּ֛ח אֶל־בְּנֵ֥י עַמּ֖וֹן לְ⁠הִלָּ֣חֶם בָּ֑⁠ם וַ⁠יִתְּנֵ֥⁠ם יְהוָ֖ה בְּ⁠יָדֽ⁠וֹ׃","wa⁠yȧʻàbò֥r yipĕţá֛̇ẖ ʼel-bĕ̇né֥y ʻaṁ֖wòn lĕ⁠hilá֣̇ẖem bá֑̇⁠m wa⁠yiţĕ̇né֥⁠m yĕhwá֖h bĕ̇⁠yádֽ⁠wò׃"],[11,33,"וַ⁠יַּכֵּ֡⁠ם מֵ⁠עֲרוֹעֵר֩ וְ⁠עַד־בּוֹאֲ⁠ךָ֨ מִנִּ֜ית עֶשְׂרִ֣ים עִ֗יר וְ⁠עַד֙ אָבֵ֣ל כְּרָמִ֔ים מַכָּ֖ה גְּדוֹלָ֣ה מְאֹ֑ד וַ⁠יִּכָּֽנְעוּ֙ בְּנֵ֣י עַמּ֔וֹן מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃פ","wa⁠yȧké̇֡⁠m mé⁠ʻàrwòʻér֩ wĕ⁠ʻad-ḃwòʼà⁠ká֨ mini̇֜yţ ʻeşĕ̂ri֣ym ʻi֗yr wĕ⁠ʻad֙ ʼábé֣l kĕ̇rámi֔ym maká֖̇h gĕ̇dwòlá֣h mĕʼò֑d wa⁠yi̇káֽ̇nĕʻẇ֙ bĕ̇né֣y ʻaṁ֔wòn mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃p"],[11,34,"וַ⁠יָּבֹ֨א יִפְתָּ֣ח הַ⁠מִּצְפָּה֮ אֶל־בֵּית⁠וֹ֒ וְ⁠הִנֵּ֤ה בִתּ⁠וֹ֙ יֹצֵ֣את לִ⁠קְרָאת֔⁠וֹ בְ⁠תֻפִּ֖ים וּ⁠בִ⁠מְחֹל֑וֹת וְ⁠רַק֙ הִ֣יא יְחִידָ֔ה אֵֽין־ל֥⁠וֹ מִמֶּ֛⁠נּוּ בֵּ֖ן אוֹ־בַֽת׃","wa⁠yá̇bò֨ʼ yipĕţá֣̇ẖ ha⁠mi̇ẕĕpá̇h֮ ʼel-bé̇yţ⁠wò֒ wĕ⁠hiné֤̇h biţ̇⁠wò֙ yòẕé֣ʼţ li⁠qĕráʼţ֔⁠wò bĕ⁠ţupi֖̇ym ẇ⁠bi⁠mĕẖòl֑wòţ wĕ⁠raq֙ hi֣yʼ yĕẖiydá֔h ʼéֽyn-l֥⁠wò mimė֛⁠ṅẇ bé֖̇n ʼwò-baֽţ׃"],[11,35,"וַ⁠יְהִי֩ כִ⁠רְאוֹת֨⁠וֹ אוֹתָ֜⁠הּ וַ⁠יִּקְרַ֣ע אֶת־בְּגָדָ֗י⁠ו וַ⁠יֹּ֨אמֶר֙ אֲהָ֤הּ בִּתִּ⁠י֙ הַכְרֵ֣עַ הִכְרַעְתִּ֔⁠נִי וְ⁠אַ֖תְּ הָיִ֣יתְ בְּ⁠עֹֽכְרָ֑⁠י וְ⁠אָנֹכִ֗י פָּצִ֤יתִי־פִ⁠י֙ אֶל־יְהוָ֔ה וְ⁠לֹ֥א אוּכַ֖ל לָ⁠שֽׁוּב׃","wa⁠yĕhiy֩ ki⁠rĕʼwòţ֨⁠wò ʼwòţá֜⁠ḣ wa⁠yi̇qĕra֣ʻ ʼeţ-bĕ̇gádá֗y⁠w wa⁠yò̇֨ʼmer֙ ʼàhá֤ḣ bi̇ţi̇⁠y֙ hakĕré֣ʻa hikĕraʻĕţi̇֔⁠niy wĕ⁠ʼa֖ţĕ̇ háyi֣yţĕ bĕ̇⁠ʻòֽkĕrá֑⁠y wĕ⁠ʼánòki֗y pá̇ẕi֤yţiy-pi⁠y֙ ʼel-yĕhwá֔h wĕ⁠lò֥ʼ ʼẇka֖l lá⁠şֽ̌ẇb׃"],[11,36,"וַ⁠תֹּ֣אמֶר אֵלָ֗י⁠ו אָבִ⁠י֙ פָּצִ֤יתָה אֶת־פִּ֨י⁠ךָ֙ אֶל־יְהוָ֔ה עֲשֵׂ֣ה לִ֔⁠י כַּ⁠אֲשֶׁ֖ר יָצָ֣א מִ⁠פִּ֑י⁠ךָ אַחֲרֵ֡י אֲשֶׁ֣ר עָשָׂה֩ לְ⁠ךָ֙ יְהוָ֧ה נְקָמ֛וֹת מֵ⁠אֹיְבֶ֖י⁠ךָ מִ⁠בְּנֵ֥י עַמּֽוֹן׃","wa⁠ţò֣̇ʼmer ʼélá֗y⁠w ʼábi⁠y֙ pá̇ẕi֤yţáh ʼeţ-pi̇֨y⁠ká֙ ʼel-yĕhwá֔h ʻàşé֣̂h li֔⁠y kȧ⁠ʼàşě֖r yáẕá֣ʼ mi⁠pi֑̇y⁠ká ʼaẖàré֡y ʼàşě֣r ʻáşá̂h֩ lĕ⁠ká֙ yĕhwá֧h nĕqám֛wòţ mé⁠ʼòyĕbe֖y⁠ká mi⁠bĕ̇né֥y ʻaṁֽwòn׃"],[11,37,"וַ⁠תֹּ֨אמֶר֙ אֶל־אָבִ֔י⁠הָ יֵעָ֥שֶׂה לִּ֖⁠י הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה הַרְפֵּ֨ה מִמֶּ֜⁠נִּי שְׁנַ֣יִם חֳדָשִׁ֗ים וְ⁠אֵֽלְכָה֙ וְ⁠יָרַדְתִּ֣י עַל־הֶֽ⁠הָרִ֔ים וְ⁠אֶבְכֶּה֙ עַל־בְּתוּלַ֔⁠י אָנֹכִ֖י ו⁠רעית⁠י׃","wa⁠ţò̇֨ʼmer֙ ʼel-ʼábi֔y⁠há yéʻá֥şêh li֖̇⁠y ha⁠dá̇bá֣r ha⁠zė֑h harĕpé̇֨h mimė֜⁠ni̇y şĕ̌na֣yim ẖodáşǐ֗ym wĕ⁠ʼéֽlĕkáh֙ wĕ⁠yáradĕţi֣̇y ʻal-heֽ⁠hári֔ym wĕ⁠ʼebĕkėh֙ ʻal-bĕ̇ţẇla֔⁠y ʼánòki֖y w⁠rʻyţ⁠y׃"],[11,38,"וַ⁠יֹּ֣אמֶר לֵ֔כִי וַ⁠יִּשְׁלַ֥ח אוֹתָ֖⁠הּ שְׁנֵ֣י חֳדָשִׁ֑ים וַ⁠תֵּ֤לֶךְ הִיא֙ וְ⁠רֵ֣עוֹתֶ֔י⁠הָ וַ⁠תֵּ֥בְךְּ עַל־בְּתוּלֶ֖י⁠הָ עַל־הֶ⁠הָרִֽים׃","wa⁠yò֣̇ʼmer lé֔kiy wa⁠yi̇şĕ̌la֥ẖ ʼwòţá֖⁠ḣ şĕ̌né֣y ẖodáşǐ֑ym wa⁠ţé֤̇lekĕ hiyʼ֙ wĕ⁠ré֣ʻwòţe֔y⁠há wa⁠ţé֥̇bĕkĕ̇ ʻal-bĕ̇ţẇle֖y⁠há ʻal-he⁠háriֽym׃"],[11,39,"וַ⁠יְהִ֞י מִ⁠קֵּ֣ץ ׀ שְׁנַ֣יִם חֳדָשִׁ֗ים וַ⁠תָּ֨שָׁב֙ אֶל־אָבִ֔י⁠הָ וַ⁠יַּ֣עַשׂ לָ֔⁠הּ אֶת־נִדְר֖⁠וֹ אֲשֶׁ֣ר נָדָ֑ר וְ⁠הִיא֙ לֹא־יָדְעָ֣ה אִ֔ישׁ וַ⁠תְּהִי־חֹ֖ק בְּ⁠יִשְׂרָאֵֽל׃","wa⁠yĕhi֞y mi⁠qé֣̇ẕ ׀ şĕ̌na֣yim ẖodáşǐ֗ym wa⁠ţá̇֨şá̌b֙ ʼel-ʼábi֔y⁠há wa⁠yȧ֣ʻaş̂ lá֔⁠ḣ ʼeţ-nidĕr֖⁠wò ʼàşě֣r nádá֑r wĕ⁠hiyʼ֙ lòʼ-yádĕʻá֣h ʼi֔yş̌ wa⁠ţĕ̇hiy-ẖò֖q bĕ̇⁠yişĕ̂ráʼéֽl׃"],[11,40,"מִ⁠יָּמִ֣ים ׀ יָמִ֗ימָ⁠ה תֵּלַ֨כְנָה֙ בְּנ֣וֹת יִשְׂרָאֵ֔ל לְ⁠תַנּ֕וֹת לְ⁠בַת־יִפְתָּ֖ח הַ⁠גִּלְעָדִ֑י אַרְבַּ֥עַת יָמִ֖ים בַּ⁠שָּׁנָֽה׃ס","mi⁠yá̇mi֣ym ׀ yámi֗ymá⁠h ţé̇la֨kĕnáh֙ bĕ̇n֣wòţ yişĕ̂ráʼé֔l lĕ⁠ţaṅ֕wòţ lĕ⁠baţ-yipĕţá֖̇ẖ ha⁠gi̇lĕʻádi֑y ʼarĕbȧ֥ʻaţ yámi֖ym bȧ⁠şá̇̌náֽh׃s"],[12,1,"וַ⁠יִּצָּעֵק֙ אִ֣ישׁ אֶפְרַ֔יִם וַֽ⁠יַּעֲבֹ֖ר צָפ֑וֹנָ⁠ה וַ⁠יֹּאמְר֨וּ לְ⁠יִפְתָּ֜ח מַדּ֣וּעַ ׀ עָבַ֣רְתָּ ׀ לְ⁠הִלָּחֵ֣ם בִּ⁠בְנֵי־עַמּ֗וֹן וְ⁠לָ֨⁠נוּ֙ לֹ֤א קָרָ֨אתָ֙ לָ⁠לֶ֣כֶת עִמָּ֔⁠ךְ בֵּיתְ⁠ךָ֕ נִשְׂרֹ֥ף עָלֶ֖י⁠ךָ בָּ⁠אֵֽשׁ׃","wa⁠yi̇ẕá̇ʻéq֙ ʼi֣yş̌ ʼepĕra֔yim waֽ⁠yȧʻàbò֖r ẕáp֑wòná⁠h wa⁠yò̇ʼmĕr֨ẇ lĕ⁠yipĕţá̇֜ẖ maḋ֣ẇʻa ׀ ʻába֣rĕţá̇ ׀ lĕ⁠hilá̇ẖé֣m bi̇⁠bĕnéy-ʻaṁ֗wòn wĕ⁠lá֨⁠nẇ֙ lò֤ʼ qárá֨ʼţá֙ lá⁠le֣keţ ʻimá̇֔⁠kĕ bé̇yţĕ⁠ká֕ nişĕ̂rò֥p ʻále֖y⁠ká bá̇⁠ʼéֽş̌׃"],[12,2,"וַ⁠יֹּ֤אמֶר יִפְתָּח֙ אֲלֵי⁠הֶ֔ם אִ֣ישׁ רִ֗יב הָיִ֛יתִי אֲנִ֛י וְ⁠עַמִּ֥⁠י וּ⁠בְנֵֽי־עַמּ֖וֹן מְאֹ֑ד וָ⁠אֶזְעַ֣ק אֶתְ⁠כֶ֔ם וְ⁠לֹֽא־הוֹשַׁעְתֶּ֥ם אוֹתִ֖⁠י מִ⁠יָּדָֽ⁠ם׃","wa⁠yò֤̇ʼmer yipĕţá̇ẖ֙ ʼàléy⁠he֔m ʼi֣yş̌ ri֗yb háyi֛yţiy ʼàni֛y wĕ⁠ʻami֥̇⁠y ẇ⁠bĕnéֽy-ʻaṁ֖wòn mĕʼò֑d wá⁠ʼezĕʻa֣q ʼeţĕ⁠ke֔m wĕ⁠lòֽʼ-hwòşǎʻĕţė֥m ʼwòţi֖⁠y mi⁠yá̇dáֽ⁠m׃"],[12,3,"וָֽ⁠אֶרְאֶ֞ה כִּֽי־אֵינְ⁠ךָ֣ מוֹשִׁ֗יע וָ⁠אָשִׂ֨ימָ⁠ה נַפְשִׁ֤⁠י בְ⁠כַפִּ⁠י֙ וָֽ⁠אֶעְבְּרָ⁠ה֙ אֶל־בְּנֵ֣י עַמּ֔וֹן וַ⁠יִּתְּנֵ֥⁠ם יְהוָ֖ה בְּ⁠יָדִ֑⁠י וְ⁠לָ⁠מָ֞ה עֲלִיתֶ֥ם אֵלַ֛⁠י הַ⁠יּ֥וֹם הַ⁠זֶּ֖ה לְ⁠הִלָּ֥חֶם בִּֽ⁠י׃","wáֽ⁠ʼerĕʼe֞h kiֽ̇y-ʼéynĕ⁠ká֣ mwòşǐ֗yʻ wá⁠ʼáşî֨ymá⁠h napĕşǐ֤⁠y bĕ⁠kapi̇⁠y֙ wáֽ⁠ʼeʻĕbĕ̇rá⁠h֙ ʼel-bĕ̇né֣y ʻaṁ֔wòn wa⁠yi̇ţĕ̇né֥⁠m yĕhwá֖h bĕ̇⁠yádi֑⁠y wĕ⁠lá⁠má֞h ʻàliyţe֥m ʼéla֛⁠y ha⁠ẏ֥wòm ha⁠zė֖h lĕ⁠hilá֥̇ẖem biֽ̇⁠y׃"],[12,4,"וַ⁠יִּקְבֹּ֤ץ יִפְתָּח֙ אֶת־כָּל־אַנְשֵׁ֣י גִלְעָ֔ד וַ⁠יִּלָּ֖חֶם אֶת־אֶפְרָ֑יִם וַ⁠יַּכּוּ֩ אַנְשֵׁ֨י גִלְעָ֜ד אֶת־אֶפְרַ֗יִם כִּ֤י אָמְרוּ֙ פְּלִיטֵ֤י אֶפְרַ֨יִם֙ אַתֶּ֔ם גִּלְעָ֕ד בְּ⁠ת֥וֹךְ אֶפְרַ֖יִם בְּ⁠ת֥וֹךְ מְנַשֶּֽׁה׃","wa⁠yi̇qĕbò֤̇ẕ yipĕţá̇ẖ֙ ʼeţ-ká̇l-ʼanĕşé֣̌y gilĕʻá֔d wa⁠yi̇lá֖̇ẖem ʼeţ-ʼepĕrá֑yim wa⁠yȧk̇ẇ֩ ʼanĕşé̌֨y gilĕʻá֜d ʼeţ-ʼepĕra֗yim ki֤̇y ʼámĕrẇ֙ pĕ̇liyté֤y ʼepĕra֨yim֙ ʼaţė֔m gi̇lĕʻá֕d bĕ̇⁠ţ֥wòkĕ ʼepĕra֖yim bĕ̇⁠ţ֥wòkĕ mĕnaşėֽ̌h׃"],[12,5,"וַ⁠יִּלְכֹּ֥ד גִּלְעָ֛ד אֶֽת־מַעְבְּר֥וֹת הַ⁠יַּרְדֵּ֖ן לְ⁠אֶפְרָ֑יִם וְֽ֠⁠הָיָה כִּ֣י יֹאמְר֞וּ פְּלִיטֵ֤י אֶפְרַ֨יִם֙ אֶעֱבֹ֔רָה וַ⁠יֹּ֨אמְרוּ ל֧⁠וֹ אַנְשֵֽׁי־גִלְעָ֛ד הַֽ⁠אֶפְרָתִ֥י אַ֖תָּה וַ⁠יֹּ֥אמֶֽר ׀ לֹֽא׃","wa⁠yi̇lĕkò֥̇d gi̇lĕʻá֛d ʼeֽţ-maʻĕbĕ̇r֥wòţ ha⁠yȧrĕdé֖̇n lĕ⁠ʼepĕrá֑yim wĕֽ֠⁠háyáh ki֣̇y yòʼmĕr֞ẇ pĕ̇liyté֤y ʼepĕra֨yim֙ ʼeʻèbò֔ráh wa⁠yò̇֨ʼmĕrẇ l֧⁠wò ʼanĕşéֽ̌y-gilĕʻá֛d haֽ⁠ʼepĕráţi֥y ʼa֖ţá̇h wa⁠yò֥̇ʼmeֽr ׀ lòֽʼ׃"],[12,6,"וַ⁠יֹּ֣אמְרוּ ל⁠וֹ֩ אֱמָר־נָ֨א שִׁבֹּ֜לֶת וַ⁠יֹּ֣אמֶר סִבֹּ֗לֶת וְ⁠לֹ֤א יָכִין֙ לְ⁠דַבֵּ֣ר כֵּ֔ן וַ⁠יֹּאחֲז֣וּ אוֹת֔⁠וֹ וַ⁠יִּשְׁחָט֖וּ⁠הוּ אֶל־מַעְבְּר֣וֹת הַ⁠יַּרְדֵּ֑ן וַ⁠יִּפֹּ֞ל בָּ⁠עֵ֤ת הַ⁠הִיא֙ מֵֽ⁠אֶפְרַ֔יִם אַרְבָּעִ֥ים וּ⁠שְׁנַ֖יִם אָֽלֶף׃","wa⁠yò֣̇ʼmĕrẇ l⁠wò֩ ʼèmár-ná֨ʼ şǐbò̇֜leţ wa⁠yò֣̇ʼmer sibò̇֗leţ wĕ⁠lò֤ʼ yákiyn֙ lĕ⁠dabé֣̇r ké̇֔n wa⁠yò̇ʼẖàz֣ẇ ʼwòţ֔⁠wò wa⁠yi̇şĕ̌ẖát֖ẇ⁠hẇ ʼel-maʻĕbĕ̇r֣wòţ ha⁠yȧrĕdé֑̇n wa⁠yi̇pò̇֞l bá̇⁠ʻé֤ţ ha⁠hiyʼ֙ méֽ⁠ʼepĕra֔yim ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌na֖yim ʼáֽlep׃"],[12,7,"וַ⁠יִּשְׁפֹּ֥ט יִפְתָּ֛ח אֶת־יִשְׂרָאֵ֖ל שֵׁ֣שׁ שָׁנִ֑ים וַ⁠יָּ֗מָת יִפְתָּח֙ הַ⁠גִּלְעָדִ֔י וַ⁠יִּקָּבֵ֖ר בְּ⁠עָרֵ֥י גִלְעָֽד׃פ","wa⁠yi̇şĕ̌pò֥̇t yipĕţá֛̇ẖ ʼeţ-yişĕ̂ráʼé֖l şé֣̌ş̌ şá̌ni֑ym wa⁠yá̇֗máţ yipĕţá̇ẖ֙ ha⁠gi̇lĕʻádi֔y wa⁠yi̇qá̇bé֖r bĕ̇⁠ʻáré֥y gilĕʻáֽd׃p"],[12,8,"וַ⁠יִּשְׁפֹּ֤ט אַֽחֲרָי⁠ו֙ אֶת־יִשְׂרָאֵ֔ל אִבְצָ֖ן מִ⁠בֵּ֥ית לָֽחֶם׃","wa⁠yi̇şĕ̌pò֤̇t ʼaֽẖàráy⁠w֙ ʼeţ-yişĕ̂ráʼé֔l ʼibĕẕá֖n mi⁠bé֥̇yţ láֽẖem׃"],[12,9,"וַ⁠יְהִי־ל֞⁠וֹ שְׁלֹשִׁ֣ים בָּנִ֗ים וּ⁠שְׁלֹשִׁ֤ים בָּנוֹת֙ שִׁלַּ֣ח הַ⁠ח֔וּצָ⁠ה וּ⁠שְׁלֹשִׁ֣ים בָּנ֔וֹת הֵבִ֥יא לְ⁠בָנָ֖י⁠ו מִן־הַ⁠ח֑וּץ וַ⁠יִּשְׁפֹּ֥ט אֶת־יִשְׂרָאֵ֖ל שֶׁ֥בַע שָׁנִֽים׃","wa⁠yĕhiy-l֞⁠wò şĕ̌lòşǐ֣ym bá̇ni֗ym ẇ⁠şĕ̌lòşǐ֤ym bá̇nwòţ֙ şǐlȧ֣ẖ ha⁠ẖ֔ẇẕá⁠h ẇ⁠şĕ̌lòşǐ֣ym bá̇n֔wòţ hébi֥yʼ lĕ⁠báná֖y⁠w min-ha⁠ẖ֑ẇẕ wa⁠yi̇şĕ̌pò֥̇t ʼeţ-yişĕ̂ráʼé֖l şě֥baʻ şá̌niֽym׃"],[12,10,"וַ⁠יָּ֣מָת אִבְצָ֔ן וַ⁠יִּקָּבֵ֖ר בְּ⁠בֵ֥ית לָֽחֶם׃פ","wa⁠yá֣̇máţ ʼibĕẕá֔n wa⁠yi̇qá̇bé֖r bĕ̇⁠bé֥yţ láֽẖem׃p"],[12,11,"וַ⁠יִּשְׁפֹּ֤ט אַֽחֲרָי⁠ו֙ אֶת־יִשְׂרָאֵ֔ל אֵיל֖וֹן הַ⁠זְּבֽוּלֹנִ֑י וַ⁠יִּשְׁפֹּ֥ט אֶת־יִשְׂרָאֵ֖ל עֶ֥שֶׂר שָׁנִֽים׃","wa⁠yi̇şĕ̌pò֤̇t ʼֽaẖàráy⁠w֙ ʼeţ-yişĕ̂ráʼé֔l ʼéyl֖wòn ha⁠zĕ̇bֽẇlòni֑y wa⁠yi̇şĕ̌pò֥̇t ʼeţ-yişĕ̂ráʼé֖l ʻe֥şêr şá̌niֽym׃"],[12,12,"וַ⁠יָּ֖מָת אֵל֣וֹן הַ⁠זְּבֽוּלֹנִ֑י וַ⁠יִּקָּבֵ֥ר בְּ⁠אַיָּל֖וֹן בְּ⁠אֶ֥רֶץ זְבוּלֻֽן׃פ","wa⁠yá֖̇máţ ʼél֣wòn ha⁠zĕ̇bֽẇlòni֑y wa⁠yi̇qá̇bé֥r bĕ̇⁠ʼayá̇l֖wòn bĕ̇⁠ʼe֥reẕ zĕbẇluֽn׃p"],[12,13,"וַ⁠יִּשְׁפֹּ֥ט אַחֲרָ֖י⁠ו אֶת־יִשְׂרָאֵ֑ל עַבְדּ֥וֹן בֶּן־הִלֵּ֖ל הַ⁠פִּרְעָתוֹנִֽי׃","wa⁠yi̇şĕ̌pò֥̇t ʼaẖàrá֖y⁠w ʼeţ-yişĕ̂ráʼé֑l ʻabĕḋ֥wòn bėn-hilé֖̇l ha⁠pi̇rĕʻáţwòniֽy׃"],[12,14,"וַ⁠יְהִי־ל֞⁠וֹ אַרְבָּעִ֣ים בָּנִ֗ים וּ⁠שְׁלֹשִׁים֙ בְּנֵ֣י בָנִ֔ים רֹכְבִ֖ים עַל־שִׁבְעִ֣ים עֲיָרִ֑ם וַ⁠יִּשְׁפֹּ֥ט אֶת־יִשְׂרָאֵ֖ל שְׁמֹנֶ֥ה שָׁנִֽים׃","wa⁠yĕhiy-l֞⁠wò ʼarĕbá̇ʻi֣ym bá̇ni֗ym ẇ⁠şĕ̌lòşǐym֙ bĕ̇né֣y báni֔ym ròkĕbi֖ym ʻal-şǐbĕʻi֣ym ʻàyári֑m wa⁠yi̇şĕ̌pò֥̇t ʼeţ-yişĕ̂ráʼé֖l şĕ̌mòne֥h şá̌niֽym׃"],[12,15,"וַ⁠יָּ֛מָת עַבְדּ֥וֹן בֶּן־הִלֵּ֖ל הַ⁠פִּרְעָתוֹנִ֑י וַ⁠יִּקָּבֵ֤ר בְּ⁠פִרְעָתוֹן֙ בְּ⁠אֶ֣רֶץ אֶפְרַ֔יִם בְּ⁠הַ֖ר הָ⁠עֲמָלֵקִֽי׃פ","wa⁠yá֛̇máţ ʻabĕḋ֥wòn bėn-hilé֖̇l ha⁠pi̇rĕʻáţwòni֑y wa⁠yi̇qá̇bé֤r bĕ̇⁠pirĕʻáţwòn֙ bĕ̇⁠ʼe֣reẕ ʼepĕra֔yim bĕ̇⁠ha֖r há⁠ʻàmáléqiֽy׃p"],[13,1,"וַ⁠יֹּסִ֨פוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל לַ⁠עֲשׂ֥וֹת הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יִּתְּנֵ֧⁠ם יְהוָ֛ה בְּ⁠יַד־פְּלִשְׁתִּ֖ים אַרְבָּעִ֥ים שָׁנָֽה׃פ","wa⁠yò̇si֨pẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l la⁠ʻàş֥̂wòţ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yi̇ţĕ̇né֧⁠m yĕhwá֛h bĕ̇⁠yad-pĕ̇lişĕ̌ţi֖̇ym ʼarĕbá̇ʻi֥ym şá̌náֽh׃p"],[13,2,"וַ⁠יְהִי֩ אִ֨ישׁ אֶחָ֧ד מִ⁠צָּרְעָ֛ה מִ⁠מִּשְׁפַּ֥חַת הַ⁠דָּנִ֖י וּ⁠שְׁמ֣⁠וֹ מָנ֑וֹחַ וְ⁠אִשְׁתּ֥⁠וֹ עֲקָרָ֖ה וְ⁠לֹ֥א יָלָֽדָה׃","wa⁠yĕhiy֩ ʼi֨yş̌ ʼeẖá֧d mi⁠ẕá̇rĕʻá֛h mi⁠mi̇şĕ̌pȧ֥ẖaţ ha⁠dá̇ni֖y ẇ⁠şĕ̌m֣⁠wò mán֑wòẖa wĕ⁠ʼişĕ̌ţ֥̇⁠wò ʻàqárá֖h wĕ⁠lò֥ʼ yáláֽdáh׃"],[13,3,"וַ⁠יֵּרָ֥א מַלְאַךְ־יְהוָ֖ה אֶל־הָ⁠אִשָּׁ֑ה וַ⁠יֹּ֣אמֶר אֵלֶ֗י⁠הָ הִנֵּה־נָ֤א אַתְּ־עֲקָרָה֙ וְ⁠לֹ֣א יָלַ֔דְתְּ וְ⁠הָרִ֖ית וְ⁠יָלַ֥דְתְּ בֵּֽן׃","wa⁠yé̇rá֥ʼ malĕʼakĕ-yĕhwá֖h ʼel-há⁠ʼişá֑̇̌h wa⁠yò֣̇ʼmer ʼéle֗y⁠há hiné̇h-ná֤ʼ ʼaţĕ̇-ʻàqáráh֙ wĕ⁠lò֣ʼ yála֔dĕţĕ̇ wĕ⁠hári֖yţ wĕ⁠yála֥dĕţĕ̇ béֽ̇n׃"],[13,4,"וְ⁠עַתָּה֙ הִשָּׁ֣מְרִי נָ֔א וְ⁠אַל־תִּשְׁתִּ֖י יַ֣יִן וְ⁠שֵׁכָ֑ר וְ⁠אַל־תֹּאכְלִ֖י כָּל־טָמֵֽא׃","wĕ⁠ʻaţá̇h֙ hişá֣̇̌mĕriy ná֔ʼ wĕ⁠ʼal-ţi̇şĕ̌ţi֖̇y ya֣yin wĕ⁠şé̌ká֑r wĕ⁠ʼal-ţò̇ʼkĕli֖y ká̇l-táméֽʼ׃"],[13,5,"כִּי֩ הִנָּ֨⁠ךְ הָרָ֜ה וְ⁠יֹלַ֣דְתְּ בֵּ֗ן וּ⁠מוֹרָה֙ לֹא־יַעֲלֶ֣ה עַל־רֹאשׁ֔⁠וֹ כִּֽי־נְזִ֧יר אֱלֹהִ֛ים יִהְיֶ֥ה הַ⁠נַּ֖עַר מִן־הַ⁠בָּ֑טֶן וְ⁠ה֗וּא יָחֵ֛ל לְ⁠הוֹשִׁ֥יעַ אֶת־יִשְׂרָאֵ֖ל מִ⁠יַּ֥ד פְּלִשְׁתִּֽים׃","ki̇y֩ hiná̇֨⁠kĕ hárá֜h wĕ⁠yòla֣dĕţĕ̇ bé̇֗n ẇ⁠mwòráh֙ lòʼ-yaʻàle֣h ʻal-ròʼş̌֔⁠wò kiֽ̇y-nĕzi֧yr ʼèlòhi֛ym yihĕye֥h ha⁠nȧ֖ʻar min-ha⁠bá֑̇ten wĕ⁠h֗ẇʼ yáẖé֛l lĕ⁠hwòşǐ֥yʻa ʼeţ-yişĕ̂ráʼé֖l mi⁠yȧ֥d pĕ̇lişĕ̌ţiֽ̇ym׃"],[13,6,"וַ⁠תָּבֹ֣א הָ⁠אִשָּׁ֗ה וַ⁠תֹּ֣אמֶר לְ⁠אִישָׁ⁠הּ֮ לֵ⁠אמֹר֒ אִ֤ישׁ הָ⁠אֱלֹהִים֙ בָּ֣א אֵלַ֔⁠י וּ⁠מַרְאֵ֕⁠הוּ כְּ⁠מַרְאֵ֛ה מַלְאַ֥ךְ הָ⁠אֱלֹהִ֖ים נוֹרָ֣א מְאֹ֑ד וְ⁠לֹ֤א שְׁאִלְתִּ֨י⁠הוּ֙ אֵֽי־מִ⁠זֶּ֣ה ה֔וּא וְ⁠אֶת־שְׁמ֖⁠וֹ לֹֽא־הִגִּ֥יד לִֽ⁠י׃","wa⁠ţá̇bò֣ʼ há⁠ʼişá̇̌֗h wa⁠ţò֣̇ʼmer lĕ⁠ʼiyşá̌⁠ḣ֮ lé⁠ʼmòr֒ ʼi֤yş̌ há⁠ʼèlòhiym֙ bá֣̇ʼ ʼéla֔⁠y ẇ⁠marĕʼé֕⁠hẇ kĕ̇⁠marĕʼé֛h malĕʼa֥kĕ há⁠ʼèlòhi֖ym nwòrá֣ʼ mĕʼò֑d wĕ⁠lò֤ʼ şĕ̌ʼilĕţi̇֨y⁠hẇ֙ ʼéֽy-mi⁠zė֣h h֔ẇʼ wĕ⁠ʼeţ-şĕ̌m֖⁠wò lòֽʼ-higi֥̇yd liֽ⁠y׃"],[13,7,"וַ⁠יֹּ֣אמֶר לִ֔⁠י הִנָּ֥⁠ךְ הָרָ֖ה וְ⁠יֹלַ֣דְתְּ בֵּ֑ן וְ⁠עַתָּ֞ה אַל־תִּשְׁתִּ֣י ׀ יַ֣יִן וְ⁠שֵׁכָ֗ר וְ⁠אַל־תֹּֽאכְלִי֙ כָּל־טֻמְאָ֔ה כִּֽי־נְזִ֤יר אֱלֹהִים֙ יִהְיֶ֣ה הַ⁠נַּ֔עַר מִן־הַ⁠בֶּ֖טֶן עַד־י֥וֹם מוֹתֽ⁠וֹ׃פ","wa⁠yò֣̇ʼmer li֔⁠y hiná֥̇⁠kĕ hárá֖h wĕ⁠yòla֣dĕţĕ̇ bé֑̇n wĕ⁠ʻaţá̇֞h ʼal-ţi̇şĕ̌ţi֣̇y ׀ ya֣yin wĕ⁠şé̌ká֗r wĕ⁠ʼal-ţòֽ̇ʼkĕliy֙ ká̇l-tumĕʼá֔h kiֽ̇y-nĕzi֤yr ʼèlòhiym֙ yihĕye֣h ha⁠nȧ֔ʻar min-ha⁠bė֖ten ʻad-y֥wòm mwòţֽ⁠wò׃p"],[13,8,"וַ⁠יֶּעְתַּ֥ר מָנ֛וֹחַ אֶל־יְהוָ֖ה וַ⁠יֹּאמַ֑ר בִּ֣י אֲדוֹנָ֔⁠י אִ֣ישׁ הָ⁠אֱלֹהִ֞ים אֲשֶׁ֣ר שָׁלַ֗חְתָּ יָבוֹא־נָ֥א עוֹד֙ אֵלֵ֔י⁠נוּ וְ⁠יוֹרֵ֕⁠נוּ מַֽה־נַּעֲשֶׂ֖ה לַ⁠נַּ֥עַר הַ⁠יּוּלָּֽד׃","wa⁠yėʻĕţȧ֥r mán֛wòẖa ʼel-yĕhwá֖h wa⁠yò̇ʼma֑r bi֣̇y ʼàdwòná֔⁠y ʼi֣yş̌ há⁠ʼèlòhi֞ym ʼàşě֣r şá̌la֗ẖĕţá̇ yábwòʼ-ná֥ʼ ʻwòd֙ ʼélé֔y⁠nẇ wĕ⁠ywòré֕⁠nẇ maֽh-nȧʻàşê֖h la⁠nȧ֥ʻar ha⁠ẏẇláֽ̇d׃"],[13,9,"וַ⁠יִּשְׁמַ֥ע הָ⁠אֱלֹהִ֖ים בְּ⁠ק֣וֹל מָנ֑וֹחַ וַ⁠יָּבֹ֣א מַלְאַךְ֩ הָ⁠אֱלֹהִ֨ים ע֜וֹד אֶל־הָ⁠אִשָּׁ֗ה וְ⁠הִיא֙ יוֹשֶׁ֣בֶת בַּ⁠שָּׂדֶ֔ה וּ⁠מָנ֥וֹחַ אִישָׁ֖⁠הּ אֵ֥ין עִמָּֽ⁠הּ׃","wa⁠yi̇şĕ̌ma֥ʻ há⁠ʼèlòhi֖ym bĕ̇⁠q֣wòl mán֑wòẖa wa⁠yá̇bò֣ʼ malĕʼakĕ֩ há⁠ʼèlòhi֨ym ʻ֜wòd ʼel-há⁠ʼişá̇̌֗h wĕ⁠hiyʼ֙ ywòşě֣beţ bȧ⁠şá̇̂de֔h ẇ⁠mán֥wòẖa ʼiyşá֖̌⁠ḣ ʼé֥yn ʻimáֽ̇⁠ḣ׃"],[13,10,"וַ⁠תְּמַהֵר֙ הָֽ⁠אִשָּׁ֔ה וַ⁠תָּ֖רָץ וַ⁠תַּגֵּ֣ד לְ⁠אִישָׁ֑⁠הּ וַ⁠תֹּ֣אמֶר אֵלָ֔י⁠ו הִנֵּ֨ה נִרְאָ֤ה אֵלַ⁠י֙ הָ⁠אִ֔ישׁ אֲשֶׁר־בָּ֥א בַ⁠יּ֖וֹם אֵלָֽ⁠י׃","wa⁠ţĕ̇mahér֙ háֽ⁠ʼişá̇̌֔h wa⁠ţá֖̇ráẕ wa⁠ţȧgé֣̇d lĕ⁠ʼiyşá֑̌⁠ḣ wa⁠ţò֣̇ʼmer ʼélá֔y⁠w hiné̇֨h nirĕʼá֤h ʼéla⁠y֙ há⁠ʼi֔yş̌ ʼàşěr-bá֥̇ʼ ba⁠ẏ֖wòm ʼéláֽ⁠y׃"],[13,11,"וַ⁠יָּ֛קָם וַ⁠יֵּ֥לֶךְ מָנ֖וֹחַ אַחֲרֵ֣י אִשְׁתּ֑⁠וֹ וַ⁠יָּבֹא֙ אֶל־הָ⁠אִ֔ישׁ וַ⁠יֹּ֣אמֶר ל֗⁠וֹ הַ⁠אַתָּ֥ה הָ⁠אִ֛ישׁ אֲשֶׁר־דִּבַּ֥רְתָּ אֶל־הָ⁠אִשָּׁ֖ה וַ⁠יֹּ֥אמֶר אָֽנִי׃","wa⁠yá֛̇qám wa⁠yé֥̇lekĕ mán֖wòẖa ʼaẖàré֣y ʼişĕ̌ţ֑̇⁠wò wa⁠yá̇bòʼ֙ ʼel-há⁠ʼi֔yş̌ wa⁠yò֣̇ʼmer l֗⁠wò ha⁠ʼaţá֥̇h há⁠ʼi֛yş̌ ʼàşěr-di̇bȧ֥rĕţá̇ ʼel-há⁠ʼişá֖̇̌h wa⁠yò֥̇ʼmer ʼáֽniy׃"],[13,12,"וַ⁠יֹּ֣אמֶר מָנ֔וֹחַ עַתָּ֖ה יָבֹ֣א דְבָרֶ֑י⁠ךָ מַה־יִּֽהְיֶ֥ה מִשְׁפַּט־הַ⁠נַּ֖עַר וּ⁠מַעֲשֵֽׂ⁠הוּ׃","wa⁠yò֣̇ʼmer mán֔wòẖa ʻaţá֖̇h yábò֣ʼ dĕbáre֑y⁠ká mah-yiֽ̇hĕye֥h mişĕ̌pȧt-ha⁠nȧ֖ʻar ẇ⁠maʻàşéֽ̂⁠hẇ׃"],[13,13,"וַ⁠יֹּ֛אמֶר מַלְאַ֥ךְ יְהוָ֖ה אֶל־מָנ֑וֹחַ מִ⁠כֹּ֛ל אֲשֶׁר־אָמַ֥רְתִּי אֶל־הָ⁠אִשָּׁ֖ה תִּשָּׁמֵֽר׃","wa⁠yò֛̇ʼmer malĕʼa֥kĕ yĕhwá֖h ʼel-mán֑wòẖa mi⁠kò֛̇l ʼàşěr-ʼáma֥rĕţi̇y ʼel-há⁠ʼişá֖̇̌h ţi̇şá̇̌méֽr׃"],[13,14,"מִ⁠כֹּ֣ל אֲשֶׁר־יֵצֵא֩ מִ⁠גֶּ֨פֶן הַ⁠יַּ֜יִן לֹ֣א תֹאכַ֗ל וְ⁠יַ֤יִן וְ⁠שֵׁכָר֙ אַל־תֵּ֔שְׁתְּ וְ⁠כָל־טֻמְאָ֖ה אַל־תֹּאכַ֑ל כֹּ֥ל אֲשֶׁר־צִוִּיתִ֖י⁠הָ תִּשְׁמֹֽר׃","mi⁠kò֣̇l ʼàşěr-yéẕéʼ֩ mi⁠gė֨pen ha⁠yȧ֜yin lò֣ʼ ţòʼka֗l wĕ⁠ya֤yin wĕ⁠şé̌kár֙ ʼal-ţé̇֔şĕ̌ţĕ̇ wĕ⁠kál-tumĕʼá֖h ʼal-ţò̇ʼka֑l kò֥̇l ʼàşěr-ẕiwi̇yţi֖y⁠há ţi̇şĕ̌mòֽr׃"],[13,15,"וַ⁠יֹּ֥אמֶר מָנ֖וֹחַ אֶל־מַלְאַ֣ךְ יְהוָ֑ה נַעְצְרָה־נָּ֣א אוֹתָ֔⁠ךְ וְ⁠נַעֲשֶׂ֥ה לְ⁠פָנֶ֖י⁠ךָ גְּדִ֥י עִזִּֽים׃","wa⁠yò֥̇ʼmer mán֖wòẖa ʼel-malĕʼa֣kĕ yĕhwá֑h naʻĕẕĕráh-ná֣̇ʼ ʼwòţá֔⁠kĕ wĕ⁠naʻàşê֥h lĕ⁠páne֖y⁠ká gĕ̇di֥y ʻiziֽ̇ym׃"],[13,16,"וַ⁠יֹּאמֶר֩ מַלְאַ֨ךְ יְהוָ֜ה אֶל־מָנ֗וֹחַ אִם־תַּעְצְרֵ֨⁠נִי֙ לֹא־אֹכַ֣ל בְּ⁠לַחְמֶ֔⁠ךָ וְ⁠אִם־תַּעֲשֶׂ֣ה עֹלָ֔ה לַ⁠יהוָ֖ה תַּעֲלֶ֑⁠נָּה כִּ֚י לֹא־יָדַ֣ע מָנ֔וֹחַ כִּֽי־מַלְאַ֥ךְ יְהוָ֖ה הֽוּא׃","wa⁠yò̇ʼmer֩ malĕʼa֨kĕ yĕhwá֜h ʼel-mán֗wòẖa ʼim-ţȧʻĕẕĕré֨⁠niy֙ lòʼ-ʼòka֣l bĕ̇⁠laẖĕme֔⁠ká wĕ⁠ʼim-ţȧʻàşê֣h ʻòlá֔h la⁠yhwá֖h ţȧʻàle֑⁠ná̇h ki֚̇y lòʼ-yáda֣ʻ mán֔wòẖa kiֽ̇y-malĕʼa֥kĕ yĕhwá֖h hֽẇʼ׃"],[13,17,"וַ⁠יֹּ֧אמֶר מָנ֛וֹחַ אֶל־מַלְאַ֥ךְ יְהוָ֖ה מִ֣י שְׁמֶ֑⁠ךָ כִּֽי־יָבֹ֥א דברי⁠ך וְ⁠כִבַּדְנֽוּ⁠ךָ׃","wa⁠yò֧̇ʼmer mán֛wòẖa ʼel-malĕʼa֥kĕ yĕhwá֖h mi֣y şĕ̌me֑⁠ká kiֽ̇y-yábò֥ʼ dbry⁠k wĕ⁠kibȧdĕnֽẇ⁠ká׃"],[13,18,"וַ⁠יֹּ֤אמֶר לּ⁠וֹ֙ מַלְאַ֣ךְ יְהוָ֔ה לָ֥⁠מָּה זֶּ֖ה תִּשְׁאַ֣ל לִ⁠שְׁמִ֑⁠י וְ⁠הוּא־פֶ֛לִאי׃ס","wa⁠yò֤̇ʼmer l̇⁠wò֙ malĕʼa֣kĕ yĕhwá֔h lá֥⁠má̇h zė֖h ţi̇şĕ̌ʼa֣l li⁠şĕ̌mi֑⁠y wĕ⁠hẇʼ-pe֛liʼy׃s"],[13,19,"וַ⁠יִּקַּ֨ח מָנ֜וֹחַ אֶת־גְּדִ֤י הָ⁠עִזִּים֙ וְ⁠אֶת־הַ⁠מִּנְחָ֔ה וַ⁠יַּ֥עַל עַל־הַ⁠צּ֖וּר לַֽ⁠יהוָ֑ה וּ⁠מַפְלִ֣א לַ⁠עֲשׂ֔וֹת וּ⁠מָנ֥וֹחַ וְ⁠אִשְׁתּ֖⁠וֹ רֹאִֽים׃","wa⁠yi̇qȧ֨ẖ mán֜wòẖa ʼeţ-gĕ̇di֤y há⁠ʻizi̇ym֙ wĕ⁠ʼeţ-ha⁠mi̇nĕẖá֔h wa⁠yȧ֥ʻal ʻal-ha⁠ẕ֖̇ẇr laֽ⁠yhwá֑h ẇ⁠mapĕli֣ʼ la⁠ʻàş̂֔wòţ ẇ⁠mán֥wòẖa wĕ⁠ʼişĕ̌ţ֖̇⁠wò ròʼiֽym׃"],[13,20,"וַ⁠יְהִי֩ בַ⁠עֲל֨וֹת הַ⁠לַּ֜הַב מֵ⁠עַ֤ל הַ⁠מִּזְבֵּ֨חַ֙ הַ⁠שָּׁמַ֔יְמָ⁠ה וַ⁠יַּ֥עַל מַלְאַךְ־יְהוָ֖ה בְּ⁠לַ֣הַב הַ⁠מִּזְבֵּ֑חַ וּ⁠מָנ֤וֹחַ וְ⁠אִשְׁתּ⁠וֹ֙ רֹאִ֔ים וַ⁠יִּפְּל֥וּ עַל־פְּנֵי⁠הֶ֖ם אָֽרְצָ⁠ה׃","wa⁠yĕhiy֩ ba⁠ʻàl֨wòţ ha⁠lȧ֜hab mé⁠ʻa֤l ha⁠mi̇zĕbé̇֨ẖa֙ ha⁠şá̇̌ma֔yĕmá⁠h wa⁠yȧ֥ʻal malĕʼakĕ-yĕhwá֖h bĕ̇⁠la֣hab ha⁠mi̇zĕbé֑̇ẖa ẇ⁠mán֤wòẖa wĕ⁠ʼişĕ̌ţ̇⁠wò֙ ròʼi֔ym wa⁠yi̇pĕ̇l֥ẇ ʻal-pĕ̇néy⁠he֖m ʼáֽrĕẕá⁠h׃"],[13,21,"וְ⁠לֹא־יָ֤סַף עוֹד֙ מַלְאַ֣ךְ יְהוָ֔ה לְ⁠הֵרָאֹ֖ה אֶל־מָנ֣וֹחַ וְ⁠אֶל־אִשְׁתּ֑⁠וֹ אָ֚ז יָדַ֣ע מָנ֔וֹחַ כִּֽי־מַלְאַ֥ךְ יְהוָ֖ה הֽוּא׃","wĕ⁠lòʼ-yá֤sap ʻwòd֙ malĕʼa֣kĕ yĕhwá֔h lĕ⁠héráʼò֖h ʼel-mán֣wòẖa wĕ⁠ʼel-ʼişĕ̌ţ֑̇⁠wò ʼá֚z yáda֣ʻ mán֔wòẖa kiֽ̇y-malĕʼa֥kĕ yĕhwá֖h hֽẇʼ׃"],[13,22,"וַ⁠יֹּ֧אמֶר מָנ֛וֹחַ אֶל־אִשְׁתּ֖⁠וֹ מ֣וֹת נָמ֑וּת כִּ֥י אֱלֹהִ֖ים רָאִֽינוּ׃","wa⁠yò֧̇ʼmer mán֛wòẖa ʼel-ʼişĕ̌ţ֖̇⁠wò m֣wòţ nám֑ẇţ ki֥̇y ʼèlòhi֖ym ráʼiֽynẇ׃"],[13,23,"וַ⁠תֹּ֧אמֶר ל֣⁠וֹ אִשְׁתּ֗⁠וֹ לוּ֩ חָפֵ֨ץ יְהוָ֤ה לַ⁠הֲמִיתֵ֨⁠נוּ֙ לֹֽא־לָקַ֤ח מִ⁠יָּדֵ֨⁠נוּ֙ עֹלָ֣ה וּ⁠מִנְחָ֔ה וְ⁠לֹ֥א הֶרְאָ֖⁠נוּ אֶת־כָּל־אֵ֑לֶּה וְ⁠כָ⁠עֵ֕ת לֹ֥א הִשְׁמִיעָ֖⁠נוּ כָּ⁠זֹֽאת׃","wa⁠ţò֧̇ʼmer l֣⁠wò ʼişĕ̌ţ̇֗⁠wò lẇ֩ ẖápé֨ẕ yĕhwá֤h la⁠hàmiyţé֨⁠nẇ֙ lòֽʼ-láqa֤ẖ mi⁠yá̇dé֨⁠nẇ֙ ʻòlá֣h ẇ⁠minĕẖá֔h wĕ⁠lò֥ʼ herĕʼá֖⁠nẇ ʼeţ-ká̇l-ʼé֑lėh wĕ⁠ká⁠ʻé֕ţ lò֥ʼ hişĕ̌miyʻá֖⁠nẇ ká̇⁠zòֽʼţ׃"],[13,24,"וַ⁠תֵּ֤לֶד הָֽ⁠אִשָּׁה֙ בֵּ֔ן וַ⁠תִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ שִׁמְשׁ֑וֹן וַ⁠יִּגְדַּ֣ל הַ⁠נַּ֔עַר וַֽ⁠יְבָרְכֵ֖⁠הוּ יְהוָֽה׃","wa⁠ţé֤̇led háֽ⁠ʼişá̇̌h֙ bé̇֔n wa⁠ţi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò şǐmĕş֑̌wòn wa⁠yi̇gĕdȧ֣l ha⁠nȧ֔ʻar waֽ⁠yĕbárĕké֖⁠hẇ yĕhwáֽh׃"],[13,25,"וַ⁠תָּ֨חֶל֙ ר֣וּחַ יְהוָ֔ה לְ⁠פַעֲמ֖⁠וֹ בְּ⁠מַחֲנֵה־דָ֑ן בֵּ֥ין צָרְעָ֖ה וּ⁠בֵ֥ין אֶשְׁתָּאֹֽל׃פ","wa⁠ţá̇֨ẖel֙ r֣ẇẖa yĕhwá֔h lĕ⁠paʻàm֖⁠wò bĕ̇⁠maẖànéh-dá֑n bé֥̇yn ẕárĕʻá֖h ẇ⁠bé֥yn ʼeşĕ̌ţá̇ʼòֽl׃p"],[14,1,"וַ⁠יֵּ֥רֶד שִׁמְשׁ֖וֹן תִּמְנָ֑תָ⁠ה וַ⁠יַּ֥רְא אִשָּׁ֛ה בְּ⁠תִמְנָ֖תָ⁠ה מִ⁠בְּנ֥וֹת פְּלִשְׁתִּֽים׃","wa⁠yé֥̇red şǐmĕş֖̌wòn ţi̇mĕná֑ţá⁠h wa⁠yȧ֥rĕʼ ʼişá֛̇̌h bĕ̇⁠ţimĕná֖ţá⁠h mi⁠bĕ̇n֥wòţ pĕ̇lişĕ̌ţiֽ̇ym׃"],[14,2,"וַ⁠יַּ֗עַל וַ⁠יַּגֵּד֙ לְ⁠אָבִ֣י⁠ו וּ⁠לְ⁠אִמּ֔⁠וֹ וַ⁠יֹּ֗אמֶר אִשָּׁ֛ה רָאִ֥יתִי בְ⁠תִמְנָ֖תָ⁠ה מִ⁠בְּנ֣וֹת פְּלִשְׁתִּ֑ים וְ⁠עַתָּ֕ה קְחוּ־אוֹתָ֥⁠הּ לִּ֖⁠י לְ⁠אִשָּֽׁה׃","wa⁠yȧ֗ʻal wa⁠yȧgé̇d֙ lĕ⁠ʼábi֣y⁠w ẇ⁠lĕ⁠ʼiṁ֔⁠wò wa⁠yò̇֗ʼmer ʼişá֛̇̌h ráʼi֥yţiy bĕ⁠ţimĕná֖ţá⁠h mi⁠bĕ̇n֣wòţ pĕ̇lişĕ̌ţi֑̇ym wĕ⁠ʻaţá̇֕h qĕẖẇ-ʼwòţá֥⁠ḣ li֖̇⁠y lĕ⁠ʼişáֽ̇̌h׃"],[14,3,"וַ⁠יֹּ֨אמֶר ל֜⁠וֹ אָבִ֣י⁠ו וְ⁠אִמּ֗⁠וֹ הַ⁠אֵין֩ בִּ⁠בְנ֨וֹת אַחֶ֤י⁠ךָ וּ⁠בְ⁠כָל־עַמִּ⁠י֙ אִשָּׁ֔ה כִּֽי־אַתָּ֤ה הוֹלֵךְ֙ לָ⁠קַ֣חַת אִשָּׁ֔ה מִ⁠פְּלִשְׁתִּ֖ים הָ⁠עֲרֵלִ֑ים וַ⁠יֹּ֨אמֶר שִׁמְשׁ֤וֹן אֶל־אָבִי⁠ו֙ אוֹתָ֣⁠הּ קַֽח־לִ֔⁠י כִּֽי־הִ֖יא יָשְׁרָ֥ה בְ⁠עֵינָֽ⁠י׃","wa⁠yò̇֨ʼmer l֜⁠wò ʼábi֣y⁠w wĕ⁠ʼiṁ֗⁠wò ha⁠ʼéyn֩ bi̇⁠bĕn֨wòţ ʼaẖe֤y⁠ká ẇ⁠bĕ⁠kál-ʻami̇⁠y֙ ʼişá̇̌֔h kiֽ̇y-ʼaţá֤̇h hwòlékĕ֙ lá⁠qa֣ẖaţ ʼişá̇̌֔h mi⁠pĕ̇lişĕ̌ţi֖̇ym há⁠ʻàréli֑ym wa⁠yò̇֨ʼmer şǐmĕş֤̌wòn ʼel-ʼábiy⁠w֙ ʼwòţá֣⁠ḣ qaֽẖ-li֔⁠y kiֽ̇y-hi֖yʼ yáşĕ̌rá֥h bĕ⁠ʻéynáֽ⁠y׃"],[14,4,"וְ⁠אָבִ֨י⁠ו וְ⁠אִמּ֜⁠וֹ לֹ֣א יָדְע֗וּ כִּ֤י מֵ⁠יְהוָה֙ הִ֔יא כִּי־תֹאֲנָ֥ה הֽוּא־מְבַקֵּ֖שׁ מִ⁠פְּלִשְׁתִּ֑ים וּ⁠בָ⁠עֵ֣ת הַ⁠הִ֔יא פְּלִשְׁתִּ֖ים מֹשְׁלִ֥ים בְּ⁠יִשְׂרָאֵֽל׃פ","wĕ⁠ʼábi֨y⁠w wĕ⁠ʼiṁ֜⁠wò lò֣ʼ yádĕʻ֗ẇ ki֤̇y mé⁠yĕhwáh֙ hi֔yʼ ki̇y-ţòʼàná֥h hֽẇʼ-mĕbaqé֖̇ş̌ mi⁠pĕ̇lişĕ̌ţi֑̇ym ẇ⁠bá⁠ʻé֣ţ ha⁠hi֔yʼ pĕ̇lişĕ̌ţi֖̇ym mòşĕ̌li֥ym bĕ̇⁠yişĕ̂ráʼéֽl׃p"],[14,5,"וַ⁠יֵּ֧רֶד שִׁמְשׁ֛וֹן וְ⁠אָבִ֥י⁠ו וְ⁠אִמּ֖⁠וֹ תִּמְנָ֑תָ⁠ה וַ⁠יָּבֹ֨אוּ֙ עַד־כַּרְמֵ֣י תִמְנָ֔תָ⁠ה וְ⁠הִנֵּה֙ כְּפִ֣יר אֲרָי֔וֹת שֹׁאֵ֖ג לִ⁠קְרָאתֽ⁠וֹ׃","wa⁠yé֧̇red şǐmĕş֛̌wòn wĕ⁠ʼábi֥y⁠w wĕ⁠ʼiṁ֖⁠wò ţi̇mĕná֑ţá⁠h wa⁠yá̇bò֨ʼẇ֙ ʻad-kȧrĕmé֣y ţimĕná֔ţá⁠h wĕ⁠hiné̇h֙ kĕ̇pi֣yr ʼàráy֔wòţ şò̌ʼé֖g li⁠qĕráʼţֽ⁠wò׃"],[14,6,"וַ⁠תִּצְלַ֨ח עָלָ֜י⁠ו ר֣וּחַ יְהוָ֗ה וַֽ⁠יְשַׁסְּעֵ֨⁠הוּ֙ כְּ⁠שַׁסַּ֣ע הַ⁠גְּדִ֔י וּ⁠מְא֖וּמָה אֵ֣ין בְּ⁠יָד֑⁠וֹ וְ⁠לֹ֤א הִגִּיד֙ לְ⁠אָבִ֣י⁠ו וּ⁠לְ⁠אִמּ֔⁠וֹ אֵ֖ת אֲשֶׁ֥ר עָשָֽׂה׃","wa⁠ţi̇ẕĕla֨ẖ ʻálá֜y⁠w r֣ẇẖa yĕhwá֗h waֽ⁠yĕşǎsĕ̇ʻé֨⁠hẇ֙ kĕ̇⁠şǎsȧ֣ʻ ha⁠gĕ̇di֔y ẇ⁠mĕʼ֖ẇmáh ʼé֣yn bĕ̇⁠yád֑⁠wò wĕ⁠lò֤ʼ higi̇yd֙ lĕ⁠ʼábi֣y⁠w ẇ⁠lĕ⁠ʼiṁ֔⁠wò ʼé֖ţ ʼàşě֥r ʻáşáֽ̂h׃"],[14,7,"וַ⁠יֵּ֖רֶד וַ⁠יְדַבֵּ֣ר לָ⁠אִשָּׁ֑ה וַ⁠תִּישַׁ֖ר בְּ⁠עֵינֵ֥י שִׁמְשֽׁוֹן׃","wa⁠yé֖̇red wa⁠yĕdabé֣̇r lá⁠ʼişá֑̇̌h wa⁠ţi̇yşǎ֖r bĕ̇⁠ʻéyné֥y şǐmĕşֽ̌wòn׃"],[14,8,"וַ⁠יָּ֤שָׁב מִ⁠יָּמִים֙ לְ⁠קַחְתָּ֔⁠הּ וַ⁠יָּ֣סַר לִ⁠רְא֔וֹת אֵ֖ת מַפֶּ֣לֶת הָ⁠אַרְיֵ֑ה וְ⁠הִנֵּ֨ה עֲדַ֧ת דְּבוֹרִ֛ים בִּ⁠גְוִיַּ֥ת הָ⁠אַרְיֵ֖ה וּ⁠דְבָֽשׁ׃","wa⁠yá֤̇şá̌b mi⁠yá̇miym֙ lĕ⁠qaẖĕţá̇֔⁠ḣ wa⁠yá֣̇sar li⁠rĕʼ֔wòţ ʼé֖ţ mapė֣leţ há⁠ʼarĕyé֑h wĕ⁠hiné̇֨h ʻàda֧ţ dĕ̇bwòri֛ym bi̇⁠gĕwiyȧ֥ţ há⁠ʼarĕyé֖h ẇ⁠dĕbáֽş̌׃"],[14,9,"וַ⁠יִּרְדֵּ֣⁠הוּ אֶל־כַּפָּ֗י⁠ו וַ⁠יֵּ֤לֶךְ הָלוֹךְ֙ וְ⁠אָכֹ֔ל וַ⁠יֵּ֨לֶךְ֙ אֶל־אָבִ֣י⁠ו וְ⁠אֶל־אִמּ֔⁠וֹ וַ⁠יִּתֵּ֥ן לָ⁠הֶ֖ם וַ⁠יֹּאכֵ֑לוּ וְ⁠לֹֽא־הִגִּ֣יד לָ⁠הֶ֔ם כִּ֛י מִ⁠גְּוִיַּ֥ת הָ⁠אַרְיֵ֖ה רָדָ֥ה הַ⁠דְּבָֽשׁ׃","wa⁠yi̇rĕdé֣̇⁠hẇ ʼel-kȧpá̇֗y⁠w wa⁠yé֤̇lekĕ hálwòkĕ֙ wĕ⁠ʼákò֔l wa⁠yé̇֨lekĕ֙ ʼel-ʼábi֣y⁠w wĕ⁠ʼel-ʼiṁ֔⁠wò wa⁠yi̇ţé֥̇n lá⁠he֖m wa⁠yò̇ʼké֑lẇ wĕ⁠lòֽʼ-higi֣̇yd lá⁠he֔m ki֛̇y mi⁠gĕ̇wiyȧ֥ţ há⁠ʼarĕyé֖h rádá֥h ha⁠dĕ̇báֽş̌׃"],[14,10,"וַ⁠יֵּ֥רֶד אָבִ֖י⁠הוּ אֶל־הָ⁠אִשָּׁ֑ה וַ⁠יַּ֨עַשׂ שָׁ֤ם שִׁמְשׁוֹן֙ מִשְׁתֶּ֔ה כִּ֛י כֵּ֥ן יַעֲשׂ֖וּ הַ⁠בַּחוּרִֽים׃","wa⁠yé֥̇red ʼábi֖y⁠hẇ ʼel-há⁠ʼişá֑̇̌h wa⁠yȧ֨ʻaş̂ şá֤̌m şǐmĕş̌wòn֙ mişĕ̌ţė֔h ki֛̇y ké֥̇n yaʻàş֖̂ẇ ha⁠bȧẖẇriֽym׃"],[14,11,"וַ⁠יְהִ֖י כִּ⁠רְאוֹתָ֣⁠ם אוֹת֑⁠וֹ וַ⁠יִּקְחוּ֙ שְׁלֹשִׁ֣ים מֵֽרֵעִ֔ים וַ⁠יִּהְי֖וּ אִתּֽ⁠וֹ׃","wa⁠yĕhi֖y ki̇⁠rĕʼwòţá֣⁠m ʼwòţ֑⁠wò wa⁠yi̇qĕẖẇ֙ şĕ̌lòşǐ֣ym méֽréʻi֔ym wa⁠yi̇hĕy֖ẇ ʼiţֽ̇⁠wò׃"],[14,12,"וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ שִׁמְשׁ֔וֹן אָחֽוּדָה־נָּ֥א לָ⁠כֶ֖ם חִידָ֑ה אִם־הַגֵּ֣ד תַּגִּידוּ֩ אוֹתָ֨⁠הּ לִ֜⁠י שִׁבְעַ֨ת יְמֵ֤י הַ⁠מִּשְׁתֶּה֙ וּ⁠מְצָאתֶ֔ם וְ⁠נָתַתִּ֤י לָ⁠כֶם֙ שְׁלֹשִׁ֣ים סְדִינִ֔ים וּ⁠שְׁלֹשִׁ֖ים חֲלִפֹ֥ת בְּגָדִֽים׃","wa⁠yò֤̇ʼmer lá⁠hem֙ şǐmĕş̌֔wòn ʼáẖֽẇdáh-ná֥̇ʼ lá⁠ke֖m ẖiydá֑h ʼim-hagé֣̇d ţȧgi̇ydẇ֩ ʼwòţá֨⁠ḣ li֜⁠y şǐbĕʻa֨ţ yĕmé֤y ha⁠mi̇şĕ̌ţėh֙ ẇ⁠mĕẕáʼţe֔m wĕ⁠náţaţi֤̇y lá⁠kem֙ şĕ̌lòşǐ֣ym sĕdiyni֔ym ẇ⁠şĕ̌lòşǐ֖ym ẖàlipò֥ţ bĕ̇gádiֽym׃"],[14,13,"וְ⁠אִם־לֹ֣א תוּכְלוּ֮ לְ⁠הַגִּ֣יד לִ⁠י֒ וּ⁠נְתַתֶּ֨ם אַתֶּ֥ם לִ⁠י֙ שְׁלֹשִׁ֣ים סְדִינִ֔ים וּ⁠שְׁלֹשִׁ֖ים חֲלִיפ֣וֹת בְּגָדִ֑ים וַ⁠יֹּ֣אמְרוּ ל֔⁠וֹ ח֥וּדָ⁠ה חִידָתְ⁠ךָ֖ וְ⁠נִשְׁמָעֶֽ⁠נָּה׃","wĕ⁠ʼim-lò֣ʼ ţẇkĕlẇ֮ lĕ⁠hagi֣̇yd li⁠y֒ ẇ⁠nĕţaţė֨m ʼaţė֥m li⁠y֙ şĕ̌lòşǐ֣ym sĕdiyni֔ym ẇ⁠şĕ̌lòşǐ֖ym ẖàliyp֣wòţ bĕ̇gádi֑ym wa⁠yò֣̇ʼmĕrẇ l֔⁠wò ẖ֥ẇdá⁠h ẖiydáţĕ⁠ká֖ wĕ⁠nişĕ̌máʻeֽ⁠ná̇h׃"],[14,14,"וַ⁠יֹּ֣אמֶר לָ⁠הֶ֗ם מֵ⁠הָֽ⁠אֹכֵל֙ יָצָ֣א מַאֲכָ֔ל וּ⁠מֵ⁠עַ֖ז יָצָ֣א מָת֑וֹק וְ⁠לֹ֥א יָכְל֛וּ לְ⁠הַגִּ֥יד הַ⁠חִידָ֖ה שְׁלֹ֥שֶׁת יָמִֽים׃","wa⁠yò֣̇ʼmer lá⁠he֗m mé⁠háֽ⁠ʼòkél֙ yáẕá֣ʼ maʼàká֔l ẇ⁠mé⁠ʻa֖z yáẕá֣ʼ máţ֑wòq wĕ⁠lò֥ʼ yákĕl֛ẇ lĕ⁠hagi֥̇yd ha⁠ẖiydá֖h şĕ̌lò֥şěţ yámiֽym׃"],[14,15,"וַ⁠יְהִ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י וַ⁠יֹּאמְר֤וּ לְ⁠אֵֽשֶׁת־שִׁמְשׁוֹן֙ פַּתִּ֣י אֶת־אִישֵׁ֗⁠ךְ וְ⁠יַגֶּד־לָ֨⁠נוּ֙ אֶת־הַ֣⁠חִידָ֔ה פֶּן־נִשְׂרֹ֥ף אוֹתָ֛⁠ךְ וְ⁠אֶת־בֵּ֥ית אָבִ֖י⁠ךְ בָּ⁠אֵ֑שׁ הַ⁠לְ⁠יָרְשֵׁ֕⁠נוּ קְרָאתֶ֥ם לָ֖⁠נוּ הֲ⁠לֹֽא׃","wa⁠yĕhi֣y ׀ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y wa⁠yò̇ʼmĕr֤ẇ lĕ⁠ʼéֽşěţ-şǐmĕş̌wòn֙ pȧţi֣̇y ʼeţ-ʼiyşé̌֗⁠kĕ wĕ⁠yagėd-lá֨⁠nẇ֙ ʼeţ-ha֣⁠ẖiydá֔h pėn-nişĕ̂rò֥p ʼwòţá֛⁠kĕ wĕ⁠ʼeţ-bé֥̇yţ ʼábi֖y⁠kĕ bá̇⁠ʼé֑ş̌ ha⁠lĕ⁠yárĕşé̌֕⁠nẇ qĕráʼţe֥m lá֖⁠nẇ hà⁠lòֽʼ׃"],[14,16,"וַ⁠תֵּבְךְּ֩ אֵ֨שֶׁת שִׁמְשׁ֜וֹן עָלָ֗י⁠ו וַ⁠תֹּ֨אמֶר֙ רַק־שְׂנֵאתַ֨⁠נִי֙ וְ⁠לֹ֣א אֲהַבְתָּ֔⁠נִי הַֽ⁠חִידָ֥ה חַ֨דְתָּ֙ לִ⁠בְנֵ֣י עַמִּ֔⁠י וְ⁠לִ֖⁠י לֹ֣א הִגַּ֑דְתָּה וַ⁠יֹּ֣אמֶר לָ֗⁠הּ הִנֵּ֨ה לְ⁠אָבִ֧⁠י וּ⁠לְ⁠אִמִּ֛⁠י לֹ֥א הִגַּ֖דְתִּי וְ⁠לָ֥⁠ךְ אַגִּֽיד׃","wa⁠ţé̇bĕkĕ̇֩ ʼé֨şěţ şǐmĕş̌֜wòn ʻálá֗y⁠w wa⁠ţò̇֨ʼmer֙ raq-şĕ̂néʼţa֨⁠niy֙ wĕ⁠lò֣ʼ ʼàhabĕţá̇֔⁠niy hֽa⁠ẖiydá֥h ẖa֨dĕţá̇֙ li⁠bĕné֣y ʻami̇֔⁠y wĕ⁠li֖⁠y lò֣ʼ higȧ֑dĕţá̇h wa⁠yò֣̇ʼmer lá֗⁠ḣ hiné̇֨h lĕ⁠ʼábi֧⁠y ẇ⁠lĕ⁠ʼimi֛̇⁠y lò֥ʼ higȧ֖dĕţi̇y wĕ⁠lá֥⁠kĕ ʼagiֽ̇yd׃"],[14,17,"וַ⁠תֵּ֤בְךְּ עָלָי⁠ו֙ שִׁבְעַ֣ת הַ⁠יָּמִ֔ים אֲשֶׁר־הָיָ֥ה לָ⁠הֶ֖ם הַ⁠מִּשְׁתֶּ֑ה וַ⁠יְהִ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י וַ⁠יַּגֶּד־לָ⁠הּ֙ כִּ֣י הֱצִיקַ֔תְ⁠הוּ וַ⁠תַּגֵּ֥ד הַ⁠חִידָ֖ה לִ⁠בְנֵ֥י עַמָּֽ⁠הּ׃","wa⁠ţé֤̇bĕkĕ̇ ʻáláy⁠w֙ şǐbĕʻa֣ţ ha⁠yá̇mi֔ym ʼàşěr-háyá֥h lá⁠he֖m ha⁠mi̇şĕ̌ţė֑h wa⁠yĕhi֣y ׀ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y wa⁠yȧgėd-lá⁠ḣ֙ ki֣̇y hèẕiyqa֔ţĕ⁠hẇ wa⁠ţȧgé֥̇d ha⁠ẖiydá֖h li⁠bĕné֥y ʻamáֽ̇⁠ḣ׃"],[14,18,"וַ⁠יֹּ֣אמְרוּ ל⁠וֹ֩ אַנְשֵׁ֨י הָ⁠עִ֜יר בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י בְּ⁠טֶ֨רֶם֙ יָבֹ֣א הַ⁠חַ֔רְסָ⁠ה מַה־מָּת֣וֹק מִ⁠דְּבַ֔שׁ וּ⁠מֶ֥ה עַ֖ז מֵ⁠אֲרִ֑י וַ⁠יֹּ֣אמֶר לָ⁠הֶ֔ם לוּלֵא֙ חֲרַשְׁתֶּ֣ם בְּ⁠עֶגְלָתִ֔⁠י לֹ֥א מְצָאתֶ֖ם חִידָתִֽ⁠י׃","wa⁠yò֣̇ʼmĕrẇ l⁠wò֩ ʼanĕşé̌֨y há⁠ʻi֜yr bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y bĕ̇⁠te֨rem֙ yábò֣ʼ ha⁠ẖa֔rĕsá⁠h mah-má̇ţ֣wòq mi⁠dĕ̇ba֔ş̌ ẇ⁠me֥h ʻa֖z mé⁠ʼàri֑y wa⁠yò֣̇ʼmer lá⁠he֔m lẇléʼ֙ ẖàraşĕ̌ţė֣m bĕ̇⁠ʻegĕláţi֔⁠y lò֥ʼ mĕẕáʼţe֖m ẖiydáţiֽ⁠y׃"],[14,19,"וַ⁠תִּצְלַ֨ח עָלָ֜י⁠ו ר֣וּחַ יְהוָ֗ה וַ⁠יֵּ֨רֶד אַשְׁקְל֜וֹן וַ⁠יַּ֥ךְ מֵ⁠הֶ֣ם ׀ שְׁלֹשִׁ֣ים אִ֗ישׁ וַ⁠יִּקַּח֙ אֶת־חֲלִ֣יצוֹתָ֔⁠ם וַ⁠יִּתֵּן֙ הַ⁠חֲלִיפ֔וֹת לְ⁠מַגִּידֵ֖י הַ⁠חִידָ֑ה וַ⁠יִּ֣חַר אַפּ֔⁠וֹ וַ⁠יַּ֖עַל בֵּ֥ית אָבִֽי⁠הוּ׃פ","wa⁠ţi̇ẕĕla֨ẖ ʻálá֜y⁠w r֣ẇẖa yĕhwá֗h wa⁠yé̇֨red ʼaşĕ̌qĕl֜wòn wa⁠yȧ֥kĕ mé⁠he֣m ׀ şĕ̌lòşǐ֣ym ʼi֗yş̌ wa⁠yi̇qȧẖ֙ ʼeţ-ẖàli֣yẕwòţá֔⁠m wa⁠yi̇ţé̇n֙ ha⁠ẖàliyp֔wòţ lĕ⁠magi̇ydé֖y ha⁠ẖiydá֑h wa⁠yi֣̇ẖar ʼaṗ֔⁠wò wa⁠yȧ֖ʻal bé֥̇yţ ʼábiֽy⁠hẇ׃p"],[14,20,"וַ⁠תְּהִ֖י אֵ֣שֶׁת שִׁמְשׁ֑וֹן לְ⁠מֵ֣רֵעֵ֔⁠הוּ אֲשֶׁ֥ר רֵעָ֖ה לֽ⁠וֹ׃","wa⁠ţĕ̇hi֖y ʼé֣şěţ şǐmĕş֑̌wòn lĕ⁠mé֣réʻé֔⁠hẇ ʼàşě֥r réʻá֖h lֽ⁠wò׃"],[15,1,"וַ⁠יְהִ֨י מִ⁠יָּמִ֜ים בִּ⁠ימֵ֣י קְצִיר־חִטִּ֗ים וַ⁠יִּפְקֹ֨ד שִׁמְשׁ֤וֹן אֶת־אִשְׁתּ⁠וֹ֙ בִּ⁠גְדִ֣י עִזִּ֔ים וַ⁠יֹּ֕אמֶר אָבֹ֥אָה אֶל־אִשְׁתִּ֖⁠י הֶ⁠חָ֑דְרָ⁠ה וְ⁠לֹֽא־נְתָנ֥⁠וֹ אָבִ֖י⁠הָ לָ⁠בֽוֹא׃","wa⁠yĕhi֨y mi⁠yá̇mi֜ym bi̇⁠ymé֣y qĕẕiyr-ẖiti̇֗ym wa⁠yi̇pĕqò֨d şǐmĕş֤̌wòn ʼeţ-ʼişĕ̌ţ̇⁠wò֙ bi̇⁠gĕdi֣y ʻizi̇֔ym wa⁠yò̇֕ʼmer ʼábò֥ʼáh ʼel-ʼişĕ̌ţi֖̇⁠y he⁠ẖá֑dĕrá⁠h wĕ⁠lòֽʼ-nĕţán֥⁠wò ʼábi֖y⁠há lá⁠bֽwòʼ׃"],[15,2,"וַ⁠יֹּ֣אמֶר אָבִ֗י⁠הָ אָמֹ֤ר אָמַ֨רְתִּי֙ כִּי־שָׂנֹ֣א שְׂנֵאתָ֔⁠הּ וָ⁠אֶתְּנֶ֖⁠נָּה לְ⁠מֵרֵעֶ֑⁠ךָ הֲ⁠לֹ֨א אֲחֹתָ֤⁠הּ הַ⁠קְּטַנָּה֙ טוֹבָ֣ה מִמֶּ֔⁠נָּה תְּהִי־נָ֥א לְ⁠ךָ֖ תַּחְתֶּֽי⁠הָ׃","wa⁠yò֣̇ʼmer ʼábi֗y⁠há ʼámò֤r ʼáma֨rĕţi̇y֙ ki̇y-şá̂nò֣ʼ şĕ̂néʼţá֔⁠ḣ wá⁠ʼeţĕ̇ne֖⁠ná̇h lĕ⁠méréʻe֑⁠ká hà⁠lò֨ʼ ʼàẖòţá֤⁠ḣ ha⁠qĕ̇taná̇h֙ twòbá֣h mimė֔⁠ná̇h ţĕ̇hiy-ná֥ʼ lĕ⁠ká֖ ţȧẖĕţėֽy⁠há׃"],[15,3,"וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ שִׁמְשׁ֔וֹן נִקֵּ֥יתִי הַ⁠פַּ֖עַם מִ⁠פְּלִשְׁתִּ֑ים כִּֽי־עֹשֶׂ֥ה אֲנִ֛י עִמָּ֖⁠ם רָעָֽה׃","wa⁠yò֤̇ʼmer lá⁠hem֙ şǐmĕş̌֔wòn niqé֥̇yţiy ha⁠pȧ֖ʻam mi⁠pĕ̇lişĕ̌ţi֑̇ym kiֽ̇y-ʻòşê֥h ʼàni֛y ʻimá֖̇⁠m ráʻáֽh׃"],[15,4,"וַ⁠יֵּ֣לֶךְ שִׁמְשׁ֔וֹן וַ⁠יִּלְכֹּ֖ד שְׁלֹשׁ־מֵא֣וֹת שׁוּעָלִ֑ים וַ⁠יִּקַּ֣ח לַפִּדִ֗ים וַ⁠יֶּ֤פֶן זָנָב֙ אֶל־זָנָ֔ב וַ⁠יָּ֨שֶׂם לַפִּ֥יד אֶחָ֛ד בֵּין־שְׁנֵ֥י הַ⁠זְּנָב֖וֹת בַּ⁠תָּֽוֶךְ׃","wa⁠yé֣̇lekĕ şǐmĕş̌֔wòn wa⁠yi̇lĕkò֖̇d şĕ̌lòş̌-méʼ֣wòţ ş̌ẇʻáli֑ym wa⁠yi̇qȧ֣ẖ lapi̇di֗ym wa⁠yė֤pen zánáb֙ ʼel-záná֔b wa⁠yá̇֨şêm lapi֥̇yd ʼeẖá֛d bé̇yn-şĕ̌né֥y ha⁠zĕ̇náb֖wòţ bȧ⁠ţáֽ̇wekĕ׃"],[15,5,"וַ⁠יַּבְעֶר־אֵשׁ֙ בַּ⁠לַּפִּידִ֔ים וַ⁠יְשַׁלַּ֖ח בְּ⁠קָמ֣וֹת פְּלִשְׁתִּ֑ים וַ⁠יַּבְעֵ֛ר מִ⁠גָּדִ֥ישׁ וְ⁠עַד־קָמָ֖ה וְ⁠עַד־כֶּ֥רֶם זָֽיִת׃","wa⁠yȧbĕʻer-ʼéş̌֙ bȧ⁠lȧpi̇ydi֔ym wa⁠yĕşǎlȧ֖ẖ bĕ̇⁠qám֣wòţ pĕ̇lişĕ̌ţi֑̇ym wa⁠yȧbĕʻé֛r mi⁠gá̇di֥yş̌ wĕ⁠ʻad-qámá֖h wĕ⁠ʻad-kė֥rem záֽyiţ׃"],[15,6,"וַ⁠יֹּאמְר֣וּ פְלִשְׁתִּים֮ מִ֣י עָ֣שָׂה זֹאת֒ וַ⁠יֹּאמְר֗וּ שִׁמְשׁוֹן֙ חֲתַ֣ן הַ⁠תִּמְנִ֔י כִּ֚י לָקַ֣ח אֶת־אִשְׁתּ֔⁠וֹ וַֽ⁠יִּתְּנָ֖⁠הּ לְ⁠מֵרֵעֵ֑⁠הוּ וַ⁠יַּעֲל֣וּ פְלִשְׁתִּ֔ים וַ⁠יִּשְׂרְפ֥וּ אוֹתָ֛⁠הּ וְ⁠אֶת־אָבִ֖י⁠הָ בָּ⁠אֵֽשׁ׃","wa⁠yò̇ʼmĕr֣ẇ pĕlişĕ̌ţi̇ym֮ mi֣y ʻá֣şá̂h zòʼţ֒ wa⁠yò̇ʼmĕr֗ẇ şǐmĕş̌wòn֙ ẖàţa֣n ha⁠ţi̇mĕni֔y ki֚̇y láqa֣ẖ ʼeţ-ʼişĕ̌ţ̇֔⁠wò waֽ⁠yi̇ţĕ̇ná֖⁠ḣ lĕ⁠méréʻé֑⁠hẇ wa⁠yȧʻàl֣ẇ pĕlişĕ̌ţi̇֔ym wa⁠yi̇şĕ̂rĕp֥ẇ ʼwòţá֛⁠ḣ wĕ⁠ʼeţ-ʼábi֖y⁠há bá̇⁠ʼéֽş̌׃"],[15,7,"וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ שִׁמְשׁ֔וֹן אִֽם־תַּעֲשׂ֖וּ⁠ן כָּ⁠זֹ֑את כִּ֛י אִם־נִקַּ֥מְתִּי בָ⁠כֶ֖ם וְ⁠אַחַ֥ר אֶחְדָּֽל׃","wa⁠yò֤̇ʼmer lá⁠hem֙ şǐmĕş̌֔wòn ʼiֽm-ţȧʻàş֖̂ẇ⁠n ká̇⁠zò֑ʼţ ki֛̇y ʼim-niqȧ֥mĕţi̇y bá⁠ke֖m wĕ⁠ʼaẖa֥r ʼeẖĕdáֽ̇l׃"],[15,8,"וַ⁠יַּ֨ךְ אוֹתָ֥⁠ם שׁ֛וֹק עַל־יָרֵ֖ךְ מַכָּ֣ה גְדוֹלָ֑ה וַ⁠יֵּ֣רֶד וַ⁠יֵּ֔שֶׁב בִּ⁠סְעִ֖יף סֶ֥לַע עֵיטָֽם׃ס","wa⁠yȧ֨kĕ ʼwòţá֥⁠m ş֛̌wòq ʻal-yáré֖kĕ maká֣̇h gĕdwòlá֑h wa⁠yé֣̇red wa⁠yé̇֔şěb bi̇⁠sĕʻi֖yp se֥laʻ ʻéytáֽm׃s"],[15,9,"וַ⁠יַּעֲל֣וּ פְלִשְׁתִּ֔ים וַֽ⁠יַּחֲנ֖וּ בִּ⁠יהוּדָ֑ה וַ⁠יִּנָּטְשׁ֖וּ בַּ⁠לֶּֽחִי׃","wa⁠yȧʻàl֣ẇ pĕlişĕ̌ţi̇֔ym waֽ⁠yȧẖàn֖ẇ bi̇⁠yhẇdá֑h wa⁠yi̇ná̇tĕş֖̌ẇ bȧ⁠lėֽẖiy׃"],[15,10,"וַ⁠יֹּֽאמְרוּ֙ אִ֣ישׁ יְהוּדָ֔ה לָ⁠מָ֖ה עֲלִיתֶ֣ם עָלֵ֑י⁠נוּ וַ⁠יֹּאמְר֗וּ לֶ⁠אֱס֤וֹר אֶת־שִׁמְשׁוֹן֙ עָלִ֔ינוּ לַ⁠עֲשׂ֣וֹת ל֔⁠וֹ כַּ⁠אֲשֶׁ֖ר עָ֥שָׂה לָֽ⁠נוּ׃","wa⁠yòֽ̇ʼmĕrẇ֙ ʼi֣yş̌ yĕhẇdá֔h lá⁠má֖h ʻàliyţe֣m ʻálé֑y⁠nẇ wa⁠yò̇ʼmĕr֗ẇ le⁠ʼès֤wòr ʼeţ-şǐmĕş̌wòn֙ ʻáli֔ynẇ la⁠ʻàş֣̂wòţ l֔⁠wò kȧ⁠ʼàşě֖r ʻá֥şá̂h láֽ⁠nẇ׃"],[15,11,"וַ⁠יֵּרְד֡וּ שְׁלֹשֶׁת֩ אֲלָפִ֨ים אִ֜ישׁ מִֽ⁠יהוּדָ֗ה אֶל־סְעִיף֮ סֶ֣לַע עֵיטָם֒ וַ⁠יֹּאמְר֣וּ לְ⁠שִׁמְשׁ֗וֹן הֲ⁠לֹ֤א יָדַ֨עְתָּ֙ כִּֽי־מֹשְׁלִ֥ים בָּ֨⁠נוּ֙ פְּלִשְׁתִּ֔ים וּ⁠מַה־זֹּ֖את עָשִׂ֣יתָ לָּ֑⁠נוּ וַ⁠יֹּ֣אמֶר לָ⁠הֶ֔ם כַּ⁠אֲשֶׁר֙ עָ֣שׂוּ לִ֔⁠י כֵּ֖ן עָשִׂ֥יתִי לָ⁠הֶֽם׃","wa⁠yé̇rĕd֡ẇ şĕ̌lòşěţ֩ ʼàlápi֨ym ʼi֜yş̌ miֽ⁠yhẇdá֗h ʼel-sĕʻiyp֮ se֣laʻ ʻéytám֒ wa⁠yò̇ʼmĕr֣ẇ lĕ⁠şǐmĕş̌֗wòn hà⁠lò֤ʼ yáda֨ʻĕţá̇֙ kiֽ̇y-mòşĕ̌li֥ym bá̇֨⁠nẇ֙ pĕ̇lişĕ̌ţi̇֔ym ẇ⁠mah-zò֖̇ʼţ ʻáşî֣yţá lá֑̇⁠nẇ wa⁠yò֣̇ʼmer lá⁠he֔m kȧ⁠ʼàşěr֙ ʻá֣ş̂ẇ li֔⁠y ké֖̇n ʻáşî֥yţiy lá⁠heֽm׃"],[15,12,"וַ⁠יֹּ֤אמְרוּ ל⁠וֹ֙ לֶ⁠אֱסָרְ⁠ךָ֣ יָרַ֔דְנוּ לְ⁠תִתְּ⁠ךָ֖ בְּ⁠יַד־פְּלִשְׁתִּ֑ים וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ שִׁמְשׁ֔וֹן הִשָּׁבְע֣וּ לִ֔⁠י פֶּֽן־תִּפְגְּע֥וּ⁠ן בִּ֖⁠י אַתֶּֽם׃","wa⁠yò֤̇ʼmĕrẇ l⁠wò֙ le⁠ʼèsárĕ⁠ká֣ yára֔dĕnẇ lĕ⁠ţiţĕ̇⁠ká֖ bĕ̇⁠yad-pĕ̇lişĕ̌ţi֑̇ym wa⁠yò֤̇ʼmer lá⁠hem֙ şǐmĕş̌֔wòn hişá̇̌bĕʻ֣ẇ li֔⁠y pėֽn-ţi̇pĕgĕ̇ʻ֥ẇ⁠n bi֖̇⁠y ʼaţėֽm׃"],[15,13,"וַ⁠יֹּ֧אמְרוּ ל֣⁠וֹ לֵ⁠אמֹ֗ר לֹ֚א כִּֽי־אָסֹ֤ר נֶֽאֱסָרְ⁠ךָ֙ וּ⁠נְתַנּ֣וּ⁠ךָ בְ⁠יָדָ֔⁠ם וְ⁠הָמֵ֖ת לֹ֣א נְמִיתֶ֑⁠ךָ וַ⁠יַּאַסְרֻ֗⁠הוּ בִּ⁠שְׁנַ֨יִם֙ עֲבֹתִ֣ים חֲדָשִׁ֔ים וַֽ⁠יַּעֲל֖וּ⁠הוּ מִן־הַ⁠סָּֽלַע׃","wa⁠yò֧̇ʼmĕrẇ l֣⁠wò lé⁠ʼmò֗r lò֚ʼ kiֽ̇y-ʼásò֤r neֽʼèsárĕ⁠ká֙ ẇ⁠nĕţaṅ֣ẇ⁠ká bĕ⁠yádá֔⁠m wĕ⁠hámé֖ţ lò֣ʼ nĕmiyţe֑⁠ká wa⁠yȧʼasĕru֗⁠hẇ bi̇⁠şĕ̌na֨yim֙ ʻàbòţi֣ym ẖàdáşǐ֔ym waֽ⁠yȧʻàl֖ẇ⁠hẇ min-ha⁠sáֽ̇laʻ׃"],[15,14,"הוּא־בָ֣א עַד־לֶ֔חִי וּ⁠פִלְשִׁתִּ֖ים הֵרִ֣יעוּ לִ⁠קְרָאת֑⁠וֹ וַ⁠תִּצְלַ֨ח עָלָ֜י⁠ו ר֣וּחַ יְהוָ֗ה וַ⁠תִּהְיֶ֨ינָה הָ⁠עֲבֹתִ֜ים אֲשֶׁ֣ר עַל־זְרוֹעוֹתָ֗י⁠ו כַּ⁠פִּשְׁתִּים֙ אֲשֶׁ֣ר בָּעֲר֣וּ בָ⁠אֵ֔שׁ וַ⁠יִּמַּ֥סּוּ אֱסוּרָ֖י⁠ו מֵ⁠עַ֥ל יָדָֽי⁠ו׃","hẇʼ-bá֣ʼ ʻad-le֔ẖiy ẇ⁠pilĕşǐţi֖̇ym héri֣yʻẇ li⁠qĕráʼţ֑⁠wò wa⁠ţi̇ẕĕla֨ẖ ʻálá֜y⁠w r֣ẇẖa yĕhwá֗h wa⁠ţi̇hĕye֨ynáh há⁠ʻàbòţi֜ym ʼàşě֣r ʻal-zĕrwòʻwòţá֗y⁠w kȧ⁠pi̇şĕ̌ţi̇ym֙ ʼàşě֣r bá̇ʻàr֣ẇ bá⁠ʼé֔ş̌ wa⁠yi̇mȧ֥ṡẇ ʼèsẇrá֖y⁠w mé⁠ʻa֥l yádáֽy⁠w׃"],[15,15,"וַ⁠יִּמְצָ֥א לְחִֽי־חֲמ֖וֹר טְרִיָּ֑ה וַ⁠יִּשְׁלַ֤ח יָד⁠וֹ֙ וַ⁠יִּקָּחֶ֔⁠הָ וַ⁠יַּךְ־בָּ֖⁠הּ אֶ֥לֶף אִֽישׁ׃","wa⁠yi̇mĕẕá֥ʼ lĕẖiֽy-ẖàm֖wòr tĕriyá֑̇h wa⁠yi̇şĕ̌la֤ẖ yád⁠wò֙ wa⁠yi̇qá̇ẖe֔⁠há wa⁠yȧkĕ-bá֖̇⁠ḣ ʼe֥lep ʼiֽyş̌׃"],[15,16,"וַ⁠יֹּ֣אמֶר שִׁמְשׁ֔וֹן בִּ⁠לְחִ֣י הַ⁠חֲמ֔וֹר חֲמ֖וֹר חֲמֹרָתָ֑יִם בִּ⁠לְחִ֣י הַ⁠חֲמ֔וֹר הִכֵּ֖יתִי אֶ֥לֶף אִֽישׁ׃","wa⁠yò֣̇ʼmer şǐmĕş̌֔wòn bi̇⁠lĕẖi֣y ha⁠ẖàm֔wòr ẖàm֖wòr ẖàmòráţá֑yim bi̇⁠lĕẖi֣y ha⁠ẖàm֔wòr hiké֖̇yţiy ʼe֥lep ʼiֽyş̌׃"],[15,17,"וַֽ⁠יְהִי֙ כְּ⁠כַלֹּת֣⁠וֹ לְ⁠דַבֵּ֔ר וַ⁠יַּשְׁלֵ֥ךְ הַ⁠לְּחִ֖י מִ⁠יָּד֑⁠וֹ וַ⁠יִּקְרָ֛א לַ⁠מָּק֥וֹם הַ⁠ה֖וּא רָ֥מַת לֶֽחִי׃","waֽ⁠yĕhiy֙ kĕ̇⁠kalò̇ţ֣⁠wò lĕ⁠dabé̇֔r wa⁠yȧşĕ̌lé֥kĕ ha⁠lĕ̇ẖi֖y mi⁠yá̇d֑⁠wò wa⁠yi̇qĕrá֛ʼ la⁠má̇q֥wòm ha⁠h֖ẇʼ rá֥maţ leֽẖiy׃"],[15,18,"וַ⁠יִּצְמָא֮ מְאֹד֒ וַ⁠יִּקְרָ֤א אֶל־יְהוָה֙ וַ⁠יֹּאמַ֔ר אַתָּה֙ נָתַ֣תָּ בְ⁠יַֽד־עַבְדְּ⁠ךָ֔ אֶת־הַ⁠תְּשׁוּעָ֥ה הַ⁠גְּדֹלָ֖ה הַ⁠זֹּ֑את וְ⁠עַתָּה֙ אָמ֣וּת בַּ⁠צָּמָ֔א וְ⁠נָפַלְתִּ֖י בְּ⁠יַ֥ד הָ⁠עֲרֵלִֽים׃","wa⁠yi̇ẕĕmáʼ֮ mĕʼòd֒ wa⁠yi̇qĕrá֤ʼ ʼel-yĕhwáh֙ wa⁠yò̇ʼma֔r ʼaţá̇h֙ náţa֣ţá̇ bĕ⁠yaֽd-ʻabĕdĕ̇⁠ká֔ ʼeţ-ha⁠ţĕ̇ş̌ẇʻá֥h ha⁠gĕ̇dòlá֖h ha⁠zò֑̇ʼţ wĕ⁠ʻaţá̇h֙ ʼám֣ẇţ bȧ⁠ẕá̇má֔ʼ wĕ⁠nápalĕţi֖̇y bĕ̇⁠ya֥d há⁠ʻàréliֽym׃"],[15,19,"וַ⁠יִּבְקַ֨ע אֱלֹהִ֜ים אֶת־הַ⁠מַּכְתֵּ֣שׁ אֲשֶׁר־בַּ⁠לֶּ֗חִי וַ⁠יֵּצְא֨וּ מִמֶּ֤⁠נּוּ מַ֨יִם֙ וַ⁠יֵּ֔שְׁתְּ וַ⁠תָּ֥שָׁב רוּח֖⁠וֹ וַ⁠יֶּ֑חִי עַל־כֵּ֣ן ׀ קָרָ֣א שְׁמָ֗⁠הּ עֵ֤ין הַקּוֹרֵא֙ אֲשֶׁ֣ר בַּ⁠לֶּ֔חִי עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yi̇bĕqa֨ʻ ʼèlòhi֜ym ʼeţ-ha⁠mȧkĕţé֣̇ş̌ ʼàşěr-bȧ⁠lė֗ẖiy wa⁠yé̇ẕĕʼ֨ẇ mimė֤⁠ṅẇ ma֨yim֙ wa⁠yé̇֔şĕ̌ţĕ̇ wa⁠ţá֥̇şá̌b rẇẖ֖⁠wò wa⁠yė֑ẖiy ʻal-ké֣̇n ׀ qárá֣ʼ şĕ̌má֗⁠ḣ ʻé֤yn haq̇wòréʼ֙ ʼàşě֣r bȧ⁠lė֔ẖiy ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[15,20,"וַ⁠יִּשְׁפֹּ֧ט אֶת־יִשְׂרָאֵ֛ל בִּ⁠ימֵ֥י פְלִשְׁתִּ֖ים עֶשְׂרִ֥ים שָׁנָֽה׃פ","wa⁠yi̇şĕ̌pò֧̇t ʼeţ-yişĕ̂ráʼé֛l bi̇⁠ymé֥y pĕlişĕ̌ţi֖̇ym ʻeşĕ̂ri֥ym şá̌náֽh׃p"],[16,1,"וַ⁠יֵּ֥לֶךְ שִׁמְשׁ֖וֹן עַזָּ֑תָ⁠ה וַ⁠יַּרְא־שָׁם֙ אִשָּׁ֣ה זוֹנָ֔ה וַ⁠יָּבֹ֖א אֵלֶֽי⁠הָ׃","wa⁠yé֥̇lekĕ şǐmĕş֖̌wòn ʻazá֑̇ţá⁠h wa⁠yȧrĕʼ-şá̌m֙ ʼişá֣̇̌h zwòná֔h wa⁠yá̇bò֖ʼ ʼéleֽy⁠há׃"],[16,2,"לַֽ⁠עַזָּתִ֣ים ׀ לֵ⁠אמֹ֗ר בָּ֤א שִׁמְשׁוֹן֙ הֵ֔נָּה וַ⁠יָּסֹ֛בּוּ וַ⁠יֶּאֶרְבוּ־ל֥⁠וֹ כָל־הַ⁠לַּ֖יְלָה בְּ⁠שַׁ֣עַר הָ⁠עִ֑יר וַ⁠יִּתְחָרְשׁ֤וּ כָל־הַ⁠לַּ֨יְלָה֙ לֵ⁠אמֹ֔ר עַד־א֥וֹר הַ⁠בֹּ֖קֶר וַ⁠הֲרְגְנֻֽ⁠הוּ׃","lֽa⁠ʻazá̇ţi֣ym ׀ lé⁠ʼmò֗r bá֤̇ʼ şǐmĕş̌wòn֙ hé֔ná̇h wa⁠yá̇sò֛ḃẇ wa⁠yėʼerĕbẇ-l֥⁠wò kál-ha⁠lȧ֖yĕláh bĕ̇⁠şǎ֣ʻar há⁠ʻi֑yr wa⁠yi̇ţĕẖárĕş֤̌ẇ kál-ha⁠lȧ֨yĕláh֙ lé⁠ʼmò֔r ʻad-ʼ֥wòr ha⁠bò֖̇qer wa⁠hàrĕgĕnuֽ⁠hẇ׃"],[16,3,"וַ⁠יִּשְׁכַּ֣ב שִׁמְשׁוֹן֮ עַד־חֲצִ֣י הַ⁠לַּיְלָה֒ וַ⁠יָּ֣קָם ׀ בַּ⁠חֲצִ֣י הַ⁠לַּ֗יְלָה וַ⁠יֶּאֱחֹ֞ז בְּ⁠דַלְת֤וֹת שַֽׁעַר־הָ⁠עִיר֙ וּ⁠בִ⁠שְׁתֵּ֣י הַ⁠מְּזוּז֔וֹת וַ⁠יִּסָּעֵ⁠ם֙ עִֽם־הַ⁠בְּרִ֔יחַ וַ⁠יָּ֖שֶׂם עַל־כְּתֵפָ֑י⁠ו וַֽ⁠יַּעֲלֵ⁠ם֙ אֶל־רֹ֣אשׁ הָ⁠הָ֔ר אֲשֶׁ֖ר עַל־פְּנֵ֥י חֶבְרֽוֹן׃פ","wa⁠yi̇şĕ̌kȧ֣b şǐmĕş̌wòn֮ ʻad-ẖàẕi֣y ha⁠lȧyĕláh֒ wa⁠yá֣̇qám ׀ bȧ⁠ẖàẕi֣y ha⁠lȧ֗yĕláh wa⁠yėʼèẖò֞z bĕ̇⁠dalĕţ֤wòţ şǎֽʻar-há⁠ʻiyr֙ ẇ⁠bi⁠şĕ̌ţé֣̇y ha⁠mĕ̇zẇz֔wòţ wa⁠yi̇sá̇ʻé⁠m֙ ʻiֽm-ha⁠bĕ̇ri֔yẖa wa⁠yá֖̇şêm ʻal-kĕ̇ţépá֑y⁠w waֽ⁠yȧʻàlé⁠m֙ ʼel-rò֣ʼş̌ há⁠há֔r ʼàşě֖r ʻal-pĕ̇né֥y ẖebĕrֽwòn׃p"],[16,4,"וַֽ⁠יְהִי֙ אַחֲרֵי־כֵ֔ן וַ⁠יֶּאֱהַ֥ב אִשָּׁ֖ה בְּ⁠נַ֣חַל שֹׂרֵ֑ק וּ⁠שְׁמָ֖⁠הּ דְּלִילָֽה׃","wֽa⁠yĕhiy֙ ʼaẖàréy-ké֔n wa⁠yėʼèha֥b ʼişá֖̇̌h bĕ̇⁠na֣ẖal şò̂ré֑q ẇ⁠şĕ̌má֖⁠ḣ dĕ̇liyláֽh׃"],[16,5,"וַ⁠יַּעֲל֨וּ אֵלֶ֜י⁠הָ סַרְנֵ֣י פְלִשְׁתִּ֗ים וַ⁠יֹּ֨אמְרוּ לָ֜⁠הּ פַּתִּ֣י אוֹת֗⁠וֹ וּ⁠רְאִי֙ בַּ⁠מֶּה֙ כֹּח֣⁠וֹ גָד֔וֹל וּ⁠בַ⁠מֶּה֙ נ֣וּכַל ל֔⁠וֹ וַ⁠אֲסַרְנֻ֖⁠הוּ לְ⁠עַנֹּת֑⁠וֹ וַ⁠אֲנַ֨חְנוּ֙ נִתַּן־לָ֔⁠ךְ אִ֕ישׁ אֶ֥לֶף וּ⁠מֵאָ֖ה כָּֽסֶף׃","wa⁠yȧʻàl֨ẇ ʼéle֜y⁠há sarĕné֣y pĕlişĕ̌ţi̇֗ym wa⁠yò̇֨ʼmĕrẇ lá֜⁠ḣ pȧţi֣̇y ʼwòţ֗⁠wò ẇ⁠rĕʼiy֙ bȧ⁠mėh֙ kò̇ẖ֣⁠wò gád֔wòl ẇ⁠ba⁠mėh֙ n֣ẇkal l֔⁠wò wa⁠ʼàsarĕnu֖⁠hẇ lĕ⁠ʻanò̇ţ֑⁠wò wa⁠ʼàna֨ẖĕnẇ֙ niţȧn-lá֔⁠kĕ ʼi֕yş̌ ʼe֥lep ẇ⁠méʼá֖h káֽ̇sep׃"],[16,6,"וַ⁠תֹּ֤אמֶר דְּלִילָה֙ אֶל־שִׁמְשׁ֔וֹן הַגִּֽידָ⁠ה־נָּ֣א לִ֔⁠י בַּ⁠מֶּ֖ה כֹּחֲ⁠ךָ֣ גָד֑וֹל וּ⁠בַ⁠מֶּ֥ה תֵאָסֵ֖ר לְ⁠עַנּוֹתֶֽ⁠ךָ׃","wa⁠ţò֤̇ʼmer dĕ̇liyláh֙ ʼel-şǐmĕş̌֔wòn hagiֽ̇ydá⁠h-ná֣̇ʼ li֔⁠y bȧ⁠mė֖h kò̇ẖà⁠ká֣ gád֑wòl ẇ⁠ba⁠mė֥h ţéʼásé֖r lĕ⁠ʻaṅwòţeֽ⁠ká׃"],[16,7,"וַ⁠יֹּ֤אמֶר אֵלֶ֨י⁠הָ֙ שִׁמְשׁ֔וֹן אִם־יַאַסְרֻ֗⁠נִי בְּ⁠שִׁבְעָ֛ה יְתָרִ֥ים לַחִ֖ים אֲשֶׁ֣ר לֹא־חֹרָ֑בוּ וְ⁠חָלִ֥יתִי וְ⁠הָיִ֖יתִי כְּ⁠אַחַ֥ד הָ⁠אָדָֽם׃","wa⁠yò֤̇ʼmer ʼéle֨y⁠há֙ şǐmĕş̌֔wòn ʼim-yaʼasĕru֗⁠niy bĕ̇⁠şǐbĕʻá֛h yĕţári֥ym laẖi֖ym ʼàşě֣r lòʼ-ẖòrá֑bẇ wĕ⁠ẖáli֥yţiy wĕ⁠háyi֖yţiy kĕ̇⁠ʼaẖa֥d há⁠ʼádáֽm׃"],[16,8,"וַ⁠יַּעֲלוּ־לָ֞⁠הּ סַרְנֵ֣י פְלִשְׁתִּ֗ים שִׁבְעָ֛ה יְתָרִ֥ים לַחִ֖ים אֲשֶׁ֣ר לֹא־חֹרָ֑בוּ וַ⁠תַּאַסְרֵ֖⁠הוּ בָּ⁠הֶֽם׃","wa⁠yȧʻàlẇ-lá֞⁠ḣ sarĕné֣y pĕlişĕ̌ţi̇֗ym şǐbĕʻá֛h yĕţári֥ym laẖi֖ym ʼàşě֣r lòʼ-ẖòrá֑bẇ wa⁠ţȧʼasĕré֖⁠hẇ bá̇⁠heֽm׃"],[16,9,"וְ⁠הָ⁠אֹרֵ֗ב יֹשֵׁ֥ב לָ⁠הּ֙ בַּ⁠חֶ֔דֶר וַ⁠תֹּ֣אמֶר אֵלָ֔י⁠ו פְּלִשְׁתִּ֥ים עָלֶ֖י⁠ךָ שִׁמְשׁ֑וֹן וַ⁠יְנַתֵּק֙ אֶת־הַ⁠יְתָרִ֔ים כַּ⁠אֲשֶׁ֨ר יִנָּתֵ֤ק פְּתִֽיל־הַ⁠נְּעֹ֨רֶת֙ בַּ⁠הֲרִיח֣⁠וֹ אֵ֔שׁ וְ⁠לֹ֥א נוֹדַ֖ע כֹּחֽ⁠וֹ׃","wĕ⁠há⁠ʼòré֗b yòşé֥̌b lá⁠ḣ֙ bȧ⁠ẖe֔der wa⁠ţò֣̇ʼmer ʼélá֔y⁠w pĕ̇lişĕ̌ţi֥̇ym ʻále֖y⁠ká şǐmĕş֑̌wòn wa⁠yĕnaţé̇q֙ ʼeţ-ha⁠yĕţári֔ym kȧ⁠ʼàşě֨r yiná̇ţé֤q pĕ̇ţiֽyl-ha⁠nĕ̇ʻò֨reţ֙ bȧ⁠hàriyẖ֣⁠wò ʼé֔ş̌ wĕ⁠lò֥ʼ nwòda֖ʻ kò̇ẖֽ⁠wò׃"],[16,10,"וַ⁠תֹּ֤אמֶר דְּלִילָה֙ אֶל־שִׁמְשׁ֔וֹן הִנֵּה֙ הֵתַ֣לְתָּ בִּ֔⁠י וַ⁠תְּדַבֵּ֥ר אֵלַ֖⁠י כְּזָבִ֑ים עַתָּה֙ הַגִּֽידָ⁠ה־נָּ֣א לִ֔⁠י בַּ⁠מֶּ֖ה תֵּאָסֵֽר׃","wa⁠ţò֤̇ʼmer dĕ̇liyláh֙ ʼel-şǐmĕş̌֔wòn hiné̇h֙ héţa֣lĕţá̇ bi̇֔⁠y wa⁠ţĕ̇dabé֥̇r ʼéla֖⁠y kĕ̇zábi֑ym ʻaţá̇h֙ hagiֽ̇ydá⁠h-ná֣̇ʼ li֔⁠y bȧ⁠mė֖h ţé̇ʼáséֽr׃"],[16,11,"וַ⁠יֹּ֣אמֶר אֵלֶ֔י⁠הָ אִם־אָס֤וֹר יַאַסְר֨וּ⁠נִי֙ בַּ⁠עֲבֹתִ֣ים חֲדָשִׁ֔ים אֲשֶׁ֛ר לֹֽא־נַעֲשָׂ֥ה בָ⁠הֶ֖ם מְלָאכָ֑ה וְ⁠חָלִ֥יתִי וְ⁠הָיִ֖יתִי כְּ⁠אַחַ֥ד הָ⁠אָדָֽם׃","wa⁠yò֣̇ʼmer ʼéle֔y⁠há ʼim-ʼás֤wòr yaʼasĕr֨ẇ⁠niy֙ bȧ⁠ʻàbòţi֣ym ẖàdáşǐ֔ym ʼàşě֛r lòֽʼ-naʻàşá֥̂h bá⁠he֖m mĕláʼká֑h wĕ⁠ẖáli֥yţiy wĕ⁠háyi֖yţiy kĕ̇⁠ʼaẖa֥d há⁠ʼádáֽm׃"],[16,12,"וַ⁠תִּקַּ֣ח דְּלִילָה֩ עֲבֹתִ֨ים חֲדָשִׁ֜ים וַ⁠תַּאַסְרֵ֣⁠הוּ בָ⁠הֶ֗ם וַ⁠תֹּ֤אמֶר אֵלָי⁠ו֙ פְּלִשְׁתִּ֤ים עָלֶ֨י⁠ךָ֙ שִׁמְשׁ֔וֹן וְ⁠הָ⁠אֹרֵ֖ב יֹשֵׁ֣ב בֶּ⁠חָ֑דֶר וַֽ⁠יְנַתְּקֵ֛⁠ם מֵ⁠עַ֥ל זְרֹעֹתָ֖י⁠ו כַּ⁠חֽוּט׃","wa⁠ţi̇qȧ֣ẖ dĕ̇liyláh֩ ʻàbòţi֨ym ẖàdáşǐ֜ym wa⁠ţȧʼasĕré֣⁠hẇ bá⁠he֗m wa⁠ţò֤̇ʼmer ʼéláy⁠w֙ pĕ̇lişĕ̌ţi֤̇ym ʻále֨y⁠ká֙ şǐmĕş̌֔wòn wĕ⁠há⁠ʼòré֖b yòşé֣̌b bė⁠ẖá֑der waֽ⁠yĕnaţĕ̇qé֛⁠m mé⁠ʻa֥l zĕròʻòţá֖y⁠w kȧ⁠ẖֽẇt׃"],[16,13,"וַ⁠תֹּ֨אמֶר דְּלִילָ֜ה אֶל־שִׁמְשׁ֗וֹן עַד־הֵ֜נָּה הֵתַ֤לְתָּ בִּ⁠י֙ וַ⁠תְּדַבֵּ֤ר אֵלַ⁠י֙ כְּזָבִ֔ים הַגִּ֣ידָ⁠ה לִּ֔⁠י בַּ⁠מֶּ֖ה תֵּאָסֵ֑ר וַ⁠יֹּ֣אמֶר אֵלֶ֔י⁠הָ אִם־תַּאַרְגִ֗י אֶת־שֶׁ֛בַע מַחְלְפ֥וֹת רֹאשִׁ֖⁠י עִם־הַ⁠מַּסָּֽכֶת׃","wa⁠ţò̇֨ʼmer dĕ̇liylá֜h ʼel-şǐmĕş̌֗wòn ʻad-hé֜ná̇h héţa֤lĕţá̇ bi̇⁠y֙ wa⁠ţĕ̇dabé֤̇r ʼéla⁠y֙ kĕ̇zábi֔ym hagi֣̇ydá⁠h li̇֔⁠y bȧ⁠mė֖h ţé̇ʼásé֑r wa⁠yò֣̇ʼmer ʼéle֔y⁠há ʼim-ţȧʼarĕgi֗y ʼeţ-şě֛baʻ maẖĕlĕp֥wòţ ròʼşǐ֖⁠y ʻim-ha⁠mȧsáֽ̇keţ׃"],[16,14,"וַ⁠תִּתְקַע֙ בַּ⁠יָּתֵ֔ד וַ⁠תֹּ֣אמֶר אֵלָ֔י⁠ו פְּלִשְׁתִּ֥ים עָלֶ֖י⁠ךָ שִׁמְשׁ֑וֹן וַ⁠יִּיקַץ֙ מִ⁠שְּׁנָת֔⁠וֹ וַ⁠יִּסַּ֛ע אֶת־הַ⁠יְתַ֥ד הָ⁠אֶ֖רֶג וְ⁠אֶת־הַ⁠מַּסָּֽכֶת׃","wa⁠ţi̇ţĕqaʻ֙ bȧ⁠yá̇ţé֔d wa⁠ţò֣̇ʼmer ʼélá֔y⁠w pĕ̇lişĕ̌ţi֥̇ym ʻále֖y⁠ká şǐmĕş֑̌wòn wa⁠yi̇yqaẕ֙ mi⁠şĕ̇̌náţ֔⁠wò wa⁠yi̇sȧ֛ʻ ʼeţ-ha⁠yĕţa֥d há⁠ʼe֖reg wĕ⁠ʼeţ-ha⁠mȧsáֽ̇keţ׃"],[16,15,"וַ⁠תֹּ֣אמֶר אֵלָ֗י⁠ו אֵ֚יךְ תֹּאמַ֣ר אֲהַבְתִּ֔י⁠ךְ וְ⁠לִבְּ⁠ךָ֖ אֵ֣ין אִתִּ֑⁠י זֶ֣ה שָׁלֹ֤שׁ פְּעָמִים֙ הֵתַ֣לְתָּ בִּ֔⁠י וְ⁠לֹא־הִגַּ֣דְתָּ לִּ֔⁠י בַּ⁠מֶּ֖ה כֹּחֲ⁠ךָ֥ גָדֽוֹל׃","wa⁠ţò֣̇ʼmer ʼélá֗y⁠w ʼé֚ykĕ ţò̇ʼma֣r ʼàhabĕţi̇֔y⁠kĕ wĕ⁠libĕ̇⁠ká֖ ʼé֣yn ʼiţi֑̇⁠y ze֣h şá̌lò֤ş̌ pĕ̇ʻámiym֙ héţa֣lĕţá̇ bi̇֔⁠y wĕ⁠lòʼ-higȧ֣dĕţá̇ li̇֔⁠y bȧ⁠mė֖h kò̇ẖà⁠ká֥ gádֽwòl׃"],[16,16,"וַ֠⁠יְהִי כִּֽי־הֵצִ֨יקָה לּ֧⁠וֹ בִ⁠דְבָרֶ֛י⁠הָ כָּל־הַ⁠יָּמִ֖ים וַ⁠תְּאַֽלֲצֵ֑⁠הוּ וַ⁠תִּקְצַ֥ר נַפְשׁ֖⁠וֹ לָ⁠מֽוּת׃","wa֠⁠yĕhiy kiֽ̇y-héẕi֨yqáh l֧̇⁠wò bi⁠dĕbáre֛y⁠há ká̇l-ha⁠yá̇mi֖ym wa⁠ţĕ̇ʼaֽlàẕé֑⁠hẇ wa⁠ţi̇qĕẕa֥r napĕş֖̌⁠wò lá⁠mֽẇţ׃"],[16,17,"וַ⁠יַּגֶּד־לָ֣⁠הּ אֶת־כָּל־לִבּ֗⁠וֹ וַ⁠יֹּ֤אמֶר לָ⁠הּ֙ מוֹרָה֙ לֹֽא־עָלָ֣ה עַל־רֹאשִׁ֔⁠י כִּֽי־נְזִ֧יר אֱלֹהִ֛ים אֲנִ֖י מִ⁠בֶּ֣טֶן אִמִּ֑⁠י אִם־גֻּלַּ֨חְתִּי֙ וְ⁠סָ֣ר מִמֶּ֣⁠נִּי כֹחִ֔⁠י וְ⁠חָלִ֥יתִי וְ⁠הָיִ֖יתִי כְּ⁠כָל־הָ⁠אָדָֽם׃","wa⁠yȧgėd-lá֣⁠ḣ ʼeţ-ká̇l-liḃ֗⁠wò wa⁠yò֤̇ʼmer lá⁠ḣ֙ mwòráh֙ lòֽʼ-ʻálá֣h ʻal-ròʼşǐ֔⁠y kiֽ̇y-nĕzi֧yr ʼèlòhi֛ym ʼàni֖y mi⁠bė֣ten ʼimi֑̇⁠y ʼim-gu̇lȧ֨ẖĕţi̇y֙ wĕ⁠sá֣r mimė֣⁠ni̇y kòẖi֔⁠y wĕ⁠ẖáli֥yţiy wĕ⁠háyi֖yţiy kĕ̇⁠kál-há⁠ʼádáֽm׃"],[16,18,"וַ⁠תֵּ֣רֶא דְלִילָ֗ה כִּֽי־הִגִּ֣יד לָ⁠הּ֮ אֶת־כָּל־לִבּ⁠וֹ֒ וַ⁠תִּשְׁלַ֡ח וַ⁠תִּקְרָא֩ לְ⁠סַרְנֵ֨י פְלִשְׁתִּ֤ים לֵ⁠אמֹר֙ עֲל֣וּ הַ⁠פַּ֔עַם כִּֽי־הִגִּ֥יד ל⁠ה אֶת־כָּל־לִבּ֑⁠וֹ וְ⁠עָל֤וּ אֵלֶ֨י⁠הָ֙ סַרְנֵ֣י פְלִשְׁתִּ֔ים וַ⁠יַּעֲל֥וּ הַ⁠כֶּ֖סֶף בְּ⁠יָדָֽ⁠ם׃","wa⁠ţé֣̇reʼ dĕliylá֗h kiֽ̇y-higi֣̇yd lá⁠ḣ֮ ʼeţ-ká̇l-liḃ⁠wò֒ wa⁠ţi̇şĕ̌la֡ẖ wa⁠ţi̇qĕráʼ֩ lĕ⁠sarĕné֨y pĕlişĕ̌ţi֤̇ym lé⁠ʼmòr֙ ʻàl֣ẇ ha⁠pȧ֔ʻam kiֽ̇y-higi֥̇yd l⁠h ʼeţ-ká̇l-liḃ֑⁠wò wĕ⁠ʻál֤ẇ ʼéle֨y⁠há֙ sarĕné֣y pĕlişĕ̌ţi̇֔ym wa⁠yȧʻàl֥ẇ ha⁠kė֖sep bĕ̇⁠yádáֽ⁠m׃"],[16,19,"וַ⁠תְּיַשְּׁנֵ֨⁠הוּ֙ עַל־בִּרְכֶּ֔י⁠הָ וַ⁠תִּקְרָ֣א לָ⁠אִ֔ישׁ וַ⁠תְּגַלַּ֕ח אֶת־שֶׁ֖בַע מַחְלְפ֣וֹת רֹאשׁ֑⁠וֹ וַ⁠תָּ֨חֶל֙ לְ⁠עַנּוֹת֔⁠וֹ וַ⁠יָּ֥סַר כֹּח֖⁠וֹ מֵ⁠עָלָֽי⁠ו׃","wa⁠ţĕ̇yaşĕ̇̌né֨⁠hẇ֙ ʻal-bi̇rĕkė֔y⁠há wa⁠ţi̇qĕrá֣ʼ lá⁠ʼi֔yş̌ wa⁠ţĕ̇galȧ֕ẖ ʼeţ-şě֖baʻ maẖĕlĕp֣wòţ ròʼş֑̌⁠wò wa⁠ţá̇֨ẖel֙ lĕ⁠ʻaṅwòţ֔⁠wò wa⁠yá֥̇sar kò̇ẖ֖⁠wò mé⁠ʻáláֽy⁠w׃"],[16,20,"וַ⁠תֹּ֕אמֶר פְּלִשְׁתִּ֥ים עָלֶ֖י⁠ךָ שִׁמְשׁ֑וֹן וַ⁠יִּקַ֣ץ מִ⁠שְּׁנָת֗⁠וֹ וַ⁠יֹּ֨אמֶר֙ אֵצֵ֞א כְּ⁠פַ֤עַם בְּ⁠פַ֨עַם֙ וְ⁠אִנָּעֵ֔ר וְ⁠הוּא֙ לֹ֣א יָדַ֔ע כִּ֥י יְהוָ֖ה סָ֥ר מֵ⁠עָלָֽי⁠ו׃","wa⁠ţò̇֕ʼmer pĕ̇lişĕ̌ţi֥̇ym ʻále֖y⁠ká şǐmĕş֑̌wòn wa⁠yi̇qa֣ẕ mi⁠şĕ̇̌náţ֗⁠wò wa⁠yò̇֨ʼmer֙ ʼéẕé֞ʼ kĕ̇⁠pa֤ʻam bĕ̇⁠pa֨ʻam֙ wĕ⁠ʼiná̇ʻé֔r wĕ⁠hẇʼ֙ lò֣ʼ yáda֔ʻ ki֥̇y yĕhwá֖h sá֥r mé⁠ʻáláֽy⁠w׃"],[16,21,"וַ⁠יֹּאחֲז֣וּ⁠הוּ פְלִשְׁתִּ֔ים וַֽ⁠יְנַקְּר֖וּ אֶת־עֵינָ֑י⁠ו וַ⁠יּוֹרִ֨ידוּ אוֹת֜⁠וֹ עַזָּ֗תָ⁠ה וַ⁠יַּאַסְר֨וּ⁠הוּ֙ בַּֽ⁠נְחֻשְׁתַּ֔יִם וַ⁠יְהִ֥י טוֹחֵ֖ן בְּ⁠בֵ֥ית ה⁠אסירים׃","wa⁠yò̇ʼẖàz֣ẇ⁠hẇ pĕlişĕ̌ţi̇֔ym wֽa⁠yĕnaqĕ̇r֖ẇ ʼeţ-ʻéyná֑y⁠w wa⁠ẏwòri֨ydẇ ʼwòţ֜⁠wò ʻazá̇֗ţá⁠h wa⁠yȧʼasĕr֨ẇ⁠hẇ֙ bȧֽ⁠nĕẖuşĕ̌ţȧ֔yim wa⁠yĕhi֥y twòẖé֖n bĕ̇⁠bé֥yţ h⁠ʼsyrym׃"],[16,22,"וַ⁠יָּ֧חֶל שְׂעַר־רֹאשׁ֛⁠וֹ לְ⁠צַמֵּ֖חַ כַּ⁠אֲשֶׁ֥ר גֻּלָּֽח׃פ","wa⁠yá֧̇ẖel şĕ̂ʻar-ròʼş֛̌⁠wò lĕ⁠ẕamé֖̇ẖa kȧ⁠ʼàşě֥r gu̇láֽ̇ẖ׃p"],[16,23,"וְ⁠סַרְנֵ֣י פְלִשְׁתִּ֗ים נֶֽאֱסְפוּ֙ לִ⁠זְבֹּ֧חַ זֶֽבַח־גָּד֛וֹל לְ⁠דָג֥וֹן אֱלֹהֵי⁠הֶ֖ם וּ⁠לְ⁠שִׂמְחָ֑ה וַ⁠יֹּ֣אמְר֔וּ נָתַ֤ן אֱלֹהֵ֨י⁠נוּ֙ בְּ⁠יָדֵ֔⁠נוּ אֵ֖ת שִׁמְשׁ֥וֹן אוֹיְבֵֽי⁠נוּ׃","wĕ⁠sarĕné֣y pĕlişĕ̌ţi̇֗ym neֽʼèsĕpẇ֙ li⁠zĕbò֧̇ẖa zeֽbaẖ-gá̇d֛wòl lĕ⁠dág֥wòn ʼèlòhéy⁠he֖m ẇ⁠lĕ⁠şîmĕẖá֑h wa⁠yò֣̇ʼmĕr֔ẇ náţa֤n ʼèlòhé֨y⁠nẇ֙ bĕ̇⁠yádé֔⁠nẇ ʼé֖ţ şǐmĕş֥̌wòn ʼwòyĕbéֽy⁠nẇ׃"],[16,24,"וַ⁠יִּרְא֤וּ אֹת⁠וֹ֙ הָ⁠עָ֔ם וַֽ⁠יְהַלְל֖וּ אֶת־אֱלֹהֵי⁠הֶ֑ם כִּ֣י אָמְר֗וּ נָתַ֨ן אֱלֹהֵ֤י⁠נוּ בְ⁠יָדֵ֨⁠נוּ֙ אֶת־א֣וֹיְבֵ֔⁠נוּ וְ⁠אֵת֙ מַחֲרִ֣יב אַרְצֵ֔⁠נוּ וַ⁠אֲשֶׁ֥ר הִרְבָּ֖ה אֶת־חֲלָלֵֽי⁠נוּ׃","wa⁠yi̇rĕʼ֤ẇ ʼòţ⁠wò֙ há⁠ʻá֔m waֽ⁠yĕhalĕl֖ẇ ʼeţ-ʼèlòhéy⁠he֑m ki֣̇y ʼámĕr֗ẇ náţa֨n ʼèlòhé֤y⁠nẇ bĕ⁠yádé֨⁠nẇ֙ ʼeţ-ʼ֣wòyĕbé֔⁠nẇ wĕ⁠ʼéţ֙ maẖàri֣yb ʼarĕẕé֔⁠nẇ wa⁠ʼàşě֥r hirĕbá֖̇h ʼeţ-ẖàláléֽy⁠nẇ׃"],[16,25,"וַֽ⁠יְהִי֙ כי טוב לִבָּ֔⁠ם וַ⁠יֹּ֣אמְר֔וּ קִרְא֥וּ לְ⁠שִׁמְשׁ֖וֹן וִ⁠ישַֽׂחֶק־לָ֑⁠נוּ וַ⁠יִּקְרְא֨וּ לְ⁠שִׁמְשׁ֜וֹן מִ⁠בֵּ֣ית ה⁠אסירים וַ⁠יְצַחֵק֙ לִ⁠פְנֵי⁠הֶ֔ם וַ⁠יַּעֲמִ֥ידוּ אוֹת֖⁠וֹ בֵּ֥ין הָ⁠עַמּוּדִֽים׃","waֽ⁠yĕhiy֙ ky twb libá̇֔⁠m wa⁠yò֣̇ʼmĕr֔ẇ qirĕʼ֥ẇ lĕ⁠şǐmĕş֖̌wòn wi⁠yşâֽẖeq-lá֑⁠nẇ wa⁠yi̇qĕrĕʼ֨ẇ lĕ⁠şǐmĕş̌֜wòn mi⁠bé֣̇yţ h⁠ʼsyrym wa⁠yĕẕaẖéq֙ li⁠pĕnéy⁠he֔m wa⁠yȧʻàmi֥ydẇ ʼwòţ֖⁠wò bé֥̇yn há⁠ʻaṁẇdiֽym׃"],[16,26,"וַ⁠יֹּ֨אמֶר שִׁמְשׁ֜וֹן אֶל־הַ⁠נַּ֨עַר הַ⁠מַּחֲזִ֣יק בְּ⁠יָד⁠וֹ֮ הַנִּ֣יחָ⁠ה אוֹתִ⁠י֒ ו⁠הימש⁠ני אֶת־הָֽ⁠עַמֻּדִ֔ים אֲשֶׁ֥ר הַ⁠בַּ֖יִת נָכ֣וֹן עֲלֵי⁠הֶ֑ם וְ⁠אֶשָּׁעֵ֖ן עֲלֵי⁠הֶֽם׃","wa⁠yò̇֨ʼmer şǐmĕş̌֜wòn ʼel-ha⁠nȧ֨ʻar ha⁠mȧẖàzi֣yq bĕ̇⁠yád⁠wò֮ hani֣̇yẖá⁠h ʼwòţi⁠y֒ w⁠hymş⁠ny ʼeţ-háֽ⁠ʻamu̇di֔ym ʼàşě֥r ha⁠bȧ֖yiţ nák֣wòn ʻàléy⁠he֑m wĕ⁠ʼeşá̇̌ʻé֖n ʻàléy⁠heֽm׃"],[16,27,"וְ⁠הַ⁠בַּ֗יִת מָלֵ֤א הָֽ⁠אֲנָשִׁים֙ וְ⁠הַ⁠נָּשִׁ֔ים וְ⁠שָׁ֕מָּ⁠ה כֹּ֖ל סַרְנֵ֣י פְלִשְׁתִּ֑ים וְ⁠עַל־הַ⁠גָּ֗ג כִּ⁠שְׁלֹ֤שֶׁת אֲלָפִים֙ אִ֣ישׁ וְ⁠אִשָּׁ֔ה הָ⁠רֹאִ֖ים בִּ⁠שְׂח֥וֹק שִׁמְשֽׁוֹן׃","wĕ⁠ha⁠bȧ֗yiţ málé֤ʼ háֽ⁠ʼànáşǐym֙ wĕ⁠ha⁠ná̇şǐ֔ym wĕ⁠şá̌֕má̇⁠h kò֖̇l sarĕné֣y pĕlişĕ̌ţi֑̇ym wĕ⁠ʻal-ha⁠gá̇֗g ki̇⁠şĕ̌lò֤şěţ ʼàlápiym֙ ʼi֣yş̌ wĕ⁠ʼişá̇̌֔h há⁠ròʼi֖ym bi̇⁠şĕ̂ẖ֥wòq şǐmĕşֽ̌wòn׃"],[16,28,"וַ⁠יִּקְרָ֥א שִׁמְשׁ֛וֹן אֶל־יְהוָ֖ה וַ⁠יֹּאמַ֑ר אֲדֹנָ֣⁠י יֱהֹוִ֡ה זָכְרֵ֣⁠נִי נָא֩ וְ⁠חַזְּקֵ֨⁠נִי נָ֜א אַ֣ךְ הַ⁠פַּ֤עַם הַ⁠זֶּה֙ הָ⁠אֱלֹהִ֔ים וְ⁠אִנָּקְמָ֧ה נְקַם־אַחַ֛ת מִ⁠שְּׁתֵ֥י עֵינַ֖⁠י מִ⁠פְּלִשְׁתִּֽים׃","wa⁠yi̇qĕrá֥ʼ şǐmĕş֛̌wòn ʼel-yĕhwá֖h wa⁠yò̇ʼma֑r ʼàdòná֣⁠y yèhòwi֡h zákĕré֣⁠niy náʼ֩ wĕ⁠ẖazĕ̇qé֨⁠niy ná֜ʼ ʼa֣kĕ ha⁠pȧ֤ʻam ha⁠zėh֙ há⁠ʼèlòhi֔ym wĕ⁠ʼiná̇qĕmá֧h nĕqam-ʼaẖa֛ţ mi⁠şĕ̇̌ţé֥y ʻéyna֖⁠y mi⁠pĕ̇lişĕ̌ţiֽ̇ym׃"],[16,29,"וַ⁠יִּלְפֹּ֨ת שִׁמְשׁ֜וֹן אֶת־שְׁנֵ֣י ׀ עַמּוּדֵ֣י הַ⁠תָּ֗וֶךְ אֲשֶׁ֤ר הַ⁠בַּ֨יִת֙ נָכ֣וֹן עֲלֵי⁠הֶ֔ם וַ⁠יִּסָּמֵ֖ךְ עֲלֵי⁠הֶ֑ם אֶחָ֥ד בִּ⁠ימִינ֖⁠וֹ וְ⁠אֶחָ֥ד בִּ⁠שְׂמֹאלֽ⁠וֹ׃","wa⁠yi̇lĕpò̇֨ţ şǐmĕş̌֜wòn ʼeţ-şĕ̌né֣y ׀ ʻaṁẇdé֣y ha⁠ţá̇֗wekĕ ʼàşě֤r ha⁠bȧ֨yiţ֙ nák֣wòn ʻàléy⁠he֔m wa⁠yi̇sá̇mé֖kĕ ʻàléy⁠he֑m ʼeẖá֥d bi̇⁠ymiyn֖⁠wò wĕ⁠ʼeẖá֥d bi̇⁠şĕ̂mòʼlֽ⁠wò׃"],[16,30,"וַ⁠יֹּ֣אמֶר שִׁמְשׁ֗וֹן תָּמ֣וֹת נַפְשִׁ⁠י֮ עִם־פְּלִשְׁתִּים֒ וַ⁠יֵּ֣ט בְּ⁠כֹ֔חַ וַ⁠יִּפֹּ֤ל הַ⁠בַּ֨יִת֙ עַל־הַ⁠סְּרָנִ֔ים וְ⁠עַל־כָּל־הָ⁠עָ֖ם אֲשֶׁר־בּ֑⁠וֹ וַ⁠יִּהְי֤וּ הַ⁠מֵּתִים֙ אֲשֶׁ֣ר הֵמִ֣ית בְּ⁠מוֹת֔⁠וֹ רַבִּ֕ים מֵ⁠אֲשֶׁ֥ר הֵמִ֖ית בְּ⁠חַיָּֽי⁠ו׃","wa⁠yò֣̇ʼmer şǐmĕş̌֗wòn ţá̇m֣wòţ napĕşǐ⁠y֮ ʻim-pĕ̇lişĕ̌ţi̇ym֒ wa⁠yé֣̇t bĕ̇⁠kò֔ẖa wa⁠yi̇pò֤̇l ha⁠bȧ֨yiţ֙ ʻal-ha⁠sĕ̇ráni֔ym wĕ⁠ʻal-ká̇l-há⁠ʻá֖m ʼàşěr-ḃ֑⁠wò wa⁠yi̇hĕy֤ẇ ha⁠mé̇ţiym֙ ʼàşě֣r hémi֣yţ bĕ̇⁠mwòţ֔⁠wò rabi̇֕ym mé⁠ʼàşě֥r hémi֖yţ bĕ̇⁠ẖayáֽ̇y⁠w׃"],[16,31,"וַ⁠יֵּרְד֨וּ אֶחָ֜י⁠ו וְ⁠כָל־בֵּ֣ית אָבִי⁠הוּ֮ וַ⁠יִּשְׂא֣וּ אֹת⁠וֹ֒ וַֽ⁠יַּעֲל֣וּ ׀ וַ⁠יִּקְבְּר֣וּ אוֹת֗⁠וֹ בֵּ֤ין צָרְעָה֙ וּ⁠בֵ֣ין אֶשְׁתָּאֹ֔ל בְּ⁠קֶ֖בֶר מָנ֣וֹחַ אָבִ֑י⁠ו וְ⁠ה֛וּא שָׁפַ֥ט אֶת־יִשְׂרָאֵ֖ל עֶשְׂרִ֥ים שָׁנָֽה׃פ","wa⁠yé̇rĕd֨ẇ ʼeẖá֜y⁠w wĕ⁠kál-bé֣̇yţ ʼábiy⁠hẇ֮ wa⁠yi̇şĕ̂ʼ֣ẇ ʼòţ⁠wò֒ waֽ⁠yȧʻàl֣ẇ ׀ wa⁠yi̇qĕbĕ̇r֣ẇ ʼwòţ֗⁠wò bé֤̇yn ẕárĕʻáh֙ ẇ⁠bé֣yn ʼeşĕ̌ţá̇ʼò֔l bĕ̇⁠qe֖ber mán֣wòẖa ʼábi֑y⁠w wĕ⁠h֛ẇʼ şá̌pa֥t ʼeţ-yişĕ̂ráʼé֖l ʻeşĕ̂ri֥ym şá̌náֽh׃p"],[17,1,"וַֽ⁠יְהִי־אִ֥ישׁ מֵֽ⁠הַר־אֶפְרָ֖יִם וּ⁠שְׁמ֥⁠וֹ מִיכָֽיְהוּ׃","waֽ⁠yĕhiy-ʼi֥yş̌ méֽ⁠har-ʼepĕrá֖yim ẇ⁠şĕ̌m֥⁠wò miykáֽyĕhẇ׃"],[17,2,"וַ⁠יֹּ֣אמֶר לְ⁠אִמּ֡⁠וֹ אֶלֶף֩ וּ⁠מֵאָ֨ה הַ⁠כֶּ֜סֶף אֲשֶׁ֣ר לֻֽקַּֽח־לָ֗⁠ךְ ו⁠אתי אָלִית֙ וְ⁠גַם֙ אָמַ֣רְתְּ בְּ⁠אָזְנַ֔⁠י הִנֵּֽה־הַ⁠כֶּ֥סֶף אִתִּ֖⁠י אֲנִ֣י לְקַחְתִּ֑י⁠ו וַ⁠תֹּ֣אמֶר אִמּ֔⁠וֹ בָּר֥וּךְ בְּנִ֖⁠י לַ⁠יהוָֽה׃","wa⁠yò֣̇ʼmer lĕ⁠ʼiṁ֡⁠wò ʼelep֩ ẇ⁠méʼá֨h ha⁠kė֜sep ʼàşě֣r luֽqȧֽẖ-lá֗⁠kĕ w⁠ʼţy ʼáliyţ֙ wĕ⁠gam֙ ʼáma֣rĕţĕ̇ bĕ̇⁠ʼázĕna֔⁠y hinéֽ̇h-ha⁠kė֥sep ʼiţi֖̇⁠y ʼàni֣y lĕqaẖĕţi֑̇y⁠w wa⁠ţò֣̇ʼmer ʼiṁ֔⁠wò bá̇r֥ẇkĕ bĕ̇ni֖⁠y la⁠yhwáֽh׃"],[17,3,"וַ⁠יָּ֛שֶׁב אֶת־אֶֽלֶף־וּ⁠מֵאָ֥ה הַ⁠כֶּ֖סֶף לְ⁠אִמּ֑⁠וֹ וַ⁠תֹּ֣אמֶר אִמּ֡⁠וֹ הַקְדֵּ֣שׁ הִקְדַּ֣שְׁתִּי אֶת־הַ⁠כֶּסֶף֩ לַ⁠יהוָ֨ה מִ⁠יָּדִ֜⁠י לִ⁠בְנִ֗⁠י לַֽ⁠עֲשׂוֹת֙ פֶּ֣סֶל וּ⁠מַסֵּכָ֔ה וְ⁠עַתָּ֖ה אֲשִׁיבֶ֥⁠נּוּ לָֽ⁠ךְ׃","wa⁠yá֛̇şěb ʼeţ-ʼeֽlep-ẇ⁠méʼá֥h ha⁠kė֖sep lĕ⁠ʼiṁ֑⁠wò wa⁠ţò֣̇ʼmer ʼiṁ֡⁠wò haqĕdé֣̇ş̌ hiqĕdȧ֣şĕ̌ţi̇y ʼeţ-ha⁠kėsep֩ la⁠yhwá֨h mi⁠yá̇di֜⁠y li⁠bĕni֗⁠y laֽ⁠ʻàş̂wòţ֙ pė֣sel ẇ⁠masé̇ká֔h wĕ⁠ʻaţá֖̇h ʼàşǐybe֥⁠ṅẇ láֽ⁠kĕ׃"],[17,4,"וַ⁠יָּ֥שֶׁב אֶת־הַ⁠כֶּ֖סֶף לְ⁠אִמּ֑⁠וֹ וַ⁠תִּקַּ֣ח אִמּ⁠וֹ֩ מָאתַ֨יִם כֶּ֜סֶף וַ⁠תִּתְּנֵ֣⁠הוּ לַ⁠צּוֹרֵ֗ף וַֽ⁠יַּעֲשֵׂ֨⁠הוּ֙ פֶּ֣סֶל וּ⁠מַסֵּכָ֔ה וַ⁠יְהִ֖י בְּ⁠בֵ֥ית מִיכָֽיְהוּ׃","wa⁠yá֥̇şěb ʼeţ-ha⁠kė֖sep lĕ⁠ʼiṁ֑⁠wò wa⁠ţi̇qȧ֣ẖ ʼiṁ⁠wò֩ máʼţa֨yim kė֜sep wa⁠ţi̇ţĕ̇né֣⁠hẇ la⁠ẕ̇wòré֗p waֽ⁠yȧʻàşé̂֨⁠hẇ֙ pė֣sel ẇ⁠masé̇ká֔h wa⁠yĕhi֖y bĕ̇⁠bé֥yţ miykáֽyĕhẇ׃"],[17,5,"וְ⁠הָ⁠אִ֣ישׁ מִיכָ֔ה ל֖⁠וֹ בֵּ֣ית אֱלֹהִ֑ים וַ⁠יַּ֤עַשׂ אֵפוֹד֙ וּ⁠תְרָפִ֔ים וַ⁠יְמַלֵּ֗א אֶת־יַ֤ד אַחַד֙ מִ⁠בָּנָ֔י⁠ו וַ⁠יְהִי־ל֖⁠וֹ לְ⁠כֹהֵֽן׃","wĕ⁠há⁠ʼi֣yş̌ miyká֔h l֖⁠wò bé֣̇yţ ʼèlòhi֑ym wa⁠yȧ֤ʻaş̂ ʼépwòd֙ ẇ⁠ţĕrápi֔ym wa⁠yĕmalé̇֗ʼ ʼeţ-ya֤d ʼaẖad֙ mi⁠bá̇ná֔y⁠w wa⁠yĕhiy-l֖⁠wò lĕ⁠kòhéֽn׃"],[17,6,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם אֵ֥ין מֶ֖לֶךְ בְּ⁠יִשְׂרָאֵ֑ל אִ֛ישׁ הַ⁠יָּשָׁ֥ר בְּ⁠עֵינָ֖י⁠ו יַעֲשֶֽׂה׃פ","bȧ⁠yá̇mi֣ym há⁠hé֔m ʼé֥yn me֖lekĕ bĕ̇⁠yişĕ̂ráʼé֑l ʼi֛yş̌ ha⁠yá̇şá֥̌r bĕ̇⁠ʻéyná֖y⁠w yaʻàşêֽh׃p"],[17,7,"וַ⁠יְהִי־נַ֗עַר מִ⁠בֵּ֥ית לֶ֨חֶם֙ יְהוּדָ֔ה מִ⁠מִּשְׁפַּ֖חַת יְהוּדָ֑ה וְ⁠ה֥וּא לֵוִ֖י וְ⁠ה֥וּא גָֽר־שָֽׁם׃","wa⁠yĕhiy-na֗ʻar mi⁠bé֥̇yţ le֨ẖem֙ yĕhẇdá֔h mi⁠mi̇şĕ̌pȧ֖ẖaţ yĕhẇdá֑h wĕ⁠h֥ẇʼ léwi֖y wĕ⁠h֥ẇʼ gáֽr-şáֽ̌m׃"],[17,8,"וַ⁠יֵּ֨לֶךְ הָ⁠אִ֜ישׁ מֵ⁠הָ⁠עִ֗יר מִ⁠בֵּ֥ית לֶ֨חֶם֙ יְהוּדָ֔ה לָ⁠ג֖וּר בַּ⁠אֲשֶׁ֣ר יִמְצָ֑א וַ⁠יָּבֹ֧א הַר־אֶפְרַ֛יִם עַד־בֵּ֥ית מִיכָ֖ה לַ⁠עֲשׂ֥וֹת דַּרְכּֽ⁠וֹ׃","wa⁠yé̇֨lekĕ há⁠ʼi֜yş̌ mé⁠há⁠ʻi֗yr mi⁠bé֥̇yţ le֨ẖem֙ yĕhẇdá֔h lá⁠g֖ẇr bȧ⁠ʼàşě֣r yimĕẕá֑ʼ wa⁠yá̇bò֧ʼ har-ʼepĕra֛yim ʻad-bé֥̇yţ miyká֖h la⁠ʻàş֥̂wòţ dȧrĕkֽ̇⁠wò׃"],[17,9,"וַ⁠יֹּאמֶר־ל֥⁠וֹ מִיכָ֖ה מֵ⁠אַ֣יִן תָּב֑וֹא וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו לֵוִ֣י אָנֹ֗כִי מִ⁠בֵּ֥ית לֶ֨חֶם֙ יְהוּדָ֔ה וְ⁠אָנֹכִ֣י הֹלֵ֔ךְ לָ⁠ג֖וּר בַּ⁠אֲשֶׁ֥ר אֶמְצָֽא׃","wa⁠yò̇ʼmer-l֥⁠wò miyká֖h mé⁠ʼa֣yin ţá̇b֑wòʼ wa⁠yò̇֨ʼmer ʼélá֜y⁠w léwi֣y ʼánò֗kiy mi⁠bé֥̇yţ le֨ẖem֙ yĕhẇdá֔h wĕ⁠ʼánòki֣y hòlé֔kĕ lá⁠g֖ẇr bȧ⁠ʼàşě֥r ʼemĕẕáֽʼ׃"],[17,10,"וַ⁠יֹּאמֶר֩ ל֨⁠וֹ מִיכָ֜ה שְׁבָ֣⁠ה עִמָּדִ֗⁠י וֶֽ⁠הְיֵה־לִ⁠י֮ לְ⁠אָ֣ב וּ⁠לְ⁠כֹהֵן֒ וְ⁠אָנֹכִ֨י אֶֽתֶּן־לְ⁠ךָ֜ עֲשֶׂ֤רֶת כֶּ֨סֶף֙ לַ⁠יָּמִ֔ים וְ⁠עֵ֥רֶךְ בְּגָדִ֖ים וּ⁠מִחְיָתֶ֑⁠ךָ וַ⁠יֵּ֖לֶךְ הַ⁠לֵּוִֽי׃","wa⁠yò̇ʼmer֩ l֨⁠wò miyká֜h şĕ̌bá֣⁠h ʻimá̇di֗⁠y weֽ⁠hĕyéh-li⁠y֮ lĕ⁠ʼá֣b ẇ⁠lĕ⁠kòhén֒ wĕ⁠ʼánòki֨y ʼeֽţėn-lĕ⁠ká֜ ʻàşê֤reţ kė֨sep֙ la⁠yá̇mi֔ym wĕ⁠ʻé֥rekĕ bĕ̇gádi֖ym ẇ⁠miẖĕyáţe֑⁠ká wa⁠yé֖̇lekĕ ha⁠lé̇wiֽy׃"],[17,11,"וַ⁠יּ֥וֹאֶל הַ⁠לֵּוִ֖י לָ⁠שֶׁ֣בֶת אֶת־הָ⁠אִ֑ישׁ וַ⁠יְהִ֤י הַ⁠נַּ֨עַר֙ ל֔⁠וֹ כְּ⁠אַחַ֖ד מִ⁠בָּנָֽי⁠ו׃","wa⁠ẏ֥wòʼel ha⁠lé̇wi֖y lá⁠şě֣beţ ʼeţ-há⁠ʼi֑yş̌ wa⁠yĕhi֤y ha⁠nȧ֨ʻar֙ l֔⁠wò kĕ̇⁠ʼaẖa֖d mi⁠bá̇náֽy⁠w׃"],[17,12,"וַ⁠יְמַלֵּ֤א מִיכָה֙ אֶת־יַ֣ד הַ⁠לֵּוִ֔י וַ⁠יְהִי־ל֥⁠וֹ הַ⁠נַּ֖עַר לְ⁠כֹהֵ֑ן וַ⁠יְהִ֖י בְּ⁠בֵ֥ית מִיכָֽה׃","wa⁠yĕmalé֤̇ʼ miykáh֙ ʼeţ-ya֣d ha⁠lé̇wi֔y wa⁠yĕhiy-l֥⁠wò ha⁠nȧ֖ʻar lĕ⁠kòhé֑n wa⁠yĕhi֖y bĕ̇⁠bé֥yţ miykáֽh׃"],[17,13,"וַ⁠יֹּ֣אמֶר מִיכָ֔ה עַתָּ֣ה יָדַ֔עְתִּי כִּֽי־יֵיטִ֥יב יְהוָ֖ה לִ֑⁠י כִּ֧י הָיָה־לִ֛⁠י הַ⁠לֵּוִ֖י לְ⁠כֹהֵֽן׃","wa⁠yò֣̇ʼmer miyká֔h ʻaţá֣̇h yáda֔ʻĕţi̇y kiֽ̇y-yéyti֥yb yĕhwá֖h li֑⁠y ki֧̇y háyáh-li֛⁠y ha⁠lé̇wi֖y lĕ⁠kòhéֽn׃"],[18,1,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם אֵ֥ין מֶ֖לֶךְ בְּ⁠יִשְׂרָאֵ֑ל וּ⁠בַ⁠יָּמִ֣ים הָ⁠הֵ֗ם שֵׁ֣בֶט הַ⁠דָּנִ֞י מְבַקֶּשׁ־ל֤⁠וֹ נַֽחֲלָה֙ לָ⁠שֶׁ֔בֶת כִּי֩ לֹֽא־נָ֨פְלָה לּ֜⁠וֹ עַד־הַ⁠יּ֥וֹם הַ⁠ה֛וּא בְּ⁠תוֹךְ־שִׁבְטֵ֥י יִשְׂרָאֵ֖ל בְּ⁠נַחֲלָֽה׃ס","bȧ⁠yá̇mi֣ym há⁠hé֔m ʼé֥yn me֖lekĕ bĕ̇⁠yişĕ̂ráʼé֑l ẇ⁠ba⁠yá̇mi֣ym há⁠hé֗m şé֣̌bet ha⁠dá̇ni֞y mĕbaqėş̌-l֤⁠wò naֽẖàláh֙ lá⁠şě֔beţ ki̇y֩ lòֽʼ-ná֨pĕláh l̇֜⁠wò ʻad-ha⁠ẏ֥wòm ha⁠h֛ẇʼ bĕ̇⁠ţwòkĕ-şǐbĕté֥y yişĕ̂ráʼé֖l bĕ̇⁠naẖàláֽh׃s"],[18,2,"וַ⁠יִּשְׁלְח֣וּ בְנֵי־דָ֣ן ׀ מִֽ⁠מִּשְׁפַּחְתָּ֡⁠ם חֲמִשָּׁ֣ה אֲנָשִׁ֣ים מִ⁠קְצוֹתָ⁠ם֩ אֲנָשִׁ֨ים בְּנֵי־חַ֜יִל מִ⁠צָּרְעָ֣ה וּ⁠מֵֽ⁠אֶשְׁתָּאֹ֗ל לְ⁠רַגֵּ֤ל אֶת־הָ⁠אָ֨רֶץ֙ וּ⁠לְ⁠חָקְרָ֔⁠הּ וַ⁠יֹּאמְר֣וּ אֲלֵ⁠הֶ֔ם לְכ֖וּ חִקְר֣וּ אֶת־הָ⁠אָ֑רֶץ וַ⁠יָּבֹ֤אוּ הַר־אֶפְרַ֨יִם֙ עַד־בֵּ֣ית מִיכָ֔ה וַ⁠יָּלִ֖ינוּ שָֽׁם׃","wa⁠yi̇şĕ̌lĕẖ֣ẇ bĕnéy-dá֣n ׀ miֽ⁠mi̇şĕ̌pȧẖĕţá̇֡⁠m ẖàmişá֣̇̌h ʼànáşǐ֣ym mi⁠qĕẕwòţá⁠m֩ ʼànáşǐ֨ym bĕ̇néy-ẖa֜yil mi⁠ẕá̇rĕʻá֣h ẇ⁠méֽ⁠ʼeşĕ̌ţá̇ʼò֗l lĕ⁠ragé֤̇l ʼeţ-há⁠ʼá֨reẕ֙ ẇ⁠lĕ⁠ẖáqĕrá֔⁠ḣ wa⁠yò̇ʼmĕr֣ẇ ʼàlé⁠he֔m lĕk֖ẇ ẖiqĕr֣ẇ ʼeţ-há⁠ʼá֑reẕ wa⁠yá̇bò֤ʼẇ har-ʼepĕra֨yim֙ ʻad-bé֣̇yţ miyká֔h wa⁠yá̇li֖ynẇ şáֽ̌m׃"],[18,3,"הֵ֚מָּה עִם־בֵּ֣ית מִיכָ֔ה וְ⁠הֵ֣מָּה הִכִּ֔ירוּ אֶת־ק֥וֹל הַ⁠נַּ֖עַר הַ⁠לֵּוִ֑י וַ⁠יָּס֣וּרוּ שָׁ֗ם וַ⁠יֹּ֤אמְרוּ ל⁠וֹ֙ מִֽי־הֱבִיאֲ⁠ךָ֣ הֲלֹ֔ם וּ⁠מָֽה־אַתָּ֥ה עֹשֶׂ֛ה בָּ⁠זֶ֖ה וּ⁠מַה־לְּ⁠ךָ֥ פֹֽה׃","hé֚má̇h ʻim-bé֣̇yţ miyká֔h wĕ⁠hé֣má̇h hiki̇֔yrẇ ʼeţ-q֥wòl ha⁠nȧ֖ʻar ha⁠lé̇wi֑y wa⁠yá̇s֣ẇrẇ şá̌֗m wa⁠yò֤̇ʼmĕrẇ l⁠wò֙ miֽy-hèbiyʼà⁠ká֣ hàlò֔m ẇ⁠máֽh-ʼaţá֥̇h ʻòşê֛h bá̇⁠ze֖h ẇ⁠mah-lĕ̇⁠ká֥ pòֽh׃"],[18,4,"וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם כָּ⁠זֹ֣ה וְ⁠כָ⁠זֶ֔ה עָ֥שָׂה לִ֖⁠י מִיכָ֑ה וַ⁠יִּשְׂכְּרֵ֕⁠נִי וָ⁠אֱהִי־ל֖⁠וֹ לְ⁠כֹהֵֽן׃","wa⁠yò֣̇ʼmer ʼàlé⁠he֔m ká̇⁠zò֣h wĕ⁠ká⁠ze֔h ʻá֥şá̂h li֖⁠y miyká֑h wa⁠yi̇şĕ̂kĕ̇ré֕⁠niy wá⁠ʼèhiy-l֖⁠wò lĕ⁠kòhéֽn׃"],[18,5,"וַ⁠יֹּ֥אמְרוּ ל֖⁠וֹ שְׁאַל־נָ֣א בֵ⁠אלֹהִ֑ים וְ⁠נֵ֣דְעָ֔ה הֲ⁠תַצְלִ֣יחַ דַּרְכֵּ֔⁠נוּ אֲשֶׁ֥ר אֲנַ֖חְנוּ הֹלְכִ֥ים עָלֶֽי⁠הָ׃","wa⁠yò֥̇ʼmĕrẇ l֖⁠wò şĕ̌ʼal-ná֣ʼ bé⁠ʼlòhi֑ym wĕ⁠né֣dĕʻá֔h hà⁠ţaẕĕli֣yẖa dȧrĕké̇֔⁠nẇ ʼàşě֥r ʼàna֖ẖĕnẇ hòlĕki֥ym ʻáleֽy⁠há׃"],[18,6,"וַ⁠יֹּ֧אמֶר לָ⁠הֶ֛ם הַ⁠כֹּהֵ֖ן לְכ֣וּ לְ⁠שָׁל֑וֹם נֹ֣כַח יְהוָ֔ה דַּרְכְּ⁠כֶ֖ם אֲשֶׁ֥ר תֵּֽלְכוּ־בָֽ⁠הּ׃פ","wa⁠yò֧̇ʼmer lá⁠he֛m ha⁠kò̇hé֖n lĕk֣ẇ lĕ⁠şá̌l֑wòm nò֣kaẖ yĕhwá֔h dȧrĕkĕ̇⁠ke֖m ʼàşě֥r ţéֽ̇lĕkẇ-báֽ⁠ḣ׃p"],[18,7,"וַ⁠יֵּלְכוּ֙ חֲמֵ֣שֶׁת הָ⁠אֲנָשִׁ֔ים וַ⁠יָּבֹ֖אוּ לָ֑יְשָׁ⁠ה וַ⁠יִּרְא֣וּ אֶת־הָ⁠עָ֣ם אֲשֶׁר־בְּ⁠קִרְבָּ֣⁠הּ יוֹשֶֽׁבֶת־לָ֠⁠בֶטַח כְּ⁠מִשְׁפַּ֨ט צִדֹנִ֜ים שֹׁקֵ֣ט ׀ וּ⁠בֹטֵ֗חַ וְ⁠אֵין־מַכְלִ֨ים דָּבָ֤ר בָּ⁠אָ֨רֶץ֙ יוֹרֵ֣שׁ עֶ֔צֶר וּ⁠רְחֹקִ֥ים הֵ֨מָּה֙ מִ⁠צִּ֣דֹנִ֔ים וְ⁠דָבָ֥ר אֵין־לָ⁠הֶ֖ם עִם־אָדָֽם׃","wa⁠yé̇lĕkẇ֙ ẖàmé֣şěţ há⁠ʼànáşǐ֔ym wa⁠yá̇bò֖ʼẇ lá֑yĕşá̌⁠h wa⁠yi̇rĕʼ֣ẇ ʼeţ-há⁠ʻá֣m ʼàşěr-bĕ̇⁠qirĕbá֣̇⁠ḣ ywòşěֽbeţ-lá֠⁠betaẖ kĕ̇⁠mişĕ̌pȧ֨t ẕidòni֜ym şò̌qé֣t ׀ ẇ⁠bòté֗ẖa wĕ⁠ʼéyn-makĕli֨ym dá̇bá֤r bá̇⁠ʼá֨reẕ֙ ywòré֣ş̌ ʻe֔ẕer ẇ⁠rĕẖòqi֥ym hé֨má̇h֙ mi⁠ẕi֣̇dòni֔ym wĕ⁠dábá֥r ʼéyn-lá⁠he֖m ʻim-ʼádáֽm׃"],[18,8,"וַ⁠יָּבֹ֨אוּ֙ אֶל־אֲחֵי⁠הֶ֔ם צָרְעָ֖ה וְ⁠אֶשְׁתָּאֹ֑ל וַ⁠יֹּאמְר֥וּ לָ⁠הֶ֛ם אֲחֵי⁠הֶ֖ם מָ֥ה אַתֶּֽם׃","wa⁠yá̇bò֨ʼẇ֙ ʼel-ʼàẖéy⁠he֔m ẕárĕʻá֖h wĕ⁠ʼeşĕ̌ţá̇ʼò֑l wa⁠yò̇ʼmĕr֥ẇ lá⁠he֛m ʼàẖéy⁠he֖m má֥h ʼaţėֽm׃"],[18,9,"וַ⁠יֹּאמְר֗וּ ק֚וּמָ⁠ה וְ⁠נַעֲלֶ֣ה עֲלֵי⁠הֶ֔ם כִּ֤י רָאִ֨ינוּ֙ אֶת־הָ⁠אָ֔רֶץ וְ⁠הִנֵּ֥ה טוֹבָ֖ה מְאֹ֑ד וְ⁠אַתֶּ֣ם מַחְשִׁ֔ים אַל־תֵּעָ֣צְל֔וּ לָ⁠לֶ֥כֶת לָ⁠בֹ֖א לָ⁠רֶ֥שֶׁת אֶת־הָ⁠אָֽרֶץ׃","wa⁠yò̇ʼmĕr֗ẇ q֚ẇmá⁠h wĕ⁠naʻàle֣h ʻàléy⁠he֔m ki֤̇y ráʼi֨ynẇ֙ ʼeţ-há⁠ʼá֔reẕ wĕ⁠hiné֥̇h twòbá֖h mĕʼò֑d wĕ⁠ʼaţė֣m maẖĕşǐ֔ym ʼal-ţé̇ʻá֣ẕĕl֔ẇ lá⁠le֥keţ lá⁠bò֖ʼ lá⁠re֥şěţ ʼeţ-há⁠ʼáֽreẕ׃"],[18,10,"כְּ⁠בֹאֲ⁠כֶ֞ם תָּבֹ֣אוּ ׀ אֶל־עַ֣ם בֹּטֵ֗חַ וְ⁠הָ⁠אָ֨רֶץ֙ רַחֲבַ֣ת יָדַ֔יִם כִּֽי־נְתָנָ֥⁠הּ אֱלֹהִ֖ים בְּ⁠יֶדְ⁠כֶ֑ם מָקוֹם֙ אֲשֶׁ֣ר אֵֽין־שָׁ֣ם מַחְס֔וֹר כָּל־דָּבָ֖ר אֲשֶׁ֥ר בָּ⁠אָֽרֶץ׃","kĕ̇⁠bòʼà⁠ke֞m ţá̇bò֣ʼẇ ׀ ʼel-ʻa֣m bò̇té֗ẖa wĕ⁠há⁠ʼá֨reẕ֙ raẖàba֣ţ yáda֔yim kiֽ̇y-nĕţáná֥⁠ḣ ʼèlòhi֖ym bĕ̇⁠yedĕ⁠ke֑m máqwòm֙ ʼàşě֣r ʼéֽyn-şá֣̌m maẖĕs֔wòr ká̇l-dá̇bá֖r ʼàşě֥r bá̇⁠ʼáֽreẕ׃"],[18,11,"וַ⁠יִּסְע֤וּ מִ⁠שָּׁם֙ מִ⁠מִּשְׁפַּ֣חַת הַ⁠דָּנִ֔י מִ⁠צָּרְעָ֖ה וּ⁠מֵ⁠אֶשְׁתָּאֹ֑ל שֵֽׁשׁ־מֵא֣וֹת אִ֔ישׁ חָג֖וּר כְּלֵ֥י מִלְחָמָֽה׃","wa⁠yi̇sĕʻ֤ẇ mi⁠şá̇̌m֙ mi⁠mi̇şĕ̌pȧ֣ẖaţ ha⁠dá̇ni֔y mi⁠ẕá̇rĕʻá֖h ẇ⁠mé⁠ʼeşĕ̌ţá̇ʼò֑l şéֽ̌ş̌-méʼ֣wòţ ʼi֔yş̌ ẖág֖ẇr kĕ̇lé֥y milĕẖámáֽh׃"],[18,12,"וַֽ⁠יַּעֲל֗וּ וַֽ⁠יַּחֲנ֛וּ בְּ⁠קִרְיַ֥ת יְעָרִ֖ים בִּֽ⁠יהוּדָ֑ה עַל־כֵּ֡ן קָרְאוּ֩ לַ⁠מָּק֨וֹם הַ⁠ה֜וּא מַחֲנֵה־דָ֗ן עַ֚ד הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה הִנֵּ֕ה אַחֲרֵ֖י קִרְיַ֥ת יְעָרִֽים׃","waֽ⁠yȧʻàl֗ẇ waֽ⁠yȧẖàn֛ẇ bĕ̇⁠qirĕya֥ţ yĕʻári֖ym biֽ̇⁠yhẇdá֑h ʻal-ké̇֡n qárĕʼẇ֩ la⁠má̇q֨wòm ha⁠h֜ẇʼ maẖànéh-dá֗n ʻa֚d ha⁠ẏ֣wòm ha⁠zė֔h hiné̇֕h ʼaẖàré֖y qirĕya֥ţ yĕʻáriֽym׃"],[18,13,"וַ⁠יַּעַבְר֥וּ מִ⁠שָּׁ֖ם הַר־אֶפְרָ֑יִם וַ⁠יָּבֹ֖אוּ עַד־בֵּ֥ית מִיכָֽה׃","wa⁠yȧʻabĕr֥ẇ mi⁠şá֖̇̌m har-ʼepĕrá֑yim wa⁠yá̇bò֖ʼẇ ʻad-bé֥̇yţ miykáֽh׃"],[18,14,"וַֽ⁠יַּעֲנ֞וּ חֲמֵ֣שֶׁת הָ⁠אֲנָשִׁ֗ים הַ⁠הֹלְכִים֮ לְ⁠רַגֵּל֮ אֶת־הָ⁠אָ֣רֶץ לַיִשׁ֒ וַ⁠יֹּֽאמְרוּ֙ אֶל־אֲחֵי⁠הֶ֔ם הַ⁠יְדַעְתֶּ֗ם כִּ֠י יֵ֣שׁ בַּ⁠בָּתִּ֤ים הָ⁠אֵ֨לֶּה֙ אֵפ֣וֹד וּ⁠תְרָפִ֔ים וּ⁠פֶ֖סֶל וּ⁠מַסֵּכָ֑ה וְ⁠עַתָּ֖ה דְּע֥וּ מַֽה־תַּעֲשֽׂוּ׃","waֽ⁠yȧʻàn֞ẇ ẖàmé֣şěţ há⁠ʼànáşǐ֗ym ha⁠hòlĕkiym֮ lĕ⁠ragé̇l֮ ʼeţ-há⁠ʼá֣reẕ layiş̌֒ wa⁠yòֽ̇ʼmĕrẇ֙ ʼel-ʼàẖéy⁠he֔m ha⁠yĕdaʻĕţė֗m ki̇֠y yé֣ş̌ bȧ⁠bá̇ţi֤̇ym há⁠ʼé֨lėh֙ ʼép֣wòd ẇ⁠ţĕrápi֔ym ẇ⁠pe֖sel ẇ⁠masé̇ká֑h wĕ⁠ʻaţá֖̇h dĕ̇ʻ֥ẇ maֽh-ţȧʻàşֽ̂ẇ׃"],[18,15,"וַ⁠יָּס֣וּרוּ שָׁ֔מָּ⁠ה וַ⁠יָּבֹ֛אוּ אֶל־בֵּֽית־הַ⁠נַּ֥עַר הַ⁠לֵּוִ֖י בֵּ֣ית מִיכָ֑ה וַ⁠יִּשְׁאֲלוּ־ל֖⁠וֹ לְ⁠שָׁלֽוֹם׃","wa⁠yá̇s֣ẇrẇ şá̌֔má̇⁠h wa⁠yá̇bò֛ʼẇ ʼel-béֽ̇yţ-ha⁠nȧ֥ʻar ha⁠lé̇wi֖y bé֣̇yţ miyká֑h wa⁠yi̇şĕ̌ʼàlẇ-l֖⁠wò lĕ⁠şá̌lֽwòm׃"],[18,16,"וְ⁠שֵׁשׁ־מֵא֣וֹת אִ֗ישׁ חֲגוּרִים֙ כְּלֵ֣י מִלְחַמְתָּ֔⁠ם נִצָּבִ֖ים פֶּ֣תַח הַ⁠שָּׁ֑עַר אֲשֶׁ֖ר מִ⁠בְּנֵי־דָֽן׃","wĕ⁠şé̌ş̌-méʼ֣wòţ ʼi֗yş̌ ẖàgẇriym֙ kĕ̇lé֣y milĕẖamĕţá̇֔⁠m niẕá̇bi֖ym pė֣ţaẖ ha⁠şá֑̇̌ʻar ʼàşě֖r mi⁠bĕ̇néy-dáֽn׃"],[18,17,"וַֽ⁠יַּעֲל֞וּ חֲמֵ֣שֶׁת הָ⁠אֲנָשִׁ֗ים הַ⁠הֹלְכִים֮ לְ⁠רַגֵּ֣ל אֶת־הָ⁠אָרֶץ֒ בָּ֣אוּ שָׁ֔מָּ⁠ה לָקְח֗וּ אֶת־הַ⁠פֶּ֨סֶל֙ וְ⁠אֶת־הָ֣⁠אֵפ֔וֹד וְ⁠אֶת־הַ⁠תְּרָפִ֖ים וְ⁠אֶת־הַ⁠מַּסֵּכָ֑ה וְ⁠הַ⁠כֹּהֵ֗ן נִצָּב֙ פֶּ֣תַח הַ⁠שַּׁ֔עַר וְ⁠שֵׁשׁ־מֵא֣וֹת הָ⁠אִ֔ישׁ הֶ⁠חָג֖וּר כְּלֵ֥י הַ⁠מִּלְחָמָֽה׃","wֽa⁠yȧʻàl֞ẇ ẖàmé֣şěţ há⁠ʼànáşǐ֗ym ha⁠hòlĕkiym֮ lĕ⁠ragé֣̇l ʼeţ-há⁠ʼáreẕ֒ bá֣̇ʼẇ şá̌֔má̇⁠h láqĕẖ֗ẇ ʼeţ-ha⁠pė֨sel֙ wĕ⁠ʼeţ-há֣⁠ʼép֔wòd wĕ⁠ʼeţ-ha⁠ţĕ̇rápi֖ym wĕ⁠ʼeţ-ha⁠mȧsé̇ká֑h wĕ⁠ha⁠kò̇hé֗n niẕá̇b֙ pė֣ţaẖ ha⁠şȧ̌֔ʻar wĕ⁠şé̌ş̌-méʼ֣wòţ há⁠ʼi֔yş̌ he⁠ẖág֖ẇr kĕ̇lé֥y ha⁠mi̇lĕẖámáֽh׃"],[18,18,"וְ⁠אֵ֗לֶּה בָּ֚אוּ בֵּ֣ית מִיכָ֔ה וַ⁠יִּקְחוּ֙ אֶת־פֶּ֣סֶל הָ⁠אֵפ֔וֹד וְ⁠אֶת־הַ⁠תְּרָפִ֖ים וְ⁠אֶת־הַ⁠מַּסֵּכָ֑ה וַ⁠יֹּ֤אמֶר אֲלֵי⁠הֶם֙ הַ⁠כֹּהֵ֔ן מָ֥ה אַתֶּ֖ם עֹשִֽׂים׃","wĕ⁠ʼé֗lėh bá֚̇ʼẇ bé֣̇yţ miyká֔h wa⁠yi̇qĕẖẇ֙ ʼeţ-pė֣sel há⁠ʼép֔wòd wĕ⁠ʼeţ-ha⁠ţĕ̇rápi֖ym wĕ⁠ʼeţ-ha⁠mȧsé̇ká֑h wa⁠yò֤̇ʼmer ʼàléy⁠hem֙ ha⁠kò̇hé֔n má֥h ʼaţė֖m ʻòşîֽym׃"],[18,19,"וַ⁠יֹּאמְרוּ֩ ל֨⁠וֹ הַחֲרֵ֜שׁ שִֽׂים־יָדְ⁠ךָ֤ עַל־פִּ֨י⁠ךָ֙ וְ⁠לֵ֣ךְ עִמָּ֔⁠נוּ וֶֽ⁠הְיֵה־לָ֖⁠נוּ לְ⁠אָ֣ב וּ⁠לְ⁠כֹהֵ֑ן הֲ⁠ט֣וֹב ׀ הֱיוֹתְ⁠ךָ֣ כֹהֵ֗ן לְ⁠בֵית֙ אִ֣ישׁ אֶחָ֔ד א֚וֹ הֱיוֹתְ⁠ךָ֣ כֹהֵ֔ן לְ⁠שֵׁ֥בֶט וּ⁠לְ⁠מִשְׁפָּחָ֖ה בְּ⁠יִשְׂרָאֵֽל׃","wa⁠yò̇ʼmĕrẇ֩ l֨⁠wò haẖàré֜ş̌ şîֽym-yádĕ⁠ká֤ ʻal-pi̇֨y⁠ká֙ wĕ⁠lé֣kĕ ʻimá̇֔⁠nẇ weֽ⁠hĕyéh-lá֖⁠nẇ lĕ⁠ʼá֣b ẇ⁠lĕ⁠kòhé֑n hà⁠t֣wòb ׀ hèywòţĕ⁠ká֣ kòhé֗n lĕ⁠béyţ֙ ʼi֣yş̌ ʼeẖá֔d ʼ֚wò hèywòţĕ⁠ká֣ kòhé֔n lĕ⁠şé֥̌bet ẇ⁠lĕ⁠mişĕ̌pá̇ẖá֖h bĕ̇⁠yişĕ̂ráʼéֽl׃"],[18,20,"וַ⁠יִּיטַב֙ לֵ֣ב הַ⁠כֹּהֵ֔ן וַ⁠יִּקַּח֙ אֶת־הָ֣⁠אֵפ֔וֹד וְ⁠אֶת־הַ⁠תְּרָפִ֖ים וְ⁠אֶת־הַ⁠פָּ֑סֶל וַ⁠יָּבֹ֖א בְּ⁠קֶ֥רֶב הָ⁠עָֽם׃","wa⁠yi̇ytab֙ lé֣b ha⁠kò̇hé֔n wa⁠yi̇qȧẖ֙ ʼeţ-há֣⁠ʼép֔wòd wĕ⁠ʼeţ-ha⁠ţĕ̇rápi֖ym wĕ⁠ʼeţ-ha⁠pá֑̇sel wa⁠yá̇bò֖ʼ bĕ̇⁠qe֥reb há⁠ʻáֽm׃"],[18,21,"וַ⁠יִּפְנ֖וּ וַ⁠יֵּלֵ֑כוּ וַ⁠יָּשִׂ֨ימוּ אֶת־הַ⁠טַּ֧ף וְ⁠אֶת־הַ⁠מִּקְנֶ֛ה וְ⁠אֶת־הַ⁠כְּבוּדָּ֖ה לִ⁠פְנֵי⁠הֶֽם׃","wa⁠yi̇pĕn֖ẇ wa⁠yé̇lé֑kẇ wa⁠yá̇şî֨ymẇ ʼeţ-ha⁠tȧ֧p wĕ⁠ʼeţ-ha⁠mi̇qĕne֛h wĕ⁠ʼeţ-ha⁠kĕ̇bẇdá֖̇h li⁠pĕnéy⁠heֽm׃"],[18,22,"הֵ֥מָּה הִרְחִ֖יקוּ מִ⁠בֵּ֣ית מִיכָ֑ה וְ⁠הָ⁠אֲנָשִׁ֗ים אֲשֶׁ֤ר בַּ⁠בָּתִּים֙ אֲשֶׁר֙ עִם־בֵּ֣ית מִיכָ֔ה נִֽזְעֲק֔וּ וַ⁠יַּדְבִּ֖יקוּ אֶת־בְּנֵי־דָֽן׃","hé֥má̇h hirĕẖi֖yqẇ mi⁠bé֣̇yţ miyká֑h wĕ⁠há⁠ʼànáşǐ֗ym ʼàşě֤r bȧ⁠bá̇ţi̇ym֙ ʼàşěr֙ ʻim-bé֣̇yţ miyká֔h niֽzĕʻàq֔ẇ wa⁠yȧdĕbi֖̇yqẇ ʼeţ-bĕ̇néy-dáֽn׃"],[18,23,"וַֽ⁠יִּקְרְאוּ֙ אֶל־בְּנֵי־דָ֔ן וַ⁠יַּסֵּ֖בּוּ פְּנֵי⁠הֶ֑ם וַ⁠יֹּאמְר֣וּ לְ⁠מִיכָ֔ה מַה־לְּ⁠ךָ֖ כִּ֥י נִזְעָֽקְתָּ׃","waֽ⁠yi̇qĕrĕʼẇ֙ ʼel-bĕ̇néy-dá֔n wa⁠yȧsé֖̇ḃẇ pĕ̇néy⁠he֑m wa⁠yò̇ʼmĕr֣ẇ lĕ⁠miyká֔h mah-lĕ̇⁠ká֖ ki֥̇y nizĕʻáֽqĕţá̇׃"],[18,24,"וַ⁠יֹּ֡אמֶר אֶת־אֱלֹהַ⁠י֩ אֲשֶׁר־עָשִׂ֨יתִי לְקַחְתֶּ֧ם וְֽ⁠אֶת־הַ⁠כֹּהֵ֛ן וַ⁠תֵּלְכ֖וּ וּ⁠מַה־לִּ֣⁠י ע֑וֹד וּ⁠מַה־זֶּ֛ה תֹּאמְר֥וּ אֵלַ֖⁠י מַה־לָּֽ⁠ךְ׃","wa⁠yò̇֡ʼmer ʼeţ-ʼèlòha⁠y֩ ʼàşěr-ʻáşî֨yţiy lĕqaẖĕţė֧m wĕֽ⁠ʼeţ-ha⁠kò̇hé֛n wa⁠ţé̇lĕk֖ẇ ẇ⁠mah-li֣̇⁠y ʻ֑wòd ẇ⁠mah-zė֛h ţò̇ʼmĕr֥ẇ ʼéla֖⁠y mah-láֽ̇⁠kĕ׃"],[18,25,"וַ⁠יֹּאמְר֤וּ אֵלָי⁠ו֙ בְּנֵי־דָ֔ן אַל־תַּשְׁמַ֥ע קוֹלְ⁠ךָ֖ עִמָּ֑⁠נוּ פֶּֽן־יִפְגְּע֣וּ בָ⁠כֶ֗ם אֲנָשִׁים֙ מָ֣רֵי נֶ֔פֶשׁ וְ⁠אָסַפְתָּ֥ה נַפְשְׁ⁠ךָ֖ וְ⁠נֶ֥פֶשׁ בֵּיתֶֽ⁠ךָ׃","wa⁠yò̇ʼmĕr֤ẇ ʼéláy⁠w֙ bĕ̇néy-dá֔n ʼal-ţȧşĕ̌ma֥ʻ qwòlĕ⁠ká֖ ʻimá֑̇⁠nẇ pėֽn-yipĕgĕ̇ʻ֣ẇ bá⁠ke֗m ʼànáşǐym֙ má֣réy ne֔peş̌ wĕ⁠ʼásapĕţá֥̇h napĕşĕ̌⁠ká֖ wĕ⁠ne֥peş̌ bé̇yţeֽ⁠ká׃"],[18,26,"וַ⁠יֵּלְכ֥וּ בְנֵי־דָ֖ן לְ⁠דַרְכָּ֑⁠ם וַ⁠יַּ֣רְא מִיכָ֗ה כִּי־חֲזָקִ֥ים הֵ֨מָּה֙ מִמֶּ֔⁠נּוּ וַ⁠יִּ֖פֶן וַ⁠יָּ֥שָׁב אֶל־בֵּיתֽ⁠וֹ׃","wa⁠yé̇lĕk֥ẇ bĕnéy-dá֖n lĕ⁠darĕká֑̇⁠m wa⁠yȧ֣rĕʼ miyká֗h ki̇y-ẖàzáqi֥ym hé֨má̇h֙ mimė֔⁠ṅẇ wa⁠yi֖̇pen wa⁠yá֥̇şá̌b ʼel-bé̇yţֽ⁠wò׃"],[18,27,"וְ⁠הֵ֨מָּה לָקְח֜וּ אֵ֧ת אֲשֶׁר־עָשָׂ֣ה מִיכָ֗ה וְֽ⁠אֶת־הַ⁠כֹּהֵן֮ אֲשֶׁ֣ר הָיָה־ל⁠וֹ֒ וַ⁠יָּבֹ֣אוּ עַל־לַ֗יִשׁ עַל־עַם֙ שֹׁקֵ֣ט וּ⁠בֹטֵ֔חַ וַ⁠יַּכּ֥וּ אוֹתָ֖⁠ם לְ⁠פִי־חָ֑רֶב וְ⁠אֶת־הָ⁠עִ֖יר שָׂרְפ֥וּ בָ⁠אֵֽשׁ׃","wĕ⁠hé֨má̇h láqĕẖ֜ẇ ʼé֧ţ ʼàşěr-ʻáşá֣̂h miyká֗h wĕֽ⁠ʼeţ-ha⁠kò̇hén֮ ʼàşě֣r háyáh-l⁠wò֒ wa⁠yá̇bò֣ʼẇ ʻal-la֗yiş̌ ʻal-ʻam֙ şò̌qé֣t ẇ⁠bòté֔ẖa wa⁠yȧk֥̇ẇ ʼwòţá֖⁠m lĕ⁠piy-ẖá֑reb wĕ⁠ʼeţ-há⁠ʻi֖yr şá̂rĕp֥ẇ bá⁠ʼéֽş̌׃"],[18,28,"וְ⁠אֵ֨ין מַצִּ֜יל כִּ֧י רְֽחוֹקָה־הִ֣יא מִ⁠צִּיד֗וֹן וְ⁠דָבָ֤ר אֵין־לָ⁠הֶם֙ עִם־אָדָ֔ם וְ⁠הִ֕יא בָּ⁠עֵ֖מֶק אֲשֶׁ֣ר לְ⁠בֵית־רְח֑וֹב וַ⁠יִּבְנ֥וּ אֶת־הָ⁠עִ֖יר וַ⁠יֵּ֥שְׁבוּ בָֽ⁠הּ׃","wĕ⁠ʼé֨yn maẕi̇֜yl ki֧̇y rĕֽẖwòqáh-hi֣yʼ mi⁠ẕi̇yd֗wòn wĕ⁠dábá֤r ʼéyn-lá⁠hem֙ ʻim-ʼádá֔m wĕ⁠hi֕yʼ bá̇⁠ʻé֖meq ʼàşě֣r lĕ⁠béyţ-rĕẖ֑wòb wa⁠yi̇bĕn֥ẇ ʼeţ-há⁠ʻi֖yr wa⁠yé֥̇şĕ̌bẇ báֽ⁠ḣ׃"],[18,29,"וַ⁠יִּקְרְא֤וּ שֵׁם־הָ⁠עִיר֙ דָּ֔ן בְּ⁠שֵׁם֙ דָּ֣ן אֲבִי⁠הֶ֔ם אֲשֶׁ֥ר יוּלַּ֖ד לְ⁠יִשְׂרָאֵ֑ל וְ⁠אוּלָ֛ם לַ֥יִשׁ שֵׁם־הָ⁠עִ֖יר לָ⁠רִאשֹׁנָֽה׃","wa⁠yi̇qĕrĕʼ֤ẇ şé̌m-há⁠ʻiyr֙ dá̇֔n bĕ̇⁠şé̌m֙ dá֣̇n ʼàbiy⁠he֔m ʼàşě֥r yẇlȧ֖d lĕ⁠yişĕ̂ráʼé֑l wĕ⁠ʼẇlá֛m la֥yiş̌ şé̌m-há⁠ʻi֖yr lá⁠riʼşò̌náֽh׃"],[18,30,"וַ⁠יָּקִ֧ימוּ לָ⁠הֶ֛ם בְּנֵי־דָ֖ן אֶת־הַ⁠פָּ֑סֶל וִ֠⁠יהוֹנָתָן בֶּן־גֵּרְשֹׁ֨ם בֶּן־מְנַשֶּׁ֜ה ה֣וּא וּ⁠בָנָ֗י⁠ו הָי֤וּ כֹהֲנִים֙ לְ⁠שֵׁ֣בֶט הַ⁠דָּנִ֔י עַד־י֖וֹם גְּל֥וֹת הָ⁠אָֽרֶץ׃","wa⁠yá̇qi֧ymẇ lá⁠he֛m bĕ̇néy-dá֖n ʼeţ-ha⁠pá֑̇sel wi֠⁠yhwònáţán bėn-gé̇rĕşò̌֨m bėn-mĕnaşė̌֜h h֣ẇʼ ẇ⁠báná֗y⁠w háy֤ẇ kòhàniym֙ lĕ⁠şé֣̌bet ha⁠dá̇ni֔y ʻad-y֖wòm gĕ̇l֥wòţ há⁠ʼáֽreẕ׃"],[18,31,"וַ⁠יָּשִׂ֣ימוּ לָ⁠הֶ֔ם אֶת־פֶּ֥סֶל מִיכָ֖ה אֲשֶׁ֣ר עָשָׂ֑ה כָּל־יְמֵ֛י הֱי֥וֹת בֵּית־הָ⁠אֱלֹהִ֖ים בְּ⁠שִׁלֹֽה׃פ","wa⁠yá̇şî֣ymẇ lá⁠he֔m ʼeţ-pė֥sel miyká֖h ʼàşě֣r ʻáşá֑̂h ká̇l-yĕmé֛y hèy֥wòţ bé̇yţ-há⁠ʼèlòhi֖ym bĕ̇⁠şǐlòֽh׃p"],[19,1,"וַ⁠יְהִי֙ בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם וּ⁠מֶ֖לֶךְ אֵ֣ין בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יְהִ֣י ׀ אִ֣ישׁ לֵוִ֗י גָּ֚ר בְּ⁠יַרְכְּתֵ֣י הַר־אֶפְרַ֔יִם וַ⁠יִּֽקַּֽח־ל⁠וֹ֙ אִשָּׁ֣ה פִילֶ֔גֶשׁ מִ⁠בֵּ֥ית לֶ֖חֶם יְהוּדָֽה׃","wa⁠yĕhiy֙ bȧ⁠yá̇mi֣ym há⁠hé֔m ẇ⁠me֖lekĕ ʼé֣yn bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yĕhi֣y ׀ ʼi֣yş̌ léwi֗y gá֚̇r bĕ̇⁠yarĕkĕ̇ţé֣y har-ʼepĕra֔yim wa⁠yiֽ̇qȧֽẖ-l⁠wò֙ ʼişá֣̇̌h piyle֔geş̌ mi⁠bé֥̇yţ le֖ẖem yĕhẇdáֽh׃"],[19,2,"וַ⁠תִּזְנֶ֤ה עָלָי⁠ו֙ פִּֽילַגְשׁ֔⁠וֹ וַ⁠תֵּ֤לֶךְ מֵֽ⁠אִתּ⁠וֹ֙ אֶל־בֵּ֣ית אָבִ֔י⁠הָ אֶל־בֵּ֥ית לֶ֖חֶם יְהוּדָ֑ה וַ⁠תְּהִי־שָׁ֕ם יָמִ֖ים אַרְבָּעָ֥ה חֳדָשִֽׁים׃","wa⁠ţi̇zĕne֤h ʻáláy⁠w֙ piֽ̇ylagĕş̌֔⁠wò wa⁠ţé֤̇lekĕ méֽ⁠ʼiţ̇⁠wò֙ ʼel-bé֣̇yţ ʼábi֔y⁠há ʼel-bé֥̇yţ le֖ẖem yĕhẇdá֑h wa⁠ţĕ̇hiy-şá̌֕m yámi֖ym ʼarĕbá̇ʻá֥h ẖodáşǐֽym׃"],[19,3,"וַ⁠יָּ֨קָם אִישָׁ֜⁠הּ וַ⁠יֵּ֣לֶךְ אַחֲרֶ֗י⁠הָ לְ⁠דַבֵּ֤ר עַל־לִבָּ⁠הּ֙ ל⁠השיב⁠ו וְ⁠נַעֲר֥⁠וֹ עִמּ֖⁠וֹ וְ⁠צֶ֣מֶד חֲמֹרִ֑ים וַ⁠תְּבִיאֵ֨⁠הוּ֙ בֵּ֣ית אָבִ֔י⁠הָ וַ⁠יִּרְאֵ֨⁠הוּ֙ אֲבִ֣י הַֽ⁠נַּעֲרָ֔ה וַ⁠יִּשְׂמַ֖ח לִ⁠קְרָאתֽ⁠וֹ׃","wa⁠yá̇֨qám ʼiyşá̌֜⁠ḣ wa⁠yé֣̇lekĕ ʼaẖàre֗y⁠há lĕ⁠dabé֤̇r ʻal-libá̇⁠ḣ֙ l⁠hşyb⁠w wĕ⁠naʻàr֥⁠wò ʻiṁ֖⁠wò wĕ⁠ẕe֣med ẖàmòri֑ym wa⁠ţĕ̇biyʼé֨⁠hẇ֙ bé֣̇yţ ʼábi֔y⁠há wa⁠yi̇rĕʼé֨⁠hẇ֙ ʼàbi֣y haֽ⁠nȧʻàrá֔h wa⁠yi̇şĕ̂ma֖ẖ li⁠qĕráʼţֽ⁠wò׃"],[19,4,"וַ⁠יֶּחֱזַק־בּ֤⁠וֹ חֹֽתְנ⁠וֹ֙ אֲבִ֣י הַֽ⁠נַּעֲרָ֔ה וַ⁠יֵּ֥שֶׁב אִתּ֖⁠וֹ שְׁלֹ֣שֶׁת יָמִ֑ים וַ⁠יֹּאכְלוּ֙ וַ⁠יִּשְׁתּ֔וּ וַ⁠יָּלִ֖ינוּ שָֽׁם׃","wa⁠yėẖèzaq-ḃ֤⁠wò ẖòֽţĕn⁠wò֙ ʼàbi֣y haֽ⁠nȧʻàrá֔h wa⁠yé֥̇şěb ʼiţ֖̇⁠wò şĕ̌lò֣şěţ yámi֑ym wa⁠yò̇ʼkĕlẇ֙ wa⁠yi̇şĕ̌ţ̇֔ẇ wa⁠yá̇li֖ynẇ şáֽ̌m׃"],[19,5,"וַֽ⁠יְהִי֙ בַּ⁠יּ֣וֹם הָ⁠רְבִיעִ֔י וַ⁠יַּשְׁכִּ֥ימוּ בַ⁠בֹּ֖קֶר וַ⁠יָּ֣קָם לָ⁠לֶ֑כֶת וַ⁠יֹּאמֶר֩ אֲבִ֨י הַֽ⁠נַּעֲרָ֜ה אֶל־חֲתָנ֗⁠וֹ סְעָ֧ד לִבְּ⁠ךָ֛ פַּת־לֶ֖חֶם וְ⁠אַחַ֥ר תֵּלֵֽכוּ׃","waֽ⁠yĕhiy֙ bȧ⁠ẏ֣wòm há⁠rĕbiyʻi֔y wa⁠yȧşĕ̌ki֥̇ymẇ ba⁠bò֖̇qer wa⁠yá֣̇qám lá⁠le֑keţ wa⁠yò̇ʼmer֩ ʼàbi֨y haֽ⁠nȧʻàrá֜h ʼel-ẖàţán֗⁠wò sĕʻá֧d libĕ̇⁠ká֛ pȧţ-le֖ẖem wĕ⁠ʼaẖa֥r ţé̇léֽkẇ׃"],[19,6,"וַ⁠יֵּשְׁב֗וּ וַ⁠יֹּאכְל֧וּ שְׁנֵי⁠הֶ֛ם יַחְדָּ֖ו וַ⁠יִּשְׁתּ֑וּ וַ⁠יֹּ֜אמֶר אֲבִ֤י הַֽ⁠נַּעֲרָה֙ אֶל־הָ⁠אִ֔ישׁ הֽוֹאֶל־נָ֥א וְ⁠לִ֖ין וְ⁠יִטַ֥ב לִבֶּֽ⁠ךָ׃","wa⁠yé̇şĕ̌b֗ẇ wa⁠yò̇ʼkĕl֧ẇ şĕ̌néy⁠he֛m yaẖĕdá֖̇w wa⁠yi̇şĕ̌ţ֑̇ẇ wa⁠yò̇֜ʼmer ʼàbi֤y haֽ⁠nȧʻàráh֙ ʼel-há⁠ʼi֔yş̌ hֽwòʼel-ná֥ʼ wĕ⁠li֖yn wĕ⁠yita֥b libėֽ⁠ká׃"],[19,7,"וַ⁠יָּ֥קָם הָ⁠אִ֖ישׁ לָ⁠לֶ֑כֶת וַ⁠יִּפְצַר־בּ⁠וֹ֙ חֹתְנ֔⁠וֹ וַ⁠יָּ֖שָׁב וַ⁠יָּ֥לֶן שָֽׁם׃","wa⁠yá֥̇qám há⁠ʼi֖yş̌ lá⁠le֑keţ wa⁠yi̇pĕẕar-ḃ⁠wò֙ ẖòţĕn֔⁠wò wa⁠yá֖̇şá̌b wa⁠yá֥̇len şáֽ̌m׃"],[19,8,"וַ⁠יַּשְׁכֵּ֨ם בַּ⁠בֹּ֜קֶר בַּ⁠יּ֣וֹם הַ⁠חֲמִישִׁי֮ לָ⁠לֶכֶת֒ וַ⁠יֹּ֣אמֶר ׀ אֲבִ֣י הַֽ⁠נַּעֲרָ֗ה סְעָד־נָא֙ לְבָ֣בְ⁠ךָ֔ וְ⁠הִֽתְמַהְמְה֖וּ עַד־נְט֣וֹת הַ⁠יּ֑וֹם וַ⁠יֹּאכְל֖וּ שְׁנֵי⁠הֶֽם׃","wa⁠yȧşĕ̌ké̇֨m bȧ⁠bò̇֜qer bȧ⁠ẏ֣wòm ha⁠ẖàmiyşǐy֮ lá⁠lekeţ֒ wa⁠yò֣̇ʼmer ׀ ʼàbi֣y haֽ⁠nȧʻàrá֗h sĕʻád-náʼ֙ lĕbá֣bĕ⁠ká֔ wĕ⁠hiֽţĕmahĕmĕh֖ẇ ʻad-nĕt֣wòţ ha⁠ẏ֑wòm wa⁠yò̇ʼkĕl֖ẇ şĕ̌néy⁠heֽm׃"],[19,9,"וַ⁠יָּ֤קָם הָ⁠אִישׁ֙ לָ⁠לֶ֔כֶת ה֥וּא וּ⁠פִילַגְשׁ֖⁠וֹ וְ⁠נַעֲר֑⁠וֹ וַ⁠יֹּ֣אמֶר ל֣⁠וֹ חֹתְנ֣⁠וֹ אֲבִ֣י הַֽ⁠נַּעֲרָ֡ה הִנֵּ֣ה נָא֩ רָפָ֨ה הַ⁠יּ֜וֹם לַ⁠עֲרֹ֗ב לִֽינוּ־נָ֞א הִנֵּ֨ה חֲנ֤וֹת הַ⁠יּוֹם֙ לִ֥ין פֹּה֙ וְ⁠יִיטַ֣ב לְבָבֶ֔⁠ךָ וְ⁠הִשְׁכַּמְתֶּ֤ם מָחָר֙ לְ⁠דַרְכְּ⁠כֶ֔ם וְ⁠הָלַכְתָּ֖ לְ⁠אֹהָלֶֽ⁠ךָ׃","wa⁠yá֤̇qám há⁠ʼiyş̌֙ lá⁠le֔keţ h֥ẇʼ ẇ⁠piylagĕş֖̌⁠wò wĕ⁠naʻàr֑⁠wò wa⁠yò֣̇ʼmer l֣⁠wò ẖòţĕn֣⁠wò ʼàbi֣y haֽ⁠nȧʻàrá֡h hiné֣̇h náʼ֩ rápá֨h ha⁠ẏ֜wòm la⁠ʻàrò֗b liֽynẇ-ná֞ʼ hiné̇֨h ẖàn֤wòţ ha⁠ẏwòm֙ li֥yn pò̇h֙ wĕ⁠yiyta֣b lĕbábe֔⁠ká wĕ⁠hişĕ̌kȧmĕţė֤m máẖár֙ lĕ⁠darĕkĕ̇⁠ke֔m wĕ⁠hálakĕţá֖̇ lĕ⁠ʼòháleֽ⁠ká׃"],[19,10,"וְ⁠לֹֽא־אָבָ֤ה הָ⁠אִישׁ֙ לָ⁠ל֔וּן וַ⁠יָּ֣קָם וַ⁠יֵּ֗לֶךְ וַ⁠יָּבֹא֙ עַד־נֹ֣כַח יְב֔וּס הִ֖יא יְרוּשָׁלִָ֑ם וְ⁠עִמּ֗⁠וֹ צֶ֤מֶד חֲמוֹרִים֙ חֲבוּשִׁ֔ים וּ⁠פִילַגְשׁ֖⁠וֹ עִמּֽ⁠וֹ׃","wĕ⁠lòֽʼ-ʼábá֤h há⁠ʼiyş̌֙ lá⁠l֔ẇn wa⁠yá֣̇qám wa⁠yé̇֗lekĕ wa⁠yá̇bòʼ֙ ʻad-nò֣kaẖ yĕb֔ẇs hi֖yʼ yĕrẇşá̌liá֑m wĕ⁠ʻiṁ֗⁠wò ẕe֤med ẖàmwòriym֙ ẖàbẇşǐ֔ym ẇ⁠piylagĕş֖̌⁠wò ʻiṁֽ⁠wò׃"],[19,11,"הֵ֣ם עִם־יְב֔וּס וְ⁠הַ⁠יּ֖וֹם רַ֣ד מְאֹ֑ד וַ⁠יֹּ֨אמֶר הַ⁠נַּ֜עַר אֶל־אֲדֹנָ֗י⁠ו לְכָ⁠ה־נָּ֛א וְ⁠נָס֛וּרָה אֶל־עִֽיר־הַ⁠יְבוּסִ֥י הַ⁠זֹּ֖את וְ⁠נָלִ֥ין בָּֽ⁠הּ׃","hé֣m ʻim-yĕb֔ẇs wĕ⁠ha⁠ẏ֖wòm ra֣d mĕʼò֑d wa⁠yò̇֨ʼmer ha⁠nȧ֜ʻar ʼel-ʼàdòná֗y⁠w lĕká⁠h-ná֛̇ʼ wĕ⁠nás֛ẇráh ʼel-ʻiֽyr-ha⁠yĕbẇsi֥y ha⁠zò֖̇ʼţ wĕ⁠náli֥yn báֽ̇⁠ḣ׃"],[19,12,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ אֲדֹנָ֔י⁠ו לֹ֤א נָסוּר֙ אֶל־עִ֣יר נָכְרִ֔י אֲשֶׁ֛ר לֹֽא־מִ⁠בְּנֵ֥י יִשְׂרָאֵ֖ל הֵ֑נָּה וְ⁠עָבַ֖רְנוּ עַד־גִּבְעָֽה׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ ʼàdòná֔y⁠w lò֤ʼ násẇr֙ ʼel-ʻi֣yr nákĕri֔y ʼàşě֛r lòֽʼ-mi⁠bĕ̇né֥y yişĕ̂ráʼé֖l hé֑ná̇h wĕ⁠ʻába֖rĕnẇ ʻad-gi̇bĕʻáֽh׃"],[19,13,"וַ⁠יֹּ֣אמֶר לְ⁠נַעֲר֔⁠וֹ לך וְ⁠נִקְרְבָ֖ה בְּ⁠אַחַ֣ד הַ⁠מְּקֹמ֑וֹת וְ⁠לַ֥נּוּ בַ⁠גִּבְעָ֖ה א֥וֹ בָ⁠רָמָֽה׃","wa⁠yò֣̇ʼmer lĕ⁠naʻàr֔⁠wò lk wĕ⁠niqĕrĕbá֖h bĕ̇⁠ʼaẖa֣d ha⁠mĕ̇qòm֑wòţ wĕ⁠la֥ṅẇ ba⁠gi̇bĕʻá֖h ʼ֥wò bá⁠rámáֽh׃"],[19,14,"וַ⁠יַּעַבְר֖וּ וַ⁠יֵּלֵ֑כוּ וַ⁠תָּבֹ֤א לָ⁠הֶם֙ הַ⁠שֶּׁ֔מֶשׁ אֵ֥צֶל הַ⁠גִּבְעָ֖ה אֲשֶׁ֥ר לְ⁠בִנְיָמִֽן׃","wa⁠yȧʻabĕr֖ẇ wa⁠yé̇lé֑kẇ wa⁠ţá̇bò֤ʼ lá⁠hem֙ ha⁠şė̌֔meş̌ ʼé֥ẕel ha⁠gi̇bĕʻá֖h ʼàşě֥r lĕ⁠binĕyámiֽn׃"],[19,15,"וַ⁠יָּסֻ֣רוּ שָׁ֔ם לָ⁠ב֖וֹא לָ⁠ל֣וּן בַּ⁠גִּבְעָ֑ה וַ⁠יָּבֹ֗א וַ⁠יֵּ֨שֶׁב֙ בִּ⁠רְח֣וֹב הָ⁠עִ֔יר וְ⁠אֵ֥ין אִ֛ישׁ מְאַסֵּֽף־אוֹתָ֥⁠ם הַ⁠בַּ֖יְתָ⁠ה לָ⁠לֽוּן׃","wa⁠yá̇su֣rẇ şá̌֔m lá⁠b֖wòʼ lá⁠l֣ẇn bȧ⁠gi̇bĕʻá֑h wa⁠yá̇bò֗ʼ wa⁠yé̇֨şěb֙ bi̇⁠rĕẖ֣wòb há⁠ʻi֔yr wĕ⁠ʼé֥yn ʼi֛yş̌ mĕʼaséֽ̇p-ʼwòţá֥⁠m ha⁠bȧ֖yĕţá⁠h lá⁠lֽẇn׃"],[19,16,"וְ⁠הִנֵּ֣ה ׀ אִ֣ישׁ זָקֵ֗ן בָּ֣א מִֽן־מַעֲשֵׂ֤⁠הוּ מִן־הַ⁠שָּׂדֶה֙ בָּ⁠עֶ֔רֶב וְ⁠הָ⁠אִישׁ֙ מֵ⁠הַ֣ר אֶפְרַ֔יִם וְ⁠הוּא־גָ֖ר בַּ⁠גִּבְעָ֑ה וְ⁠אַנְשֵׁ֥י הַ⁠מָּק֖וֹם בְּנֵ֥י יְמִינִֽי׃","wĕ⁠hiné֣̇h ׀ ʼi֣yş̌ záqé֗n bá֣̇ʼ miֽn-maʻàşé֤̂⁠hẇ min-ha⁠şá̇̂deh֙ bá̇⁠ʻe֔reb wĕ⁠há⁠ʼiyş̌֙ mé⁠ha֣r ʼepĕra֔yim wĕ⁠hẇʼ-gá֖r bȧ⁠gi̇bĕʻá֑h wĕ⁠ʼanĕşé֥̌y ha⁠má̇q֖wòm bĕ̇né֥y yĕmiyniֽy׃"],[19,17,"וַ⁠יִּשָּׂ֣א עֵינָ֗י⁠ו וַ⁠יַּ֛רְא אֶת־הָ⁠אִ֥ישׁ הָ⁠אֹרֵ֖חַ בִּ⁠רְחֹ֣ב הָ⁠עִ֑יר וַ⁠יֹּ֨אמֶר הָ⁠אִ֧ישׁ הַ⁠זָּקֵ֛ן אָ֥נָה תֵלֵ֖ךְ וּ⁠מֵ⁠אַ֥יִן תָּבֽוֹא׃","wa⁠yi̇şá֣̇̂ʼ ʻéyná֗y⁠w wa⁠yȧ֛rĕʼ ʼeţ-há⁠ʼi֥yş̌ há⁠ʼòré֖ẖa bi̇⁠rĕẖò֣b há⁠ʻi֑yr wa⁠yò̇֨ʼmer há⁠ʼi֧yş̌ ha⁠zá̇qé֛n ʼá֥náh ţélé֖kĕ ẇ⁠mé⁠ʼa֥yin ţá̇bֽwòʼ׃"],[19,18,"וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו עֹבְרִ֨ים אֲנַ֜חְנוּ מִ⁠בֵּֽית־לֶ֣חֶם יְהוּדָה֮ עַד־יַרְכְּתֵ֣י הַר־אֶפְרַיִם֒ מִ⁠שָּׁ֣ם אָנֹ֔כִי וָ⁠אֵלֵ֕ךְ עַד־בֵּ֥ית לֶ֖חֶם יְהוּדָ֑ה וְ⁠אֶת־בֵּ֤ית יְהוָה֙ אֲנִ֣י הֹלֵ֔ךְ וְ⁠אֵ֣ין אִ֔ישׁ מְאַסֵּ֥ף אוֹתִ֖⁠י הַ⁠בָּֽיְתָ⁠ה׃","wa⁠yò֣̇ʼmer ʼélá֗y⁠w ʻòbĕri֨ym ʼàna֜ẖĕnẇ mi⁠béֽ̇yţ-le֣ẖem yĕhẇdáh֮ ʻad-yarĕkĕ̇ţé֣y har-ʼepĕrayim֒ mi⁠şá֣̇̌m ʼánò֔kiy wá⁠ʼélé֕kĕ ʻad-bé֥̇yţ le֖ẖem yĕhẇdá֑h wĕ⁠ʼeţ-bé֤̇yţ yĕhwáh֙ ʼàni֣y hòlé֔kĕ wĕ⁠ʼé֣yn ʼi֔yş̌ mĕʼasé֥̇p ʼwòţi֖⁠y ha⁠báֽ̇yĕţá⁠h׃"],[19,19,"וְ⁠גַם־תֶּ֤בֶן גַּם־מִסְפּוֹא֙ יֵ֣שׁ לַ⁠חֲמוֹרֵ֔י⁠נוּ וְ֠⁠גַם לֶ֣חֶם וָ⁠יַ֤יִן יֶשׁ־לִ⁠י֙ וְ⁠לַֽ⁠אֲמָתֶ֔⁠ךָ וְ⁠לַ⁠נַּ֖עַר עִם־עֲבָדֶ֑י⁠ךָ אֵ֥ין מַחְס֖וֹר כָּל־דָּבָֽר׃","wĕ⁠gam-ţė֤ben gȧm-misĕṗwòʼ֙ yé֣ş̌ la⁠ẖàmwòré֔y⁠nẇ wĕ֠⁠gam le֣ẖem wá⁠ya֤yin yeş̌-li⁠y֙ wĕ⁠laֽ⁠ʼàmáţe֔⁠ká wĕ⁠la⁠nȧ֖ʻar ʻim-ʻàbáde֑y⁠ká ʼé֥yn maẖĕs֖wòr ká̇l-dá̇báֽr׃"],[19,20,"וַ⁠יֹּ֨אמֶר הָ⁠אִ֤ישׁ הַ⁠זָּקֵן֙ שָׁל֣וֹם לָ֔⁠ךְ רַ֥ק כָּל־מַחְסוֹרְ⁠ךָ֖ עָלָ֑⁠י רַ֥ק בָּ⁠רְח֖וֹב אַל־תָּלַֽן׃","wa⁠yò̇֨ʼmer há⁠ʼi֤yş̌ ha⁠zá̇qén֙ şá̌l֣wòm lá֔⁠kĕ ra֥q ká̇l-maẖĕswòrĕ⁠ká֖ ʻálá֑⁠y ra֥q bá̇⁠rĕẖ֖wòb ʼal-ţá̇laֽn׃"],[19,21,"וַ⁠יְבִיאֵ֣⁠הוּ לְ⁠בֵית֔⁠וֹ ויבול לַ⁠חֲמוֹרִ֑ים וַֽ⁠יִּרְחֲצוּ֙ רַגְלֵי⁠הֶ֔ם וַ⁠יֹּאכְל֖וּ וַ⁠יִּשְׁתּֽוּ׃","wa⁠yĕbiyʼé֣⁠hẇ lĕ⁠béyţ֔⁠wò wybwl la⁠ẖàmwòri֑ym waֽ⁠yi̇rĕẖàẕẇ֙ ragĕléy⁠he֔m wa⁠yò̇ʼkĕl֖ẇ wa⁠yi̇şĕ̌ţֽ̇ẇ׃"],[19,22,"הֵמָּה֮ מֵיטִיבִ֣ים אֶת־לִבָּ⁠ם֒ וְ⁠הִנֵּה֩ אַנְשֵׁ֨י הָ⁠עִ֜יר אַנְשֵׁ֣י בְנֵֽי־בְלִיַּ֗עַל נָסַ֨בּוּ֙ אֶת־הַ⁠בַּ֔יִת מִֽתְדַּפְּקִ֖ים עַל־הַ⁠דָּ֑לֶת וַ⁠יֹּאמְר֗וּ אֶל־הָ֠⁠אִישׁ בַּ֣עַל הַ⁠בַּ֤יִת הַ⁠זָּקֵן֙ לֵ⁠אמֹ֔ר הוֹצֵ֗א אֶת־הָ⁠אִ֛ישׁ אֲשֶׁר־בָּ֥א אֶל־בֵּיתְ⁠ךָ֖ וְ⁠נֵדָעֶֽ⁠נּוּ׃","hémá̇h֮ méytiybi֣ym ʼeţ-libá̇⁠m֒ wĕ⁠hiné̇h֩ ʼanĕşé̌֨y há⁠ʻi֜yr ʼanĕşé֣̌y bĕnéֽy-bĕliyȧ֗ʻal nása֨ḃẇ֙ ʼeţ-ha⁠bȧ֔yiţ miֽţĕdȧpĕ̇qi֖ym ʻal-ha⁠dá֑̇leţ wa⁠yò̇ʼmĕr֗ẇ ʼel-há֠⁠ʼiyş̌ bȧ֣ʻal ha⁠bȧ֤yiţ ha⁠zá̇qén֙ lé⁠ʼmò֔r hwòẕé֗ʼ ʼeţ-há⁠ʼi֛yş̌ ʼàşěr-bá֥̇ʼ ʼel-bé̇yţĕ⁠ká֖ wĕ⁠nédáʻeֽ⁠ṅẇ׃"],[19,23,"וַ⁠יֵּצֵ֣א אֲלֵי⁠הֶ֗ם הָ⁠אִישׁ֙ בַּ֣עַל הַ⁠בַּ֔יִת וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם אַל־אַחַ֖⁠י אַל־תָּרֵ֣עוּ נָ֑א אַ֠חֲרֵי אֲשֶׁר־בָּ֞א הָ⁠אִ֤ישׁ הַ⁠זֶּה֙ אַל־בֵּיתִ֔⁠י אַֽל־תַּעֲשׂ֖וּ אֶת־הַ⁠נְּבָלָ֥ה הַ⁠זֹּֽאת׃","wa⁠yé̇ẕé֣ʼ ʼàléy⁠he֗m há⁠ʼiyş̌֙ bȧ֣ʻal ha⁠bȧ֔yiţ wa⁠yò֣̇ʼmer ʼàlé⁠he֔m ʼal-ʼaẖa֖⁠y ʼal-ţá̇ré֣ʻẇ ná֑ʼ ʼa֠ẖàréy ʼàşěr-bá̇֞ʼ há⁠ʼi֤yş̌ ha⁠zėh֙ ʼal-bé̇yţi֔⁠y ʼaֽl-ţȧʻàş֖̂ẇ ʼeţ-ha⁠nĕ̇bálá֥h ha⁠zòֽ̇ʼţ׃"],[19,24,"הִנֵּה֩ בִתִּ֨⁠י הַ⁠בְּתוּלָ֜ה וּ⁠פִֽילַגְשֵׁ֗⁠הוּ אוֹצִֽיאָה־נָּ֤א אוֹתָ⁠ם֙ וְ⁠עַנּ֣וּ אוֹתָ֔⁠ם וַ⁠עֲשׂ֣וּ לָ⁠הֶ֔ם הַ⁠טּ֖וֹב בְּ⁠עֵינֵי⁠כֶ֑ם וְ⁠לָ⁠אִ֤ישׁ הַ⁠זֶּה֙ לֹ֣א תַעֲשׂ֔וּ דְּבַ֖ר הַ⁠נְּבָלָ֥ה הַ⁠זֹּֽאת׃","hiné̇h֩ biţi̇֨⁠y ha⁠bĕ̇ţẇlá֜h ẇ⁠piֽylagĕşé̌֗⁠hẇ ʼwòẕiֽyʼáh-ná֤̇ʼ ʼwòţá⁠m֙ wĕ⁠ʻaṅ֣ẇ ʼwòţá֔⁠m wa⁠ʻàş֣̂ẇ lá⁠he֔m ha⁠ṫ֖wòb bĕ̇⁠ʻéynéy⁠ke֑m wĕ⁠lá⁠ʼi֤yş̌ ha⁠zėh֙ lò֣ʼ ţaʻàş̂֔ẇ dĕ̇ba֖r ha⁠nĕ̇bálá֥h ha⁠zòֽ̇ʼţ׃"],[19,25,"וְ⁠לֹֽא־אָב֤וּ הָ⁠אֲנָשִׁים֙ לִ⁠שְׁמֹ֣עַֽ ל֔⁠וֹ וַ⁠יַּחֲזֵ֤ק הָ⁠אִישׁ֙ בְּ⁠פִ֣ילַגְשׁ֔⁠וֹ וַ⁠יֹּצֵ֥א אֲלֵי⁠הֶ֖ם הַ⁠ח֑וּץ וַ⁠יֵּדְע֣וּ א֠וֹתָ⁠הּ וַ⁠יִּֽתְעַלְּלוּ־בָ֤⁠הּ כָּל־הַ⁠לַּ֨יְלָה֙ עַד־הַ⁠בֹּ֔קֶר וַֽ⁠יְשַׁלְּח֖וּ⁠הָ ב⁠עלות הַ⁠שָּֽׁחַר׃","wĕ⁠lòֽʼ-ʼáb֤ẇ há⁠ʼànáşǐym֙ li⁠şĕ̌mò֣ʻaֽ l֔⁠wò wa⁠yȧẖàzé֤q há⁠ʼiyş̌֙ bĕ̇⁠pi֣ylagĕş̌֔⁠wò wa⁠yò̇ẕé֥ʼ ʼàléy⁠he֖m ha⁠ẖ֑ẇẕ wa⁠yé̇dĕʻ֣ẇ ʼ֠wòţá⁠ḣ wa⁠yiֽ̇ţĕʻalĕ̇lẇ-bá֤⁠ḣ ká̇l-ha⁠lȧ֨yĕláh֙ ʻad-ha⁠bò̇֔qer waֽ⁠yĕşǎlĕ̇ẖ֖ẇ⁠há b⁠ʻlwţ ha⁠şáֽ̇̌ẖar׃"],[19,26,"וַ⁠תָּבֹ֥א הָ⁠אִשָּׁ֖ה לִ⁠פְנ֣וֹת הַ⁠בֹּ֑קֶר וַ⁠תִּפֹּ֞ל פֶּ֧תַח בֵּית־הָ⁠אִ֛ישׁ אֲשֶׁר־אֲדוֹנֶ֥י⁠הָ שָּׁ֖ם עַד־הָ⁠אֽוֹר׃","wa⁠ţá̇bò֥ʼ há⁠ʼişá֖̇̌h li⁠pĕn֣wòţ ha⁠bò֑̇qer wa⁠ţi̇pò̇֞l pė֧ţaẖ bé̇yţ-há⁠ʼi֛yş̌ ʼàşěr-ʼàdwòne֥y⁠há şá֖̇̌m ʻad-há⁠ʼֽwòr׃"],[19,27,"וַ⁠יָּ֨קָם אֲדֹנֶ֜י⁠הָ בַּ⁠בֹּ֗קֶר וַ⁠יִּפְתַּח֙ דַּלְת֣וֹת הַ⁠בַּ֔יִת וַ⁠יֵּצֵ֖א לָ⁠לֶ֣כֶת לְ⁠דַרְכּ֑⁠וֹ וְ⁠הִנֵּ֧ה הָ⁠אִשָּׁ֣ה פִֽילַגְשׁ֗⁠וֹ נֹפֶ֨לֶת֙ פֶּ֣תַח הַ⁠בַּ֔יִת וְ⁠יָדֶ֖י⁠הָ עַל־הַ⁠סַּֽף׃","wa⁠yá̇֨qám ʼàdòne֜y⁠há bȧ⁠bò̇֗qer wa⁠yi̇pĕţȧẖ֙ dȧlĕţ֣wòţ ha⁠bȧ֔yiţ wa⁠yé̇ẕé֖ʼ lá⁠le֣keţ lĕ⁠darĕk֑̇⁠wò wĕ⁠hiné֧̇h há⁠ʼişá֣̇̌h piֽylagĕş̌֗⁠wò nòpe֨leţ֙ pė֣ţaẖ ha⁠bȧ֔yiţ wĕ⁠yáde֖y⁠há ʻal-ha⁠sȧֽp׃"],[19,28,"וַ⁠יֹּ֧אמֶר אֵלֶ֛י⁠הָ ק֥וּמִי וְ⁠נֵלֵ֖כָה וְ⁠אֵ֣ין עֹנֶ֑ה וַ⁠יִּקָּחֶ֨⁠הָ֙ עַֽל־הַ⁠חֲמ֔וֹר וַ⁠יָּ֣קָם הָ⁠אִ֔ישׁ וַ⁠יֵּ֖לֶךְ לִ⁠מְקֹמֽ⁠וֹ׃","wa⁠yò֧̇ʼmer ʼéle֛y⁠há q֥ẇmiy wĕ⁠nélé֖káh wĕ⁠ʼé֣yn ʻòne֑h wa⁠yi̇qá̇ẖe֨⁠há֙ ʻaֽl-ha⁠ẖàm֔wòr wa⁠yá֣̇qám há⁠ʼi֔yş̌ wa⁠yé֖̇lekĕ li⁠mĕqòmֽ⁠wò׃"],[19,29,"וַ⁠יָּבֹ֣א אֶל־בֵּית֗⁠וֹ וַ⁠יִּקַּ֤ח אֶת־הַֽ⁠מַּאֲכֶ֨לֶת֙ וַ⁠יַּחֲזֵ֣ק בְּ⁠פִֽילַגְשׁ֔⁠וֹ וַֽ⁠יְנַתְּחֶ֨⁠הָ֙ לַ⁠עֲצָמֶ֔י⁠הָ לִ⁠שְׁנֵ֥ים עָשָׂ֖ר נְתָחִ֑ים וַֽ⁠יְשַׁלְּחֶ֔⁠הָ בְּ⁠כֹ֖ל גְּב֥וּל יִשְׂרָאֵֽל׃","wa⁠yá̇bò֣ʼ ʼel-bé̇yţ֗⁠wò wa⁠yi̇qȧ֤ẖ ʼeţ-haֽ⁠mȧʼàke֨leţ֙ wa⁠yȧẖàzé֣q bĕ̇⁠piֽylagĕş̌֔⁠wò waֽ⁠yĕnaţĕ̇ẖe֨⁠há֙ la⁠ʻàẕáme֔y⁠há li⁠şĕ̌né֥ym ʻáşá֖̂r nĕţáẖi֑ym waֽ⁠yĕşǎlĕ̇ẖe֔⁠há bĕ̇⁠kò֖l gĕ̇b֥ẇl yişĕ̂ráʼéֽl׃"],[19,30,"וְ⁠הָיָ֣ה כָל־הָ⁠רֹאֶ֗ה וְ⁠אָמַר֙ לֹֽא־נִהְיְתָ֤ה וְ⁠לֹֽא־נִרְאֲתָה֙ כָּ⁠זֹ֔את לְ⁠מִ⁠יּ֞וֹם עֲל֤וֹת בְּנֵֽי־יִשְׂרָאֵל֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה שִֽׂימוּ־לָ⁠כֶ֥ם עָלֶ֖י⁠הָ עֻ֥צוּ וְ⁠דַבֵּֽרוּ׃פ","wĕ⁠háyá֣h kál-há⁠ròʼe֗h wĕ⁠ʼámar֙ lòֽʼ-nihĕyĕţá֤h wĕ⁠lòֽʼ-nirĕʼàţáh֙ ká̇⁠zò֔ʼţ lĕ⁠mi⁠ẏ֞wòm ʻàl֤wòţ bĕ̇néֽy-yişĕ̂ráʼél֙ mé⁠ʼe֣reẕ miẕĕra֔yim ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h şîֽymẇ-lá⁠ke֥m ʻále֖y⁠há ʻu֥ẕẇ wĕ⁠dabéֽ̇rẇ׃p"],[20,1,"וַ⁠יֵּצְאוּ֮ כָּל־בְּנֵ֣י יִשְׂרָאֵל֒ וַ⁠תִּקָּהֵ֨ל הָ⁠עֵדָ֜ה כְּ⁠אִ֣ישׁ אֶחָ֗ד לְ⁠מִ⁠דָּן֙ וְ⁠עַד־בְּאֵ֣ר שֶׁ֔בַע וְ⁠אֶ֖רֶץ הַ⁠גִּלְעָ֑ד אֶל־יְהוָ֖ה הַ⁠מִּצְפָּֽה׃","wa⁠yé̇ẕĕʼẇ֮ ká̇l-bĕ̇né֣y yişĕ̂ráʼél֒ wa⁠ţi̇qá̇hé֨l há⁠ʻédá֜h kĕ̇⁠ʼi֣yş̌ ʼeẖá֗d lĕ⁠mi⁠dá̇n֙ wĕ⁠ʻad-bĕ̇ʼé֣r şě֔baʻ wĕ⁠ʼe֖reẕ ha⁠gi̇lĕʻá֑d ʼel-yĕhwá֖h ha⁠mi̇ẕĕpáֽ̇h׃"],[20,2,"וַ⁠יִּֽתְיַצְּב֞וּ פִּנּ֣וֹת כָּל־הָ⁠עָ֗ם כֹּ֚ל שִׁבְטֵ֣י יִשְׂרָאֵ֔ל בִּ⁠קְהַ֖ל עַ֣ם הָ⁠אֱלֹהִ֑ים אַרְבַּ֨ע מֵא֥וֹת אֶ֛לֶף אִ֥ישׁ רַגְלִ֖י שֹׁ֥לֵֽף חָֽרֶב׃פ","wa⁠yiֽ̇ţĕyaẕĕ̇b֞ẇ pi̇ṅ֣wòţ ká̇l-há⁠ʻá֗m kò֚̇l şǐbĕté֣y yişĕ̂ráʼé֔l bi̇⁠qĕha֖l ʻa֣m há⁠ʼèlòhi֑ym ʼarĕbȧ֨ʻ méʼ֥wòţ ʼe֛lep ʼi֥yş̌ ragĕli֖y şò֥̌léֽp ẖáֽreb׃p"],[20,3,"וַֽ⁠יִּשְׁמְעוּ֙ בְּנֵ֣י בִנְיָמִ֔ן כִּֽי־עָל֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל הַ⁠מִּצְפָּ֑ה וַ⁠יֹּֽאמְרוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל דַּבְּר֕וּ אֵיכָ֥ה נִהְיְתָ֖ה הָ⁠רָעָ֥ה הַ⁠זֹּֽאת׃","waֽ⁠yi̇şĕ̌mĕʻẇ֙ bĕ̇né֣y binĕyámi֔n kiֽ̇y-ʻál֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l ha⁠mi̇ẕĕpá֑̇h wa⁠yòֽ̇ʼmĕrẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l dȧbĕ̇r֕ẇ ʼéyká֥h nihĕyĕţá֖h há⁠ráʻá֥h ha⁠zòֽ̇ʼţ׃"],[20,4,"וַ⁠יַּ֜עַן הָ⁠אִ֣ישׁ הַ⁠לֵּוִ֗י אִ֛ישׁ הָ⁠אִשָּׁ֥ה הַ⁠נִּרְצָחָ֖ה וַ⁠יֹּאמַ֑ר הַ⁠גִּבְעָ֨תָ⁠ה֙ אֲשֶׁ֣ר לְ⁠בִנְיָמִ֔ן בָּ֛אתִי אֲנִ֥י וּ⁠פִֽילַגְשִׁ֖⁠י לָ⁠לֽוּן׃","wa⁠yȧ֜ʻan há⁠ʼi֣yş̌ ha⁠lé̇wi֗y ʼi֛yş̌ há⁠ʼişá֥̇̌h ha⁠ni̇rĕẕáẖá֖h wa⁠yò̇ʼma֑r ha⁠gi̇bĕʻá֨ţá⁠h֙ ʼàşě֣r lĕ⁠binĕyámi֔n bá֛̇ʼţiy ʼàni֥y ẇ⁠piֽylagĕşǐ֖⁠y lá⁠lֽẇn׃"],[20,5,"וַ⁠יָּקֻ֤מוּ עָלַ⁠י֙ בַּעֲלֵ֣י הַ⁠גִּבְעָ֔ה וַ⁠יָּסֹ֧בּוּ עָלַ֛⁠י אֶת־הַ⁠בַּ֖יִת לָ֑יְלָה אוֹתִ⁠י֙ דִּמּ֣וּ לַ⁠הֲרֹ֔ג וְ⁠אֶת־פִּילַגְשִׁ֥⁠י עִנּ֖וּ וַ⁠תָּמֹֽת׃","wa⁠yá̇qu֤mẇ ʻála⁠y֙ bȧʻàlé֣y ha⁠gi̇bĕʻá֔h wa⁠yá̇sò֧ḃẇ ʻála֛⁠y ʼeţ-ha⁠bȧ֖yiţ lá֑yĕláh ʼwòţi⁠y֙ di̇ṁ֣ẇ la⁠hàrò֔g wĕ⁠ʼeţ-pi̇ylagĕşǐ֥⁠y ʻiṅ֖ẇ wa⁠ţá̇mòֽţ׃"],[20,6,"וָֽ⁠אֹחֵ֤ז בְּ⁠פִֽילַגְשִׁ⁠י֙ וָֽ⁠אֲנַתְּחֶ֔⁠הָ וָֽ⁠אֲשַׁלְּחֶ֔⁠הָ בְּ⁠כָל־שְׂדֵ֖ה נַחֲלַ֣ת יִשְׂרָאֵ֑ל כִּ֥י עָשׂ֛וּ זִמָּ֥ה וּ⁠נְבָלָ֖ה בְּ⁠יִשְׂרָאֵֽל׃","wáֽ⁠ʼòẖé֤z bĕ̇⁠piֽylagĕşǐ⁠y֙ wáֽ⁠ʼànaţĕ̇ẖe֔⁠há wֽá⁠ʼàşǎlĕ̇ẖe֔⁠há bĕ̇⁠kál-şĕ̂dé֖h naẖàla֣ţ yişĕ̂ráʼé֑l ki֥̇y ʻáş֛̂ẇ zimá֥̇h ẇ⁠nĕbálá֖h bĕ̇⁠yişĕ̂ráʼéֽl׃"],[20,7,"הִנֵּ֥ה כֻלְּ⁠כֶ֖ם בְּנֵ֣י יִשְׂרָאֵ֑ל הָב֥וּ לָ⁠כֶ֛ם דָּבָ֥ר וְ⁠עֵצָ֖ה הֲלֹֽם׃","hiné֥̇h kulĕ̇⁠ke֖m bĕ̇né֣y yişĕ̂ráʼé֑l háb֥ẇ lá⁠ke֛m dá̇bá֥r wĕ⁠ʻéẕá֖h hàlòֽm׃"],[20,8,"וַ⁠יָּ֨קָם֙ כָּל־הָ⁠עָ֔ם כְּ⁠אִ֥ישׁ אֶחָ֖ד לֵ⁠אמֹ֑ר לֹ֤א נֵלֵךְ֙ אִ֣ישׁ לְ⁠אָהֳל֔⁠וֹ וְ⁠לֹ֥א נָס֖וּר אִ֥ישׁ לְ⁠בֵיתֽ⁠וֹ׃","wa⁠yá̇֨qám֙ ká̇l-há⁠ʻá֔m kĕ̇⁠ʼi֥yş̌ ʼeẖá֖d lé⁠ʼmò֑r lò֤ʼ nélékĕ֙ ʼi֣yş̌ lĕ⁠ʼáhol֔⁠wò wĕ⁠lò֥ʼ nás֖ẇr ʼi֥yş̌ lĕ⁠béyţֽ⁠wò׃"],[20,9,"וְ⁠עַתָּ֕ה זֶ֣ה הַ⁠דָּבָ֔ר אֲשֶׁ֥ר נַעֲשֶׂ֖ה לַ⁠גִּבְעָ֑ה עָלֶ֖י⁠הָ בְּ⁠גוֹרָֽל׃","wĕ⁠ʻaţá̇֕h ze֣h ha⁠dá̇bá֔r ʼàşě֥r naʻàşê֖h la⁠gi̇bĕʻá֑h ʻále֖y⁠há bĕ̇⁠gwòráֽl׃"],[20,10,"וְ⁠לָקַ֣חְנוּ עֲשָׂרָה֩ אֲנָשִׁ֨ים לַ⁠מֵּאָ֜ה לְ⁠כֹ֣ל ׀ שִׁבְטֵ֣י יִשְׂרָאֵ֗ל וּ⁠מֵאָ֤ה לָ⁠אֶ֨לֶף֙ וְ⁠אֶ֣לֶף לָ⁠רְבָבָ֔ה לָ⁠קַ֥חַת צֵדָ֖ה לָ⁠עָ֑ם לַ⁠עֲשׂ֗וֹת לְ⁠בוֹאָ⁠ם֙ לְ⁠גֶ֣בַע בִּנְיָמִ֔ן כְּ⁠כָל־הַ֨⁠נְּבָלָ֔ה אֲשֶׁ֥ר עָשָׂ֖ה בְּ⁠יִשְׂרָאֵֽל׃","wĕ⁠láqa֣ẖĕnẇ ʻàşá̂ráh֩ ʼànáşǐ֨ym la⁠mé̇ʼá֜h lĕ⁠kò֣l ׀ şǐbĕté֣y yişĕ̂ráʼé֗l ẇ⁠méʼá֤h lá⁠ʼe֨lep֙ wĕ⁠ʼe֣lep lá⁠rĕbábá֔h lá⁠qa֥ẖaţ ẕédá֖h lá⁠ʻá֑m la⁠ʻàş̂֗wòţ lĕ⁠bwòʼá⁠m֙ lĕ⁠ge֣baʻ bi̇nĕyámi֔n kĕ̇⁠kál-ha֨⁠nĕ̇bálá֔h ʼàşě֥r ʻáşá֖̂h bĕ̇⁠yişĕ̂ráʼéֽl׃"],[20,11,"וַ⁠יֵּֽאָסֵ֞ף כָּל־אִ֤ישׁ יִשְׂרָאֵל֙ אֶל־הָ⁠עִ֔יר כְּ⁠אִ֥ישׁ אֶחָ֖ד חֲבֵרִֽים׃פ","wa⁠yéֽ̇ʼásé֞p ká̇l-ʼi֤yş̌ yişĕ̂ráʼél֙ ʼel-há⁠ʻi֔yr kĕ̇⁠ʼi֥yş̌ ʼeẖá֖d ẖàbériֽym׃p"],[20,12,"וַֽ⁠יִּשְׁלְח֞וּ שִׁבְטֵ֤י יִשְׂרָאֵל֙ אֲנָשִׁ֔ים בְּ⁠כָל־שִׁבְטֵ֥י בִנְיָמִ֖ן לֵ⁠אמֹ֑ר מָ֚ה הָ⁠רָעָ֣ה הַ⁠זֹּ֔את אֲשֶׁ֥ר נִהְיְתָ֖ה בָּ⁠כֶֽם׃","waֽ⁠yi̇şĕ̌lĕẖ֞ẇ şǐbĕté֤y yişĕ̂ráʼél֙ ʼànáşǐ֔ym bĕ̇⁠kál-şǐbĕté֥y binĕyámi֖n lé⁠ʼmò֑r má֚h há⁠ráʻá֣h ha⁠zò̇֔ʼţ ʼàşě֥r nihĕyĕţá֖h bá̇⁠keֽm׃"],[20,13,"וְ⁠עַתָּ֡ה תְּנוּ֩ אֶת־הָ⁠אֲנָשִׁ֨ים בְּנֵֽי־בְלִיַּ֜עַל אֲשֶׁ֤ר בַּ⁠גִּבְעָה֙ וּ⁠נְמִיתֵ֔⁠ם וּ⁠נְבַעֲרָ֥ה רָעָ֖ה מִ⁠יִּשְׂרָאֵ֑ל וְ⁠לֹ֤א אָבוּ֙ בִּנְיָמִ֔ן לִ⁠שְׁמֹ֕עַ בְּ⁠ק֖וֹל אֲחֵי⁠הֶ֥ם בְּנֵֽי־יִשְׂרָאֵֽל׃","wĕ⁠ʻaţá̇֡h ţĕ̇nẇ֩ ʼeţ-há⁠ʼànáşǐ֨ym bĕ̇néֽy-bĕliyȧ֜ʻal ʼàşě֤r bȧ⁠gi̇bĕʻáh֙ ẇ⁠nĕmiyţé֔⁠m ẇ⁠nĕbaʻàrá֥h ráʻá֖h mi⁠yi̇şĕ̂ráʼé֑l wĕ⁠lò֤ʼ ʼábẇ֙ bi̇nĕyámi֔n li⁠şĕ̌mò֕ʻa bĕ̇⁠q֖wòl ʼàẖéy⁠he֥m bĕ̇néֽy-yişĕ̂ráʼéֽl׃"],[20,14,"וַ⁠יֵּאָסְפ֧וּ בְנֵֽי־בִנְיָמִ֛ן מִן־הֶ⁠עָרִ֖ים הַ⁠גִּבְעָ֑תָ⁠ה לָ⁠צֵ֥את לַ⁠מִּלְחָמָ֖ה עִם־בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yé̇ʼásĕp֧ẇ bĕnéֽy-binĕyámi֛n min-he⁠ʻári֖ym ha⁠gi̇bĕʻá֑ţá⁠h lá⁠ẕé֥ʼţ la⁠mi̇lĕẖámá֖h ʻim-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[20,15,"וַ⁠יִּתְפָּֽקְדוּ֩ בְנֵ֨י בִנְיָמִ֜ן בַּ⁠יּ֤וֹם הַ⁠הוּא֙ מֵ⁠הֶ֣⁠עָרִ֔ים עֶשְׂרִ֨ים וְ⁠שִׁשָּׁ֥ה אֶ֛לֶף אִ֖ישׁ שֹׁ֣לֵֽף חָ֑רֶב לְ֠⁠בַד מִ⁠יֹּשְׁבֵ֤י הַ⁠גִּבְעָה֙ הִתְפָּ֣קְד֔וּ שְׁבַ֥ע מֵא֖וֹת אִ֥ישׁ בָּחֽוּר׃","wa⁠yi̇ţĕpáֽ̇qĕdẇ֩ bĕné֨y binĕyámi֜n bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ mé⁠he֣⁠ʻári֔ym ʻeşĕ̂ri֨ym wĕ⁠şǐşá֥̇̌h ʼe֛lep ʼi֖yş̌ şò֣̌léֽp ẖá֑reb lĕ֠⁠bad mi⁠yò̇şĕ̌bé֤y ha⁠gi̇bĕʻáh֙ hiţĕpá֣̇qĕd֔ẇ şĕ̌ba֥ʻ méʼ֖wòţ ʼi֥yş̌ bá̇ẖֽẇr׃"],[20,16,"מִ⁠כֹּ֣ל ׀ הָ⁠עָ֣ם הַ⁠זֶּ֗ה שְׁבַ֤ע מֵאוֹת֙ אִ֣ישׁ בָּח֔וּר אִטֵּ֖ר יַד־יְמִינ֑⁠וֹ כָּל־זֶ֗ה קֹלֵ֧עַ בָּ⁠אֶ֛בֶן אֶל־הַֽ⁠שַּׂעֲרָ֖ה וְ⁠לֹ֥א יַחֲטִֽא׃פ","mi⁠kò֣̇l ׀ há⁠ʻá֣m ha⁠zė֗h şĕ̌ba֤ʻ méʼwòţ֙ ʼi֣yş̌ bá̇ẖ֔ẇr ʼité֖̇r yad-yĕmiyn֑⁠wò ká̇l-ze֗h qòlé֧ʻa bá̇⁠ʼe֛ben ʼel-haֽ⁠şȧ̂ʻàrá֖h wĕ⁠lò֥ʼ yaẖàtiֽʼ׃p"],[20,17,"וְ⁠אִ֨ישׁ יִשְׂרָאֵ֜ל הִתְפָּֽקְד֗וּ לְ⁠בַד֙ מִ⁠בִּנְיָמִ֔ן אַרְבַּ֨ע מֵא֥וֹת אֶ֛לֶף אִ֖ישׁ שֹׁ֣לֵֽף חָ֑רֶב כָּל־זֶ֖ה אִ֥ישׁ מִלְחָמָֽה׃","wĕ⁠ʼi֨yş̌ yişĕ̂ráʼé֜l hiţĕpáֽ̇qĕd֗ẇ lĕ⁠bad֙ mi⁠bi̇nĕyámi֔n ʼarĕbȧ֨ʻ méʼ֥wòţ ʼe֛lep ʼi֖yş̌ şò֣̌léֽp ẖá֑reb ká̇l-ze֖h ʼi֥yş̌ milĕẖámáֽh׃"],[20,18,"וַ⁠יָּקֻ֜מוּ וַ⁠יַּעֲל֣וּ בֵֽית־אֵל֮ וַ⁠יִּשְׁאֲל֣וּ בֵ⁠אלֹהִים֒ וַ⁠יֹּֽאמְרוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל מִ֚י יַעֲלֶה־לָּ֣⁠נוּ בַ⁠תְּחִלָּ֔ה לַ⁠מִּלְחָמָ֖ה עִם־בְּנֵ֣י בִנְיָמִ֑ן וַ⁠יֹּ֥אמֶר יְהוָ֖ה יְהוּדָ֥ה בַ⁠תְּחִלָּֽה׃","wa⁠yá̇qu֜mẇ wa⁠yȧʻàl֣ẇ béֽyţ-ʼél֮ wa⁠yi̇şĕ̌ʼàl֣ẇ bé⁠ʼlòhiym֒ wa⁠yòֽ̇ʼmĕrẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l mi֚y yaʻàleh-lá֣̇⁠nẇ ba⁠ţĕ̇ẖilá̇֔h la⁠mi̇lĕẖámá֖h ʻim-bĕ̇né֣y binĕyámi֑n wa⁠yò֥̇ʼmer yĕhwá֖h yĕhẇdá֥h ba⁠ţĕ̇ẖiláֽ̇h׃"],[20,19,"וַ⁠יָּק֥וּמוּ בְנֵֽי־יִשְׂרָאֵ֖ל בַּ⁠בֹּ֑קֶר וַ⁠יַּֽחֲנ֖וּ עַל־הַ⁠גִּבְעָֽה׃פ","wa⁠yá̇q֥ẇmẇ bĕnéֽy-yişĕ̂ráʼé֖l bȧ⁠bò֑̇qer wa⁠ẏֽaẖàn֖ẇ ʻal-ha⁠gi̇bĕʻáֽh׃p"],[20,20,"וַ⁠יֵּצֵא֙ אִ֣ישׁ יִשְׂרָאֵ֔ל לַ⁠מִּלְחָמָ֖ה עִם־בִּנְיָמִ֑ן וַ⁠יַּעַרְכ֨וּ אִתָּ֧⁠ם אִֽישׁ־יִשְׂרָאֵ֛ל מִלְחָמָ֖ה אֶל־הַ⁠גִּבְעָֽה׃","wa⁠yé̇ẕéʼ֙ ʼi֣yş̌ yişĕ̂ráʼé֔l la⁠mi̇lĕẖámá֖h ʻim-bi̇nĕyámi֑n wa⁠yȧʻarĕk֨ẇ ʼiţá֧̇⁠m ʼiֽyş̌-yişĕ̂ráʼé֛l milĕẖámá֖h ʼel-ha⁠gi̇bĕʻáֽh׃"],[20,21,"וַ⁠יֵּצְא֥וּ בְנֵֽי־בִנְיָמִ֖ן מִן־הַ⁠גִּבְעָ֑ה וַ⁠יַּשְׁחִ֨יתוּ בְ⁠יִשְׂרָאֵ֜ל בַּ⁠יּ֣וֹם הַ⁠ה֗וּא שְׁנַ֨יִם וְ⁠עֶשְׂרִ֥ים אֶ֛לֶף אִ֖ישׁ אָֽרְצָ⁠ה׃","wa⁠yé̇ẕĕʼ֥ẇ bĕnéֽy-binĕyámi֖n min-ha⁠gi̇bĕʻá֑h wa⁠yȧşĕ̌ẖi֨yţẇ bĕ⁠yişĕ̂ráʼé֜l bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ şĕ̌na֨yim wĕ⁠ʻeşĕ̂ri֥ym ʼe֛lep ʼi֖yş̌ ʼáֽrĕẕá⁠h׃"],[20,22,"וַ⁠יִּתְחַזֵּ֥ק הָ⁠עָ֖ם אִ֣ישׁ יִשְׂרָאֵ֑ל וַ⁠יֹּסִ֨פוּ֙ לַ⁠עֲרֹ֣ךְ מִלְחָמָ֔ה בַּ⁠מָּק֕וֹם אֲשֶׁר־עָ֥רְכוּ שָׁ֖ם בַּ⁠יּ֥וֹם הָ⁠רִאשֽׁוֹן׃","wa⁠yi̇ţĕẖazé֥̇q há⁠ʻá֖m ʼi֣yş̌ yişĕ̂ráʼé֑l wa⁠yò̇si֨pẇ֙ la⁠ʻàrò֣kĕ milĕẖámá֔h bȧ⁠má̇q֕wòm ʼàşěr-ʻá֥rĕkẇ şá֖̌m bȧ⁠ẏ֥wòm há⁠riʼşֽ̌wòn׃"],[20,23,"וַ⁠יַּעֲל֣וּ בְנֵֽי־יִשְׂרָאֵ֗ל וַ⁠יִּבְכּ֣וּ לִ⁠פְנֵֽי־יְהוָה֮ עַד־הָ⁠עֶרֶב֒ וַ⁠יִּשְׁאֲל֤וּ בַֽ⁠יהוָה֙ לֵ⁠אמֹ֔ר הַ⁠אוֹסִ֗יף לָ⁠גֶ֨שֶׁת֙ לַ⁠מִּלְחָמָ֔ה עִם־בְּנֵ֥י בִנְיָמִ֖ן אָחִ֑⁠י וַ⁠יֹּ֥אמֶר יְהוָ֖ה עֲל֥וּ אֵלָֽי⁠ו׃פ","wa⁠yȧʻàl֣ẇ bĕnéֽy-yişĕ̂ráʼé֗l wa⁠yi̇bĕk֣̇ẇ li⁠pĕnéֽy-yĕhwáh֮ ʻad-há⁠ʻereb֒ wa⁠yi̇şĕ̌ʼàl֤ẇ baֽ⁠yhwáh֙ lé⁠ʼmò֔r ha⁠ʼwòsi֗yp lá⁠ge֨şěţ֙ la⁠mi̇lĕẖámá֔h ʻim-bĕ̇né֥y binĕyámi֖n ʼáẖi֑⁠y wa⁠yò֥̇ʼmer yĕhwá֖h ʻàl֥ẇ ʼéláֽy⁠w׃p"],[20,24,"וַ⁠יִּקְרְב֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל אֶל־בְּנֵ֥י בִנְיָמִ֖ן בַּ⁠יּ֥וֹם הַ⁠שֵּׁנִֽי׃","wa⁠yi̇qĕrĕb֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l ʼel-bĕ̇né֥y binĕyámi֖n bȧ⁠ẏ֥wòm ha⁠şé̇̌niֽy׃"],[20,25,"וַ⁠יֵּצֵא֩ בִנְיָמִ֨ן ׀ לִ⁠קְרָאתָ֥⁠ם ׀ מִֽן־הַ⁠גִּבְעָה֮ בַּ⁠יּ֣וֹם הַ⁠שֵּׁנִי֒ וַ⁠יַּשְׁחִיתוּ֩ בִ⁠בְנֵ֨י יִשְׂרָאֵ֜ל ע֗וֹד שְׁמֹנַ֨ת עָשָׂ֥ר אֶ֛לֶף אִ֖ישׁ אָ֑רְצָ⁠ה כָּל־אֵ֖לֶּה שֹׁ֥לְפֵי חָֽרֶב׃","wa⁠yé̇ẕéʼ֩ binĕyámi֨n ׀ li⁠qĕráʼţá֥⁠m ׀ miֽn-ha⁠gi̇bĕʻáh֮ bȧ⁠ẏ֣wòm ha⁠şé̇̌niy֒ wa⁠yȧşĕ̌ẖiyţẇ֩ bi⁠bĕné֨y yişĕ̂ráʼé֜l ʻ֗wòd şĕ̌mòna֨ţ ʻáşá֥̂r ʼe֛lep ʼi֖yş̌ ʼá֑rĕẕá⁠h ká̇l-ʼé֖lėh şò֥̌lĕpéy ẖáֽreb׃"],[20,26,"וַ⁠יַּעֲל֣וּ כָל־בְּנֵי֩ יִשְׂרָאֵ֨ל וְ⁠כָל־הָ⁠עָ֜ם וַ⁠יָּבֹ֣אוּ בֵֽית־אֵ֗ל וַ⁠יִּבְכּוּ֙ וַ⁠יֵּ֤שְׁבוּ שָׁם֙ לִ⁠פְנֵ֣י יְהוָ֔ה וַ⁠יָּצ֥וּמוּ בַ⁠יּוֹם־הַ⁠ה֖וּא עַד־הָ⁠עָ֑רֶב וַֽ⁠יַּעֲל֛וּ עֹל֥וֹת וּ⁠שְׁלָמִ֖ים לִ⁠פְנֵ֥י יְהוָֽה׃","wa⁠yȧʻàl֣ẇ kál-bĕ̇néy֩ yişĕ̂ráʼé֨l wĕ⁠kál-há⁠ʻá֜m wa⁠yá̇bò֣ʼẇ béֽyţ-ʼé֗l wa⁠yi̇bĕk̇ẇ֙ wa⁠yé֤̇şĕ̌bẇ şá̌m֙ li⁠pĕné֣y yĕhwá֔h wa⁠yá̇ẕ֥ẇmẇ ba⁠ẏwòm-ha⁠h֖ẇʼ ʻad-há⁠ʻá֑reb waֽ⁠yȧʻàl֛ẇ ʻòl֥wòţ ẇ⁠şĕ̌lámi֖ym li⁠pĕné֥y yĕhwáֽh׃"],[20,27,"וַ⁠יִּשְׁאֲל֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל בַּֽ⁠יהוָ֑ה וְ⁠שָׁ֗ם אֲרוֹן֙ בְּרִ֣ית הָ⁠אֱלֹהִ֔ים בַּ⁠יָּמִ֖ים הָ⁠הֵֽם׃","wa⁠yi̇şĕ̌ʼàl֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l bȧֽ⁠yhwá֑h wĕ⁠şá̌֗m ʼàrwòn֙ bĕ̇ri֣yţ há⁠ʼèlòhi֔ym bȧ⁠yá̇mi֖ym há⁠héֽm׃"],[20,28,"וּ֠⁠פִינְחָס בֶּן־אֶלְעָזָ֨ר בֶּֽן־אַהֲרֹ֜ן עֹמֵ֣ד ׀ לְ⁠פָנָ֗י⁠ו בַּ⁠יָּמִ֣ים הָ⁠הֵם֮ לֵ⁠אמֹר֒ הַ⁠אוֹסִ֨ף ע֜וֹד לָ⁠צֵ֧את לַ⁠מִּלְחָמָ֛ה עִם־בְּנֵֽי־בִנְיָמִ֥ן אָחִ֖⁠י אִם־אֶחְדָּ֑ל וַ⁠יֹּ֤אמֶר יְהוָה֙ עֲל֔וּ כִּ֥י מָחָ֖ר אֶתְּנֶ֥⁠נּוּ בְ⁠יָדֶֽ⁠ךָ׃","ẇ֠⁠piynĕẖás bėn-ʼelĕʻázá֨r bėֽn-ʼahàrò֜n ʻòmé֣d ׀ lĕ⁠páná֗y⁠w bȧ⁠yá̇mi֣ym há⁠hém֮ lé⁠ʼmòr֒ ha⁠ʼwòsi֨p ʻ֜wòd lá⁠ẕé֧ʼţ la⁠mi̇lĕẖámá֛h ʻim-bĕ̇néֽy-binĕyámi֥n ʼáẖi֖⁠y ʼim-ʼeẖĕdá֑̇l wa⁠yò֤̇ʼmer yĕhwáh֙ ʻàl֔ẇ ki֥̇y máẖá֖r ʼeţĕ̇ne֥⁠ṅẇ bĕ⁠yádeֽ⁠ká׃"],[20,29,"וַ⁠יָּ֤שֶׂם יִשְׂרָאֵל֙ אֹֽרְבִ֔ים אֶל־הַ⁠גִּבְעָ֖ה סָבִֽיב׃פ","wa⁠yá֤̇şêm yişĕ̂ráʼél֙ ʼòֽrĕbi֔ym ʼel-ha⁠gi̇bĕʻá֖h sábiֽyb׃p"],[20,30,"וַ⁠יַּעֲל֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל אֶל־בְּנֵ֥י בִנְיָמִ֖ן בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֑י וַ⁠יַּעַרְכ֥וּ אֶל־הַ⁠גִּבְעָ֖ה כְּ⁠פַ֥עַם בְּ⁠פָֽעַם׃","wa⁠yȧʻàl֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l ʼel-bĕ̇né֥y binĕyámi֖n bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֑y wa⁠yȧʻarĕk֥ẇ ʼel-ha⁠gi̇bĕʻá֖h kĕ̇⁠pa֥ʻam bĕ̇⁠páֽʻam׃"],[20,31,"וַ⁠יֵּצְא֤וּ בְנֵֽי־בִנְיָמִן֙ לִ⁠קְרַ֣את הָ⁠עָ֔ם הָנְתְּק֖וּ מִן־הָ⁠עִ֑יר וַ⁠יָּחֵ֡לּוּ לְ⁠הַכּוֹת֩ מֵ⁠הָ⁠עָ֨ם חֲלָלִ֜ים כְּ⁠פַ֣עַם ׀ בְּ⁠פַ֗עַם בַּֽ⁠מְסִלּוֹת֙ אֲשֶׁ֨ר אַחַ֜ת עֹלָ֣ה בֵֽית־אֵ֗ל וְ⁠אַחַ֤ת גִּבְעָ֨תָ⁠ה֙ בַּ⁠שָּׂדֶ֔ה כִּ⁠שְׁלֹשִׁ֥ים אִ֖ישׁ בְּ⁠יִשְׂרָאֵֽל׃","wa⁠yé̇ẕĕʼ֤ẇ bĕnéֽy-binĕyámin֙ li⁠qĕra֣ʼţ há⁠ʻá֔m hánĕţĕ̇q֖ẇ min-há⁠ʻi֑yr wa⁠yá̇ẖé֡l̇ẇ lĕ⁠hak̇wòţ֩ mé⁠há⁠ʻá֨m ẖàláli֜ym kĕ̇⁠pa֣ʻam ׀ bĕ̇⁠pa֗ʻam bȧֽ⁠mĕsil̇wòţ֙ ʼàşě֨r ʼaẖa֜ţ ʻòlá֣h béֽyţ-ʼé֗l wĕ⁠ʼaẖa֤ţ gi̇bĕʻá֨ţá⁠h֙ bȧ⁠şá̇̂de֔h ki̇⁠şĕ̌lòşǐ֥ym ʼi֖yş̌ bĕ̇⁠yişĕ̂ráʼéֽl׃"],[20,32,"וַ⁠יֹּֽאמְרוּ֙ בְּנֵ֣י בִנְיָמִ֔ן נִגָּפִ֥ים הֵ֛ם לְ⁠פָנֵ֖י⁠נוּ כְּ⁠בָ⁠רִאשֹׁנָ֑ה וּ⁠בְנֵ֧י יִשְׂרָאֵ֣ל אָמְר֗וּ נָנ֨וּסָה֙ וּֽ⁠נְתַקְּנֻ֔⁠הוּ מִן־הָ⁠עִ֖יר אֶל־הַֽ⁠מְסִלּֽוֹת׃","wa⁠yòֽ̇ʼmĕrẇ֙ bĕ̇né֣y binĕyámi֔n nigá̇pi֥ym hé֛m lĕ⁠páné֖y⁠nẇ kĕ̇⁠bá⁠riʼşò̌ná֑h ẇ⁠bĕné֧y yişĕ̂ráʼé֣l ʼámĕr֗ẇ nán֨ẇsáh֙ ẇֽ⁠nĕţaqĕ̇nu֔⁠hẇ min-há⁠ʻi֖yr ʼel-haֽ⁠mĕsilֽ̇wòţ׃"],[20,33,"וְ⁠כֹ֣ל ׀ אִ֣ישׁ יִשְׂרָאֵ֗ל קָ֚מוּ מִ⁠מְּקוֹמ֔⁠וֹ וַ⁠יַּעַרְכ֖וּ בְּ⁠בַ֣עַל תָּמָ֑ר וְ⁠אֹרֵ֧ב יִשְׂרָאֵ֛ל מֵגִ֥יחַ מִ⁠מְּקֹמ֖⁠וֹ מִ⁠מַּֽעֲרֵה־גָֽבַע׃","wĕ⁠kò֣l ׀ ʼi֣yş̌ yişĕ̂ráʼé֗l qá֚mẇ mi⁠mĕ̇qwòm֔⁠wò wa⁠yȧʻarĕk֖ẇ bĕ̇⁠ba֣ʻal ţá̇má֑r wĕ⁠ʼòré֧b yişĕ̂ráʼé֛l mégi֥yẖa mi⁠mĕ̇qòm֖⁠wò mi⁠mȧֽʻàréh-gáֽbaʻ׃"],[20,34,"וַ⁠יָּבֹאוּ֩ מִ⁠נֶּ֨גֶד לַ⁠גִּבְעָ֜ה עֲשֶׂרֶת֩ אֲלָפִ֨ים אִ֤ישׁ בָּחוּר֙ מִ⁠כָּל־יִשְׂרָאֵ֔ל וְ⁠הַ⁠מִּלְחָמָ֖ה כָּבֵ֑דָה וְ⁠הֵם֙ לֹ֣א יָדְע֔וּ כִּֽי־נֹגַ֥עַת עֲלֵי⁠הֶ֖ם הָ⁠רָעָֽה׃פ","wa⁠yá̇bòʼẇ֩ mi⁠nė֨ged la⁠gi̇bĕʻá֜h ʻàşêreţ֩ ʼàlápi֨ym ʼi֤yş̌ bá̇ẖẇr֙ mi⁠ká̇l-yişĕ̂ráʼé֔l wĕ⁠ha⁠mi̇lĕẖámá֖h ká̇bé֑dáh wĕ⁠hém֙ lò֣ʼ yádĕʻ֔ẇ kiֽ̇y-nòga֥ʻaţ ʻàléy⁠he֖m há⁠ráʻáֽh׃p"],[20,35,"וַ⁠יִּגֹּ֨ף יְהוָ֥ה ׀ אֶֽת־בִּנְיָמִן֮ לִ⁠פְנֵ֣י יִשְׂרָאֵל֒ וַ⁠יַּשְׁחִיתוּ֩ בְנֵ֨י יִשְׂרָאֵ֤ל בְּ⁠בִנְיָמִן֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא עֶשְׂרִ֨ים וַ⁠חֲמִשָּׁ֥ה אֶ֛לֶף וּ⁠מֵאָ֖ה אִ֑ישׁ כָּל־אֵ֖לֶּה שֹׁ֥לֵף חָֽרֶב׃","wa⁠yi̇gò̇֨p yĕhwá֥h ׀ ʼeֽţ-bi̇nĕyámin֮ li⁠pĕné֣y yişĕ̂ráʼél֒ wa⁠yȧşĕ̌ẖiyţẇ֩ bĕné֨y yişĕ̂ráʼé֤l bĕ̇⁠binĕyámin֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ʻeşĕ̂ri֨ym wa⁠ẖàmişá֥̇̌h ʼe֛lep ẇ⁠méʼá֖h ʼi֑yş̌ ká̇l-ʼé֖lėh şò֥̌lép ẖáֽreb׃"],[20,36,"וַ⁠יִּרְא֥וּ בְנֵֽי־בִנְיָמִ֖ן כִּ֣י נִגָּ֑פוּ וַ⁠יִּתְּנ֨וּ אִֽישׁ־יִשְׂרָאֵ֤ל מָקוֹם֙ לְ⁠בִנְיָמִ֔ן כִּ֤י בָֽטְחוּ֙ אֶל־הָ֣⁠אֹרֵ֔ב אֲשֶׁר שָׂ֖מוּ אֶל־הַ⁠גִּבְעָֽה׃","wa⁠yi̇rĕʼ֥ẇ bĕnéֽy-binĕyámi֖n ki֣̇y nigá֑̇pẇ wa⁠yi̇ţĕ̇n֨ẇ ʼiֽyş̌-yişĕ̂ráʼé֤l máqwòm֙ lĕ⁠binĕyámi֔n ki֤̇y báֽtĕẖẇ֙ ʼel-há֣⁠ʼòré֔b ʼàşěr şá֖̂mẇ ʼel-ha⁠gi̇bĕʻáֽh׃"],[20,37,"וְ⁠הָ⁠אֹרֵ֣ב הֵחִ֔ישׁוּ וַֽ⁠יִּפְשְׁט֖וּ אֶל־הַ⁠גִּבְעָ֑ה וַ⁠יִּמְשֹׁךְ֙ הָ⁠אֹרֵ֔ב וַ⁠יַּ֥ךְ אֶת־כָּל־הָ⁠עִ֖יר לְ⁠פִי־חָֽרֶב׃","wĕ⁠há⁠ʼòré֣b héẖi֔yş̌ẇ waֽ⁠yi̇pĕşĕ̌t֖ẇ ʼel-ha⁠gi̇bĕʻá֑h wa⁠yi̇mĕşò̌kĕ֙ há⁠ʼòré֔b wa⁠yȧ֥kĕ ʼeţ-ká̇l-há⁠ʻi֖yr lĕ⁠piy-ẖáֽreb׃"],[20,38,"וְ⁠הַ⁠מּוֹעֵ֗ד הָיָ֛ה לְ⁠אִ֥ישׁ יִשְׂרָאֵ֖ל עִם־הָ⁠אֹרֵ֑ב הֶ֕רֶב לְ⁠הַעֲלוֹתָ֛⁠ם מַשְׂאַ֥ת הֶ⁠עָשָׁ֖ן מִן־הָ⁠עִֽיר׃","wĕ⁠ha⁠ṁwòʻé֗d háyá֛h lĕ⁠ʼi֥yş̌ yişĕ̂ráʼé֖l ʻim-há⁠ʼòré֑b he֕reb lĕ⁠haʻàlwòţá֛⁠m maşĕ̂ʼa֥ţ he⁠ʻáşá֖̌n min-há⁠ʻiֽyr׃"],[20,39,"וַ⁠יַּהֲפֹ֥ךְ אִֽישׁ־יִשְׂרָאֵ֖ל בַּ⁠מִּלְחָמָ֑ה וּ⁠בִנְיָמִ֡ן הֵחֵל֩ לְ⁠הַכּ֨וֹת חֲלָלִ֤ים בְּ⁠אִֽישׁ־יִשְׂרָאֵל֙ כִּ⁠שְׁלֹשִׁ֣ים אִ֔ישׁ כִּ֣י אָמְר֔וּ אַךְ֩ נִגּ֨וֹף נִגָּ֥ף הוּא֙ לְ⁠פָנֵ֔י⁠נוּ כַּ⁠מִּלְחָמָ֖ה הָ⁠רִאשֹׁנָֽה׃","wa⁠yȧhàpò֥kĕ ʼiֽyş̌-yişĕ̂ráʼé֖l bȧ⁠mi̇lĕẖámá֑h ẇ⁠binĕyámi֡n héẖél֩ lĕ⁠hak̇֨wòţ ẖàláli֤ym bĕ̇⁠ʼiֽyş̌-yişĕ̂ráʼél֙ ki̇⁠şĕ̌lòşǐ֣ym ʼi֔yş̌ ki֣̇y ʼámĕr֔ẇ ʼakĕ֩ niġ֨wòp nigá֥̇p hẇʼ֙ lĕ⁠páné֔y⁠nẇ kȧ⁠mi̇lĕẖámá֖h há⁠riʼşò̌náֽh׃"],[20,40,"וְ⁠הַ⁠מַּשְׂאֵ֗ת הֵחֵ֛לָּה לַ⁠עֲל֥וֹת מִן־הָ⁠עִ֖יר עַמּ֣וּד עָשָׁ֑ן וַ⁠יִּ֤פֶן בִּנְיָמִן֙ אַחֲרָ֔י⁠ו וְ⁠הִנֵּ֛ה עָלָ֥ה כְלִיל־הָ⁠עִ֖יר הַ⁠שָּׁמָֽיְמָ⁠ה׃","wĕ⁠ha⁠mȧşĕ̂ʼé֗ţ héẖé֛lá̇h la⁠ʻàl֥wòţ min-há⁠ʻi֖yr ʻaṁ֣ẇd ʻáşá֑̌n wa⁠yi֤̇pen bi̇nĕyámin֙ ʼaẖàrá֔y⁠w wĕ⁠hiné֛̇h ʻálá֥h kĕliyl-há⁠ʻi֖yr ha⁠şá̇̌máֽyĕmá⁠h׃"],[20,41,"וְ⁠אִ֤ישׁ יִשְׂרָאֵל֙ הָפַ֔ךְ וַ⁠יִּבָּהֵ֖ל אִ֣ישׁ בִּנְיָמִ֑ן כִּ֣י רָאָ֔ה כִּֽי־נָגְעָ֥ה עָלָ֖י⁠ו הָ⁠רָעָֽה׃","wĕ⁠ʼi֤yş̌ yişĕ̂ráʼél֙ hápa֔kĕ wa⁠yi̇bá̇hé֖l ʼi֣yş̌ bi̇nĕyámi֑n ki֣̇y ráʼá֔h kiֽ̇y-nágĕʻá֥h ʻálá֖y⁠w há⁠ráʻáֽh׃"],[20,42,"וַ⁠יִּפְנ֞וּ לִ⁠פְנֵ֨י אִ֤ישׁ יִשְׂרָאֵל֙ אֶל־דֶּ֣רֶךְ הַ⁠מִּדְבָּ֔ר וְ⁠הַ⁠מִּלְחָמָ֖ה הִדְבִּיקָ֑תְ⁠הוּ וַ⁠אֲשֶׁר֙ מֵ⁠הֶ֣⁠עָרִ֔ים מַשְׁחִיתִ֥ים אוֹת֖⁠וֹ בְּ⁠תוֹכֽ⁠וֹ׃","wa⁠yi̇pĕn֞ẇ li⁠pĕné֨y ʼi֤yş̌ yişĕ̂ráʼél֙ ʼel-dė֣rekĕ ha⁠mi̇dĕbá̇֔r wĕ⁠ha⁠mi̇lĕẖámá֖h hidĕbi̇yqá֑ţĕ⁠hẇ wa⁠ʼàşěr֙ mé⁠he֣⁠ʻári֔ym maşĕ̌ẖiyţi֥ym ʼwòţ֖⁠wò bĕ̇⁠ţwòkֽ⁠wò׃"],[20,43,"כִּתְּר֤וּ אֶת־בִּנְיָמִן֙ הִרְדִיפֻ֔⁠הוּ מְנוּחָ֖ה הִדְרִיכֻ֑⁠הוּ עַ֛ד נֹ֥כַח הַ⁠גִּבְעָ֖ה מִ⁠מִּזְרַח־שָֽׁמֶשׁ׃","ki̇ţĕ̇r֤ẇ ʼeţ-bi̇nĕyámin֙ hirĕdiypu֔⁠hẇ mĕnẇẖá֖h hidĕriyku֑⁠hẇ ʻa֛d nò֥kaẖ ha⁠gi̇bĕʻá֖h mi⁠mi̇zĕraẖ-şáֽ̌meş̌׃"],[20,44,"וַֽ⁠יִּפְּלוּ֙ מִ⁠בִּנְיָמִ֔ן שְׁמֹנָֽה־עָשָׂ֥ר אֶ֖לֶף אִ֑ישׁ אֶת־כָּל־אֵ֖לֶּה אַנְשֵׁי־חָֽיִל׃","waֽ⁠yi̇pĕ̇lẇ֙ mi⁠bi̇nĕyámi֔n şĕ̌mònáֽh-ʻáşá֥̂r ʼe֖lep ʼi֑yş̌ ʼeţ-ká̇l-ʼé֖lėh ʼanĕşé̌y-ẖáֽyil׃"],[20,45,"וַ⁠יִּפְנ֞וּ וַ⁠יָּנֻ֤סוּ הַ⁠מִּדְבָּ֨רָ⁠ה֙ אֶל־סֶ֣לַע הָֽ⁠רִמּ֔וֹן וַ⁠יְעֹֽלְלֻ֨⁠הוּ֙ בַּֽ⁠מְסִלּ֔וֹת חֲמֵ֥שֶׁת אֲלָפִ֖ים אִ֑ישׁ וַ⁠יַּדְבִּ֤יקוּ אַחֲרָי⁠ו֙ עַד־גִּדְעֹ֔ם וַ⁠יַּכּ֥וּ מִמֶּ֖⁠נּוּ אַלְפַּ֥יִם אִֽישׁ׃","wa⁠yi̇pĕn֞ẇ wa⁠yá̇nu֤sẇ ha⁠mi̇dĕbá̇֨rá⁠h֙ ʼel-se֣laʻ háֽ⁠riṁ֔wòn wa⁠yĕʻòֽlĕlu֨⁠hẇ֙ bȧֽ⁠mĕsil̇֔wòţ ẖàmé֥şěţ ʼàlápi֖ym ʼi֑yş̌ wa⁠yȧdĕbi֤̇yqẇ ʼaẖàráy⁠w֙ ʻad-gi̇dĕʻò֔m wa⁠yȧk֥̇ẇ mimė֖⁠ṅẇ ʼalĕpȧ֥yim ʼiֽyş̌׃"],[20,46,"וַ⁠יְהִי֩ כָל־הַ⁠נֹּ֨פְלִ֜ים מִ⁠בִּנְיָמִ֗ן עֶשְׂרִים֩ וַ⁠חֲמִשָּׁ֨ה אֶ֥לֶף אִ֛ישׁ שֹׁ֥לֵֽף חֶ֖רֶב בַּ⁠יּ֣וֹם הַ⁠ה֑וּא אֶֽת־כָּל־אֵ֖לֶּה אַנְשֵׁי־חָֽיִל׃","wa⁠yĕhiy֩ kál-ha⁠nò̇֨pĕli֜ym mi⁠bi̇nĕyámi֗n ʻeşĕ̂riym֩ wa⁠ẖàmişá̇̌֨h ʼe֥lep ʼi֛yş̌ şò֥̌léֽp ẖe֖reb bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ ʼeֽţ-ká̇l-ʼé֖lėh ʼanĕşé̌y-ẖáֽyil׃"],[20,47,"וַ⁠יִּפְנ֞וּ וַ⁠יָּנֻ֤סוּ הַ⁠מִּדְבָּ֨רָ⁠ה֙ אֶל־סֶ֣לַע הָֽ⁠רִמּ֔וֹן שֵׁ֥שׁ מֵא֖וֹת אִ֑ישׁ וַ⁠יֵּֽשְׁבוּ֙ בְּ⁠סֶ֣לַע רִמּ֔וֹן אַרְבָּעָ֖ה חֳדָשִֽׁים׃","wa⁠yi̇pĕn֞ẇ wa⁠yá̇nu֤sẇ ha⁠mi̇dĕbá̇֨rá⁠h֙ ʼel-se֣laʻ háֽ⁠riṁ֔wòn şé֥̌ş̌ méʼ֖wòţ ʼi֑yş̌ wa⁠yéֽ̇şĕ̌bẇ֙ bĕ̇⁠se֣laʻ riṁ֔wòn ʼarĕbá̇ʻá֖h ẖodáşǐֽym׃"],[20,48,"וְ⁠אִ֨ישׁ יִשְׂרָאֵ֜ל שָׁ֣בוּ אֶל־בְּנֵ֤י בִנְיָמִן֙ וַ⁠יַּכּ֣וּ⁠ם לְ⁠פִי־חֶ֔רֶב מֵ⁠עִ֤יר מְתֹם֙ עַד־בְּהֵמָ֔ה עַ֖ד כָּל־הַ⁠נִּמְצָ֑א גַּ֛ם כָּל־הֶ⁠עָרִ֥ים הַ⁠נִּמְצָא֖וֹת שִׁלְּח֥וּ בָ⁠אֵֽשׁ׃פ","wĕ⁠ʼi֨yş̌ yişĕ̂ráʼé֜l şá֣̌bẇ ʼel-bĕ̇né֤y binĕyámin֙ wa⁠yȧk֣̇ẇ⁠m lĕ⁠piy-ẖe֔reb mé⁠ʻi֤yr mĕţòm֙ ʻad-bĕ̇hémá֔h ʻa֖d ká̇l-ha⁠ni̇mĕẕá֑ʼ gȧ֛m ká̇l-he⁠ʻári֥ym ha⁠ni̇mĕẕáʼ֖wòţ şǐlĕ̇ẖ֥ẇ bá⁠ʼéֽş̌׃p"],[21,1,"וְ⁠אִ֣ישׁ יִשְׂרָאֵ֔ל נִשְׁבַּ֥ע בַּ⁠מִּצְפָּ֖ה לֵ⁠אמֹ֑ר אִ֣ישׁ מִמֶּ֔⁠נּוּ לֹא־יִתֵּ֥ן בִּתּ֛⁠וֹ לְ⁠בִנְיָמִ֖ן לְ⁠אִשָּֽׁה׃","wĕ⁠ʼi֣yş̌ yişĕ̂ráʼé֔l nişĕ̌bȧ֥ʻ bȧ⁠mi̇ẕĕpá֖̇h lé⁠ʼmò֑r ʼi֣yş̌ mimė֔⁠ṅẇ lòʼ-yiţé֥̇n bi̇ţ֛̇⁠wò lĕ⁠binĕyámi֖n lĕ⁠ʼişáֽ̇̌h׃"],[21,2,"וַ⁠יָּבֹ֤א הָ⁠עָם֙ בֵּֽית־אֵ֔ל וַ⁠יֵּ֤שְׁבוּ שָׁם֙ עַד־הָ⁠עֶ֔רֶב לִ⁠פְנֵ֖י הָ⁠אֱלֹהִ֑ים וַ⁠יִּשְׂא֣וּ קוֹלָ֔⁠ם וַ⁠יִּבְכּ֖וּ בְּכִ֥י גָדֽוֹל׃","wa⁠yá̇bò֤ʼ há⁠ʻám֙ béֽ̇yţ-ʼé֔l wa⁠yé֤̇şĕ̌bẇ şá̌m֙ ʻad-há⁠ʻe֔reb li⁠pĕné֖y há⁠ʼèlòhi֑ym wa⁠yi̇şĕ̂ʼ֣ẇ qwòlá֔⁠m wa⁠yi̇bĕk֖̇ẇ bĕ̇ki֥y gádֽwòl׃"],[21,3,"וַ⁠יֹּ֣אמְר֔וּ לָ⁠מָ֗ה יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הָ֥יְתָה זֹּ֖את בְּ⁠יִשְׂרָאֵ֑ל לְ⁠הִפָּקֵ֥ד הַ⁠יּ֛וֹם מִ⁠יִּשְׂרָאֵ֖ל שֵׁ֥בֶט אֶחָֽד׃","wa⁠yò֣̇ʼmĕr֔ẇ lá⁠má֗h yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l há֥yĕţáh zò֖̇ʼţ bĕ̇⁠yişĕ̂ráʼé֑l lĕ⁠hipá̇qé֥d ha⁠ẏ֛wòm mi⁠yi̇şĕ̂ráʼé֖l şé֥̌bet ʼeẖáֽd׃"],[21,4,"וַֽ⁠יְהִי֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יַּשְׁכִּ֣ימוּ הָ⁠עָ֔ם וַ⁠יִּבְנוּ־שָׁ֖ם מִזְבֵּ֑חַ וַ⁠יַּעֲל֥וּ עֹל֖וֹת וּ⁠שְׁלָמִֽים׃פ","waֽ⁠yĕhiy֙ miֽ⁠má̇ẖorá֔ţ wa⁠yȧşĕ̌ki֣̇ymẇ há⁠ʻá֔m wa⁠yi̇bĕnẇ-şá֖̌m mizĕbé֑̇ẖa wa⁠yȧʻàl֥ẇ ʻòl֖wòţ ẇ⁠şĕ̌lámiֽym׃p"],[21,5,"וַ⁠יֹּֽאמְרוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל מִ֠י אֲשֶׁ֨ר לֹא־עָלָ֧ה בַ⁠קָּהָ֛ל מִ⁠כָּל־שִׁבְטֵ֥י יִשְׂרָאֵ֖ל אֶל־יְהוָ֑ה כִּי֩ הַ⁠שְּׁבוּעָ֨ה הַ⁠גְּדוֹלָ֜ה הָיְתָ֗ה לַ֠⁠אֲשֶׁר לֹא־עָלָ֨ה אֶל־יְהוָ֧ה הַ⁠מִּצְפָּ֛ה לֵ⁠אמֹ֖ר מ֥וֹת יוּמָֽת׃","wa⁠yòֽ̇ʼmĕrẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l mi֠y ʼàşě֨r lòʼ-ʻálá֧h ba⁠qá̇há֛l mi⁠ká̇l-şǐbĕté֥y yişĕ̂ráʼé֖l ʼel-yĕhwá֑h ki̇y֩ ha⁠şĕ̇̌bẇʻá֨h ha⁠gĕ̇dwòlá֜h háyĕţá֗h la֠⁠ʼàşěr lòʼ-ʻálá֨h ʼel-yĕhwá֧h ha⁠mi̇ẕĕpá֛̇h lé⁠ʼmò֖r m֥wòţ yẇmáֽţ׃"],[21,6,"וַ⁠יִּנָּֽחֲמוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֶל־בִּנְיָמִ֖ן אָחִ֑י⁠ו וַ⁠יֹּ֣אמְר֔וּ נִגְדַּ֥ע הַ⁠יּ֛וֹם שֵׁ֥בֶט אֶחָ֖ד מִ⁠יִּשְׂרָאֵֽל׃","wa⁠yi̇náֽ̇ẖàmẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼel-bi̇nĕyámi֖n ʼáẖi֑y⁠w wa⁠yò֣̇ʼmĕr֔ẇ nigĕdȧ֥ʻ ha⁠ẏ֛wòm şé֥̌bet ʼeẖá֖d mi⁠yi̇şĕ̂ráʼéֽl׃"],[21,7,"מַה־נַּעֲשֶׂ֥ה לָ⁠הֶ֛ם לַ⁠נּוֹתָרִ֖ים לְ⁠נָשִׁ֑ים וַ⁠אֲנַ֨חְנוּ֙ נִשְׁבַּ֣עְנוּ בַֽ⁠יהוָ֔ה לְ⁠בִלְתִּ֛י תֵּת־לָ⁠הֶ֥ם מִ⁠בְּנוֹתֵ֖י⁠נוּ לְ⁠נָשִֽׁים׃","mah-nȧʻàşê֥h lá⁠he֛m la⁠ṅwòţári֖ym lĕ⁠náşǐ֑ym wa⁠ʼàna֨ẖĕnẇ֙ nişĕ̌bȧ֣ʻĕnẇ baֽ⁠yhwá֔h lĕ⁠bilĕţi֛̇y ţé̇ţ-lá⁠he֥m mi⁠bĕ̇nwòţé֖y⁠nẇ lĕ⁠náşǐֽym׃"],[21,8,"וַ⁠יֹּ֣אמְר֔וּ מִ֗י אֶחָד֙ מִ⁠שִּׁבְטֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֛ר לֹֽא־עָלָ֥ה אֶל־יְהוָ֖ה הַ⁠מִּצְפָּ֑ה וְ֠⁠הִנֵּה לֹ֣א בָא־אִ֧ישׁ אֶל־הַֽ⁠מַּחֲנֶ֛ה מִ⁠יָּבֵ֥ישׁ גִּלְעָ֖ד אֶל־הַ⁠קָּהָֽל׃","wa⁠yò֣̇ʼmĕr֔ẇ mi֗y ʼeẖád֙ mi⁠şi̇̌bĕté֣y yişĕ̂ráʼé֔l ʼàşě֛r lòֽʼ-ʻálá֥h ʼel-yĕhwá֖h ha⁠mi̇ẕĕpá֑̇h wĕ֠⁠hiné̇h lò֣ʼ báʼ-ʼi֧yş̌ ʼel-haֽ⁠mȧẖàne֛h mi⁠yá̇bé֥yş̌ gi̇lĕʻá֖d ʼel-ha⁠qá̇háֽl׃"],[21,9,"וַ⁠יִּתְפָּקֵ֖ד הָ⁠עָ֑ם וְ⁠הִנֵּ֤ה אֵֽין־שָׁם֙ אִ֔ישׁ מִ⁠יּוֹשְׁבֵ֖י יָבֵ֥שׁ גִּלְעָֽד׃","wa⁠yi̇ţĕpá̇qé֖d há⁠ʻá֑m wĕ⁠hiné֤̇h ʼéֽyn-şá̌m֙ ʼi֔yş̌ mi⁠ẏwòşĕ̌bé֖y yábé֥ş̌ gi̇lĕʻáֽd׃"],[21,10,"וַ⁠יִּשְׁלְחוּ־שָׁ֣ם הָ⁠עֵדָ֗ה שְׁנֵים־עָשָׂ֥ר אֶ֛לֶף אִ֖ישׁ מִ⁠בְּנֵ֣י הֶ⁠חָ֑יִל וַ⁠יְצַוּ֨וּ אוֹתָ֜⁠ם לֵ⁠אמֹ֗ר לְ֠כוּ וְ⁠הִכִּיתֶ֞ם אֶת־יוֹשְׁבֵ֨י יָבֵ֤שׁ גִּלְעָד֙ לְ⁠פִי־חֶ֔רֶב וְ⁠הַ⁠נָּשִׁ֖ים וְ⁠הַ⁠טָּֽף׃","wa⁠yi̇şĕ̌lĕẖẇ-şá֣̌m há⁠ʻédá֗h şĕ̌néym-ʻáşá֥̂r ʼe֛lep ʼi֖yş̌ mi⁠bĕ̇né֣y he⁠ẖá֑yil wa⁠yĕẕaẇ֨ẇ ʼwòţá֜⁠m lé⁠ʼmò֗r lĕ֠kẇ wĕ⁠hiki̇yţe֞m ʼeţ-ywòşĕ̌bé֨y yábé֤ş̌ gi̇lĕʻád֙ lĕ⁠piy-ẖe֔reb wĕ⁠ha⁠ná̇şǐ֖ym wĕ⁠ha⁠táֽ̇p׃"],[21,11,"וְ⁠זֶ֥ה הַ⁠דָּבָ֖ר אֲשֶׁ֣ר תַּעֲשׂ֑וּ כָּל־זָכָ֗ר וְ⁠כָל־אִשָּׁ֛ה יֹדַ֥עַת מִשְׁכַּב־זָכָ֖ר תַּחֲרִֽימוּ׃","wĕ⁠ze֥h ha⁠dá̇bá֖r ʼàşě֣r ţȧʻàş֑̂ẇ ká̇l-záká֗r wĕ⁠kál-ʼişá֛̇̌h yòda֥ʻaţ mişĕ̌kȧb-záká֖r ţȧẖàriֽymẇ׃"],[21,12,"וַֽ⁠יִּמְצְא֞וּ מִ⁠יּוֹשְׁבֵ֣י ׀ יָבֵ֣ישׁ גִּלְעָ֗ד אַרְבַּ֤ע מֵאוֹת֙ נַעֲרָ֣ה בְתוּלָ֔ה אֲשֶׁ֧ר לֹֽא־יָדְעָ֛ה אִ֖ישׁ לְ⁠מִשְׁכַּ֣ב זָכָ֑ר וַ⁠יָּבִ֨יאוּ אוֹתָ֤⁠ם אֶל־הַֽ⁠מַּחֲנֶה֙ שִׁלֹ֔ה אֲשֶׁ֖ר בְּ⁠אֶ֥רֶץ כְּנָֽעַן׃ס","waֽ⁠yi̇mĕẕĕʼ֞ẇ mi⁠ẏwòşĕ̌bé֣y ׀ yábé֣yş̌ gi̇lĕʻá֗d ʼarĕbȧ֤ʻ méʼwòţ֙ naʻàrá֣h bĕţẇlá֔h ʼàşě֧r lòֽʼ-yádĕʻá֛h ʼi֖yş̌ lĕ⁠mişĕ̌kȧ֣b záká֑r wa⁠yá̇bi֨yʼẇ ʼwòţá֤⁠m ʼel-haֽ⁠mȧẖàneh֙ şǐlò֔h ʼàşě֖r bĕ̇⁠ʼe֥reẕ kĕ̇náֽʻan׃s"],[21,13,"וַֽ⁠יִּשְׁלְחוּ֙ כָּל־הָ֣⁠עֵדָ֔ה וַֽ⁠יְדַבְּרוּ֙ אֶל־בְּנֵ֣י בִנְיָמִ֔ן אֲשֶׁ֖ר בְּ⁠סֶ֣לַע רִמּ֑וֹן וַ⁠יִּקְרְא֥וּ לָ⁠הֶ֖ם שָׁלֽוֹם׃","waֽ⁠yi̇şĕ̌lĕẖẇ֙ ká̇l-há֣⁠ʻédá֔h waֽ⁠yĕdabĕ̇rẇ֙ ʼel-bĕ̇né֣y binĕyámi֔n ʼàşě֖r bĕ̇⁠se֣laʻ riṁ֑wòn wa⁠yi̇qĕrĕʼ֥ẇ lá⁠he֖m şá̌lֽwòm׃"],[21,14,"וַ⁠יָּ֤שָׁב בִּנְיָמִן֙ בָּ⁠עֵ֣ת הַ⁠הִ֔יא וַ⁠יִּתְּנ֤וּ לָ⁠הֶם֙ הַ⁠נָּשִׁ֔ים אֲשֶׁ֣ר חִיּ֔וּ מִ⁠נְּשֵׁ֖י יָבֵ֣שׁ גִּלְעָ֑ד וְ⁠לֹֽא־מָצְא֥וּ לָ⁠הֶ֖ם כֵּֽן׃","wa⁠yá֤̇şá̌b bi̇nĕyámin֙ bá̇⁠ʻé֣ţ ha⁠hi֔yʼ wa⁠yi̇ţĕ̇n֤ẇ lá⁠hem֙ ha⁠ná̇şǐ֔ym ʼàşě֣r ẖiẏ֔ẇ mi⁠nĕ̇şé֖̌y yábé֣ş̌ gi̇lĕʻá֑d wĕ⁠lòֽʼ-máẕĕʼ֥ẇ lá⁠he֖m kéֽ̇n׃"],[21,15,"וְ⁠הָ⁠עָ֥ם נִחָ֖ם לְ⁠בִנְיָמִ֑ן כִּֽי־עָשָׂ֧ה יְהוָ֛ה פֶּ֖רֶץ בְּ⁠שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠há⁠ʻá֥m niẖá֖m lĕ⁠binĕyámi֑n kiֽ̇y-ʻáşá֧̂h yĕhwá֛h pė֖reẕ bĕ̇⁠şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[21,16,"וַ⁠יֹּֽאמְר֨וּ זִקְנֵ֣י הָ⁠עֵדָ֔ה מַה־נַּעֲשֶׂ֥ה לַ⁠נּוֹתָרִ֖ים לְ⁠נָשִׁ֑ים כִּֽי־נִשְׁמְדָ֥ה מִ⁠בִּנְיָמִ֖ן אִשָּֽׁה׃","wa⁠yòֽ̇ʼmĕr֨ẇ ziqĕné֣y há⁠ʻédá֔h mah-nȧʻàşê֥h la⁠ṅwòţári֖ym lĕ⁠náşǐ֑ym kiֽ̇y-nişĕ̌mĕdá֥h mi⁠bi̇nĕyámi֖n ʼişáֽ̇̌h׃"],[21,17,"וַ⁠יֹּ֣אמְר֔וּ יְרֻשַּׁ֥ת פְּלֵיטָ֖ה לְ⁠בִנְיָמִ֑ן וְ⁠לֹֽא־יִמָּחֶ֥ה שֵׁ֖בֶט מִ⁠יִּשְׂרָאֵֽל׃","wa⁠yò֣̇ʼmĕr֔ẇ yĕruşȧ֥̌ţ pĕ̇léytá֖h lĕ⁠binĕyámi֑n wĕ⁠lòֽʼ-yimá̇ẖe֥h şé֖̌bet mi⁠yi̇şĕ̂ráʼéֽl׃"],[21,18,"וַ⁠אֲנַ֗חְנוּ לֹ֥א נוּכַ֛ל לָ⁠תֵת־לָ⁠הֶ֥ם נָשִׁ֖ים מִ⁠בְּנוֹתֵ֑י⁠נוּ כִּֽי־נִשְׁבְּע֤וּ בְנֵֽי־יִשְׂרָאֵל֙ לֵ⁠אמֹ֔ר אָר֕וּר נֹתֵ֥ן אִשָּׁ֖ה לְ⁠בִנְיָמִֽן׃ס","wa⁠ʼàna֗ẖĕnẇ lò֥ʼ nẇka֛l lá⁠ţéţ-lá⁠he֥m náşǐ֖ym mi⁠bĕ̇nwòţé֑y⁠nẇ kiֽ̇y-nişĕ̌bĕ̇ʻ֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ lé⁠ʼmò֔r ʼár֕ẇr nòţé֥n ʼişá֖̇̌h lĕ⁠binĕyámiֽn׃s"],[21,19,"וַ⁠יֹּאמְר֡וּ הִנֵּה֩ חַג־יְהוָ֨ה בְּ⁠שִׁל֜וֹ מִ⁠יָּמִ֣ים ׀ יָמִ֗ימָ⁠ה אֲשֶׁ֞ר מִ⁠צְּפ֤וֹנָ⁠ה לְ⁠בֵֽית־אֵל֙ מִזְרְחָ֣⁠ה הַ⁠שֶּׁ֔מֶשׁ לִ⁠מְסִלָּ֔ה הָ⁠עֹלָ֥ה מִ⁠בֵּֽית־אֵ֖ל שְׁכֶ֑מָ⁠ה וּ⁠מִ⁠נֶּ֖גֶב לִ⁠לְבוֹנָֽה׃","wa⁠yò̇ʼmĕr֡ẇ hiné̇h֩ ẖag-yĕhwá֨h bĕ̇⁠şǐl֜wò mi⁠yá̇mi֣ym ׀ yámi֗ymá⁠h ʼàşě֞r mi⁠ẕĕ̇p֤wòná⁠h lĕ⁠béֽyţ-ʼél֙ mizĕrĕẖá֣⁠h ha⁠şė̌֔meş̌ li⁠mĕsilá̇֔h há⁠ʻòlá֥h mi⁠béֽ̇yţ-ʼé֖l şĕ̌ke֑má⁠h ẇ⁠mi⁠nė֖geb li⁠lĕbwònáֽh׃"],[21,20,"ו⁠יצו אֶת־בְּנֵ֥י בִנְיָמִ֖ן לֵ⁠אמֹ֑ר לְכ֖וּ וַ⁠אֲרַבְתֶּ֥ם בַּ⁠כְּרָמִֽים׃","w⁠yẕw ʼeţ-bĕ̇né֥y binĕyámi֖n lé⁠ʼmò֑r lĕk֖ẇ wa⁠ʼàrabĕţė֥m bȧ⁠kĕ̇rámiֽym׃"],[21,21,"וּ⁠רְאִיתֶ֗ם וְ֠⁠הִנֵּה אִם־יֵ֨צְא֥וּ בְנוֹת־שִׁילוֹ֮ לָ⁠ח֣וּל בַּ⁠מְּחֹלוֹת֒ וִֽ⁠יצָאתֶם֙ מִן־הַ⁠כְּרָמִ֔ים וַ⁠חֲטַפְתֶּ֥ם לָ⁠כֶ֛ם אִ֥ישׁ אִשְׁתּ֖⁠וֹ מִ⁠בְּנ֣וֹת שִׁיל֑וֹ וַ⁠הֲלַכְתֶּ֖ם אֶ֥רֶץ בִּנְיָמִֽן׃","ẇ⁠rĕʼiyţe֗m wĕ֠⁠hiné̇h ʼim-yé֨ẕĕʼ֥ẇ bĕnwòţ-şǐylwò֮ lá⁠ẖ֣ẇl bȧ⁠mĕ̇ẖòlwòţ֒ wiֽ⁠yẕáʼţem֙ min-ha⁠kĕ̇rámi֔ym wa⁠ẖàtapĕţė֥m lá⁠ke֛m ʼi֥yş̌ ʼişĕ̌ţ֖̇⁠wò mi⁠bĕ̇n֣wòţ şǐyl֑wò wa⁠hàlakĕţė֖m ʼe֥reẕ bi̇nĕyámiֽn׃"],[21,22,"וְ⁠הָיָ֡ה כִּֽי־יָבֹ֣אוּ אֲבוֹתָ⁠ם֩ א֨וֹ אֲחֵי⁠הֶ֜ם לרוב ׀ אֵלֵ֗י⁠נוּ וְ⁠אָמַ֤רְנוּ אֲלֵי⁠הֶם֙ חָנּ֣וּ⁠נוּ אוֹתָ֔⁠ם כִּ֣י לֹ֥א לָקַ֛חְנוּ אִ֥ישׁ אִשְׁתּ֖⁠וֹ בַּ⁠מִּלְחָמָ֑ה כִּ֣י לֹ֥א אַתֶּ֛ם נְתַתֶּ֥ם לָ⁠הֶ֖ם כָּ⁠עֵ֥ת תֶּאְשָֽׁמוּ׃ס","wĕ⁠háyá֡h kiֽ̇y-yábò֣ʼẇ ʼàbwòţá⁠m֩ ʼ֨wò ʼàẖéy⁠he֜m lrwb ׀ ʼélé֗y⁠nẇ wĕ⁠ʼáma֤rĕnẇ ʼàléy⁠hem֙ ẖáṅ֣ẇ⁠nẇ ʼwòţá֔⁠m ki֣̇y lò֥ʼ láqa֛ẖĕnẇ ʼi֥yş̌ ʼişĕ̌ţ֖̇⁠wò bȧ⁠mi̇lĕẖámá֑h ki֣̇y lò֥ʼ ʼaţė֛m nĕţaţė֥m lá⁠he֖m ká̇⁠ʻé֥ţ ţėʼĕşáֽ̌mẇ׃s"],[21,23,"וַ⁠יַּֽעֲשׂוּ־כֵן֙ בְּנֵ֣י בִנְיָמִ֔ן וַ⁠יִּשְׂא֤וּ נָשִׁים֙ לְ⁠מִסְפָּרָ֔⁠ם מִן־הַ⁠מְּחֹלְל֖וֹת אֲשֶׁ֣ר גָּזָ֑לוּ וַ⁠יֵּלְכ֗וּ וַ⁠יָּשׁ֨וּבוּ֙ אֶל־נַ֣חֲלָתָ֔⁠ם וַ⁠יִּבְנוּ֙ אֶת־הֶ֣⁠עָרִ֔ים וַ⁠יֵּשְׁב֖וּ בָּ⁠הֶֽם׃","wa⁠yȧֽʻàş̂ẇ-kén֙ bĕ̇né֣y binĕyámi֔n wa⁠yi̇şĕ̂ʼ֤ẇ náşǐym֙ lĕ⁠misĕpá̇rá֔⁠m min-ha⁠mĕ̇ẖòlĕl֖wòţ ʼàşě֣r gá̇zá֑lẇ wa⁠yé̇lĕk֗ẇ wa⁠yá̇ş̌֨ẇbẇ֙ ʼel-na֣ẖàláţá֔⁠m wa⁠yi̇bĕnẇ֙ ʼeţ-he֣⁠ʻári֔ym wa⁠yé̇şĕ̌b֖ẇ bá̇⁠heֽm׃"],[21,24,"וַ⁠יִּתְהַלְּכ֨וּ מִ⁠שָּׁ֤ם בְּנֵֽי־יִשְׂרָאֵל֙ בָּ⁠עֵ֣ת הַ⁠הִ֔יא אִ֥ישׁ לְ⁠שִׁבְט֖⁠וֹ וּ⁠לְ⁠מִשְׁפַּחְתּ֑⁠וֹ וַ⁠יֵּצְא֣וּ מִ⁠שָּׁ֔ם אִ֖ישׁ לְ⁠נַחֲלָתֽ⁠וֹ׃","wa⁠yi̇ţĕhalĕ̇k֨ẇ mi⁠şá֤̇̌m bĕ̇néֽy-yişĕ̂ráʼél֙ bá̇⁠ʻé֣ţ ha⁠hi֔yʼ ʼi֥yş̌ lĕ⁠şǐbĕt֖⁠wò ẇ⁠lĕ⁠mişĕ̌pȧẖĕţ֑̇⁠wò wa⁠yé̇ẕĕʼ֣ẇ mi⁠şá̇̌֔m ʼi֖yş̌ lĕ⁠naẖàláţֽ⁠wò׃"],[21,25,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם אֵ֥ין מֶ֖לֶךְ בְּ⁠יִשְׂרָאֵ֑ל אִ֛ישׁ הַ⁠יָּשָׁ֥ר בְּ⁠עֵינָ֖י⁠ו יַעֲשֶֽׂה׃","bȧ⁠yá̇mi֣ym há⁠hé֔m ʼé֥yn me֖lekĕ bĕ̇⁠yişĕ̂ráʼé֑l ʼi֛yş̌ ha⁠yá̇şá֥̌r bĕ̇⁠ʻéyná֖y⁠w yaʻàşêֽh׃"]]}};